-- ------------------------------------------------------------------------
-- [1/376] Stored Procedure: [dbo].[BT_ActivityData]
-- Created: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author:      Vishal Verma
-- CREATE OR ALTER OR ALTER date: 22 Jul 2026
-- Description: Production CCLH Plan Execution Grid
-- =============================================
CREATE   PROCEDURE [dbo].[BT_ActivityData]
    @SKUID INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT MIN(ActivityID) AS FirstActivityID,
           MAX(ActivityID) AS LastActivityID
    FROM [PPMS_BajajPant].[dbo].[Config_Activity] Where ActivityEnable =1
    and SKUID = @SKUID;
END
GO

