CREATE     PROCEDURE [dbo].[BT_ApplicationSetting]

    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,

    @UID INT = NULL,
    @LineID INT = NULL,
    @ParameterID INT = NULL,
    @ParameterName NVARCHAR(100) = NULL,
    @ParameterValue NVARCHAR(50) = NULL,
    @ParameterType INT = NULL,

    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)

AS
BEGIN

    SET NOCOUNT ON;

    BEGIN TRY

        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------

        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END


        IF @Mode IN (2,3) AND ISNULL(@UID,0) = 0
        BEGIN
            SET @ResultMessage = 'UID is required';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END


        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------

        IF @Mode IN (1,2)
        BEGIN

            IF ISNULL(@LineID,0) = 0
               OR ISNULL(@ParameterID,0) = 0
               OR ISNULL(@ParameterName,'') = ''
               OR ISNULL(@ParameterValue,'') = ''
               OR ISNULL(@ParameterType,0) = 0
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END


            -------------------------------------------------
            -- MAX LENGTH VALIDATION
            -------------------------------------------------

            IF LEN(@ParameterName) > 100
            BEGIN
                SET @ResultMessage = 'Parameter Name cannot exceed 100 characters';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END


            IF LEN(@ParameterValue) > 50
            BEGIN
                SET @ResultMessage = 'Parameter Value cannot exceed 50 characters';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END


            -------------------------------------------------
            -- DUPLICATE VALIDATION
            -------------------------------------------------

            IF EXISTS
            (
                SELECT 1
                FROM dbo.ApplicationSetting
                WHERE LineID = @LineID
                  AND ParameterID = @ParameterID
                  AND ParameterName = @ParameterName
                  AND (@Mode = 1 OR UID <> @UID)
            )
            BEGIN
                SET @ResultMessage = 'Application Setting already exists';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

        END


        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------

        IF @Mode = 1
        BEGIN

            INSERT INTO dbo.ApplicationSetting
            (
                LineID,
                ParameterID,
                ParameterName,
                ParameterValue,
                ParameterType
            )
            VALUES
            (
                @LineID,
                @ParameterID,
                @ParameterName,
                @ParameterValue,
                @ParameterType
            );


            SET @UID = SCOPE_IDENTITY();


            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Application Setting Configuration',
                @UID,
                'Add Record',
                '',
                '',
                1,
                @Remark,
                @UserName
            );


            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END


        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------

        ELSE IF @Mode = 2
        BEGIN

            DECLARE
                @OldLineID INT,
                @OldParameterID INT,
                @OldParameterName NVARCHAR(100),
                @OldParameterValue NVARCHAR(50),
                @OldParameterType INT;


            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.ApplicationSetting
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'Record not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END


            SELECT
                @OldLineID = LineID,
                @OldParameterID = ParameterID,
                @OldParameterName = ParameterName,
                @OldParameterValue = ParameterValue,
                @OldParameterType = ParameterType
            FROM dbo.ApplicationSetting
            WHERE UID = @UID;


            UPDATE dbo.ApplicationSetting
            SET
                LineID = @LineID,
                ParameterID = @ParameterID,
                ParameterName = @ParameterName,
                ParameterValue = @ParameterValue,
                ParameterType = @ParameterType
            WHERE UID = @UID;


            IF ISNULL(@OldLineID,0) <> ISNULL(@LineID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Application Setting Configuration',
                    @UID,
                    'LineID',
                    @OldLineID,
                    @LineID,
                    2,
                    @Remark,
                    @UserName
                );
            END


            IF ISNULL(@OldParameterID,0) <> ISNULL(@ParameterID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Application Setting Configuration',
                    @UID,
                    'ParameterID',
                    @OldParameterID,
                    @ParameterID,
                    2,
                    @Remark,
                    @UserName
                );
            END


            IF ISNULL(@OldParameterName,'') <> ISNULL(@ParameterName,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Application Setting Configuration',
                    @UID,
                    'ParameterName',
                    @OldParameterName,
                    @ParameterName,
                    2,
                    @Remark,
                    @UserName
                );
            END


            IF ISNULL(@OldParameterValue,'') <> ISNULL(@ParameterValue,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Application Setting Configuration',
                    @UID,
                    'ParameterValue',
                    @OldParameterValue,
                    @ParameterValue,
                    2,
                    @Remark,
                    @UserName
                );
            END


            IF ISNULL(@OldParameterType,0) <> ISNULL(@ParameterType,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Application Setting Configuration',
                    @UID,
                    'ParameterType',
                    @OldParameterType,
                    @ParameterType,
                    2,
                    @Remark,
                    @UserName
                );
            END


            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END


        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------

        ELSE IF @Mode = 3
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.ApplicationSetting
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'Record not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END


            DELETE
            FROM dbo.ApplicationSetting
            WHERE UID = @UID;


            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Application Setting Configuration',
                @UID,
                'Delete Record',
                '',
                '',
                3,
                @Remark,
                @UserName
            );


            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END


    END TRY


    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END CATCH

END
