CREATE       PROCEDURE [dbo].[BT_Config_Activity_SOP_Mapping]

    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,

    @UID INT = NULL,
    @StationID INT = NULL,
    @ActivityID INT = NULL,
    @SOPID INT = NULL,
    @ModelFamilyID INT = NULL,
    @ModelID INT = NULL,
    @SKUID INT = NULL,
    @SequenceNo INT = NULL,

    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)

AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF @Mode IN (2,3) AND ISNULL(@UID,0) = 0
        BEGIN
            SET @ResultMessage = 'UID is required';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode IN (1,2)
        BEGIN
            -- Validating required operational keys based on standard table schema
            IF ISNULL(@StationID,0) = 0 
               OR ISNULL(@ActivityID,0) = 0 
               OR ISNULL(@SOPID,0) = 0
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields ';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            -------------------------------------------------
            -- FOREIGN KEY VALIDATION (Prevents Constraint Conflicts)
            -------------------------------------------------
            IF NOT EXISTS 
            (
                SELECT 1 
                FROM dbo.Config_Activity 
                WHERE UID = @ActivityID
            )
            BEGIN
                SET @ResultMessage = 'Selected Activity ID does not exist in master records.';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            -------------------------------------------------
            -- DUPLICATE VALIDATION
            -- Prevents duplicate combination of Station, Activity, and SOP mapping
            -------------------------------------------------
            IF EXISTS
            (
                SELECT 1
                FROM dbo.Config_Activity_SOP_Mapping
                WHERE StationID = @StationID
                  AND ActivityID = @ActivityID
                  AND SOPID = @SOPID
                  AND ISNULL(ModelFamilyID, 0) = ISNULL(@ModelFamilyID, 0)
                  AND ISNULL(ModelID, 0) = ISNULL(@ModelID, 0)
                  AND ISNULL(SKUID, 0) = ISNULL(@SKUID, 0)
                  AND (@Mode = 1 OR UID <> @UID)
            )
            BEGIN
                SET @ResultMessage = 'Mapping combination already exists';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
        END

        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN

            INSERT INTO dbo.Config_Activity_SOP_Mapping
            (
                StationID,
                ActivityID,
                SOPID,
                ModelFamilyID,
                ModelID,
                SKUID,
                SequenceNo
            )
            VALUES
            (
                @StationID,
                @ActivityID,
                @SOPID,
                @ModelFamilyID,
                @ModelID,
                @SKUID,
                @SequenceNo
            );

            SET @UID = SCOPE_IDENTITY();

            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Activity SOP Mapping',
                @UID,
                'Add Record',
                '',
                '',
                1,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN

            DECLARE
                @OldStationID INT,
                @OldActivityID INT,
                @OldSOPID INT,
                @OldModelFamilyID INT,
                @OldModelID INT,
                @OldSKUID INT,
                @OldSequenceNo INT;

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_Activity_SOP_Mapping
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'Record not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            SELECT
                @OldStationID     = StationID,
                @OldActivityID    = ActivityID,
                @OldSOPID         = SOPID,
                @OldModelFamilyID = ModelFamilyID,
                @OldModelID       = ModelID,
                @OldSKUID         = SKUID,
                @OldSequenceNo    = SequenceNo
            FROM dbo.Config_Activity_SOP_Mapping
            WHERE UID = @UID;

            UPDATE dbo.Config_Activity_SOP_Mapping
            SET
                StationID     = @StationID,
                ActivityID    = @ActivityID,
                SOPID         = @SOPID,
                ModelFamilyID = @ModelFamilyID,
                ModelID       = @ModelID,
                SKUID         = @SKUID,
                SequenceNo    = @SequenceNo
            WHERE UID = @UID;

            -- Field-level History Tracking
            IF ISNULL(@OldStationID,0) <> ISNULL(@StationID,0)
            BEGIN
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(), 'Activity SOP Mapping', @UID, 'StationID', @OldStationID, @StationID, 2, @Remark, @UserName);
            END

            IF ISNULL(@OldActivityID,0) <> ISNULL(@ActivityID,0)
            BEGIN
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(), 'Activity SOP Mapping', @UID, 'ActivityID', @OldActivityID, @ActivityID, 2, @Remark, @UserName);
            END

            IF ISNULL(@OldSOPID,0) <> ISNULL(@SOPID,0)
            BEGIN
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(), 'Activity SOP Mapping', @UID, 'SOPID', @OldSOPID, @SOPID, 2, @Remark, @UserName);
            END

            IF ISNULL(@OldModelFamilyID,0) <> ISNULL(@ModelFamilyID,0)
            BEGIN
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(), 'Activity SOP Mapping', @UID, 'ModelFamilyID', @OldModelFamilyID, @ModelFamilyID, 2, @Remark, @UserName);
            END

            IF ISNULL(@OldModelID,0) <> ISNULL(@ModelID,0)
            BEGIN
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(), 'Activity SOP Mapping', @UID, 'ModelID', @OldModelID, @ModelID, 2, @Remark, @UserName);
            END

            IF ISNULL(@OldSKUID,0) <> ISNULL(@SKUID,0)
            BEGIN
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(), 'Activity SOP Mapping', @UID, 'SKUID', @OldSKUID, @SKUID, 2, @Remark, @UserName);
            END

            IF ISNULL(@OldSequenceNo,0) <> ISNULL(@SequenceNo,0)
            BEGIN
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(), 'Activity SOP Mapping', @UID, 'SequenceNo', @OldSequenceNo, @SequenceNo, 2, @Remark, @UserName);
            END

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_Activity_SOP_Mapping
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'Record not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            DELETE
            FROM dbo.Config_Activity_SOP_Mapping
            WHERE UID = @UID;

            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Activity SOP Mapping',
                @UID,
                'Delete Record',
                '',
                '',
                3,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END CATCH

END
