CREATE       PROCEDURE [dbo].[BT_Config_Alarm]
    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,

    @AlarmID INT,
    @DepartmentID INT,
    @EquipmentID INT,
    @AlarmMessage NVARCHAR(200),
    @AlarmDesc NVARCHAR(300),
    @AlarmType INT,
    @Priority INT,
    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified';
            SET @ResultStatus = 0;
            SELECT @ResultMessage, @ResultStatus;
            RETURN;
        END

        --IF @AlarmID IS NULL
        --BEGIN
        --    SET @ResultMessage = 'AlarmID is required';
        --    SET @ResultStatus = 0;
        --    SELECT @ResultMessage, @ResultStatus;
        --    RETURN;
        --END

        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode IN (1,2)
        BEGIN
IF (
       ISNULL(@DepartmentID, 0) = 0
    OR ISNULL(@EquipmentID, 0) = 0
    OR ISNULL(LTRIM(RTRIM(@AlarmMessage)), '') = ''
    OR ISNULL(LTRIM(RTRIM(@AlarmDesc)), '') = ''
    OR ISNULL(@AlarmType, 0) = 0
    OR ISNULL(@Priority, 0) = 0
   )
BEGIN
    SET @ResultMessage = 'Fill all mandatory fields';
    SET @ResultStatus = 0;

    SELECT
        @ResultMessage AS ResultMessage,
        @ResultStatus AS ResultStatus;

    RETURN;
END
            IF ISNULL(@EquipmentID,0) = 0
            BEGIN
                SET @ResultMessage = 'Equipment name is required';
                SET @ResultStatus = 0;
                RETURN;
            END

            IF ISNULL(@DepartmentID,0) = 0
            BEGIN
                SET @ResultMessage = 'Department name is required';
                SET @ResultStatus = 0;
                RETURN;
            END

            IF ISNULL(LTRIM(RTRIM(@AlarmMessage)),'') = ''
            BEGIN
                SET @ResultMessage = 'Alarm Message is required';
                SET @ResultStatus = 0;
                RETURN;
            END

            IF ISNULL(@AlarmType,0) = 0
            BEGIN
                SET @ResultMessage = 'Alarm Type is required';
                SET @ResultStatus = 0;
                RETURN;
            END
             IF ISNULL(@Priority,0) = 0
            BEGIN
                SET @ResultMessage = 'Priority is required';
                SET @ResultStatus = 0;
                RETURN;
            END
            
        END

        -------------------------------------------------
        -- INSERT
        -------------------------------------------------
        IF @Mode = 1
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.Config_Alarm WHERE AlarmID = @AlarmID)
            BEGIN
                SET @ResultMessage = 'Alarm details already exists';
                SET @ResultStatus = 0;
                RETURN;
            END

            INSERT INTO dbo.Config_Alarm
            (
                --AlarmID,
                DepartmentID,
                EquipmentID,
                AlarmMessage,
                AlarmDesc,
                AlarmType,
                Priority
            )
            VALUES
            (
                --@AlarmID,
                @DepartmentID,
                @EquipmentID,
                @AlarmMessage,
                @AlarmDesc,
                @AlarmType,
                @Priority
            );

            INSERT INTO dbo.Config_History
            VALUES (GETDATE(),'Alarm Configuration',@AlarmID,'Add Record',' ',' ',1,@Remark,@UserName);

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage, @ResultStatus;
        END

        -------------------------------------------------
        -- UPDATE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN
            IF NOT EXISTS (SELECT 1 FROM dbo.Config_Alarm WHERE AlarmID = @AlarmID)
            BEGIN
                SET @ResultMessage = 'Alarm detail not found';
                SET @ResultStatus = 0;
                RETURN;
            END

            UPDATE dbo.Config_Alarm
            SET
                DepartmentID = @DepartmentID,
                EquipmentID = @EquipmentID,
                AlarmMessage = @AlarmMessage,
                AlarmDesc = @AlarmDesc,
                AlarmType = @AlarmType,
                Priority = @Priority
            WHERE AlarmID = @AlarmID;

            INSERT INTO dbo.Config_History
            VALUES (GETDATE(),'Alarm Configuration',@AlarmID,'Update Record',' ',' ',2,@Remark,@UserName);

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage, @ResultStatus;
        END

        -------------------------------------------------
        -- DELETE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN
            DELETE FROM dbo.Config_Alarm
            WHERE AlarmID = @AlarmID;

            IF @@ROWCOUNT = 0
            BEGIN
                SET @ResultMessage = 'Alarm not found';
                SET @ResultStatus = 0;
                RETURN;
            END

            INSERT INTO dbo.Config_History
            VALUES (GETDATE(),'Alarm Configuration',@AlarmID,'Delete Record',' ',' ',3,@Remark,@UserName);

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage, @ResultStatus;
        END

    END TRY

    BEGIN CATCH
        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;
        SELECT @ResultMessage, @ResultStatus;
    END CATCH
END
