    @AuditListScreen NVARCHAR(100)   = NULL,
    @Remark          NVARCHAR(300)   = NULL,
    @UserName        NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        -------------------------------------------------
        -- MODE VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1, 2, 3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode IN (1, 2)
        BEGIN
            IF (
                ISNULL(@AuditGroup, '')   = ''
                OR ISNULL(@DocumentNo, 0)  = 0
                OR ISNULL(@AuditListID, 0) = 0
            )
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END
        END

        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN
            -- Duplicate check
            IF EXISTS
            (
                SELECT 1 FROM dbo.Config_AuditDocumentMapping
                WHERE DocumentNo  = @DocumentNo
                AND   AuditListID = @AuditListID
            )
            BEGIN
                SET @ResultMessage = 'This Document is already mapped to the selected Audit List';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            INSERT INTO dbo.Config_AuditDocumentMapping
            (
                AuditGroup,
                DocumentNo,
                ModelFamily,
                Model,
                SKU,
                PartID,
                AuditListID,
                AuditListScreen
            )
            VALUES
            (
                @AuditGroup,
                @DocumentNo,
                @ModelFamily,
                @Model,
                @SKU,
                @PartID,
                @AuditListID,
                @AuditListScreen
            );

            DECLARE @NewUID INT = SCOPE_IDENTITY();

            INSERT INTO dbo.Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Audit Document Mapping Configuration',
                @NewUID,
                'Add Record',
                ' ', ' ',
                1,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN
            IF NOT EXISTS
            (
                SELECT 1 FROM dbo.Config_AuditDocumentMapping
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'UID not found';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            -- Duplicate check (exclude current record)
            IF EXISTS
            (
                SELECT 1 FROM dbo.Config_AuditDocumentMapping
                WHERE DocumentNo  = @DocumentNo
                AND   AuditListID = @AuditListID
                AND   UID        <> @UID
            )
            BEGIN
                SET @ResultMessage = 'This Document is already mapped to the selected Audit List';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            UPDATE dbo.Config_AuditDocumentMapping
            SET
                AuditGroup      = @AuditGroup,
                DocumentNo      = @DocumentNo,
                ModelFamily     = @ModelFamily,
                Model           = @Model,
                SKU             = @SKU,
                PartID          = @PartID,
                AuditListID     = @AuditListID,
                AuditListScreen = @AuditListScreen
            WHERE UID = @UID;

            INSERT INTO dbo.Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Audit Document Mapping Configuration',
                @UID,
                'Update Record',
                ' ', ' ',
                2,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN
            IF NOT EXISTS
            (
                SELECT 1 FROM dbo.Config_AuditDocumentMapping
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'UID not found';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            DELETE FROM dbo.Config_AuditDocumentMapping
            WHERE UID = @UID;

            INSERT INTO dbo.Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Audit Document Mapping Configuration',
                @UID,
                'Delete Record',
                ' ', ' ',
                3,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

    END TRY

    BEGIN CATCH
        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;
        SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
    END CATCH
END
GO

-- ------------------------------------------------------------------------
-- [6/376] Stored Procedure: [dbo].[BT_Config_AuditList]
-- Created: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Shubham Patil
-- CREATE OR ALTER OR ALTER date : 22-05-2026
-- Description : Procedure for Add, Modify & Delete Audit List Configuration.
--               Handles history tracking & exception handling.
-- =============================================

--*************************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY     | DESCRIPTION     |
-----------------------------------------------------------
--| 22-05-2026 | Shubham Patil  | CREATE OR ALTER OR ALTERd         |
-----------------------------------------------------------
--*************************************************************************

CREATE       PROCEDURE [dbo].[BT_Config_AuditList]

    @ResultMessage VARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT, -- 0 = ERROR , 1 = SUCCESS
    @Mode INT,                -- 1 = ADD, 2 = UPDATE, 3 = DELETE

    -- PARAMETERS FROM GRAPHWORX
    @AuditListID INT = NULL,
    @DocumentID INT = NULL,
    @ModelFamilyID INT = NULL,
    @ModelID INT = NULL,
    @SKUID INT = NULL,
    @PartID NVARCHAR(20) = NULL,
    @AuditListName NVARCHAR(300) = NULL,

    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)

AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        -- =============================================
        -- COMMON VALIDATION
        -- =============================================

        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        -- =============================================
        -- INSERT / UPDATE VALIDATION
        -- =============================================

        IF @Mode IN (1,2)
        BEGIN

            IF (
                    ISNULL(@DocumentID,0) = 0
                    OR ISNULL(@ModelFamilyID,0) = 0
                    OR ISNULL(@ModelID,0) = 0
                    OR ISNULL(@SKUID,0) = 0
                    OR ISNULL(LTRIM(RTRIM(@PartID)),'') = ''
                    OR ISNULL(LTRIM(RTRIM(@AuditListName)),'') = ''
               )
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(ISNULL(@AuditListName,'')) > 300
            BEGIN
                SET @ResultMessage = 'Audit Description exceeds max length (300)';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

        END

        -- =============================================
        -- INSERT MODE
        -- =============================================

        IF @Mode = 1
        BEGIN

            -- VALIDATION CHECKS

            IF NOT EXISTS (SELECT 1 FROM Config_QADocumentList WHERE DocumentID = @DocumentID)
            BEGIN
                SET @ResultMessage = 'Invalid DocumentID';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
                RETURN;
            END

            IF NOT EXISTS (SELECT 1 FROM Config_ModelFamily WHERE ModelFamilyID = @ModelFamilyID)
            BEGIN
                SET @ResultMessage = 'Invalid ModelFamilyID';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
                RETURN;
            END

            IF NOT EXISTS (SELECT 1 FROM Config_Model WHERE ModelID = @ModelID)
            BEGIN
                SET @ResultMessage = 'Invalid ModelID';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
                RETURN;
            END

            IF NOT EXISTS (SELECT 1 FROM Config_SKU WHERE SKUID = @SKUID)
            BEGIN
                SET @ResultMessage = 'Invalid SKUID';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
                RETURN;
            END

            IF NOT EXISTS (SELECT 1 FROM Config_Part WHERE PartID = @PartID)
            BEGIN
                SET @ResultMessage = 'Invalid PartID';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
                RETURN;
            END

            -- DUPLICATE CHECK

            --IF EXISTS
            --(
            --    SELECT 1
            --    FROM Config_AuditList
            --    WHERE DocumentID = @DocumentID
            --    AND ModelFamilyID = @ModelFamilyID
            --    AND ModelID = @ModelID
            --    AND SKUID = @SKUID
            --    AND PartID = @PartID
            --)
            --BEGIN
            --    SET @ResultMessage = 'Audit List already exists';
            --    SET @ResultStatus = 0;

            --    SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
            --    RETURN;
            --END

            -- INSERT

            INSERT INTO Config_AuditList
            (
                DocumentID,
                ModelFamilyID,
                ModelID,
                SKUID,
                PartID,
                AuditListName
            )
            VALUES
            (
                @DocumentID,
                @ModelFamilyID,
                @ModelID,
                @SKUID,
                @PartID,
                @AuditListName
            );

            DECLARE @NewAuditListID INT;
            SET @NewAuditListID = SCOPE_IDENTITY();

            -- HISTORY

            INSERT INTO Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Audit List Configuration',
                @NewAuditListID,
                'Insert',
                ' ',
                ' ',
                1,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

        -- =============================================
        -- UPDATE MODE
        -- =============================================

        ELSE IF @Mode = 2
        BEGIN

            DECLARE @OldDocumentID INT;
            DECLARE @OldModelFamilyID INT;
            DECLARE @OldModelID INT;
            DECLARE @OldSKUID INT;
            DECLARE @OldPartID NVARCHAR(20);
            DECLARE @OldAuditListName NVARCHAR(300);

            IF NOT EXISTS (SELECT 1 FROM Config_AuditList WHERE AuditListID = @AuditListID)
            BEGIN
                SET @ResultMessage = 'AuditListID not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            -- GET OLD VALUES

            SELECT
                @OldDocumentID = DocumentID,
                @OldModelFamilyID = ModelFamilyID,
                @OldModelID = ModelID,
                @OldSKUID = SKUID,
                @OldPartID = PartID,
                @OldAuditListName = AuditListName
            FROM Config_AuditList
            WHERE AuditListID = @AuditListID;

            -- UPDATE

            UPDATE Config_AuditList
            SET
                DocumentID = CASE WHEN ISNULL(DocumentID,0) <> ISNULL(@DocumentID,0)
                                  THEN @DocumentID ELSE DocumentID END,

                ModelFamilyID = CASE WHEN ISNULL(ModelFamilyID,0) <> ISNULL(@ModelFamilyID,0)
                                  THEN @ModelFamilyID ELSE ModelFamilyID END,

                ModelID = CASE WHEN ISNULL(ModelID,0) <> ISNULL(@ModelID,0)
                                  THEN @ModelID ELSE ModelID END,

                SKUID = CASE WHEN ISNULL(SKUID,0) <> ISNULL(@SKUID,0)
                                  THEN @SKUID ELSE SKUID END,

                PartID = CASE WHEN ISNULL(PartID,'') <> ISNULL(@PartID,'')
                                  THEN @PartID ELSE PartID END,

                AuditListName = CASE WHEN ISNULL(AuditListName,'') <> ISNULL(@AuditListName,'')
                                  THEN @AuditListName ELSE AuditListName END

            WHERE AuditListID = @AuditListID;

            -- HISTORY : DocumentID

            IF ISNULL(@OldDocumentID,0) <> ISNULL(@DocumentID,0)
            BEGIN
                INSERT INTO Config_History
                VALUES
                (
                    GETDATE(),
                    'Audit List Configuration',
                    @AuditListID,
                    'DocumentID',
                    CAST(ISNULL(@OldDocumentID,0) AS VARCHAR(100)),
                    CAST(ISNULL(@DocumentID,0) AS VARCHAR(100)),
                    2,
                    @Remark,
                    @UserName
                );
            END

            -- HISTORY : ModelFamilyID

            IF ISNULL(@OldModelFamilyID,0) <> ISNULL(@ModelFamilyID,0)
            BEGIN
                INSERT INTO Config_History
                VALUES
                (
                    GETDATE(),
                    'Audit List Configuration',
                    @AuditListID,
                    'ModelFamilyID',
                    CAST(ISNULL(@OldModelFamilyID,0) AS VARCHAR(100)),
                    CAST(ISNULL(@ModelFamilyID,0) AS VARCHAR(100)),
                    2,
                    @Remark,
                    @UserName
                );
            END

            -- HISTORY : ModelID

            IF ISNULL(@OldModelID,0) <> ISNULL(@ModelID,0)
            BEGIN
                INSERT INTO Config_History
                VALUES
                (
                    GETDATE(),
                    'Audit List Configuration',
                    @AuditListID,
                    'ModelID',
                    CAST(ISNULL(@OldModelID,0) AS VARCHAR(100)),
                    CAST(ISNULL(@ModelID,0) AS VARCHAR(100)),
                    2,
                    @Remark,
                    @UserName
                );
            END

            -- HISTORY : SKUID

            IF ISNULL(@OldSKUID,0) <> ISNULL(@SKUID,0)
            BEGIN
                INSERT INTO Config_History
                VALUES
                (
                    GETDATE(),
                    'Audit List Configuration',
                    @AuditListID,
                    'SKUID',
                    CAST(ISNULL(@OldSKUID,0) AS VARCHAR(100)),
                    CAST(ISNULL(@SKUID,0) AS VARCHAR(100)),
                    2,
                    @Remark,
                    @UserName
                );
            END

            -- HISTORY : PartID

            IF ISNULL(@OldPartID,'') <> ISNULL(@PartID,'')
            BEGIN
                INSERT INTO Config_History
                VALUES
                (
                    GETDATE(),
                    'Audit List Configuration',
                    @AuditListID,
                    'PartID',
                    ISNULL(@OldPartID,''),
                    ISNULL(@PartID,''),
                    2,
                    @Remark,
                    @UserName
                );
            END

            -- HISTORY : AuditListName

            IF ISNULL(@OldAuditListName,'') <> ISNULL(@AuditListName,'')
            BEGIN
                INSERT INTO Config_History
                VALUES
                (
                    GETDATE(),
                    'Audit List Configuration',
                    @AuditListID,
                    'AuditListName',
                    ISNULL(@OldAuditListName,''),
                    ISNULL(@AuditListName,''),
                    2,
                    @Remark,
                    @UserName
                );
            END

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

        -- =============================================
        -- DELETE MODE
        -- =============================================

        ELSE IF @Mode = 3
        BEGIN

            IF NOT EXISTS (SELECT 1 FROM Config_AuditList WHERE AuditListID = @AuditListID)
            BEGIN
                SET @ResultMessage = 'AuditListID not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            DELETE FROM Config_AuditList
            WHERE AuditListID = @AuditListID;

            INSERT INTO Config_History
            VALUES
            (
                GETDATE(),
                'Audit List Configuration',
                @AuditListID,
                'Delete',
                ' ',
                ' ',
                3,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

    END TRY

    BEGIN CATCH

        EXEC RethrowError;

        SET @ResultMessage = 'SQL ERROR';
        SET @ResultStatus = 0;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END CATCH

END
GO

-- ------------------------------------------------------------------------
-- [7/376] Stored Procedure: [dbo].[BT_Config_AuditPointLinking]
-- Created: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 04-08-2026
-- Description : Procedure for Add, Modify & Delete Buttons - Audit Point Linking
-- =============================================

--***************************************************************
--Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION                                        |
-----------------------------------------------------------
--| 04-08-2026 | Sumit      | CREATE OR ALTER OR ALTERd                                            |
--| 03-09-2026 | Sumit      | Aligned to table structure: renamed SubAsslyLineID |
--|            |            | to SubAsslyLineID, changed EnginePartID to NVARCHAR(10)|
--|            |            | added SOPID support                                |
-----------------------------------------------------------
--***************************************************************/

CREATE       PROCEDURE [dbo].[BT_Config_AuditPointLinking]

    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,

    @UID INT,
    @DocumentID INT,
    @AuditListID INT,
    @AuditPointID INT,
    @Revision INT,
    @StationID INT,
    @SubAsslyLineID INT = NULL,
    @PartID NVARCHAR(20) = NULL,
    @EnginePartID NVARCHAR(10) = NULL,
    @ActivityID INT = NULL,
    @ParameterID INT = NULL,
    @SOPID INT = NULL,

    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)

AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF @Mode IN (2,3) AND ISNULL(@UID,0) = 0
        BEGIN
            SET @ResultMessage = 'UID is required';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode IN (1,2)
        BEGIN
            IF ISNULL(@DocumentID,0) = 0
               OR ISNULL(@AuditListID,0) = 0
               OR ISNULL(@AuditPointID,0) = 0
               OR ISNULL(@Revision,0) = 0
               OR ISNULL(@StationID,0) = 0
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            -------------------------------------------------
            -- MAX LENGTH VALIDATION
            -------------------------------------------------
            IF LEN(ISNULL(@PartID,'')) > 20
            BEGIN
                SET @ResultMessage = 'Part ID cannot exceed 20 characters';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(ISNULL(@EnginePartID,'')) > 10
            BEGIN
                SET @ResultMessage = 'Engine Part ID cannot exceed 10 characters';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            -------------------------------------------------
            -- DUPLICATE VALIDATION
            -------------------------------------------------
            IF EXISTS
            (
                SELECT 1
                FROM dbo.Config_AuditPointLinking
                WHERE DocumentID   = @DocumentID
                  AND AuditListID  = @AuditListID
                  AND AuditPointID = @AuditPointID
                  AND Revision     = @Revision
                  AND StationID    = @StationID
                  AND ISNULL(SubAsslyLineID,0)   = ISNULL(@SubAsslyLineID,0)
                  AND ISNULL(PartID,'')      = ISNULL(@PartID,'')
                  AND ISNULL(EnginePartID,'') = ISNULL(@EnginePartID,'')
                  AND ISNULL(ActivityID,0)   = ISNULL(@ActivityID,0)
                  AND ISNULL(ParameterID,0)  = ISNULL(@ParameterID,0)
                  AND ISNULL(SOPID,0)        = ISNULL(@SOPID,0)
                  AND (@Mode = 1 OR UID <> @UID)
            )
            BEGIN
                SET @ResultMessage = 'Audit Point Linking already exists';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
        END

        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN

            INSERT INTO dbo.Config_AuditPointLinking
            (
                DocumentID,
                AuditListID,
                AuditPointID,
                Revision,
                StationID,
                SubAsslyLineID,
                PartID,
                EnginePartID,
                ActivityID,
                ParameterID,
                SOPID
            )
            VALUES
            (
                @DocumentID,
                @AuditListID,
                @AuditPointID,
                @Revision,
                @StationID,
                @SubAsslyLineID,
                @PartID,
                @EnginePartID,
                @ActivityID,
                @ParameterID,
                @SOPID
            );

            SET @UID = SCOPE_IDENTITY();

            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Audit Point Linking Configuration',
                @UID,
                'Add Record',
                '',
                '',
                1,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN

            DECLARE
                @OldDocumentID   INT,
                @OldAuditListID  INT,
                @OldAuditPointID INT,
                @OldRevision     INT,
                @OldStationID    INT,
                @OldSubAsslyLineID   INT,
                @OldPartID       NVARCHAR(20),
                @OldEnginePartID NVARCHAR(10),
                @OldActivityID   INT,
                @OldParameterID  INT,
                @OldSOPID        INT;

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_AuditPointLinking
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'Record not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            SELECT
                @OldDocumentID   = DocumentID,
                @OldAuditListID  = AuditListID,
                @OldAuditPointID = AuditPointID,
                @OldRevision     = Revision,
                @OldStationID    = StationID,
                @OldSubAsslyLineID   = SubAsslyLineID,
                @OldPartID       = PartID,
                @OldEnginePartID = EnginePartID,
                @OldActivityID   = ActivityID,
                @OldParameterID  = ParameterID,
                @OldSOPID        = SOPID
            FROM dbo.Config_AuditPointLinking
            WHERE UID = @UID;

            UPDATE dbo.Config_AuditPointLinking
            SET
                DocumentID   = @DocumentID,
                AuditListID  = @AuditListID,
                AuditPointID = @AuditPointID,
                Revision     = @Revision,
                StationID    = @StationID,
                SubAsslyLineID   = @SubAsslyLineID,
                PartID       = @PartID,
                EnginePartID = @EnginePartID,
                ActivityID   = @ActivityID,
                ParameterID  = @ParameterID,
                SOPID        = @SOPID
            WHERE UID = @UID;

            IF ISNULL(@OldDocumentID,0) <> ISNULL(@DocumentID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Audit Point Linking Configuration', @UID,
                    'DocumentID', @OldDocumentID, @DocumentID,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldAuditListID,0) <> ISNULL(@AuditListID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Audit Point Linking Configuration', @UID,
                    'AuditListID', @OldAuditListID, @AuditListID,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldAuditPointID,0) <> ISNULL(@AuditPointID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Audit Point Linking Configuration', @UID,
                    'AuditPointID', @OldAuditPointID, @AuditPointID,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldRevision,0) <> ISNULL(@Revision,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Audit Point Linking Configuration', @UID,
                    'Revision', @OldRevision, @Revision,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldStationID,0) <> ISNULL(@StationID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Audit Point Linking Configuration', @UID,
                    'StationID', @OldStationID, @StationID,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldSubAsslyLineID,0) <> ISNULL(@SubAsslyLineID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
