                    'SubAsslyLineID', @OldSubAsslyLineID, @SubAsslyLineID,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldPartID,'') <> ISNULL(@PartID,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Audit Point Linking Configuration', @UID,
                    'PartID', @OldPartID, @PartID,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldEnginePartID,'') <> ISNULL(@EnginePartID,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Audit Point Linking Configuration', @UID,
                    'EnginePartID', @OldEnginePartID, @EnginePartID,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldActivityID,0) <> ISNULL(@ActivityID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Audit Point Linking Configuration', @UID,
                    'ActivityID', @OldActivityID, @ActivityID,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldParameterID,0) <> ISNULL(@ParameterID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Audit Point Linking Configuration', @UID,
                    'ParameterID', @OldParameterID, @ParameterID,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldSOPID,0) <> ISNULL(@SOPID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Audit Point Linking Configuration', @UID,
                    'SOPID', @OldSOPID, @SOPID,
                    2, @Remark, @UserName
                );
            END

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_AuditPointLinking
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'Record not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            DELETE
            FROM dbo.Config_AuditPointLinking
            WHERE UID = @UID;

            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Audit Point Linking Configuration',
                @UID,
                'Delete Record',
                '',
                '',
                3,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END CATCH

END
