-- ------------------------------------------------------------------------
-- [8/376] Stored Procedure: [dbo].[BT_Config_AuditSchedule]
-- Created: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 03-07-2026
-- Description : Procedure for Add, Modify & Delete
--               Audit Schedule Configuration.
-- =============================================

--*************************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION                 |
-----------------------------------------------------------
--| 03-07-2026 | Sumit      | CREATE OR ALTER OR ALTERd                     |
--| 03-07-2026 | Sumit      | Fixed column alignment,     |
--|            |            | UID validation, history,    |
--|            |            | Mode 3 UID check            |
--| 07-09-2026 | Sumit      | AuditInstanceID is now      |
--|            |            | auto-incremented per        |
--|            |            | DocumentID internally;      |
--|            |            | removed as input param      |
-----------------------------------------------------------
--*************************************************************************

CREATE       PROCEDURE [dbo].[BT_Config_AuditSchedule]

    @ResultMessage  NVARCHAR(MAX)   OUTPUT,
    @ResultStatus   INT             OUTPUT,
    @Mode           INT,

    @UID            INT             = NULL,
    @LineID         INT             = NULL,
    @DocumentID     INT             = NULL,
    @StartDateTime  DATETIME        = NULL,
    @NextDueDate    DATETIME        = NULL,
    @FrequencyType  INT             = NULL,
    @FrequencyValue INT             = NULL,
    @Notification   INT             = NULL,
    @Status         INT             = NULL,

    @Remark         NVARCHAR(300)   = NULL,
    @UserName       NVARCHAR(100)

AS
BEGIN

    SET NOCOUNT ON;

    BEGIN TRY

        -- =============================================
        -- MODE VALIDATION
        -- =============================================

        IF @Mode NOT IN (1, 2, 3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus  = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        -- =============================================
        -- UID VALIDATION
        -- =============================================

        IF @Mode IN (2, 3) AND ISNULL(@UID, 0) = 0
        BEGIN
            SET @ResultMessage = 'UID is required';
            SET @ResultStatus  = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        -- =============================================
        -- INSERT / UPDATE VALIDATION
        -- =============================================

        IF @Mode IN (1, 2)
        BEGIN

            IF (
                ISNULL(@LineID,        0) = 0
                OR ISNULL(@DocumentID, 0) = 0
                --OR @StartDateTime         IS NULL
                --OR @NextDueDate           IS NULL
                OR ISNULL(@FrequencyType,  0) = 0
                OR ISNULL(@FrequencyValue, 0) = 0
            )
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            --IF @FrequencyType NOT IN (1, 2, 3)
            --BEGIN
            --    SET @ResultMessage = 'Invalid FrequencyType. 1=Day, 2=Count, 3=Hourly';
            --    SET @ResultStatus  = 0;
            --    SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            --    RETURN;
            --END

            --IF @Notification IS NOT NULL AND @Notification NOT IN (1, 2, 3, 4)
            --BEGIN
            --    SET @ResultMessage = 'Invalid Notification. 1=Normal, 2=Alert, 3=Warning, 4=Alarm';
            --    SET @ResultStatus  = 0;
            --    SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            --    RETURN;
            --END

            IF @StartDateTime >= @NextDueDate
            BEGIN
                SET @ResultMessage = 'NextDueDate must be after StartDateTime';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

        END

        -- =============================================
        -- INSERT MODE
        -- =============================================

        IF @Mode = 1
        BEGIN

            -- AuditInstanceID is system-generated: next sequence number
            -- scoped per DocumentID (not user/frontend supplied).
            DECLARE @NewAuditInstanceID INT;

            SELECT @NewAuditInstanceID = ISNULL(MAX(AuditInstanceID), 0) + 1
            FROM dbo.Config_AuditSchedule
            WHERE DocumentID = @DocumentID;

            INSERT INTO dbo.Config_AuditSchedule
            (
                LineID,
                DocumentID,
                AuditInstanceID,
                StartDateTime,
                NextDueDate,
                FrequencyType,
                FrequencyValue,
                Notification,
                Status
            )
            VALUES
            (
                @LineID,
                @DocumentID,
                @NewAuditInstanceID,
                @StartDateTime,
                @NextDueDate,
                @FrequencyType,
                @FrequencyValue,
                @Notification,
                ISNULL(@Status, 0)      -- default 0 = NotSchedule
            );

            DECLARE @NewUID INT;
            SET @NewUID = SCOPE_IDENTITY();

            INSERT INTO dbo.Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(), 'Audit Schedule Configuration', @NewUID,
                'Insert', '', '',
                1, @Remark, @UserName
            );

            SET @ResultMessage = 'Inserted Successfully';
            SET @ResultStatus  = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;

        END

        -- =============================================
        -- UPDATE MODE
        -- =============================================

        ELSE IF @Mode = 2
        BEGIN

            DECLARE @OldLineID          INT;
            DECLARE @OldDocumentID      INT;
            DECLARE @OldStartDateTime   DATETIME;
            DECLARE @OldNextDueDate     DATETIME;
            DECLARE @OldFrequencyType   INT;
            DECLARE @OldFrequencyValue  INT;
            DECLARE @OldNotification    INT;
            DECLARE @OldStatus          INT;

            IF NOT EXISTS
            (
                SELECT 1 FROM dbo.Config_AuditSchedule
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'UID not found';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            SELECT
                @OldLineID          = LineID,
                @OldDocumentID      = DocumentID,
                @OldStartDateTime   = StartDateTime,
                @OldNextDueDate     = NextDueDate,
                @OldFrequencyType   = FrequencyType,
                @OldFrequencyValue  = FrequencyValue,
                @OldNotification    = Notification,
                @OldStatus          = Status
            FROM dbo.Config_AuditSchedule
            WHERE UID = @UID;

            -- AuditInstanceID is not editable; DocumentID is intentionally left
            -- unchanged too, since AuditInstanceID's sequence is scoped to the
            -- original DocumentID it was generated under.
            UPDATE dbo.Config_AuditSchedule
            SET
                LineID          = @LineID,
                StartDateTime   = @StartDateTime,
                NextDueDate     = @NextDueDate,
                FrequencyType   = @FrequencyType,
                FrequencyValue  = @FrequencyValue,
                Notification    = @Notification,
                Status          = @Status
            WHERE UID = @UID;

            -- HISTORY
            IF ISNULL(@OldLineID, 0) <> ISNULL(@LineID, 0)
            BEGIN
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(), 'Audit Schedule Configuration', @UID,
                 'LineID', @OldLineID, @LineID, 2, @Remark, @UserName);
            END

            IF ISNULL(@OldStartDateTime, '1900-01-01') <> ISNULL(@StartDateTime, '1900-01-01')
            BEGIN
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(), 'Audit Schedule Configuration', @UID,
                 'StartDateTime', @OldStartDateTime, @StartDateTime, 2, @Remark, @UserName);
            END

            IF ISNULL(@OldNextDueDate, '1900-01-01') <> ISNULL(@NextDueDate, '1900-01-01')
            BEGIN
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(), 'Audit Schedule Configuration', @UID,
                 'NextDueDate', @OldNextDueDate, @NextDueDate, 2, @Remark, @UserName);
            END

            IF ISNULL(@OldFrequencyType, 0) <> ISNULL(@FrequencyType, 0)
            BEGIN
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(), 'Audit Schedule Configuration', @UID,
                 'FrequencyType', @OldFrequencyType, @FrequencyType, 2, @Remark, @UserName);
            END

            IF ISNULL(@OldFrequencyValue, 0) <> ISNULL(@FrequencyValue, 0)
            BEGIN
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(), 'Audit Schedule Configuration', @UID,
                 'FrequencyValue', @OldFrequencyValue, @FrequencyValue, 2, @Remark, @UserName);
            END

            IF ISNULL(@OldNotification, 0) <> ISNULL(@Notification, 0)
            BEGIN
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(), 'Audit Schedule Configuration', @UID,
                 'Notification', @OldNotification, @Notification, 2, @Remark, @UserName);
            END

            IF ISNULL(@OldStatus, 0) <> ISNULL(@Status, 0)
            BEGIN
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(), 'Audit Schedule Configuration', @UID,
                 'Status', @OldStatus, @Status, 2, @Remark, @UserName);
            END

            SET @ResultMessage = 'Updated Successfully';
            SET @ResultStatus  = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;

        END

        -- =============================================
        -- DELETE MODE
        -- =============================================

        ELSE IF @Mode = 3
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1 FROM dbo.Config_AuditSchedule
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'UID not found';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            DELETE FROM dbo.Config_AuditSchedule
            WHERE UID = @UID;

            INSERT INTO dbo.Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(), 'Audit Schedule Configuration', @UID,
                'Delete', '', '',
                3, @Remark, @UserName
            );

            SET @ResultMessage = 'Deleted Successfully';
            SET @ResultStatus  = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;

        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL ERROR';
        SET @ResultStatus  = 0;
        SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;

    END CATCH

END
GO

