-- [9/376] Stored Procedure: [dbo].[BT_Config_BOM]
-- Created: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 03-07-2026
-- Description : Procedure for Add, Modify & Delete
--               BOM Configuration.
-- =============================================

--*************************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION                 |
-----------------------------------------------------------
--| 03-07-2026 | Sumit      | CREATE OR ALTER OR ALTERd                     |
--| 04-07-2026 | Sumit      | UID manual increment added  |
--| 06-07-2026 | Sumit      | Added PreferredPartID param;|
--| 06-07-2026 | Sumit      | Added MaterialMoveType param;
--|            |            | PreferredPartID made mandatory
--|            |            | to match table structure     |
--| 06-07-2026 | Sumit      | UID is an IDENTITY column in |
--|            |            | table; removed manual MAX+1  |
--|            |            | logic, now uses              |
--|            |            | SCOPE_IDENTITY() instead      |
-----------------------------------------------------------
--*************************************************************************

CREATE       PROCEDURE [dbo].[BT_Config_BOM]

    @ResultMessage      NVARCHAR(MAX)   OUTPUT,
    @ResultStatus       INT             OUTPUT,
    @Mode               INT,

    @UID                INT,
    @SKUID              INT,
    @PartID             NVARCHAR(20),
    @PartDesc           NVARCHAR(300),
    @PartLevel          INT,
    @PartQuantity       INT,
    @ParentID           NVARCHAR(20)             = NULL,
    @AlternatePartFlag  INT,
    @StationID          INT,
    @PreferredPartID    NVARCHAR(20)             = NULL,
    @MaterialMoveType   INT,

    @Remark             NVARCHAR(300)   = NULL,
    @UserName           NVARCHAR(100)

AS
BEGIN

    SET NOCOUNT ON;

    BEGIN TRY

        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1, 2, 3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus  = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF @Mode IN (2, 3) AND ISNULL(@UID, 0) = 0
        BEGIN
            SET @ResultMessage = 'UID is required';
            SET @ResultStatus  = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode IN (1, 2)
        BEGIN

            IF (
                ISNULL(@SKUID,   0) = 0
                OR ISNULL(LTRIM(RTRIM(@PartID)),   '') = ''
                OR ISNULL(LTRIM(RTRIM(@PartDesc)), '') = ''
                OR ISNULL(@StationID, 0) = 0
                OR @PartLevel IS NULL
                OR @PartQuantity IS NULL
                OR @AlternatePartFlag IS NULL
                OR ISNULL(LTRIM(RTRIM(@PreferredPartID)), '') = ''
                OR @MaterialMoveType IS NULL
            )
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            -------------------------------------------------
            -- DUPLICATE VALIDATION
            -------------------------------------------------
            IF EXISTS
            (
                SELECT 1
                FROM dbo.Config_BOM
                WHERE SKUID                  = @SKUID
                  AND PartID                 = @PartID
                  AND ISNULL(ParentID, 0)    = ISNULL(@ParentID, 0)
                  AND StationID              = @StationID
                  AND (@Mode = 1 OR UID <> @UID)
            )
            BEGIN
                SET @ResultMessage = 'BOM record already exists';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

        END

        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN

            DECLARE @NewUID INT;

            INSERT INTO dbo.Config_BOM
            (
                SKUID,
                PartID,
                PartDesc,
                PartLevel,
                PartQuantity,
                ParentID,
                AlternatePartFlag,
                StationID,
                PreferredPartID,
                MaterialMoveType
            )
            VALUES
            (
                @SKUID,
                @PartID,
                @PartDesc,
                @PartLevel,
                @PartQuantity,
                @ParentID,
                @AlternatePartFlag,
                @StationID,
                @PreferredPartID,
                @MaterialMoveType
            );

            SET @NewUID = SCOPE_IDENTITY();

            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'BOM Configuration',
                @NewUID,
                'Add Record',
                '',
                '',
                1,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus  = 1;

            SELECT @ResultMessage   AS ResultMessage,
                   @ResultStatus    AS ResultStatus,
                   @NewUID          AS NewUID;

        END

        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN

            DECLARE
                @OldSKUID             INT,
                @OldPartID            NVARCHAR(20),
                @OldPartDesc          NVARCHAR(300),
                @OldPartLevel         INT,
                @OldPartQuantity      INT,
                @OldParentID          NVARCHAR(20),
                @OldAlternatePartFlag INT,
                @OldStationID         INT,
                @OldPreferredPartID   NVARCHAR(20),
                @OldMaterialMoveType  INT;

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_BOM
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'Record not found';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            SELECT
                @OldSKUID             = SKUID,
                @OldPartID            = PartID,
                @OldPartDesc          = PartDesc,
                @OldPartLevel         = PartLevel,
                @OldPartQuantity      = PartQuantity,
                @OldParentID          = ParentID,
                @OldAlternatePartFlag = AlternatePartFlag,
                @OldStationID         = StationID,
                @OldPreferredPartID   = PreferredPartID,
                @OldMaterialMoveType  = MaterialMoveType
            FROM dbo.Config_BOM
            WHERE UID = @UID;

            UPDATE dbo.Config_BOM
            SET
                SKUID             = @SKUID,
                PartID            = @PartID,
                PartDesc          = @PartDesc,
                PartLevel         = @PartLevel,
                PartQuantity      = @PartQuantity,
                ParentID          = @ParentID,
                AlternatePartFlag = @AlternatePartFlag,
                StationID         = @StationID,
                PreferredPartID   = @PreferredPartID,
                MaterialMoveType  = @MaterialMoveType
            WHERE UID = @UID;

            IF ISNULL(@OldSKUID, 0) <> ISNULL(@SKUID, 0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'BOM Configuration', @UID,
                    'SKUID', @OldSKUID, @SKUID,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldPartID, '') <> ISNULL(@PartID, '')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'BOM Configuration', @UID,
                    'PartID', @OldPartID, @PartID,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldPartDesc, '') <> ISNULL(@PartDesc, '')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'BOM Configuration', @UID,
                    'PartDesc', @OldPartDesc, @PartDesc,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldPartLevel, 0) <> ISNULL(@PartLevel, 0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'BOM Configuration', @UID,
                    'PartLevel', @OldPartLevel, @PartLevel,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldPartQuantity, 0) <> ISNULL(@PartQuantity, 0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'BOM Configuration', @UID,
                    'PartQuantity', @OldPartQuantity, @PartQuantity,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldParentID, 0) <> ISNULL(@ParentID, 0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'BOM Configuration', @UID,
                    'ParentID', @OldParentID, @ParentID,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldAlternatePartFlag, 0) <> ISNULL(@AlternatePartFlag, 0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'BOM Configuration', @UID,
                    'AlternatePartFlag', @OldAlternatePartFlag, @AlternatePartFlag,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldStationID, 0) <> ISNULL(@StationID, 0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'BOM Configuration', @UID,
                    'StationID', @OldStationID, @StationID,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldPreferredPartID, '') <> ISNULL(@PreferredPartID, '')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'BOM Configuration', @UID,
                    'PreferredPartID', @OldPreferredPartID, @PreferredPartID,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldMaterialMoveType, 0) <> ISNULL(@MaterialMoveType, 0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'BOM Configuration', @UID,
                    'MaterialMoveType', @OldMaterialMoveType, @MaterialMoveType,
                    2, @Remark, @UserName
                );
            END

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus  = 1;

            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;

        END

        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_BOM
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'Record not found';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            DELETE
            FROM dbo.Config_BOM
            WHERE UID = @UID;

            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'BOM Configuration',
                @UID,
                'Delete Record',
                '',
                '',
                3,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus  = 1;

            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;

        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus  = 0;

        SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;

    END CATCH

END
