CREATE       PROCEDURE [dbo].[BT_Config_Department]
    @ResultMessage VARCHAR(MAX) OUTPUT,   -- ERROR HANDLING STORED IN THIS OUTPUT VARIABLE
    @ResultStatus INT OUTPUT,             -- 0 = ERROR(RED) , 1=SUCCESS(GREEN)
    @Mode INT,                            -- 1 = ADD, 2 = UPDATE, 3 = DELETE

    /*ADD PARAMETERS RELATED TO THE GRAPHWORX SCREEN*/
    @DepartmentID INT,                       -- PRIMARY KEY OF TABLE
    @DepartmentName NVARCHAR(100),
	@DepartmentDesc NVARCHAR(300),

    @Remark NVARCHAR(300) = NULL,        -- ON UPDATE/DELETE USER ENTERS REMARK FROM GRAPHWORX SCREEN
    @UserName NVARCHAR(100)              -- USER ID/NAME IS PASSED FROM THE GRAPHWORX SCREEN 
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        
        -- COMMON VALIDATION
        -- CHECKS WHETHER MODE IS VALID OR NOT
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        /*CHANGE PARAMETER NAME AND FIELD NAME IN THE MESSAGE*/ 
        -- CHECK PRIMARY KEY SHOULD NOT BE NULL
        IF @DepartmentID IS NULL
        BEGIN
	            SET @ResultMessage = 'Department ID is required';
				SET @ResultStatus = 0;
				SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	            RETURN;
	        END

        -- VALIDATION FOR INSERT / UPDATE ONLY
        IF @Mode IN (1,2)
        BEGIN

        IF (
                   ISNULL(@DepartmentID, 0) = 0
               
                OR ISNULL(LTRIM(RTRIM(@DepartmentName)), '') = ''
               )
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT
                    @ResultMessage AS ResultMessage,
                    @ResultStatus AS ResultStatus;

                RETURN;
            END


            /*CHANGE PARAMETER NAME AND FIELD NAME IN THE MESSAGE*/
            /*ADD ALL THE FIELDS WHICH ARE NOT NULL*/
            -- REQUIRED FIELD VALIDATION
           IF @DepartmentName IS NULL OR LTRIM(RTRIM(@DepartmentName)) = '' 
            BEGIN
	                SET @ResultMessage = 'Department Name is required';
					SET @ResultStatus = 0;
				SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	                RETURN;
            END

            IF @DepartmentDesc IS NULL OR LTRIM(RTRIM(@DepartmentDesc)) = ''
	        BEGIN
	            SET @ResultMessage = 'Department Description is required';
		        SET @ResultStatus = 0;
			    SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	            RETURN;
	        END

            /*CHANGE PARAMETER NAME AND FIELD NAME IN THE MESSAGE*/
            /*ADD ALL THE FIELDS WHICH REQUIRES CHARACTER LENGTH VALIDATION*/
            /*USE THIS EXCEPTION HANDLING ONLY FOR FIELDS WITH STRING DATATYPE*/

            -- LENGTH VALIDATION
            IF LEN(@DepartmentName) > 100
	            BEGIN
	                
	                SET @ResultMessage = 'Department Name exceeds max length (100)';
					SET @ResultStatus = 0;
					SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
					RETURN;
	            END

            -- LENGTH VALIDATION FOR DESCRIPTION FIELD
            IF LEN(ISNULL(@DepartmentDesc,'')) > 300
	            BEGIN
	                SET @ResultMessage = 'Department Description exceeds max length (300)';
					SET @ResultStatus = 0;
					SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	                RETURN;
	            END
        END

        -- INSERT MODE
        IF @Mode = 1
        BEGIN
            /*RENAME TABLE COLUMN AND PARAMETERS NAME */

            -- CHECKS IF RECORD ALREADY EXISTS
            IF EXISTS (SELECT 1 FROM Config_Department WHERE DepartmentID = @DepartmentID)
	            BEGIN
	                SET @ResultMessage = 'Department details already exists';
					SET @ResultStatus = 0;
					SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
					RETURN;
	            END

            /*RENAME TABLE COLUMN AND PARAMETERS NAME */

            -- INSERT NEW RECORD
            INSERT INTO Config_Department
	            (
	                DepartmentName,
	                DepartmentDesc
	            )
	            VALUES
	            (
	                @DepartmentName,
	                @DepartmentDesc
	            );

            -- INSERT HISTORY FOR ADD OPERATION
            INSERT INTO Config_History (TimeStamp, ScreenName, PrimaryKeyValue, FieldName, OldValue, NewValue, Status, Remark, UpdatedBy)
            VALUES (GETDATE(), 'Department Configuration', @DepartmentID, 'Add Record', ' ', ' ', 1, @Remark, @UserName);
	            

            -- SUCCESS MESSAGE
            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

        -- UPDATE MODE
        ELSE IF @Mode = 2
        BEGIN
            /*DECLARE THE PARAMETERS TO STORE THE VALUE BEFORE UPDATE*/
             DECLARE @OldDepartmentID INT;
	         DECLARE @OldDepartmentName VARCHAR(100);
	         DECLARE @OldDepartmentDesc VARCHAR(300);

            /*RENAME TABLE COLUMN AND PARAMETERS NAME */

            -- CHECK IF RECORD EXISTS
            IF NOT EXISTS (SELECT 1 FROM Config_Department WHERE DepartmentID = @DepartmentID)
	    BEGIN
	        SET @ResultMessage = 'Department details not found';
	        SET @ResultStatus = 0;
			SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	        RETURN;
	    END

            /*RENAME THE DECLARED PARAMETERS AS PER YOUR PARAMETERS DECLARED ABOVE */

            -- GET OLD VALUES
            SELECT
	        @OldDepartmentID = DepartmentID,
	        @OldDepartmentName = DepartmentName,
	        @OldDepartmentDesc = DepartmentDesc
	    FROM Config_Department
	    WHERE DepartmentID = @DepartmentID;

            /*RENAME AND ADD THE PARAMETERS AS PER YOUR TABLE*/

            -- UPDATE ONLY CHANGED VALUES
            UPDATE Config_Department
	    SET
	        
	
	        DepartmentName = CASE 
	                    WHEN ISNULL(DepartmentName,'') <> ISNULL(@DepartmentName,'') 
	                    THEN @DepartmentName 
	                    ELSE DepartmentName 
	                  END,
	
	        DepartmentDesc = CASE 
	                    WHEN ISNULL(DepartmentDesc,'') <> ISNULL(@DepartmentDesc,'') 
	                    THEN @DepartmentDesc 
	                    ELSE DepartmentDesc 
	                  END
	    WHERE DepartmentID = @DepartmentID;
	    

            /* BELOW INSERT STATEMENTS ARE USED TO MAINTAIN THE HISTORY BEFORE AND AFTER UPDATE FOR EACH COLUMN */

            -- DepartmentName History
		    /*RENAME AND ADD THE PARAMETERS AS PER YOUR TABLE*/
	    IF ISNULL(@OldDepartmentName,'') <> ISNULL(@DepartmentName,'')
	    BEGIN
	        INSERT INTO Config_History(TimeStamp,ScreenName,PrimaryKeyValue,FieldName,OldValue,NewValue,Status,Remark, UpdatedBy)
	        VALUES(GETDATE(),'Department Configuration',@DepartmentID,'DepartmentName',ISNULL(@OldDepartmentName,''),ISNULL(@DepartmentName,''),2,@Remark,@UserName);
	    END
	
	    -- DepartmentDesc History
		    /*RENAME AND ADD THE PARAMETERS AS PER YOUR TABLE*/
	    IF ISNULL(@OldDepartmentDesc,'') <> ISNULL(@DepartmentDesc,'')
	    BEGIN
	        INSERT INTO Config_History(TimeStamp,ScreenName,PrimaryKeyValue,FieldName,OldValue,NewValue,Status,Remark,UpdatedBy)
	        VALUES(GETDATE(),'Department Configuration',@DepartmentID,'DepartmentDesc',ISNULL(@OldDepartmentDesc,''),ISNULL(@DepartmentDesc,''),2,@Remark,@UserName);
	    END

            -- SUCCESS MESSAGE
            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END     

        -- DELETE MODE
        ELSE IF @Mode = 3
        BEGIN
            /*RENAME THE COLUMN NAME AND TABLE NAME */

            -- DELETE RECORD
            DELETE FROM Config_Department
	            WHERE DepartmentID = @DepartmentID;

            -- CHECK IF RECORD EXISTS
            IF @@ROWCOUNT = 0
	            BEGIN
	                SET @ResultMessage = 'Department details not found';
					SET @ResultStatus = 0;
					SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	                RETURN;
	            END

            /*RENAME AND ADD THE PARAMETERS AS PER YOUR TABLE*/

            -- INSERT DELETE HISTORY
            INSERT INTO Config_History (TimeStamp, ScreenName, PrimaryKeyValue, FieldName, OldValue, NewValue, Status, Remark, UpdatedBy)
                VALUES (GETDATE(), 'Department Configuration', @DepartmentID, 'Delete Record', ' ', ' ', 3, @Remark, @UserName);
	           
            -- SUCCESS MESSAGE
            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

    END TRY

    BEGIN CATCH
        -- ERROR HANDLING
	EXEC RethrowError;--If procedure fails to execute, the error message will be stored in SP_ERROR_LOG

        --SET @ResultMessage = ERROR_MESSAGE();-- ERROR HANDLING MESSAGE IS SET TO THE OUTPUT VARIABLE
        SET @ResultMessage = 'SQL ERROR';
        SET @ResultStatus = 0;
        SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
    END CATCH
END
GO

