CREATE       PROCEDURE [dbo].[BT_Config_Dropdown]
    @ResultMessage VARCHAR(MAX) OUTPUT,   -- ERROR HANDLING STORED IN THIS OUTPUT VARIABLE
    @ResultStatus INT OUTPUT,             -- 0 = ERROR(RED) , 1=SUCCESS(GREEN)
    @Mode INT,                            -- 1 = ADD, 2 = UPDATE, 3 = DELETE

    /*ADD PARAMETERS RELATED TO THE GRAPHWORX SCREEN*/
    --@UID INT,
    @TableName  NVARCHAR(100),
    @FieldName  NVARCHAR(100),
    @FieldValue INT,
    @FieldDesc  NVARCHAR(20)

AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        
        -- COMMON VALIDATION
        -- CHECKS WHETHER MODE IS VALID OR NOT
        IF @Mode NOT IN (1)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        -- VALIDATION FOR INSERT 
        IF @Mode IN (1)
        BEGIN

            -- REQUIRED FIELD VALIDATION
            IF (ISNULL(LTRIM(RTRIM(@FieldName)), '') = '' OR ISNULL(LTRIM(RTRIM(@FieldDesc)), '') = '')
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT
                    @ResultMessage AS ResultMessage,
                    @ResultStatus AS ResultStatus;

                RETURN;
            END

            /*CHANGE PARAMETER NAME AND FIELD NAME IN THE MESSAGE*/
            /*ADD ALL THE FIELDS WHICH REQUIRES CHARACTER LENGTH VALIDATION*/
            /*USE THIS EXCEPTION HANDLING ONLY FOR FIELDS WITH STRING DATATYPE*/

            -- LENGTH VALIDATION
            IF LEN(ISNULL(@FieldName,'')) > 100
	            BEGIN
	                
	                SET @ResultMessage = 'Field Name exceeds max length (100)';
					SET @ResultStatus = 0;
					SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
					RETURN;
	            END

            -- LENGTH VALIDATION
            IF LEN(ISNULL(@FieldDesc,'')) > 20
	            BEGIN
	                SET @ResultMessage = 'Field Description exceeds max length (20)';
					SET @ResultStatus = 0;
					SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	                RETURN;
	            END
        END

        -- INSERT MODE
        IF @Mode = 1
        BEGIN
            -- CHECKS IF RECORD ALREADY EXISTS
            IF EXISTS (SELECT 1 FROM Config_Dropdown WHERE TableName=@TableName AND FieldName=@FieldName AND FieldDesc=@FieldDesc)
	            BEGIN
	                SET @ResultMessage = 'Field details already exists';
					SET @ResultStatus = 0;
					SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
					RETURN;
	            END

            /*RENAME TABLE COLUMN AND PARAMETERS NAME */

            -- INSERT NEW RECORD
            INSERT INTO Config_Dropdown
	            (
                    TableName,
	                FieldName,
                    FieldValue,
	                FieldDesc
	            )
	            VALUES
	            (
                    @TableName,
	                @FieldName,
                    @FieldValue,
	                @FieldDesc
	            );

            -- SUCCESS MESSAGE
            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;
            --SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

    END TRY

    BEGIN CATCH
        -- ERROR HANDLING
	    EXEC RethrowError;--If procedure fails to execute, the error message will be stored in SP_ERROR_LOG

        --SET @ResultMessage = ERROR_MESSAGE();-- ERROR HANDLING MESSAGE IS SET TO THE OUTPUT VARIABLE
        SET @ResultMessage = 'SQL ERROR';
        SET @ResultStatus = 0;
        SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
    END CATCH
END
