-- ------------------------------------------------------------------------
-- [12/376] Stored Procedure: [dbo].[BT_Config_EnginePart]
-- Created: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 28-07-2026
-- Description : Add, Modify & Delete Engine Part Configuration
-- =============================================
CREATE       PROCEDURE [dbo].[BT_Config_EnginePart]

    @ResultMessage     NVARCHAR(MAX) OUTPUT,
    @ResultStatus      INT OUTPUT,
    @Mode              INT,

    @UID               INT = NULL,
    @EnginePartID      NVARCHAR(10) = NULL,
    @EnginePartDesc    NVARCHAR(300) = NULL,
    @EnginePartLevel   INT = NULL,

    @Remark            NVARCHAR(300) = NULL,
    @UserName          NVARCHAR(100)

AS
BEGIN

    SET NOCOUNT ON;

    BEGIN TRY

    ---------------------------------------------------------
    -- MODE VALIDATION
    ---------------------------------------------------------
    IF @Mode NOT IN (1,2,3)
    BEGIN
        SET @ResultMessage='Invalid Mode specified.';
        SET @ResultStatus=0;
        SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
        RETURN;
    END

    ---------------------------------------------------------
    -- UPDATE / DELETE VALIDATION
    ---------------------------------------------------------
    IF @Mode IN (2,3) AND ISNULL(@UID,0)=0
    BEGIN
        SET @ResultMessage='UID is required';
        SET @ResultStatus=0;
        SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
        RETURN;
    END

    ---------------------------------------------------------
    -- INSERT / UPDATE VALIDATION
    ---------------------------------------------------------
    IF @Mode IN (1,2)
    BEGIN

        IF ISNULL(LTRIM(RTRIM(@EnginePartID)),'')=''
           OR ISNULL(LTRIM(RTRIM(@EnginePartDesc)),'')=''
           OR @EnginePartLevel IS NULL
        BEGIN
            SET @ResultMessage='Fill all mandatory fields';
            SET @ResultStatus=0;
            SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
            RETURN;
        END

        IF LEN(@EnginePartID)>10
        BEGIN
            SET @ResultMessage='EnginePartID exceeds max length (10)';
            SET @ResultStatus=0;
            SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
            RETURN;
        END

        IF LEN(@EnginePartDesc)>300
        BEGIN
            SET @ResultMessage='EnginePartDesc exceeds max length (300)';
            SET @ResultStatus=0;
            SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
            RETURN;
        END

        -- Duplicate Check
        IF EXISTS
        (
            SELECT 1
            FROM dbo.Config_EnginePart
            WHERE EnginePartID=@EnginePartID
            AND (@Mode=1 OR UID<>@UID)
        )
        BEGIN
            SET @ResultMessage='EnginePartID already exists';
            SET @ResultStatus=0;
            SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
            RETURN;
        END

    END

    ---------------------------------------------------------
    -- INSERT
    ---------------------------------------------------------
    IF @Mode=1
    BEGIN

        INSERT INTO dbo.Config_EnginePart
        (
            EnginePartID,
            EnginePartDesc,
            EnginePartLevel
        )
        VALUES
        (
            @EnginePartID,
            @EnginePartDesc,
            @EnginePartLevel
        );

        SET @UID=SCOPE_IDENTITY();

        INSERT INTO dbo.Config_History
        (
            TimeStamp,
            ScreenName,
            PrimaryKeyValue,
            FieldName,
            OldValue,
            NewValue,
            Status,
            Remark,
            UpdatedBy
        )
        VALUES
        (
            GETDATE(),
            'Engine Part Configuration',
            @UID,
            'Insert',
            '',
            '',
            1,
            @Remark,
            @UserName
        );

        SET @ResultMessage='Inserted Successfully';
        SET @ResultStatus=1;

        SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
        RETURN;

    END

    ---------------------------------------------------------
    -- UPDATE
    ---------------------------------------------------------
    ELSE IF @Mode=2
    BEGIN

        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Config_EnginePart
            WHERE UID=@UID
        )
        BEGIN
            SET @ResultMessage='UID not found';
            SET @ResultStatus=0;
            SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
            RETURN;
        END

        DECLARE
            @OldEnginePartID NVARCHAR(10),
            @OldEnginePartDesc NVARCHAR(300),
            @OldEnginePartLevel INT;

        SELECT
            @OldEnginePartID=EnginePartID,
            @OldEnginePartDesc=EnginePartDesc,
            @OldEnginePartLevel=EnginePartLevel
        FROM dbo.Config_EnginePart
        WHERE UID=@UID;

        UPDATE dbo.Config_EnginePart
        SET
            EnginePartID=@EnginePartID,
            EnginePartDesc=@EnginePartDesc,
            EnginePartLevel=@EnginePartLevel
        WHERE UID=@UID;

        IF ISNULL(@OldEnginePartID,'')<>ISNULL(@EnginePartID,'')
        INSERT INTO dbo.Config_History
        VALUES
        (
            GETDATE(),
            'Engine Part Configuration',
            @UID,
            'EnginePartID',
            @OldEnginePartID,
            @EnginePartID,
            2,
            @Remark,
            @UserName
        );

        IF ISNULL(@OldEnginePartDesc,'')<>ISNULL(@EnginePartDesc,'')
        INSERT INTO dbo.Config_History
        VALUES
        (
            GETDATE(),
            'Engine Part Configuration',
            @UID,
            'EnginePartDesc',
            @OldEnginePartDesc,
            @EnginePartDesc,
            2,
            @Remark,
            @UserName
        );

        IF ISNULL(@OldEnginePartLevel,0)<>ISNULL(@EnginePartLevel,0)
        INSERT INTO dbo.Config_History
        VALUES
        (
            GETDATE(),
            'Engine Part Configuration',
            @UID,
            'EnginePartLevel',
            @OldEnginePartLevel,
            @EnginePartLevel,
            2,
            @Remark,
            @UserName
        );

        SET @ResultMessage='Updated Successfully';
        SET @ResultStatus=1;

        SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
        RETURN;

    END

    ---------------------------------------------------------
    -- DELETE
    ---------------------------------------------------------
    ELSE IF @Mode=3
    BEGIN

        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Config_EnginePart
            WHERE UID=@UID
        )
        BEGIN
            SET @ResultMessage='UID not found';
            SET @ResultStatus=0;
            SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
            RETURN;
        END

        DELETE FROM dbo.Config_EnginePart
        WHERE UID=@UID;

        INSERT INTO dbo.Config_History
        (
            TimeStamp,
            ScreenName,
            PrimaryKeyValue,
            FieldName,
            OldValue,
            NewValue,
            Status,
            Remark,
            UpdatedBy
        )
        VALUES
        (
            GETDATE(),
            'Engine Part Configuration',
            @UID,
            'Delete',
            '',
            '',
            3,
            @Remark,
            @UserName
        );

        SET @ResultMessage='Deleted Successfully';
        SET @ResultStatus=1;

        SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
        RETURN;

    END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage='SQL ERROR';
        SET @ResultStatus=0;

        SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
        RETURN;

    END CATCH

END
GO

