-- [13/376] Stored Procedure: [dbo].[BT_Config_Equipment]
-- Created: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 26-04-2026
-- Description : Procedure for Add, Modify & Delete Buttons. Also handles data moving to history & exception handling.
-- =============================================

--***************************************************************
--Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION            |
-----------------------------------------------------------
--| 26-04-2026 | Sumit      | CREATE OR ALTER OR ALTERd                |
--| 07-04-2026 | Sumit      | Standardized fixes     |
--| 18-05-2026 | Sumit      | Duplicate record condition is added|
-----------------------------------------------------------
--***************************************************************/
CREATE       PROCEDURE [dbo].[BT_Config_Equipment]
    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,

    @EquipmentID INT,
    @EquipmentName NVARCHAR(100),
    @EquipmentDesc NVARCHAR(300),
    @StationID INT,
    @EquipmentTypeID INT,

    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
           IF @Mode = 1
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.Config_Equipment WHERE EquipmentID = @EquipmentID)
            BEGIN
                SET @ResultMessage = 'Equipment ID already exists';
                SET @ResultStatus = 0;
                RETURN;
            END
            END
        
        
        
        IF @Mode IN (1,2)
        BEGIN
        IF (
                   ISNULL(LTRIM(RTRIM(@EquipmentName)), '') = ''
                   OR ISNULL(LTRIM(RTRIM(@EquipmentID)), 0) = 0
                   OR ISNULL(LTRIM(RTRIM(@EquipmentTypeID)),0)=0
                   OR ISNULL(LTRIM(RTRIM(@StationID)),0)=0
                  
               )
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
            IF @EquipmentName IS NULL
               OR LTRIM(RTRIM(@EquipmentName)) = ''
            BEGIN
                SET @ResultMessage = 'Equipment Name is required';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            --IF @EquipmentDesc IS NULL
           --    OR LTRIM(RTRIM(@EquipmentDesc)) = ''
            --BEGIN
             --   SET @ResultMessage = 'Equipment Description is required';
              --  SET @ResultStatus = 0;

               -- SELECT @ResultMessage AS ResultMessage,
                      -- @ResultStatus AS ResultStatus;
                --RETURN;
           -- END

            IF @StationID IS NULL OR @StationID = 0
            BEGIN
                SET @ResultMessage = 'Station is required';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF @EquipmentTypeID IS NULL OR @EquipmentTypeID = 0
            BEGIN
                SET @ResultMessage = 'Equipment Type is required';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(@EquipmentName) > 100
            BEGIN
                SET @ResultMessage = 'Equipment Name exceeds max length (100)';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(ISNULL(@EquipmentDesc,'')) > 300
            BEGIN
                SET @ResultMessage = 'Equipment Description exceeds max length (300)';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
        END

        -------------------------------------------------
        -- UPDATE / DELETE VALIDATION
        -------------------------------------------------
        IF @Mode IN (2,3)
        BEGIN
            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_Equipment
                WHERE EquipmentID = @EquipmentID
            )
            BEGIN
                SET @ResultMessage = 'Equipment ID not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
        END

        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN

            INSERT INTO dbo.Config_Equipment
            (
                EquipmentName,
                EquipmentDesc,
                StationID,
                EquipmentTypeID
            )
            VALUES
            (
                @EquipmentName,
                @EquipmentDesc,
                @StationID,
                @EquipmentTypeID
            );

            SET @EquipmentID = SCOPE_IDENTITY();

            INSERT INTO dbo.Config_History
            VALUES
            (
                GETDATE(),
                'Equipment Configuration',
                @EquipmentID,
                'Add Record',
                ' ',
                ' ',
                1,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus,
                   @EquipmentID AS EquipmentID;
        END

        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN

            DECLARE
                @OldEquipmentName NVARCHAR(100),
                @OldEquipmentDesc NVARCHAR(300),
                @OldStationID INT,
                @OldEquipmentTypeID INT;

            SELECT
                @OldEquipmentName = EquipmentName,
                @OldEquipmentDesc = EquipmentDesc,
                @OldStationID = StationID,
                @OldEquipmentTypeID = EquipmentTypeID
            FROM dbo.Config_Equipment
            WHERE EquipmentID = @EquipmentID;

            UPDATE dbo.Config_Equipment
            SET
                EquipmentName = @EquipmentName,
                EquipmentDesc = @EquipmentDesc,
                StationID = @StationID,
                EquipmentTypeID = @EquipmentTypeID
            WHERE EquipmentID = @EquipmentID;

            IF ISNULL(@OldEquipmentName,'') <> ISNULL(@EquipmentName,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Equipment Configuration',
                    @EquipmentID,
                    'EquipmentName',
                    @OldEquipmentName,
                    @EquipmentName,
                    2,
                    @Remark,
                    @UserName
                );
            END

            IF ISNULL(@OldEquipmentDesc,'') <> ISNULL(@EquipmentDesc,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Equipment Configuration',
                    @EquipmentID,
                    'EquipmentDesc',
                    @OldEquipmentDesc,
                    @EquipmentDesc,
                    2,
                    @Remark,
                    @UserName
                );
            END

            IF ISNULL(@OldStationID,0) <> ISNULL(@StationID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Equipment Configuration',
                    @EquipmentID,
                    'StationID',
                    @OldStationID,
                    @StationID,
                    2,
                    @Remark,
                    @UserName
                );
            END

            IF ISNULL(@OldEquipmentTypeID,0) <> ISNULL(@EquipmentTypeID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Equipment Configuration',
                    @EquipmentID,
                    'EquipmentTypeID',
                    @OldEquipmentTypeID,
                    @EquipmentTypeID,
                    2,
                    @Remark,
                    @UserName
                );
            END

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN

            DELETE FROM dbo.Config_Equipment
            WHERE EquipmentID = @EquipmentID;

            INSERT INTO dbo.Config_History
            VALUES
            (
                GETDATE(),
                'Equipment Configuration',
                @EquipmentID,
                'Delete Record',
                ' ',
                ' ',
                3,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END CATCH
END
