-- [14/376] Stored Procedure: [dbo].[BT_Config_Equipment_Part]
-- Created: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 23-04-2026
-- Description : Procedure for Add, Modify & Delete Buttons
-- =============================================

--***************************************************************
--Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION            |
-----------------------------------------------------------
--| 26-04-2026 | Sumit      | CREATE OR ALTER OR ALTERd                |
--| 30-04-2026 | Sumit      | Standardized fixes     |
--| 06-05-2026 | Sumit      | changed screen name and error message to sql error   |
--| 18-05-2026 | Sumit      | Duplicate record condition related changes    |
-----------------------------------------------------------
--***************************************************************/

CREATE         PROCEDURE [dbo].[BT_Config_Equipment_Part]
    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,

    @EquipmentPartID INT,
    @EquipmentPartName NVARCHAR(100),
    @EquipmentPartDesc NVARCHAR(300),
    @EquipmentID INT,
    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        
        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF @EquipmentPartID IS NULL
        BEGIN
            SET @ResultMessage = 'EquipmentPartID is required';
            SET @ResultStatus = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode IN (1,2)
        BEGIN
         IF (
                   ISNULL(LTRIM(RTRIM(@EquipmentPartName)), '') = ''
                   OR ISNULL(LTRIM(RTRIM(@EquipmentID)), 0) = 0
                   
                  
               )
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
            IF @EquipmentPartName IS NULL OR LTRIM(RTRIM(@EquipmentPartName)) = ''
            BEGIN
                SET @ResultMessage = 'EquipmentPart Name is required';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            -- ✅ FIXED INT validation
            IF @EquipmentID IS NULL OR @EquipmentID = 0
            BEGIN
                SET @ResultMessage = 'EquipmentID is required';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(@EquipmentPartName) > 100
            BEGIN
                SET @ResultMessage = 'EquipmentPart Name exceeds max length (100)';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(ISNULL(@EquipmentPartDesc,'')) > 300
            BEGIN
                SET @ResultMessage = 'EquipmentPart Description exceeds max length (300)';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END
        END

        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.Config_Equipment_Part WHERE EquipmentPartID = @EquipmentPartID)
            BEGIN
                SET @ResultMessage = 'EquipmentPartID already exists';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            INSERT INTO dbo.Config_Equipment_Part
            (
                EquipmentID,
                EquipmentPartName,
                EquipmentPartDesc
            )
            VALUES
            (
                @EquipmentID,
                @EquipmentPartName,
                @EquipmentPartDesc
            );

            INSERT INTO dbo.Config_History
            VALUES (GETDATE(),'Equipment Part Configuration',@EquipmentPartID,'Add Record',' ',' ',1,@Remark,@UserName);

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN
            DECLARE 
                @OldEquipmentPartName NVARCHAR(100),
                @OldEquipmentPartDesc NVARCHAR(300),
                @OldEquipmentID INT;

            IF NOT EXISTS (SELECT 1 FROM dbo.Config_Equipment_Part WHERE EquipmentPartID = @EquipmentPartID)
            BEGIN
                SET @ResultMessage = 'EquipmentPartID not found';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            SELECT
                @OldEquipmentPartName = EquipmentPartName,
                @OldEquipmentPartDesc = EquipmentPartDesc,
                @OldEquipmentID = EquipmentID
            FROM dbo.Config_Equipment_Part
            WHERE EquipmentPartID = @EquipmentPartID;

            UPDATE dbo.Config_Equipment_Part
            SET
                EquipmentPartName = CASE WHEN ISNULL(EquipmentPartName,'') <> ISNULL(@EquipmentPartName,'') THEN @EquipmentPartName ELSE EquipmentPartName END,
                EquipmentPartDesc = CASE WHEN ISNULL(EquipmentPartDesc,'') <> ISNULL(@EquipmentPartDesc,'') THEN @EquipmentPartDesc ELSE EquipmentPartDesc END,
                EquipmentID = CASE WHEN ISNULL(EquipmentID,0) <> ISNULL(@EquipmentID,0) THEN @EquipmentID ELSE EquipmentID END
            WHERE EquipmentPartID = @EquipmentPartID;

            IF ISNULL(@OldEquipmentPartName,'') <> ISNULL(@EquipmentPartName,'')
                INSERT INTO dbo.Config_History VALUES(GETDATE(),'Equipment Part Configuration',@EquipmentPartID,'EquipmentPartName',@OldEquipmentPartName,@EquipmentPartName,2,@Remark,@UserName);

            IF ISNULL(@OldEquipmentPartDesc,'') <> ISNULL(@EquipmentPartDesc,'')
                INSERT INTO dbo.Config_History VALUES(GETDATE(),'Equipment Part Configuration',@EquipmentPartID,'EquipmentPartDesc',@OldEquipmentPartDesc,@EquipmentPartDesc,2,@Remark,@UserName);

            IF ISNULL(@OldEquipmentID,0) <> ISNULL(@EquipmentID,0)
                INSERT INTO dbo.Config_History VALUES(GETDATE(),'Equipment Part Configuration',@EquipmentPartID,'EquipmentID',@OldEquipmentID,@EquipmentID,2,@Remark,@UserName);

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END     

        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN
            DELETE FROM dbo.Config_Equipment_Part
            WHERE EquipmentPartID = @EquipmentPartID;

            IF @@ROWCOUNT = 0
            BEGIN
                SET @ResultMessage = 'EquipmentPartID not found';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            INSERT INTO dbo.Config_History
            VALUES (GETDATE(),'Equipment Part Configuration',@EquipmentPartID,'Delete Record',' ',' ',3,@Remark,@UserName);

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

    END TRY

    BEGIN CATCH
        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;
        SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
    END CATCH
END
GO

