--|            |            | soft insert pattern         |
-----------------------------------------------------------
--*************************************************************************

CREATE       PROCEDURE [dbo].[BT_Config_FQC_EngInbuiltAuditPoint]

    @ResultMessage  NVARCHAR(MAX)    OUTPUT,
    @ResultStatus   INT             OUTPUT,
    @Mode           INT,

    @UID            INT             = NULL,
    @AuditListID    INT             = NULL,
    @AuditPointId   INT             = NULL,
    @AuditPointName NVARCHAR(100)   = NULL,
    @LowerLimit     DECIMAL(5,2)    = NULL,
    @UpperLimit     DECIMAL(5,2)    = NULL,
    @CheckingMethod NVARCHAR(100)   = NULL,
    @Status         INT             = 1,
    @Revision       INT             = NULL,
    @DocumentID     INT             = NULL,

    @Remark         NVARCHAR(300)   = NULL,
    @UserName       NVARCHAR(100)

AS
BEGIN

    SET NOCOUNT ON;

    BEGIN TRY

        -- =============================================
        -- MODE VALIDATION
        -- =============================================

        IF @Mode NOT IN (1, 2, 3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus  = 0;
           
            RETURN;
        END

        -- =============================================
        -- DELETE VALIDATION
        -- =============================================

        IF @Mode = 3
        BEGIN
            IF ISNULL(@UID, 0) = 0
            BEGIN
                SET @ResultMessage = 'UID is required';
                SET @ResultStatus  = 0;
                
                RETURN;
            END
        END

        -- =============================================
        -- INSERT / UPDATE VALIDATION
        -- =============================================

        IF @Mode IN (1, 2)
        BEGIN

            IF (
                ISNULL(@AuditListID,  0) = 0
                OR ISNULL(@AuditPointId, 0) = 0
                OR ISNULL(LTRIM(RTRIM(@AuditPointName)), '') = ''
                OR ISNULL(@LowerLimit, 0) = 0
                OR ISNULL(@UpperLimit, 0) = 0
                OR ISNULL(LTRIM(RTRIM(@CheckingMethod)), '') = ''
                OR ISNULL(@Status,   0) = 0
                OR ISNULL(@Revision, 0) = 0
            )
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus  = 0;
               
                RETURN;
            END

            -- ✅ NULL guard added
            IF @LowerLimit IS NOT NULL AND @UpperLimit IS NOT NULL
            BEGIN
                IF @LowerLimit > @UpperLimit
                BEGIN
                    SET @ResultMessage = 'Lower Limit cannot be greater than Upper Limit';
                    SET @ResultStatus  = 0;
                   
                    RETURN;
                END
            END

            IF @Status NOT IN (1, 2)
            BEGIN
                SET @ResultMessage = 'Invalid Status value';
                SET @ResultStatus  = 0;
                
                RETURN;
            END

        END

        -- =============================================
        -- DOCUMENT REVISION CALCULATION
        -- =============================================

        DECLARE @DocumentNumber NVARCHAR(50);
        SET @DocumentNumber = (
            SELECT DISTINCT DocumentNo
            FROM Config_QADocumentList
            WHERE DocumentID = @DocumentID
        );

        DECLARE @NewRevision INT;
        SET @NewRevision = (
            SELECT MAX(Revision) + 1
            FROM Config_QADocumentList
            WHERE DocumentNo = @DocumentNumber
        );

        -- =============================================
        -- INSERT MODE (Add)
        -- =============================================

        IF @Mode = 1
        BEGIN

            -- DUPLICATE CHECK
            IF EXISTS
            (
                SELECT 1
                FROM dbo.Config_FQC_EngInbuiltAuditPoint
                WHERE AuditListID  = @AuditListID
                  AND AuditPointId = @AuditPointId
                  AND Status       = 1
            )
            BEGIN
                SET @ResultMessage = 'Record already exists';
                SET @ResultStatus  = 0;
                
                RETURN;
            END

            -- INSERT new row
            INSERT INTO dbo.Config_FQC_EngInbuiltAuditPoint
            (
                AuditListID,
                AuditPointId,
                AuditPointName,
                LowerLimit,
                UpperLimit,
                CheckingMethod,
                [Status],
                Revision
            )
            VALUES
            (
                @AuditListID,
                @AuditPointId,
                @AuditPointName,
                @LowerLimit,
                @UpperLimit,
                @CheckingMethod,
                @Status,
                @NewRevision
            );

            -- ✅ SCOPE_IDENTITY immediately after INSERT
            DECLARE @NewUID INT;
            SET @NewUID = SCOPE_IDENTITY();

            -- Update document revision
            UPDATE dbo.Config_QADocumentList
            SET    Revision = @NewRevision
            WHERE  DocumentID = @DocumentID;

            -- History log
            INSERT INTO dbo.Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(), 'FQC Eng Inbuilt Audit Point', @NewUID,
                'Insert', '', '',
                1, @Remark, @UserName
            );

            SET @ResultMessage = 'Inserted Successfully';
            SET @ResultStatus  = 1;
            RETURN;

        END

        -- =============================================
        -- MODIFY MODE
        -- Soft INSERT new row with updated values + @NewRevision
        -- =============================================

        ELSE IF @Mode = 2
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1 FROM dbo.Config_FQC_EngInbuiltAuditPoint
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'UID not found';
                SET @ResultStatus  = 0;
                
                RETURN;
            END

            -- INSERT new row with updated values and new revision
            INSERT INTO dbo.Config_FQC_EngInbuiltAuditPoint
            (
                AuditListID,
                AuditPointId,
                AuditPointName,
                LowerLimit,
                UpperLimit,
                CheckingMethod,
                [Status],
                Revision
            )
            VALUES
            (
                @AuditListID,
                @AuditPointId,
                @AuditPointName,
                @LowerLimit,
                @UpperLimit,
                @CheckingMethod,
                @Status,
                @NewRevision
            );

            DECLARE @ModifiedUID INT;
            SET @ModifiedUID = SCOPE_IDENTITY();

            -- Update document revision
            UPDATE dbo.Config_QADocumentList
            SET    Revision = @NewRevision
            WHERE  DocumentID = @DocumentID;

            -- History log
            INSERT INTO dbo.Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(), 'FQC Eng Inbuilt Audit Point', @ModifiedUID,
                'Modify', '', '',
                2, @Remark, @UserName
            );

            SET @ResultMessage = 'Updated Successfully';
            SET @ResultStatus  = 1;
            RETURN;

        END

        -- =============================================
        -- DELETE MODE
        -- Soft INSERT new row with Status=2 + @NewRevision
        -- =============================================

        ELSE IF @Mode = 3
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1 FROM dbo.Config_FQC_EngInbuiltAuditPoint
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'UID not found';
                SET @ResultStatus  = 0;
                RETURN;
                
            END

            -- Fetch existing row values to carry forward
            DECLARE @ExistingAuditListID    INT;
            DECLARE @ExistingAuditPointId   INT;
            DECLARE @ExistingAuditPointName NVARCHAR(100);
            DECLARE @ExistingLowerLimit     DECIMAL(5,2);
            DECLARE @ExistingUpperLimit     DECIMAL(5,2);
            DECLARE @ExistingCheckingMethod NVARCHAR(100);

            SELECT
                @ExistingAuditListID    = AuditListID,
                @ExistingAuditPointId   = AuditPointId,
                @ExistingAuditPointName = AuditPointName,
                @ExistingLowerLimit     = LowerLimit,
                @ExistingUpperLimit     = UpperLimit,
                @ExistingCheckingMethod = CheckingMethod
            FROM dbo.Config_FQC_EngInbuiltAuditPoint
            WHERE UID = @UID;

            -- INSERT new row as disabled (Status = 2)
            INSERT INTO dbo.Config_FQC_EngInbuiltAuditPoint
            (
                AuditListID,
                AuditPointId,
                AuditPointName,
                LowerLimit,
                UpperLimit,
                CheckingMethod,
                [Status],
                Revision
            )
            VALUES
            (
                @ExistingAuditListID,
                @ExistingAuditPointId,
                @ExistingAuditPointName,
                @ExistingLowerLimit,
                @ExistingUpperLimit,
                @ExistingCheckingMethod,
                2,              -- disabled
                @NewRevision
            );

            DECLARE @DeletedUID INT;
            SET @DeletedUID = SCOPE_IDENTITY();

            -- Update document revision
            UPDATE dbo.Config_QADocumentList
            SET    Revision = @NewRevision
            WHERE  DocumentID = @DocumentID;

            -- History log
            INSERT INTO dbo.Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(), 'FQC Eng Inbuilt Audit Point', @DeletedUID,
                'Delete', '', '',
                3, @Remark, @UserName
            );

            SET @ResultMessage = 'Deleted Successfully';
            SET @ResultStatus  = 1;
            RETURN;

        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL ERROR';
        SET @ResultStatus  = 0;
        RETURN;

    END CATCH

END
