            -- INSERT new row with updated values and new revision
            INSERT INTO Config_FQC_EngStripAuditPoint
            (
                AuditListID,
                AuditPointId,
                AuditPointName,
                LowerLimit,
                UpperLimit,
                Status,
                Revision
            )
            VALUES
            (
                @AuditListID,
                @AuditPointId,
                @AuditPointName,
                @LowerLimit,
                @UpperLimit,
                @Status,
                @NewRevision
            );

            DECLARE @ModifiedUID INT;
            SET @ModifiedUID = SCOPE_IDENTITY();

            -- Update document revision
            UPDATE Config_QADocumentList
            SET    Revision = @NewRevision
            WHERE  DocumentID = @DocumentID;

            -- History log
            INSERT INTO Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(), 'FQC Eng Strip Audit Point', @ModifiedUID,
                'Modify', '', '',
                2, @Remark, @UserName
            );

            SET @ResultMessage = 'Updated Successfully';
            SET @ResultStatus  = 1;
            RETURN;

        END

        -- =============================================
        -- DELETE MODE
        -- Soft INSERT new row with Status=2 + @NewRevision
        -- =============================================

        ELSE IF @Mode = 3
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1 FROM Config_FQC_EngStripAuditPoint
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'UID not found';
                SET @ResultStatus  = 0;
                RETURN;
                RETURN;
            END

            -- Fetch existing row values to carry forward
            DECLARE @ExistingAuditListID    INT;
            DECLARE @ExistingAuditPointId   INT;
            DECLARE @ExistingAuditPointName NVARCHAR(100);
            DECLARE @ExistingLowerLimit     DECIMAL(5,2);
            DECLARE @ExistingUpperLimit     DECIMAL(5,2);

            SELECT
                @ExistingAuditListID    = AuditListID,
                @ExistingAuditPointId   = AuditPointId,
                @ExistingAuditPointName = AuditPointName,
                @ExistingLowerLimit     = LowerLimit,
                @ExistingUpperLimit     = UpperLimit
            FROM Config_FQC_EngStripAuditPoint
            WHERE UID = @UID;

            -- INSERT new row as disabled (Status = 2)
            INSERT INTO Config_FQC_EngStripAuditPoint
            (
                AuditListID,
                AuditPointId,
                AuditPointName,
                LowerLimit,
                UpperLimit,
                Status,
                Revision
            )
            VALUES
            (
                @ExistingAuditListID,
                @ExistingAuditPointId,
                @ExistingAuditPointName,
                @ExistingLowerLimit,
                @ExistingUpperLimit,
                2,              -- disabled
                @NewRevision
            );

            DECLARE @DeletedUID INT;
            SET @DeletedUID = SCOPE_IDENTITY();

            -- Update document revision
            UPDATE Config_QADocumentList
            SET    Revision = @NewRevision
            WHERE  DocumentID = @DocumentID;

            -- History log
            INSERT INTO Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(), 'FQC Eng Strip Audit Point', @DeletedUID,
                'Delete', '', '',
                3, @Remark, @UserName
            );

            SET @ResultMessage = 'Deleted Successfully';
            SET @ResultStatus  = 1;
            RETURN;

        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL ERROR';
        SET @ResultStatus  = 0;
        RETURN;

    END CATCH

END
GO

-- ------------------------------------------------------------------------
-- [20/376] Stored Procedure: [dbo].[BT_Config_Inspection_Action]
-- Created: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 27-07-2026
-- Desc : Procedure for Add, Modify & Delete
--               Inspection Action Configuration.
-- =============================================

--*************************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | Description                |
-----------------------------------------------------------
--| 25-06-2026 | Sumit      | CREATE OR ALTER OR ALTERd                     |
--| 13-08-2026 | Sumit      | Added DefectID column;      |
--|            |            | duplicate check now scoped  |
--|            |            | by DefectID+ActionDesc      |
-----------------------------------------------------------
--*************************************************************************

CREATE       PROCEDURE [dbo].[BT_Config_Inspection_Action]

    @ResultMessage  NVARCHAR(MAX)   OUTPUT,
    @ResultStatus   INT             OUTPUT,
    @Mode           INT,

    @ActionID       INT             = NULL,
    @DefectID       INT             = NULL,
    @ActionDesc     NVARCHAR(100)   = NULL,

    @Remark         NVARCHAR(300)   = NULL,
    @UserName       NVARCHAR(100)

AS
BEGIN

    SET NOCOUNT ON;

    BEGIN TRY

        -- =============================================
        -- MODE VALIDATION
        -- =============================================

        IF @Mode NOT IN (1, 2, 3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus  = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        -- =============================================
        -- DELETE VALIDATION
        -- =============================================

        IF @Mode IN (2, 3) AND ISNULL(@ActionID, 0) = 0
        BEGIN
            SET @ResultMessage = 'ActionID is required';
            SET @ResultStatus  = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        -- =============================================
        -- INSERT / UPDATE VALIDATION
        -- =============================================

        IF @Mode IN (1, 2)
        BEGIN

            IF ISNULL(@DefectID, 0) = 0
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF ISNULL(LTRIM(RTRIM(@ActionDesc)), '') = ''
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(@ActionDesc) > 100
            BEGIN
                SET @ResultMessage = 'ActionDesc exceeds max length (100)';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            -- DUPLICATE CHECK
            -- Same ActionDesc is allowed to repeat under a different DefectID,
            -- so the check is scoped to DefectID + ActionDesc together.
            IF EXISTS
            (
                SELECT 1
                FROM dbo.Config_Inspection_Action
                WHERE DefectID   = @DefectID
                  AND ActionDesc = @ActionDesc
                  AND (@Mode = 1 OR ActionID <> @ActionID)
            )
            BEGIN
                SET @ResultMessage = 'ActionDesc already exists for this Defect';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

        END

        -- =============================================
        -- INSERT MODE
        -- =============================================

        IF @Mode = 1
        BEGIN

            INSERT INTO dbo.Config_Inspection_Action
            (
                DefectID,
                ActionDesc
            )
            VALUES
            (
                @DefectID,
                @ActionDesc
            );

            SET @ActionID = SCOPE_IDENTITY();

            INSERT INTO dbo.Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(), 'Inspection Action Configuration', @ActionID,
                'Insert', '', '',
                1, @Remark, @UserName
            );

            SET @ResultMessage = 'Inserted Successfully';
            SET @ResultStatus  = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;

        END

        -- =============================================
        -- UPDATE MODE
        -- =============================================

        ELSE IF @Mode = 2
        BEGIN

            DECLARE @OldActionDesc NVARCHAR(100);
            DECLARE @OldDefectID   INT;

            IF NOT EXISTS
            (
                SELECT 1 FROM dbo.Config_Inspection_Action
                WHERE ActionID = @ActionID
            )
            BEGIN
                SET @ResultMessage = 'ActionID not found';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            SELECT @OldActionDesc = ActionDesc,
                   @OldDefectID   = DefectID
            FROM dbo.Config_Inspection_Action
            WHERE ActionID = @ActionID;

            UPDATE dbo.Config_Inspection_Action
            SET ActionDesc = CASE
                                WHEN ISNULL(ActionDesc, '') <> ISNULL(@ActionDesc, '')
                                THEN @ActionDesc
                                ELSE ActionDesc
                              END,
                DefectID   = CASE
                                WHEN ISNULL(DefectID, 0) <> ISNULL(@DefectID, 0)
                                THEN @DefectID
                                ELSE DefectID
                              END
            WHERE ActionID = @ActionID;

            IF ISNULL(@OldActionDesc, '') <> ISNULL(@ActionDesc, '')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Inspection Action Configuration', @ActionID,
                    'ActionDesc', @OldActionDesc, @ActionDesc,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldDefectID, 0) <> ISNULL(@DefectID, 0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Inspection Action Configuration', @ActionID,
                    'DefectID', @OldDefectID, @DefectID,
                    2, @Remark, @UserName
                );
            END

            SET @ResultMessage = 'Updated Successfully';
            SET @ResultStatus  = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;

        END

        -- =============================================
        -- DELETE MODE
        -- =============================================

        ELSE IF @Mode = 3
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1 FROM dbo.Config_Inspection_Action
                WHERE ActionID = @ActionID
            )
            BEGIN
                SET @ResultMessage = 'ActionID not found';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            DELETE FROM dbo.Config_Inspection_Action
            WHERE ActionID = @ActionID;

            INSERT INTO dbo.Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(), 'Inspection Action Configuration', @ActionID,
                'Delete', '', '',
                3, @Remark, @UserName
            );

            SET @ResultMessage = 'Deleted Successfully';
            SET @ResultStatus  = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;

        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL ERROR';
        SET @ResultStatus  = 0;
        SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;

    END CATCH

END
GO

