-- [21/376] Stored Procedure: [dbo].[BT_Config_Inspection_Point]
-- Created: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 18-07-2026
-- Description : Procedure for Add, Modify & Delete Buttons
-- =============================================

--***************************************************************
--Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION                  |
-----------------------------------------------------------
--| 18-07-2026 | Sumit      | CREATE OR ALTER OR ALTERd                      |
-----------------------------------------------------------
--***************************************************************

CREATE      PROCEDURE [dbo].[BT_Config_Inspection_Point]

    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,

    @UID INT,

    @InspectionPointID INT,
    @InspectionStationID INT,
    @ModelFamilyID INT,
    @ModelID INT,
    @SKUID INT,
    @InspectionPointName NVARCHAR(100),
    @InspectionPointDes NVARCHAR(300),
    @InspectionPointType INT,
    @InspectionPointAction INT,

    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)

AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage='Invalid Mode specified.';
            SET @ResultStatus=0;
            SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
            RETURN;
        END

        IF @UID IS NULL
        BEGIN
            SET @ResultMessage='UID is required';
            SET @ResultStatus=0;
            SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
            RETURN;
        END

        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode IN (1,2)
        BEGIN
            IF
            (
                ISNULL(@InspectionStationID,0)=0 OR
                ISNULL(@ModelFamilyID,0)=0 OR
                ISNULL(@ModelID,0)=0 OR
                ISNULL(@SKUID,0)=0 OR
                ISNULL(LTRIM(RTRIM(@InspectionPointName)),'')='' OR
                ISNULL(@InspectionPointType,0)=0 OR
                ISNULL(@InspectionPointAction,0)=0
            )
            BEGIN
                SET @ResultMessage='Fill all mandatory fields';
                SET @ResultStatus=0;
                SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
                RETURN;
            END

            IF LEN(@InspectionPointName)>100
            BEGIN
                SET @ResultMessage='Inspection Point Name exceeds max length (100)';
                SET @ResultStatus=0;
                SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
                RETURN;
            END

            IF LEN(ISNULL(@InspectionPointDes,''))>300
            BEGIN
                SET @ResultMessage='Inspection Point Description exceeds max length (300)';
                SET @ResultStatus=0;
                SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
                RETURN;
            END
        END

        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode=1
        BEGIN
            IF EXISTS
            (
                SELECT 1
                FROM Config_Inspection_Point
                WHERE UID=@UID
            )
            BEGIN
                SET @ResultMessage='UID already exists';
                SET @ResultStatus=0;
                SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
                RETURN;
            END

            INSERT INTO Config_Inspection_Point
            (
                InspectionPointID,
                InspectionStationID,
                ModelFamilyID,
                ModelID,
                SKUID,
                InspectionPointName,
                InspectionPointDes,
                InspectionPointType,
                InspectionPointAction
            )
            VALUES
            (
                @InspectionPointID,
                @InspectionStationID,
                @ModelFamilyID,
                @ModelID,
                @SKUID,
                @InspectionPointName,
                @InspectionPointDes,
                @InspectionPointType,
                @InspectionPointAction
            );

            INSERT INTO Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Inspection Point Configuration',
                @UID,
                'Add Record',
                ' ',
                ' ',
                1,
                @Remark,
                @UserName
            );

            SET @ResultMessage='Inserted successfully';
            SET @ResultStatus=1;

            SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
        END

        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode=2
        BEGIN

            DECLARE
                @OldInspectionPointID INT,
                @OldInspectionStationID INT,
                @OldModelFamilyID INT,
                @OldModelID INT,
                @OldSKUID INT,
                @OldInspectionPointName NVARCHAR(100),
                @OldInspectionPointDes NVARCHAR(300),
                @OldInspectionPointType INT,
                @OldInspectionPointAction INT;

            IF NOT EXISTS
            (
                SELECT 1
                FROM Config_Inspection_Point
                WHERE UID=@UID
            )
            BEGIN
                SET @ResultMessage='UID not found';
                SET @ResultStatus=0;
                SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
                RETURN;
            END

            SELECT
                @OldInspectionPointID=InspectionPointID,
                @OldInspectionStationID=InspectionStationID,
                @OldModelFamilyID=ModelFamilyID,
                @OldModelID=ModelID,
                @OldSKUID=SKUID,
                @OldInspectionPointName=InspectionPointName,
                @OldInspectionPointDes=InspectionPointDes,
                @OldInspectionPointType=InspectionPointType,
                @OldInspectionPointAction=InspectionPointAction
            FROM Config_Inspection_Point
            WHERE UID=@UID;

            UPDATE Config_Inspection_Point
            SET
                InspectionPointID=CASE WHEN ISNULL(InspectionPointID,0)<>ISNULL(@InspectionPointID,0) THEN @InspectionPointID ELSE InspectionPointID END,
                InspectionStationID=CASE WHEN ISNULL(InspectionStationID,0)<>ISNULL(@InspectionStationID,0) THEN @InspectionStationID ELSE InspectionStationID END,
                ModelFamilyID=CASE WHEN ISNULL(ModelFamilyID,0)<>ISNULL(@ModelFamilyID,0) THEN @ModelFamilyID ELSE ModelFamilyID END,
                ModelID=CASE WHEN ISNULL(ModelID,0)<>ISNULL(@ModelID,0) THEN @ModelID ELSE ModelID END,
                SKUID=CASE WHEN ISNULL(SKUID,0)<>ISNULL(@SKUID,0) THEN @SKUID ELSE SKUID END,
                InspectionPointName=CASE WHEN ISNULL(InspectionPointName,'')<>ISNULL(@InspectionPointName,'') THEN @InspectionPointName ELSE InspectionPointName END,
                InspectionPointDes=CASE WHEN ISNULL(InspectionPointDes,'')<>ISNULL(@InspectionPointDes,'') THEN @InspectionPointDes ELSE InspectionPointDes END,
                InspectionPointType=CASE WHEN ISNULL(InspectionPointType,0)<>ISNULL(@InspectionPointType,0) THEN @InspectionPointType ELSE InspectionPointType END,
                InspectionPointAction=CASE WHEN ISNULL(InspectionPointAction,0)<>ISNULL(@InspectionPointAction,0) THEN @InspectionPointAction ELSE InspectionPointAction END
            WHERE UID=@UID;

            IF ISNULL(@OldInspectionPointID,0)<>ISNULL(@InspectionPointID,0)
                INSERT INTO Config_History VALUES(GETDATE(),'Inspection Point Configuration',@UID,'InspectionPointID',@OldInspectionPointID,@InspectionPointID,2,@Remark,@UserName);

            IF ISNULL(@OldInspectionStationID,0)<>ISNULL(@InspectionStationID,0)
                INSERT INTO Config_History VALUES(GETDATE(),'Inspection Point Configuration',@UID,'InspectionStationID',@OldInspectionStationID,@InspectionStationID,2,@Remark,@UserName);

            IF ISNULL(@OldModelFamilyID,0)<>ISNULL(@ModelFamilyID,0)
                INSERT INTO Config_History VALUES(GETDATE(),'Inspection Point Configuration',@UID,'ModelFamilyID',@OldModelFamilyID,@ModelFamilyID,2,@Remark,@UserName);

            IF ISNULL(@OldModelID,0)<>ISNULL(@ModelID,0)
                INSERT INTO Config_History VALUES(GETDATE(),'Inspection Point Configuration',@UID,'ModelID',@OldModelID,@ModelID,2,@Remark,@UserName);

            IF ISNULL(@OldSKUID,0)<>ISNULL(@SKUID,0)
                INSERT INTO Config_History VALUES(GETDATE(),'Inspection Point Configuration',@UID,'SKUID',@OldSKUID,@SKUID,2,@Remark,@UserName);

            IF ISNULL(@OldInspectionPointName,'')<>ISNULL(@InspectionPointName,'')
                INSERT INTO Config_History VALUES(GETDATE(),'Inspection Point Configuration',@UID,'InspectionPointName',@OldInspectionPointName,@InspectionPointName,2,@Remark,@UserName);

            IF ISNULL(@OldInspectionPointDes,'')<>ISNULL(@InspectionPointDes,'')
                INSERT INTO Config_History VALUES(GETDATE(),'Inspection Point Configuration',@UID,'InspectionPointDes',@OldInspectionPointDes,@InspectionPointDes,2,@Remark,@UserName);

            IF ISNULL(@OldInspectionPointType,0)<>ISNULL(@InspectionPointType,0)
                INSERT INTO Config_History VALUES(GETDATE(),'Inspection Point Configuration',@UID,'InspectionPointType',@OldInspectionPointType,@InspectionPointType,2,@Remark,@UserName);

            IF ISNULL(@OldInspectionPointAction,0)<>ISNULL(@InspectionPointAction,0)
                INSERT INTO Config_History VALUES(GETDATE(),'Inspection Point Configuration',@UID,'InspectionPointAction',@OldInspectionPointAction,@InspectionPointAction,2,@Remark,@UserName);

            SET @ResultMessage='Updated successfully';
            SET @ResultStatus=1;

            SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
        END

        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode=3
        BEGIN

            DELETE
            FROM Config_Inspection_Point
            WHERE UID=@UID;

            IF @@ROWCOUNT=0
            BEGIN
                SET @ResultMessage='UID not found';
                SET @ResultStatus=0;
                SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
                RETURN;
            END

            INSERT INTO Config_History
            VALUES
            (
                GETDATE(),
                'Inspection Point Configuration',
                @UID,
                'Delete Record',
                ' ',
                ' ',
                3,
                @Remark,
                @UserName
            );

            SET @ResultMessage='Deleted successfully';
            SET @ResultStatus=1;

            SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;
        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage='SQL Error';
        SET @ResultStatus=0;

        SELECT @ResultMessage ResultMessage,@ResultStatus ResultStatus;

    END CATCH
END
GO

