                ' ',
                1,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;

            SELECT 
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus,
                @UID AS UID;
        END

        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN

            DECLARE
                @OldDefectID INT,
                @OldDefectName NVARCHAR(100),
                --@OldModelFamilyID INT,
                --@OldModelID INT,
                --@OldSKUID INT,
                @OldInspectionPointID INT,
                @OldQAlertStation INT;

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_Inspection_Defect
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'Defect details not found';
                SET @ResultStatus = 0;

                SELECT 
                    @ResultMessage AS ResultMessage,
                    @ResultStatus AS ResultStatus;

                RETURN;
            END

            SELECT
                @OldDefectID = DefectID,
                @OldDefectName = DefectName,
                --@OldModelFamilyID = ModelFamilyID,
                --@OldModelID = ModelID,
                --@OldSKUID = SKUID,
                @OldInspectionPointID = InspectionPointID,
                @OldQAlertStation = QAlertStation
            FROM dbo.Config_Inspection_Defect
            WHERE UID = @UID;

            UPDATE dbo.Config_Inspection_Defect
            SET
                DefectID =
                    CASE WHEN ISNULL(DefectID,0) <> ISNULL(@DefectID,0)
                         THEN @DefectID ELSE DefectID END,

                DefectName =
                    CASE WHEN ISNULL(DefectName,'') <> ISNULL(@DefectName,'')
                         THEN @DefectName ELSE DefectName END,


                InspectionPointID =
                    CASE WHEN ISNULL(InspectionPointID,0) <> ISNULL(@InspectionPointID,0)
                         THEN @InspectionPointID ELSE InspectionPointID END,

                QAlertStation =
                    CASE WHEN ISNULL(QAlertStation,0) <> ISNULL(@QAlertStation,0)
                         THEN @QAlertStation ELSE QAlertStation END

            WHERE UID = @UID;

            IF ISNULL(@OldDefectID,0) <> ISNULL(@DefectID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (GETDATE(), 'Inspection Defect Configuration', @UID, 'DefectID',
                 @OldDefectID, @DefectID, 2, @Remark, @UserName);
            END

            IF ISNULL(@OldDefectName,'') <> ISNULL(@DefectName,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (GETDATE(), 'Inspection Defect Configuration', @UID, 'DefectName',
                 @OldDefectName, @DefectName, 2, @Remark, @UserName);
            END

            

            IF ISNULL(@OldInspectionPointID,0) <> ISNULL(@InspectionPointID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (GETDATE(), 'Inspection Defect Configuration', @UID, 'InspectionPointID',
                 @OldInspectionPointID, @InspectionPointID, 2, @Remark, @UserName);
            END

            IF ISNULL(@OldQAlertStation,0) <> ISNULL(@QAlertStation,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (GETDATE(), 'Inspection Defect Configuration', @UID, 'QAlertStation',
                 @OldQAlertStation, @QAlertStation, 2, @Remark, @UserName);
            END

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;

            SELECT 
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

        END

        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN

            DELETE FROM dbo.Config_Inspection_Defect
            WHERE UID = @UID;

            IF @@ROWCOUNT = 0
            BEGIN
                SET @ResultMessage = 'Defect Details not found';
                SET @ResultStatus = 0;

                SELECT 
                    @ResultMessage AS ResultMessage,
                    @ResultStatus AS ResultStatus;

                RETURN;
            END

            INSERT INTO dbo.Config_History
            VALUES
            (
                GETDATE(),
                'Inspection Defect Configuration',
                @UID,
                'Delete Record',
                ' ',
                ' ',
                3,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;

            SELECT 
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;

        SELECT
            @ResultMessage AS ResultMessage,
            @ResultStatus AS ResultStatus;
    END CATCH
END
GO

-- ------------------------------------------------------------------------
-- [23/376] Stored Procedure: [dbo].[BT_Config_InspectionStation]
-- Created: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE       PROCEDURE [dbo].[BT_Config_InspectionStation]

    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,

    @InspectionStationID INT,
    @StationID INT,
    @InspectionStationName NVARCHAR(100),
    @InspectionStationDesc NVARCHAR(300),

    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)

AS
BEGIN

    SET NOCOUNT ON;

    BEGIN TRY

        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------

        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified';
            SET @ResultStatus = 0;

            SELECT
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

            RETURN;
        END

        IF @InspectionStationID IS NULL
        BEGIN
            SET @ResultMessage = 'Inspection Station ID is required';
            SET @ResultStatus = 0;

            SELECT
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

            RETURN;
        END

        -------------------------------------------------
        -- INSERT VALIDATION ONLY
        -------------------------------------------------

        IF @Mode = 1
        BEGIN
            IF (
                   ISNULL(LTRIM(RTRIM(@StationID)),0) = 0
                OR ISNULL(LTRIM(RTRIM(@InspectionStationName)), '') = ''
                OR ISNULL(LTRIM(RTRIM(@InspectionStationDesc)), '') = ''
               )
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            --IF ISNULL(@StationID,0) = 0
            --BEGIN
            --    SET @ResultMessage = 'Station Name is required';
            --    SET @ResultStatus = 0;

            --    SELECT
            --        @ResultMessage AS ResultMessage,
            --        @ResultStatus AS ResultStatus;

            --    RETURN;
            --END

            --IF ISNULL(LTRIM(RTRIM(@InspectionStationName)),'') = ''
            --BEGIN
            --    SET @ResultMessage = 'Inspection Station Name is required';
            --    SET @ResultStatus = 0;

            --    SELECT
            --        @ResultMessage AS ResultMessage,
            --        @ResultStatus AS ResultStatus;

            --    RETURN;
            --END

            --IF ISNULL(LTRIM(RTRIM(@InspectionStationDesc)),'') = ''
            --BEGIN
            --    SET @ResultMessage = 'Inspection Station Description is required';
            --    SET @ResultStatus = 0;

            --    SELECT
            --        @ResultMessage AS ResultMessage,
            --        @ResultStatus AS ResultStatus;

            --    RETURN;
            --END

            IF LEN(@InspectionStationName) > 100
            BEGIN
                SET @ResultMessage = 'Inspection Station Name exceeds max length (100)';
                SET @ResultStatus = 0;

                SELECT
                    @ResultMessage AS ResultMessage,
                    @ResultStatus AS ResultStatus;

                RETURN;
            END

            IF LEN(ISNULL(@InspectionStationDesc,'')) > 300
            BEGIN
                SET @ResultMessage = 'Inspection Station Description exceeds max length (300)';
                SET @ResultStatus = 0;

                SELECT
                    @ResultMessage AS ResultMessage,
                    @ResultStatus AS ResultStatus;

                RETURN;
            END

        END

        -------------------------------------------------
        -- INSERT
        -------------------------------------------------

        IF @Mode = 1
        BEGIN

            IF EXISTS
            (
                SELECT 1
                FROM dbo.Config_Inspection_Station
                WHERE InspectionStationID = @InspectionStationID
            )
            BEGIN
                SET @ResultMessage = 'Inspection Station details already exists';
                SET @ResultStatus = 0;

                SELECT
                    @ResultMessage AS ResultMessage,
                    @ResultStatus AS ResultStatus;

                RETURN;
            END

            INSERT INTO dbo.Config_Inspection_Station
            (
                StationID,
                InspectionStationName,
                InspectionStationDesc
            )
            VALUES
            (
                @StationID,
                @InspectionStationName,
                @InspectionStationDesc
            );

            SET @InspectionStationID = SCOPE_IDENTITY();

            INSERT INTO dbo.Config_History
            VALUES
            (
                GETDATE(),
                'Inspection Station Configuration',
                @InspectionStationID,
                'Add Record',
                ' ',
                ' ',
                1,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;

            SELECT
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus,
                @InspectionStationID AS InspectionStationID;

        END

        -------------------------------------------------
        -- UPDATE
        -------------------------------------------------

        ELSE IF @Mode = 2
        BEGIN

            DECLARE
                @OldStationID INT,
                @OldInspectionStationName NVARCHAR(100),
                @OldInspectionStationDesc NVARCHAR(300);

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_Inspection_Station
                WHERE InspectionStationID = @InspectionStationID
            )
            BEGIN
                SET @ResultMessage = 'Inspection Station details not found';
                SET @ResultStatus = 0;

                SELECT
                    @ResultMessage AS ResultMessage,
                    @ResultStatus AS ResultStatus;

                RETURN;
            END

            -------------------------------------------------
            -- KEEP OLD VALUES IF NEW VALUES ARE EMPTY
            -------------------------------------------------

            SELECT
                @StationID =
                    CASE
                        WHEN ISNULL(@StationID,0) = 0
                        THEN StationID
                        ELSE @StationID
                    END,

                @InspectionStationName =
                    CASE
                        WHEN ISNULL(LTRIM(RTRIM(@InspectionStationName)),'') = ''
                        THEN InspectionStationName
                        ELSE @InspectionStationName
                    END,

                @InspectionStationDesc =
                    CASE
                        WHEN @InspectionStationDesc IS NULL
                        THEN InspectionStationDesc
                        ELSE @InspectionStationDesc
                    END,

                @OldStationID = StationID,
                @OldInspectionStationName = InspectionStationName,
                @OldInspectionStationDesc = InspectionStationDesc

            FROM dbo.Config_Inspection_Station
            WHERE InspectionStationID = @InspectionStationID;

            -------------------------------------------------
            -- UPDATE RECORD
            -------------------------------------------------

            UPDATE dbo.Config_Inspection_Station
            SET
                StationID = @StationID,
                InspectionStationName = @InspectionStationName,
                InspectionStationDesc = @InspectionStationDesc
            WHERE InspectionStationID = @InspectionStationID;

            -------------------------------------------------
            -- HISTORY
            -------------------------------------------------

            IF ISNULL(@OldStationID,0) <> ISNULL(@StationID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Inspection Station Configuration',
                    @InspectionStationID,
                    'StationID',
                    @OldStationID,
                    @StationID,
                    2,
                    @Remark,
                    @UserName
                );
            END

            IF ISNULL(@OldInspectionStationName,'') <> ISNULL(@InspectionStationName,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Inspection Station Configuration',
                    @InspectionStationID,
                    'InspectionStationName',
                    @OldInspectionStationName,
                    @InspectionStationName,
                    2,
                    @Remark,
                    @UserName
                );
            END

            IF ISNULL(@OldInspectionStationDesc,'') <> ISNULL(@InspectionStationDesc,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Inspection Station Configuration',
                    @InspectionStationID,
                    'InspectionStationDesc',
                    @OldInspectionStationDesc,
                    @InspectionStationDesc,
                    2,
                    @Remark,
                    @UserName
                );
            END

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;

            SELECT
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

        END

        -------------------------------------------------
        -- DELETE
        -------------------------------------------------

        ELSE IF @Mode = 3
        BEGIN

            DELETE FROM dbo.Config_Inspection_Station
            WHERE InspectionStationID = @InspectionStationID;

            IF @@ROWCOUNT = 0
            BEGIN
                SET @ResultMessage = 'Inspection Station details not found';
                SET @ResultStatus = 0;

                SELECT
                    @ResultMessage AS ResultMessage,
                    @ResultStatus AS ResultStatus;

                RETURN;
            END

            INSERT INTO dbo.Config_History
            VALUES
            (
                GETDATE(),
                'Inspection Station Configuration',
                @InspectionStationID,
                'Delete Record',
                ' ',
                ' ',
                3,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;

            SELECT
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;

        SELECT
            @ResultMessage AS ResultMessage,
            @ResultStatus AS ResultStatus;

    END CATCH

END
GO

-- ------------------------------------------------------------------------
-- [24/376] Stored Procedure: [dbo].[BT_Config_IPQC_ManagerAuditPoint]
-- Created: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Shubham Patil
-- CREATE OR ALTER OR ALTER date : 25-05-2026
-- Description : Procedure for Add, Modify & Delete
--               IPQC Manager Audit Point Configuration.
-- =============================================

--*************************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY     | DESCRIPTION             |
-----------------------------------------------------------
--| 25-05-2026 | Shubham Patil  | CREATE OR ALTER OR ALTERd                 |
--| 18-06-2026 | Shubham Patil  | Fixed to standard       |
--|            |                | soft insert pattern,    |
--|            |                | added @DocumentID param |
-----------------------------------------------------------
--*************************************************************************

CREATE       PROCEDURE [dbo].[BT_Config_IPQC_ManagerAuditPoint]

    @ResultMessage  NVARCHAR(MAX)    OUTPUT,
    @ResultStatus   INT             OUTPUT,
    @Mode           INT,

    @UID            INT             = NULL,
    @AuditListID    INT             = NULL,
    @AuditPointId   INT             = NULL,
    @AuditPointName NVARCHAR(100)   = NULL,
    @Category       NVARCHAR(100)   = NULL,
    @Type           NVARCHAR(50)    = NULL,
    @CheckingMethod NVARCHAR(100)   = NULL,
    @UpperLimit     DECIMAL(5,2)    = NULL,
    @LowerLimit     DECIMAL(5,2)    = NULL,
    @Status         INT             = NULL,
    @Revision       INT             = NULL,
    @DocumentID     INT             = NULL,

    @Remark         NVARCHAR(300)   = NULL,
    @UserName       NVARCHAR(100)

AS
BEGIN

    SET NOCOUNT ON;

    BEGIN TRY

        -- =============================================
        -- MODE VALIDATION
        -- =============================================

        IF @Mode NOT IN (1, 2, 3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus  = 0;
          
            RETURN;
        END

        -- =============================================
        -- DELETE VALIDATION
        -- =============================================

        IF @Mode = 3
        BEGIN
            IF ISNULL(@UID, 0) = 0
            BEGIN
                SET @ResultMessage = 'UID is required';
                SET @ResultStatus  = 0;
             
                RETURN;
            END
        END

        -- =============================================
        -- INSERT / UPDATE VALIDATION
        -- =============================================

        IF @Mode IN (1, 2)
        BEGIN

            IF (
                ISNULL(@AuditListID,  0) = 0
                OR ISNULL(@AuditPointId, 0) = 0
                OR ISNULL(LTRIM(RTRIM(@AuditPointName)), '') = ''
                OR ISNULL(LTRIM(RTRIM(@Category)),       '') = ''
                OR ISNULL(LTRIM(RTRIM(@Type)),           '') = ''
                OR ISNULL(LTRIM(RTRIM(@CheckingMethod)), '') = ''
                OR ISNULL(@Status,  -1) = -1
                OR ISNULL(@Revision, 0) = 0
            )
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus  = 0;
               
                RETURN;
            END

            IF LEN(ISNULL(@AuditPointName, '')) > 100
            BEGIN
                SET @ResultMessage = 'AuditPointName exceeds max length (100)';
                SET @ResultStatus  = 0;
              
                RETURN;
            END

            IF LEN(ISNULL(@Category, '')) > 100
            BEGIN
                SET @ResultMessage = 'Category exceeds max length (100)';
                SET @ResultStatus  = 0;
              
                RETURN;
            END

            IF LEN(ISNULL(@Type, '')) > 50
            BEGIN
                SET @ResultMessage = 'Type exceeds max length (50)';
                SET @ResultStatus  = 0;
             
                RETURN;
            END

            IF LEN(ISNULL(@CheckingMethod, '')) > 100
            BEGIN
                SET @ResultMessage = 'CheckingMethod exceeds max length (100)';
                SET @ResultStatus  = 0;
               
                RETURN;
            END

        END

        -- =============================================
        -- DOCUMENT REVISION CALCULATION
        -- =============================================

        DECLARE @DocumentNumber NVARCHAR(50);
        SET @DocumentNumber = (
            SELECT DISTINCT DocumentNo
            FROM Config_QADocumentList
            WHERE DocumentID = @DocumentID
        );

        DECLARE @NewRevision INT;
        SET @NewRevision = (
            SELECT MAX(Revision) + 1
            FROM Config_QADocumentList
            WHERE DocumentNo = @DocumentNumber
        );

        -- =============================================
        -- INSERT MODE (Add)
        -- =============================================

        IF @Mode = 1
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1 FROM Config_AuditList
                WHERE AuditListID = @AuditListID
            )
            BEGIN
                SET @ResultMessage = 'Invalid AuditListID';
                SET @ResultStatus  = 0;
             
                RETURN;
            END

            -- DUPLICATE CHECK
            IF EXISTS
            (
                SELECT 1
                FROM Config_IPQC_ManagerAuditPoint
                WHERE AuditListID  = @AuditListID
                  AND AuditPointId = @AuditPointId
                  AND Status       = 1
            )
            BEGIN
                SET @ResultMessage = 'Record already exists';
                SET @ResultStatus  = 0;
               
                RETURN;
            END

            -- INSERT new row
            INSERT INTO Config_IPQC_ManagerAuditPoint
            (
                AuditListID,
                AuditPointId,
                AuditPointName,
                Category,
                Type,
                CheckingMethod,
                UpperLimit,
                LowerLimit,
                Status,
                Revision
            )
            VALUES
            (
                @AuditListID,
                @AuditPointId,
                @AuditPointName,
                @Category,
                @Type,
                @CheckingMethod,
                @UpperLimit,
                @LowerLimit,
                @Status,
                @NewRevision
            );

            DECLARE @NewUID INT;
            SET @NewUID = SCOPE_IDENTITY();

            -- Update document revision
            UPDATE Config_QADocumentList
            SET    Revision = @NewRevision
            WHERE  DocumentID = @DocumentID;

            -- History log
            INSERT INTO Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(), 'IPQC Manager Audit Point', @NewUID,
                'Insert', '', '',
                1, @Remark, @UserName
            );

            SET @ResultMessage = 'Inserted Successfully';
            SET @ResultStatus  = 1;
            RETURN;

        END

        -- =============================================
        -- MODIFY MODE
        -- Soft INSERT new row with updated values + @NewRevision
        -- =============================================

        ELSE IF @Mode = 2
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1 FROM Config_IPQC_ManagerAuditPoint
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'UID not found';
                SET @ResultStatus  = 0;
                
                RETURN;
            END

            -- INSERT new row with updated values and new revision
            INSERT INTO Config_IPQC_ManagerAuditPoint
            (
                AuditListID,
                AuditPointId,
                AuditPointName,
                Category,
                Type,
                CheckingMethod,
                UpperLimit,
                LowerLimit,
                Status,
                Revision
            )
            VALUES
            (
                @AuditListID,
                @AuditPointId,
                @AuditPointName,
                @Category,
                @Type,
                @CheckingMethod,
                @UpperLimit,
                @LowerLimit,
                @Status,
                @NewRevision
            );

            DECLARE @ModifiedUID INT;
            SET @ModifiedUID = SCOPE_IDENTITY();

            -- Update document revision
            UPDATE Config_QADocumentList
            SET    Revision = @NewRevision
            WHERE  DocumentID = @DocumentID;

            -- History log
            INSERT INTO Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(), 'IPQC Manager Audit Point', @ModifiedUID,
                'Modify', '', '',
                2, @Remark, @UserName
            );

            SET @ResultMessage = 'Updated Successfully';
            SET @ResultStatus  = 1;
            RETURN;

        END

        -- =============================================
        -- DELETE MODE
        -- Soft INSERT new row with Status=2 + @NewRevision
        -- =============================================

        ELSE IF @Mode = 3
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1 FROM Config_IPQC_ManagerAuditPoint
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'UID not found';
                SET @ResultStatus  = 0;
                
                RETURN;
            END

            -- Fetch existing row values to carry forward
            DECLARE @ExistingAuditListID    INT;
            DECLARE @ExistingAuditPointId   INT;
            DECLARE @ExistingAuditPointName NVARCHAR(100);
            DECLARE @ExistingCategory       NVARCHAR(100);
            DECLARE @ExistingType           NVARCHAR(50);
            DECLARE @ExistingCheckingMethod NVARCHAR(100);
            DECLARE @ExistingUpperLimit     DECIMAL(5,2);
            DECLARE @ExistingLowerLimit     DECIMAL(5,2);

            SELECT
                @ExistingAuditListID    = AuditListID,
                @ExistingAuditPointId   = AuditPointId,
                @ExistingAuditPointName = AuditPointName,
                @ExistingCategory       = Category,
                @ExistingType           = Type,
                @ExistingCheckingMethod = CheckingMethod,
                @ExistingUpperLimit     = UpperLimit,
                @ExistingLowerLimit     = LowerLimit
            FROM Config_IPQC_ManagerAuditPoint
            WHERE UID = @UID;

            -- INSERT new row as disabled (Status = 2)
            INSERT INTO Config_IPQC_ManagerAuditPoint
            (
                AuditListID,
                AuditPointId,
                AuditPointName,
                Category,
                Type,
                CheckingMethod,
                UpperLimit,
                LowerLimit,
                Status,
                Revision
            )
            VALUES
            (
                @ExistingAuditListID,
                @ExistingAuditPointId,
                @ExistingAuditPointName,
                @ExistingCategory,
                @ExistingType,
                @ExistingCheckingMethod,
                @ExistingUpperLimit,
                @ExistingLowerLimit,
                2,              -- disabled
                @NewRevision
            );

            DECLARE @DeletedUID INT;
            SET @DeletedUID = SCOPE_IDENTITY();

            -- Update document revision
            UPDATE Config_QADocumentList
            SET    Revision = @NewRevision
            WHERE  DocumentID = @DocumentID;

            -- History log
            INSERT INTO Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(), 'IPQC Manager Audit Point', @DeletedUID,
                'Delete', '', '',
                3, @Remark, @UserName
            );

            SET @ResultMessage = 'Deleted Successfully';
            SET @ResultStatus  = 1;
            RETURN;

        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL ERROR';
        SET @ResultStatus  = 0;
        RETURN;

    END CATCH

END
GO

-- ------------------------------------------------------------------------
