CREATE     PROCEDURE [dbo].[BT_Config_IPQC_SOPAuditPoint]

    @ResultMessage  VARCHAR(MAX) OUTPUT,
    @ResultStatus   INT OUTPUT,
    @Mode           INT,

    @UID                INT             = NULL,
    @AuditListID        INT             = NULL,
    @AuditPointId       INT             = NULL,
    @AuditPointName     NVARCHAR(100)   = NULL,
    @Category           NVARCHAR(100)   = NULL,
    @AuditProcess       NVARCHAR(300)   = NULL,
    @CheckingMethod     NVARCHAR(100)   = NULL,
    @Status             INT             = 1,
    @Revision           INT             = NULL,
    @DocumentID         INT             = NULL,

    @Remark     NVARCHAR(300) = NULL,
    @UserName   NVARCHAR(100)

AS
BEGIN

    SET NOCOUNT ON;

    BEGIN TRY

        -- =============================================
        -- MODE VALIDATION
        -- =============================================

        IF @Mode NOT IN (1, 2, 3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus  = 0;
         
            RETURN;
        END

        -- =============================================
        -- DELETE VALIDATION
        -- =============================================

        IF @Mode = 3
        BEGIN
            IF ISNULL(@UID, 0) = 0
            BEGIN
                SET @ResultMessage = 'UID is required';
                SET @ResultStatus  = 0;
            
                RETURN;
            END
        END

        -- =============================================
        -- INSERT / UPDATE VALIDATION
        -- =============================================

        IF @Mode IN (1, 2)
        BEGIN

            IF (
                ISNULL(@AuditListID, 0) = 0
                OR ISNULL(@AuditPointId, 0) = 0
                OR ISNULL(LTRIM(RTRIM(@AuditPointName)), '')  = ''
                OR ISNULL(LTRIM(RTRIM(@Category)),       '')  = ''
                OR ISNULL(LTRIM(RTRIM(@AuditProcess)),   '')  = ''
                OR ISNULL(LTRIM(RTRIM(@CheckingMethod)), '')  = ''
                OR ISNULL(@Status,   0) = 0
                OR ISNULL(@Revision, 0) = 0
            )
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus  = 0;
                
                RETURN;
            END

            IF @Status NOT IN (1, 2)
            BEGIN
                SET @ResultMessage = 'Invalid Status value';
                SET @ResultStatus  = 0;
               
                RETURN;
            END

        END

        -- =============================================
        -- REVISION CALCULATION
        -- =============================================
        DECLARE @DocumentNumber NVARCHAR(50);
        SET @DocumentNumber = (SELECT DISTINCT DocumentNo FROM Config_QADocumentList WHERE DocumentID = @DocumentID);

        DECLARE @NewRevision INT;
        SET @NewRevision = (SELECT MAX(Revision) + 1 FROM Config_QADocumentList WHERE DocumentNo = @DocumentNumber);

        -- =============================================
        -- INSERT MODE (Add)
        -- =============================================

        IF @Mode = 1
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1 FROM Config_AuditList
                WHERE AuditListID = @AuditListID
            )
            BEGIN
                SET @ResultMessage = 'Invalid AuditListID';
                SET @ResultStatus  = 0;
               
                RETURN;
            END

            -- DUPLICATE CHECK
            IF EXISTS
            (
                SELECT 1
                FROM Config_IPQC_SOPAuditPoint
                WHERE AuditListID  = @AuditListID
                  AND AuditPointId = @AuditPointId
                  AND Status       = 1
            )
            BEGIN
                SET @ResultMessage = 'Record already exists';
                SET @ResultStatus  = 0;
                RETURN;
              
            END

            -- INSERT new row
            INSERT INTO Config_IPQC_SOPAuditPoint
            (
                AuditListID,
                AuditPointId,
                AuditPointName,
                Category,
                AuditProcess,
                CheckingMethod,
                [Status],
                Revision
            )
            VALUES
            (
                @AuditListID,
                @AuditPointId,
                @AuditPointName,
                @Category,
                @AuditProcess,
                @CheckingMethod,
                @Status,
                @NewRevision
            );

            DECLARE @NewUID INT;
            SET @NewUID = SCOPE_IDENTITY();

            -- Update document revision
            UPDATE Config_QADocumentList
            SET    Revision = @NewRevision
            WHERE  DocumentID = @DocumentID;

            -- History log
            INSERT INTO Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(), 'IPQC SOP Audit Point', @NewUID,
                'Insert', '', '',
                1, @Remark, @UserName
            );

            SET @ResultMessage = 'Inserted Successfully';
            SET @ResultStatus  = 1;
            RETURN;

        END

        -- =============================================
        -- MODIFY MODE
        -- INSERT new row with updated values + Revision+1
        -- =============================================

        ELSE IF @Mode = 2
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1 FROM Config_IPQC_SOPAuditPoint
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'UID not found';
                SET @ResultStatus  = 0;
                RETURN;
              
            END

            -- INSERT new row with updated values and new revision
            INSERT INTO Config_IPQC_SOPAuditPoint
            (
                AuditListID,
                AuditPointId,
                AuditPointName,
                Category,
                AuditProcess,
                CheckingMethod,
                [Status],
                Revision
            )
            VALUES
            (
                @AuditListID,
                @AuditPointId,
                @AuditPointName,
                @Category,
                @AuditProcess,
                @CheckingMethod,
                @Status,
                @NewRevision
            );

            DECLARE @ModifiedUID INT;
            SET @ModifiedUID = SCOPE_IDENTITY();

            -- Update document revision
            UPDATE Config_QADocumentList
            SET    Revision = @NewRevision
            WHERE  DocumentID = @DocumentID;

            -- History log
            INSERT INTO Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(), 'IPQC SOP Audit Point', @ModifiedUID,
                'Modify', '', '',
                2, @Remark, @UserName
            );

            SET @ResultMessage = 'Updated Successfully';
            SET @ResultStatus  = 1;
            RETURN;

        END

        -- =============================================
        -- DELETE MODE
        -- INSERT new row with Status=2 (disabled) + Revision+1
        -- =============================================

        ELSE IF @Mode = 3
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1 FROM Config_IPQC_SOPAuditPoint
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'UID not found';
                SET @ResultStatus  = 0;
                RETURN;
               
            END

            -- Fetch existing row values to carry forward into new disabled row
            DECLARE @ExistingAuditListID    INT;
            DECLARE @ExistingAuditPointId   INT;
            DECLARE @ExistingAuditPointName NVARCHAR(100);
            DECLARE @ExistingCategory       NVARCHAR(100);
            DECLARE @ExistingAuditProcess   NVARCHAR(300);
            DECLARE @ExistingCheckingMethod NVARCHAR(100);

            SELECT
                @ExistingAuditListID    = AuditListID,
                @ExistingAuditPointId   = AuditPointId,
                @ExistingAuditPointName = AuditPointName,
                @ExistingCategory       = Category,
                @ExistingAuditProcess   = AuditProcess,
                @ExistingCheckingMethod = CheckingMethod
            FROM Config_IPQC_SOPAuditPoint
            WHERE UID = @UID;

            -- INSERT new row as disabled (Status = 2) with Revision + 1
            INSERT INTO Config_IPQC_SOPAuditPoint
            (
                AuditListID,
                AuditPointId,
                AuditPointName,
                Category,
                AuditProcess,
                CheckingMethod,
                [Status],
                Revision
            )
            VALUES
            (
                @ExistingAuditListID,
                @ExistingAuditPointId,
                @ExistingAuditPointName,
                @ExistingCategory,
                @ExistingAuditProcess,
                @ExistingCheckingMethod,
                2,                  -- disabled
                @NewRevision
            );

            DECLARE @DeletedUID INT;
            SET @DeletedUID = SCOPE_IDENTITY();

            -- Update document revision
            UPDATE Config_QADocumentList
            SET    Revision = @NewRevision
            WHERE  DocumentID = @DocumentID;

            -- History log
            INSERT INTO Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(), 'IPQC SOP Audit Point', @DeletedUID,
                'Delete', '', '',
                3, @Remark, @UserName
            );

            SET @ResultMessage = 'Deleted Successfully';
            SET @ResultStatus  = 1;
            RETURN;

        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL ERROR';
        SET @ResultStatus  = 0;
        RETURN;

    END CATCH

END
