    @Revision           INT             = NULL,
    @DocumentID         INT             = NULL,

    @Remark             NVARCHAR(300)   = NULL,
    @UserName           NVARCHAR(100)

AS
BEGIN

    SET NOCOUNT ON;

    BEGIN TRY

        -- =============================================
        -- MODE VALIDATION
        -- =============================================

        IF @Mode NOT IN (1, 2, 3)
