            END

            IF ISNULL(@OldStatus, 0) <> ISNULL(@Status, 0)
            BEGIN
                INSERT INTO Config_History VALUES
                (
                    GETDATE(), 'IQC Visual Inspect Audit Point', @ModifiedUID,
                    'Status', @OldStatus, @Status,
                    2, @Remark, @UserName
                );
            END

            SET @ResultMessage = 'Updated Successfully';
            SET @ResultStatus  = 1;
            RETURN;

        END

        -- =============================================
        -- DELETE MODE
        -- INSERT new row with Status=2 (disabled) + Revision+1
        -- =============================================

        ELSE IF @Mode = 3
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1 FROM Config_IQC_VisualInspectAuditPoint
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'UID not found';
                SET @ResultStatus  = 0;

                RETURN;
            END

            -- Fetch existing row values to carry forward into new disabled row
            DECLARE @ExistingAuditListID       INT;
            DECLARE @ExistingModelFamilyID     INT;
            DECLARE @ExistingModelID           INT;
            DECLARE @ExistingAuditPointID      INT;
            DECLARE @ExistingAuditPointName    NVARCHAR(100);
            DECLARE @ExistingAspect            NVARCHAR(50);
            DECLARE @ExistingUpperLimit        DECIMAL(5,2);
            DECLARE @ExistingLowerLimit        DECIMAL(5,2);
            DECLARE @ExistingCheckingMethod    NVARCHAR(100);
            SELECT
                @ExistingAuditListID       = AuditListID,
                @ExistingModelFamilyID     = ModelFamilyID,
                @ExistingModelID           = ModelID,
                @ExistingAuditPointID      = AuditPointId,
                @ExistingAuditPointName    = AuditPointName,
                @ExistingAspect            = Aspect,
                @ExistingUpperLimit        = UpperLimit,
                @ExistingLowerLimit        = LowerLimit,
                @ExistingCheckingMethod    = CheckingMethod
            FROM Config_IQC_VisualInspectAuditPoint
            WHERE UID = @UID;

            -- INSERT new row as disabled (Status = 2) with Revision + 1
            INSERT INTO Config_IQC_VisualInspectAuditPoint
            (
                AuditPointId,
                AuditListID,
                ModelFamilyID,
                ModelID,
                AuditPointName,
                Aspect,
                UpperLimit,
                LowerLimit,
                CheckingMethod,
                [Status],
                Revision
            )
            VALUES
            (
                @ExistingAuditPointID,
                @ExistingAuditListID,
                @ExistingModelFamilyID,
                @ExistingModelID,
                @ExistingAuditPointName,
                @ExistingAspect,
                @ExistingUpperLimit,
                @ExistingLowerLimit,
                @ExistingCheckingMethod,
                2,                  -- disabled
                @NewRevision
            );

            DECLARE @DeletedUID INT;
            SET @DeletedUID = SCOPE_IDENTITY();

            -- Update document revision
            UPDATE Config_QADocumentList
            SET    Revision = @NewRevision
            WHERE  DocumentID = @DocumentID;

            -- History log
            INSERT INTO Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(), 'IQC Visual Inspect Audit Point', @DeletedUID,
                'Delete', '', '',
                3, @Remark, @UserName
            );

            SET @ResultMessage = 'Deleted Successfully';
            SET @ResultStatus  = 1;
            RETURN;

        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL ERROR';
        SET @ResultStatus  = 0;
        RETURN;

    END CATCH

END
GO

