-----------------------------------------------------------
--| 25-06-2026 | Sumit      | CREATE OR ALTER OR ALTERd                     |
-----------------------------------------------------------
--*************************************************************************

CREATE       PROCEDURE [dbo].[BT_Config_JHActivity]

    @ResultMessage  NVARCHAR(MAX)   OUTPUT,
    @ResultStatus   INT             OUTPUT,
    @Mode           INT,

    @JHActivityID            INT             = NULL,
    @Description    NVARCHAR(100)   = NULL,

    @Remark         NVARCHAR(300)   = NULL,
    @UserName       NVARCHAR(100)

AS
BEGIN

    SET NOCOUNT ON;

    BEGIN TRY

        -- =============================================
        -- MODE VALIDATION
        -- =============================================

        IF @Mode NOT IN (1, 2, 3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus  = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        -- =============================================
        -- DELETE VALIDATION
        -- =============================================

        IF @Mode IN (2, 3) AND ISNULL(@JHActivityID, 0) = 0
        BEGIN
            SET @ResultMessage = 'JHActivityID is required';
            SET @ResultStatus  = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        -- =============================================
        -- INSERT / UPDATE VALIDATION
        -- =============================================

        IF @Mode IN (1, 2)
        BEGIN

            IF ISNULL(LTRIM(RTRIM(@Description)), '') = ''
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(@Description) > 100
            BEGIN
                SET @ResultMessage = 'Description exceeds max length (100)';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            -- DUPLICATE CHECK
            IF EXISTS
            (
                SELECT 1
                FROM dbo.Config_JHActivity
                WHERE Description = @Description
                  AND (@Mode = 1 OR JHActivityID <> @JHActivityID)
            )
            BEGIN
                SET @ResultMessage = 'Description already exists';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

        END

        -- =============================================
        -- INSERT MODE
        -- =============================================

        IF @Mode = 1
        BEGIN

            INSERT INTO dbo.Config_JHActivity
            (
                Description
            )
            VALUES
            (
                @Description
            );

            SET @JHActivityID = SCOPE_IDENTITY();

            INSERT INTO dbo.Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(), 'JH Activity Configuration', @JHActivityID,
                'Insert', '', '',
                1, @Remark, @UserName
            );

            SET @ResultMessage = 'Inserted Successfully';
            SET @ResultStatus  = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;

        END

        -- =============================================
        -- UPDATE MODE
        -- =============================================

        ELSE IF @Mode = 2
        BEGIN

            DECLARE @OldDescription NVARCHAR(100);

            IF NOT EXISTS
            (
                SELECT 1 FROM dbo.Config_JHActivity
                WHERE JHActivityID = @JHActivityID
            )
            BEGIN
                SET @ResultMessage = 'JHActivityID not found';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            SELECT @OldDescription = Description
            FROM dbo.Config_JHActivity
            WHERE JHActivityID = @JHActivityID;

            UPDATE dbo.Config_JHActivity
            SET Description = CASE
                                WHEN ISNULL(Description, '') <> ISNULL(@Description, '')
                                THEN @Description
                                ELSE Description
                              END
            WHERE JHActivityID = @JHActivityID;

            IF ISNULL(@OldDescription, '') <> ISNULL(@Description, '')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'JH Activity Configuration', @JHActivityID,
                    'Description', @OldDescription, @Description,
                    2, @Remark, @UserName
                );
            END

            SET @ResultMessage = 'Updated Successfully';
            SET @ResultStatus  = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;

        END

        -- =============================================
        -- DELETE MODE
        -- =============================================

        ELSE IF @Mode = 3
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1 FROM dbo.Config_JHActivity
                WHERE JHActivityID = @JHActivityID
            )
            BEGIN
                SET @ResultMessage = 'JHActivityID not found';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            DELETE FROM dbo.Config_JHActivity
            WHERE JHActivityID = @JHActivityID;

            INSERT INTO dbo.Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(), 'JH Activity Configuration', @JHActivityID,
                'Delete', '', '',
                3, @Remark, @UserName
            );

            SET @ResultMessage = 'Deleted Successfully';
            SET @ResultStatus  = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;

        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL ERROR';
        SET @ResultStatus  = 0;
        SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;

    END CATCH

END
