CREATE       PROCEDURE [dbo].[BT_Config_KitBOM]

    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,

    @UID INT = NULL,
    @SKUID INT,
    @PartID NVARCHAR(20),
    @PartQuantity INT,
    @KitSlotID INT,
    @KitZoneID INT,

    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)

AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage='Invalid Mode specified.';
            SET @ResultStatus=0;

            SELECT @ResultMessage ResultMessage,
                   @ResultStatus ResultStatus;
            RETURN;
        END

        IF @Mode IN (2,3) --AND ISNULL(@UID,0)=0
        BEGIN
            SET @ResultMessage='UID is required.';
            SET @ResultStatus=0;

            SELECT @ResultMessage ResultMessage,
                   @ResultStatus ResultStatus;
            RETURN;
        END

        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode IN (1,2)
        BEGIN

            IF ISNULL(@SKUID,0)=0
            OR ISNULL(@PartID,'')=''
            OR ISNULL(@PartQuantity,0)=0
            OR ISNULL(@KitSlotID,0)=0
            OR ISNULL(@KitZoneID,0)=0
            BEGIN
                SET @ResultMessage='Fill all mandatory fields.';
                SET @ResultStatus=0;

                SELECT @ResultMessage ResultMessage,
                       @ResultStatus ResultStatus;
                RETURN;
            END

            -------------------------------------------------
            -- DUPLICATE VALIDATION
            -------------------------------------------------
            IF EXISTS
            (
                SELECT 1
                FROM dbo.Config_KitBOM
                WHERE SKUID=@SKUID
                AND PartID=@PartID
                AND KitSlotID=@KitSlotID
                AND KitZoneID=@KitZoneID
                AND (@Mode=1 OR UID<>@UID)
            )
            BEGIN
                SET @ResultMessage='Record already exists.';
                SET @ResultStatus=0;

                SELECT @ResultMessage ResultMessage,
                       @ResultStatus ResultStatus;
                RETURN;
            END
        END

        -------------------------------------------------
        -- INSERT
        -------------------------------------------------
        IF @Mode=1
        BEGIN

            INSERT INTO dbo.Config_KitBOM
            (
                SKUID,
                PartID,
                PartQuantity,
                KitSlotID,
                KitZoneID
            )
            VALUES
            (
                @SKUID,
                @PartID,
                @PartQuantity,
                @KitSlotID,
                @KitZoneID
            );

            SET @UID=SCOPE_IDENTITY();

            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Kit BOM Configuration',
                @UID,
                'Add Record',
                '',
                '',
                1,
                @Remark,
                @UserName
            );

            SET @ResultMessage='Inserted successfully.';
            SET @ResultStatus=1;

            SELECT @ResultMessage ResultMessage,
                   @ResultStatus ResultStatus;
        END

        -------------------------------------------------
        -- UPDATE
        -------------------------------------------------
        ELSE IF @Mode=2
        BEGIN

            DECLARE
                @OldSKUID INT,
                @OldPartID NVARCHAR(20),
                @OldPartQuantity INT,
                @OldKitSlotID INT,
                @OldKitZoneID INT;

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_KitBOM
                WHERE UID=@UID
            )
            BEGIN
                SET @ResultMessage='Record not found.';
                SET @ResultStatus=0;

                SELECT @ResultMessage ResultMessage,
                       @ResultStatus ResultStatus;
                RETURN;
            END

            SELECT
                @OldSKUID=SKUID,
                @OldPartID=PartID,
                @OldPartQuantity=PartQuantity,
                @OldKitSlotID=KitSlotID,
                @OldKitZoneID=KitZoneID
            FROM dbo.Config_KitBOM
            WHERE UID=@UID;

            UPDATE dbo.Config_KitBOM
            SET
                SKUID=@SKUID,
                PartID=@PartID,
                PartQuantity=@PartQuantity,
                KitSlotID=@KitSlotID,
                KitZoneID=@KitZoneID
            WHERE UID=@UID;

            IF ISNULL(@OldSKUID,0)<>ISNULL(@SKUID,0)
                INSERT INTO dbo.Config_History VALUES(GETDATE(),'Kit BOM Configuration',@UID,'SKUID',@OldSKUID,@SKUID,2,@Remark,@UserName);

            IF ISNULL(@OldPartID,'')<>ISNULL(@PartID,'')
                INSERT INTO dbo.Config_History VALUES(GETDATE(),'Kit BOM Configuration',@UID,'PartID',@OldPartID,@PartID,2,@Remark,@UserName);

            IF ISNULL(@OldPartQuantity,0)<>ISNULL(@PartQuantity,0)
                INSERT INTO dbo.Config_History VALUES(GETDATE(),'Kit BOM Configuration',@UID,'PartQuantity',@OldPartQuantity,@PartQuantity,2,@Remark,@UserName);

            IF ISNULL(@OldKitSlotID,0)<>ISNULL(@KitSlotID,0)
                INSERT INTO dbo.Config_History VALUES(GETDATE(),'Kit BOM Configuration',@UID,'KitSlotID',@OldKitSlotID,@KitSlotID,2,@Remark,@UserName);

            IF ISNULL(@OldKitZoneID,0)<>ISNULL(@KitZoneID,0)
                INSERT INTO dbo.Config_History VALUES(GETDATE(),'Kit BOM Configuration',@UID,'KitZoneID',@OldKitZoneID,@KitZoneID,2,@Remark,@UserName);

            SET @ResultMessage='Updated successfully.';
            SET @ResultStatus=1;

            SELECT @ResultMessage ResultMessage,
                   @ResultStatus ResultStatus;
        END

        -------------------------------------------------
        -- DELETE
        -------------------------------------------------
        ELSE IF @Mode=3
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_KitBOM
                WHERE UID=@UID
            )
            BEGIN
                SET @ResultMessage='Record not found.';
                SET @ResultStatus=0;

                SELECT @ResultMessage ResultMessage,
                       @ResultStatus ResultStatus;
                RETURN;
            END

            DELETE
            FROM dbo.Config_KitBOM
            WHERE UID=@UID;

            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Kit BOM Configuration',
                @UID,
                'Delete Record',
                '',
                '',
                3,
                @Remark,
                @UserName
            );

            SET @ResultMessage='Deleted successfully.';
            SET @ResultStatus=1;

            SELECT @ResultMessage ResultMessage,
                   @ResultStatus ResultStatus;
        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage='SQL Error';
        SET @ResultStatus=0;

        SELECT @ResultMessage ResultMessage,
               @ResultStatus ResultStatus;

    END CATCH
END
