-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 23-04-2026
-- Description : Procedure for Add, Modify & Delete Buttons
-- =============================================

--***************************************************************
--Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION            |
-----------------------------------------------------------
--| 23-04-2026 | Sumit      | CREATE OR ALTER OR ALTERd                |
--| 30-04-2026 | Sumit      | Standardized fixes     |
--| 06-05-2026 | Sumit      | changed screen name and error message to sql error   |
-----------------------------------------------------------
--***************************************************************/

CREATE         PROCEDURE [dbo].[BT_Config_Line]
    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,

    @LineID INT,
    @LineName NVARCHAR(100),
    @LineDesc NVARCHAR(300),
    @ShopID INT,
    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        
        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF @LineID IS NULL
        BEGIN
            SET @ResultMessage = 'LineID is required';
            SET @ResultStatus = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode IN (1,2)
        BEGIN
         -------------------------------------------------
        -- Mandatory validation
        -------------------------------------------------
         IF (
                   ISNULL(LTRIM(RTRIM(@LineName)), '') = ''
                 OR ISNULL(LTRIM(RTRIM(@ShopID)), 0) = 0
               )
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
            -- ✅ FIXED: INT validation
            IF @ShopID IS NULL OR @ShopID = 0
            BEGIN
                SET @ResultMessage = 'Shop Name is required';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF @LineName IS NULL OR LTRIM(RTRIM(@LineName)) = ''
            BEGIN
                SET @ResultMessage = 'Line Name is required';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            --IF @LineDesc IS NULL OR LTRIM(RTRIM(@LineDesc)) = ''
            --BEGIN
            --    SET @ResultMessage = 'Line Description is required';
            --    SET @ResultStatus = 0;
            --    SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            --    RETURN;
            --END

            IF LEN(@LineName) > 100
            BEGIN
                SET @ResultMessage = 'Line Name exceeds max length (100)';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(ISNULL(@LineDesc,'')) > 300
            BEGIN
                SET @ResultMessage = 'Line Description exceeds max length (300)';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END
        END

        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.Config_Line WHERE LineID = @LineID)
            BEGIN
                SET @ResultMessage = 'Line details already exists';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            INSERT INTO dbo.Config_Line
            (
                ShopID,
                LineName,
                LineDesc
            )
            VALUES
            (
                @ShopID,
                @LineName,
                @LineDesc
            );

            INSERT INTO dbo.Config_History
            (TimeStamp, ScreenName, PrimaryKeyValue, FieldName, OldValue, NewValue, Status, Remark, UpdatedBy)
            VALUES
            (GETDATE(), 'Line Configuration', @LineID, 'Add Record', ' ', ' ', 1, @Remark, @UserName);

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN
            DECLARE 
                @OldLineName NVARCHAR(100),
                @OldLineDesc NVARCHAR(300),
                @OldShopID INT;

            IF NOT EXISTS (SELECT 1 FROM dbo.Config_Line WHERE LineID = @LineID)
            BEGIN
                SET @ResultMessage = 'Line details not found';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            SELECT
                @OldLineName = LineName,
                @OldLineDesc = LineDesc,
                @OldShopID = ShopID
            FROM dbo.Config_Line
            WHERE LineID = @LineID;

            UPDATE dbo.Config_Line
            SET
                LineName = CASE WHEN ISNULL(LineName,'') <> ISNULL(@LineName,'') THEN @LineName ELSE LineName END,
                LineDesc = CASE WHEN ISNULL(LineDesc,'') <> ISNULL(@LineDesc,'') THEN @LineDesc ELSE LineDesc END,
                ShopID   = CASE WHEN ISNULL(ShopID,0) <> ISNULL(@ShopID,0) THEN @ShopID ELSE ShopID END
            WHERE LineID = @LineID;

            IF ISNULL(@OldLineName,'') <> ISNULL(@LineName,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES (GETDATE(),'Line Configuration',@LineID,'LineName',@OldLineName,@LineName,2,@Remark,@UserName);
            END

            IF ISNULL(@OldLineDesc,'') <> ISNULL(@LineDesc,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES (GETDATE(),'Line Configuration',@LineID,'LineDesc',@OldLineDesc,@LineDesc,2,@Remark,@UserName);
            END

            IF ISNULL(@OldShopID,0) <> ISNULL(@ShopID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES (GETDATE(),'Line Configuration',@LineID,'ShopID',@OldShopID,@ShopID,2,@Remark,@UserName);
            END

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END     

        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN
            DELETE FROM dbo.Config_Line
            WHERE LineID = @LineID;

            IF @@ROWCOUNT = 0
            BEGIN
                SET @ResultMessage = 'Line details not found';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            INSERT INTO dbo.Config_History
            VALUES (GETDATE(),'Line Configuration',@LineID,'Delete Record',' ',' ',3,@Remark,@UserName);

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

    END TRY

    BEGIN CATCH
        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;
        SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
    END CATCH
END
GO

