                OR @LineSpeed IS NULL
                OR @OperatorCount IS NULL
               )
            BEGIN

                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;

            END

            -------------------------------------------------
            -- DUPLICATE VALIDATION
            -------------------------------------------------
            IF EXISTS
            (
                SELECT 1
                FROM dbo.Config_LineSpeedOperatorCount
                WHERE LineID = @LineID
                 
                  AND LineSpeed = @LineSpeed
                  AND (@Mode = 1 OR UID <> @UID)
            )
            BEGIN

                SET @ResultMessage = 'Details already exists for this Line, Sub Assembly Line and Line Speed';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;

            END

        END

        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN

            INSERT INTO dbo.Config_LineSpeedOperatorCount
            (
                LineID,
               
                LineSpeed,
                OperatorCount
            )
            VALUES
            (
                @LineID,
              
                @LineSpeed,
                @OperatorCount
            );

            SET @UID = SCOPE_IDENTITY();

            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Line Speed Operator Count Configuration',
                @UID,
                'Add Record',
                '',
                '',
                1,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;

        END

        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN

            DECLARE
                @OldLineID INT,
               
                @OldLineSpeed INT,
                @OldOperatorCount INT;

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_LineSpeedOperatorCount
                WHERE UID = @UID
            )
            BEGIN

                SET @ResultMessage = 'Details not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;

            END

            SELECT
                @OldLineID = LineID,
                
                @OldLineSpeed = LineSpeed,
                @OldOperatorCount = OperatorCount
            FROM dbo.Config_LineSpeedOperatorCount
            WHERE UID = @UID;

            UPDATE dbo.Config_LineSpeedOperatorCount
            SET
                LineID = CASE
                            WHEN ISNULL(LineID,0) <> ISNULL(@LineID,0)
                            THEN @LineID
                            ELSE LineID
                         END,

               

                LineSpeed = CASE
                               WHEN ISNULL(LineSpeed,0) <> ISNULL(@LineSpeed,0)
                               THEN @LineSpeed
                               ELSE LineSpeed
                            END,

                OperatorCount = CASE
                                   WHEN ISNULL(OperatorCount,0) <> ISNULL(@OperatorCount,0)
                                   THEN @OperatorCount
                                   ELSE OperatorCount
                                END
            WHERE UID = @UID;

            IF ISNULL(@OldLineID,0) <> ISNULL(@LineID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Line Speed Operator Count Configuration',
                    @UID,
                    'LineID',
                    @OldLineID,
                    @LineID,
                    2,
                    @Remark,
                    @UserName
                );
            END


            IF ISNULL(@OldLineSpeed,0) <> ISNULL(@LineSpeed,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Line Speed Operator Count Configuration',
                    @UID,
                    'LineSpeed',
                    @OldLineSpeed,
                    @LineSpeed,
                    2,
                    @Remark,
                    @UserName
                );
            END

            IF ISNULL(@OldOperatorCount,0) <> ISNULL(@OperatorCount,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Line Speed Operator Count Configuration',
                    @UID,
                    'OperatorCount',
                    @OldOperatorCount,
                    @OperatorCount,
                    2,
                    @Remark,
                    @UserName
                );
            END

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;

        END

        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN

            DELETE
            FROM dbo.Config_LineSpeedOperatorCount
            WHERE UID = @UID;

            IF @@ROWCOUNT = 0
            BEGIN

                SET @ResultMessage = 'Details not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;

            END

            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Line Speed Operator Count Configuration',
                @UID,
                'Delete Record',
                '',
                '',
                3,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;

        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END CATCH

END
