CREATE       PROCEDURE [dbo].[BT_Config_LossCategory]
(
    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT, -- 1=ADD, 2=UPDATE, 3=DELETE

    @LossID INT,
    @LossName NVARCHAR(100),
    @LossDesc NVARCHAR(300),
    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)
)
AS
BEGIN

    SET NOCOUNT ON;

    BEGIN TRY

        ----------------------------------------
        -- COMMON VALIDATION
        ----------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF @LossID IS NULL
        BEGIN
            SET @ResultMessage = 'LossID is required';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        ----------------------------------------
        -- INSERT / UPDATE VALIDATION
        ----------------------------------------
        IF @Mode IN (1,2)
        BEGIN

         IF (
                   ISNULL(LTRIM(RTRIM(@LossName)), '') = ''
                 OR ISNULL(LTRIM(RTRIM(@LossID)), 0) = 0
               )
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF @LossName IS NULL OR LTRIM(RTRIM(@LossName)) = ''
            BEGIN
                SET @ResultMessage = 'Loss Name is required';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            --IF @LossDesc IS NULL OR LTRIM(RTRIM(@LossDesc)) = ''
            --BEGIN
            --    SET @ResultMessage = 'Loss Description is required';
            --    SET @ResultStatus = 0;

            --    SELECT @ResultMessage AS ResultMessage,
            --           @ResultStatus AS ResultStatus;
            --    RETURN;
            --END

            IF LEN(@LossName) > 100
            BEGIN
                SET @ResultMessage = 'Loss Name exceeds max length (100)';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(ISNULL(@LossDesc,'')) > 300
            BEGIN
                SET @ResultMessage = 'Loss Description exceeds max length (300)';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

        END

        ----------------------------------------
        -- INSERT
        ----------------------------------------
        IF @Mode = 1
        BEGIN

            IF EXISTS
            (
                SELECT 1
                FROM dbo.Config_LossCategory
                WHERE LossID = @LossID
            )
            BEGIN
                SET @ResultMessage = 'Loss Details already exists';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            INSERT INTO dbo.Config_LossCategory
            (
                LossName,
                LossDesc
            )
            VALUES
            (
                @LossName,
                @LossDesc
            );

            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Loss Category Configuration',
                @LossID,
                'Add Record',
                '',
                '',
                1,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;

            RETURN;
        END

        ----------------------------------------
        -- UPDATE
        ----------------------------------------
        ELSE IF @Mode = 2
        BEGIN

            DECLARE
                @OldLossName NVARCHAR(100),
                @OldLossDesc NVARCHAR(300);

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_LossCategory
                WHERE LossID = @LossID
            )
            BEGIN
                SET @ResultMessage = 'Loss Details not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;

                RETURN;
            END

            SELECT
                @OldLossName = LossName,
                @OldLossDesc = LossDesc
            FROM dbo.Config_LossCategory
            WHERE LossID = @LossID;

            UPDATE dbo.Config_LossCategory
            SET
                LossName =
                    CASE
                        WHEN ISNULL(LossName,'') <> ISNULL(@LossName,'')
                        THEN @LossName
                        ELSE LossName
                    END,

                LossDesc =
                    CASE
                        WHEN ISNULL(LossDesc,'') <> ISNULL(@LossDesc,'')
                        THEN @LossDesc
                        ELSE LossDesc
                    END

            WHERE LossID = @LossID;

            IF ISNULL(@OldLossName,'') <> ISNULL(@LossName,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Loss Category Configuration',
                    @LossID,
                    'LossName',
                    @OldLossName,
                    @LossName,
                    2,
                    @Remark,
                    @UserName
                );
            END

            IF ISNULL(@OldLossDesc,'') <> ISNULL(@LossDesc,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Loss Category Configuration',
                    @LossID,
                    'LossDesc',
                    @OldLossDesc,
                    @LossDesc,
                    2,
                    @Remark,
                    @UserName
                );
            END

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;

            RETURN;
        END

        ----------------------------------------
        -- DELETE
        ----------------------------------------
        ELSE IF @Mode = 3
        BEGIN

            DELETE FROM dbo.Config_LossCategory
            WHERE LossID = @LossID;

            IF @@ROWCOUNT = 0
            BEGIN
                SET @ResultMessage = 'Loss Details not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;

                RETURN;
            END

            INSERT INTO dbo.Config_History
            VALUES
            (
                GETDATE(),
                'Loss Category Configuration',
                @LossID,
                'Delete Record',
                '',
                '',
                3,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;

            RETURN;
        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END CATCH

END
