            IF (
                   ISNULL(@DeviceID,0) = 0
                OR ISNULL(@LineID,0) = 0
                OR ISNULL(@StationID,0) = 0
                OR ISNULL(@StaticIP,'') = ''
                OR ISNULL(@DeviceType,0) = 0
                OR ISNULL(@DeviceStatus,0) = 0
               )
            BEGIN

                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;

            END

            IF LEN(@StaticIP) > 50
            BEGIN

                SET @ResultMessage = 'Static IP exceeds max length (50)';
                SET @ResultStatus = 0;

                RETURN;

            END

            IF LEN(ISNULL(@DeviceDesc,'')) > 300
            BEGIN

                SET @ResultMessage = 'Device description exceeds max length (300)';
                SET @ResultStatus = 0;

                RETURN;

            END

        END
      
        -- ================= INSERT =================
        IF @Mode = 1
        BEGIN
            IF EXISTS (SELECT 1 FROM Config_MobileTerminal WHERE DeviceID = @DeviceID)
            BEGIN
                SET @ResultMessage = 'Device details already exists';
                SET @ResultStatus = 0;
                RETURN;
            END

            INSERT INTO Config_MobileTerminal
            (
                LineID,
                StationID,
                StaticIP,
                DeviceDesc,
                DeviceType,
                DeviceStatus
            )
            VALUES
            (
                @LineID,
                @StationID,
                @StaticIP,
                @DeviceDesc,
                @DeviceType,
                @DeviceStatus
            );

            INSERT INTO Config_History
            (TimeStamp, ScreenName, PrimaryKeyValue, FieldName, OldValue, NewValue, Status, Remark, UpdatedBy)
            VALUES (GETDATE(), 'Mobile Terminal Configuration', @DeviceID, 'Add', '', '', 1, @Remark, @UserName);

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;
        END
       
        -- ================= UPDATE =================
        ELSE IF @Mode = 2
        BEGIN
            DECLARE 
                @OldLineID INT,
                @OldStationID INT,
                @OldStaticIP NVARCHAR(50),
                @OldDeviceDesc NVARCHAR(300),
                @OldDeviceType INT,
                @OldDeviceStatus INT;

            IF NOT EXISTS (SELECT 1 FROM Config_MobileTerminal WHERE DeviceID = @DeviceID)
            BEGIN
                SET @ResultMessage = 'Device details not found';
                SET @ResultStatus = 0;
                RETURN;
            END

            -- ✅ FIXED (no string assignment bug)
            SELECT
                @OldLineID = LineID,
                @OldStationID = StationID,
                @OldStaticIP = StaticIP,
                @OldDeviceDesc = DeviceDesc,
                @OldDeviceType = DeviceType,
                @OldDeviceStatus = DeviceStatus
            FROM Config_MobileTerminal
            WHERE DeviceID = @DeviceID;

            -- ✅ CLEAN UPDATE
            UPDATE Config_MobileTerminal
            SET
                LineID = @LineID,
                StationID = @StationID,
                StaticIP = @StaticIP,
                DeviceDesc = @DeviceDesc,
                DeviceType = @DeviceType,
                DeviceStatus = @DeviceStatus
            WHERE DeviceID = @DeviceID;

            -- ✅ HISTORY
            IF ISNULL(@OldLineID,0) <> ISNULL(@LineID,0)
                INSERT INTO Config_History VALUES (GETDATE(),'Mobile Terminal Configuration',@DeviceID,'LineID',@OldLineID,@LineID,2,@Remark,@UserName);

            IF ISNULL(@OldStationID,0) <> ISNULL(@StationID,0)
                INSERT INTO Config_History VALUES (GETDATE(),'Mobile Terminal Configuration',@DeviceID,'StationID',@OldStationID,@StationID,2,@Remark,@UserName);

            IF ISNULL(@OldStaticIP,'') <> ISNULL(@StaticIP,'')
                INSERT INTO Config_History VALUES (GETDATE(),'Mobile Terminal Configuration',@DeviceID,'StaticIP',@OldStaticIP,@StaticIP,2,@Remark,@UserName);

            IF ISNULL(@OldDeviceDesc,'') <> ISNULL(@DeviceDesc,'')
                INSERT INTO Config_History VALUES (GETDATE(),'Mobile Terminal Configuration',@DeviceID,'DeviceDesc',@OldDeviceDesc,@DeviceDesc,2,@Remark,@UserName);

            IF ISNULL(@OldDeviceType,0) <> ISNULL(@DeviceType,0)
                INSERT INTO Config_History VALUES (GETDATE(),'Mobile Terminal Configuration',@DeviceID,'DeviceType',@OldDeviceType,@DeviceType,2,@Remark,@UserName);

            IF ISNULL(@OldDeviceStatus,0) <> ISNULL(@DeviceStatus,0)
                INSERT INTO Config_History VALUES (GETDATE(),'Mobile Terminal Configuration',@DeviceID,'DeviceStatus',@OldDeviceStatus,@DeviceStatus,2,@Remark,@UserName);

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;
        END

        -- ================= DELETE =================
        ELSE IF @Mode = 3
        BEGIN
            DELETE FROM Config_MobileTerminal
            WHERE DeviceID = @DeviceID;

            IF @@ROWCOUNT = 0
            BEGIN
                SET @ResultMessage = 'Device details not found';
                SET @ResultStatus = 0;
                RETURN;
            END

            INSERT INTO Config_History
            VALUES (GETDATE(), 'Mobile Terminal Configuration', @DeviceID, 'Delete', '', '', 3, @Remark, @UserName);

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;
        END

    END TRY
    BEGIN CATCH
        SET @ResultMessage =ERROR_MESSAGE();
        --SET @ResultMessage ='SQL ERROR';
        SET @ResultStatus = 0;
    END CATCH
END
GO

