-- [40/376] Stored Procedure: [dbo].[BT_Config_Model]
-- Created: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Shubham Patil
-- CREATE OR ALTER OR ALTER date : 26-04-2026
-- Description : Procedure for Add, Modify & Delete Model Configuration.
--               Handles history tracking & exception handling.
-- =============================================

--*************************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY     | DESCRIPTION     |
-----------------------------------------------------------
--| 26-04-2026 | Shubham Patil  | CREATE OR ALTER OR ALTERd         |
-----------------------------------------------------------
--*************************************************************************

CREATE       PROCEDURE [dbo].[BT_Config_Model]
    @ResultMessage VARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT, -- 0 = ERROR , 1 = SUCCESS
    @Mode INT,                -- 1 = ADD, 2 = UPDATE, 3 = DELETE

    -- PARAMETERS FROM GRAPHWORX
    @ModelID INT,
    @ModelFamilyID INT = NULL,
    --@ModelFamilyName NVARCHAR(100) = NULL,
    @ModelName NVARCHAR(100) = NULL,
    @ModelDesc NVARCHAR(300) = NULL,

    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        -- =============================================
        -- COMMON VALIDATION
        -- =============================================

        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;
            SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
            RETURN;
        END

        IF @ModelID IS NULL
        BEGIN
            SET @ResultMessage = 'Model ID is required';
            SET @ResultStatus = 0;
            SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
            RETURN;
        END

        -- =============================================
        -- INSERT / UPDATE VALIDATION
        -- =============================================

        IF @Mode IN (1,2)
        BEGIN
         IF (
                   ISNULL(LTRIM(RTRIM(@ModelName)), '') = ''
                  OR ISNULL(LTRIM(RTRIM(@ModelFamilyID)), 0) = 0
                  OR ISNULL(LTRIM(RTRIM(@ModelID)), 0) = 0
               )
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
            IF @ModelFamilyID IS NULL or @ModelFamilyID = 0
            BEGIN
                SET @ResultMessage = 'Model Family Name is required';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
                RETURN;
            END

            IF @ModelName IS NULL OR LTRIM(RTRIM(@ModelName)) = ''
            BEGIN
                SET @ResultMessage = 'Model Name is required';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(@ModelName) > 100
            BEGIN
                SET @ResultMessage = 'Model Name exceeds max length (100)';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(ISNULL(@ModelDesc,'')) > 300
            BEGIN
                SET @ResultMessage = 'Model Description exceeds max length (300)';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
                RETURN;
            END

        END

        -- =============================================
        -- INSERT MODE
        -- =============================================

        IF @Mode = 1
        BEGIN
            IF EXISTS (SELECT 1 FROM Config_Model WHERE ModelID = @ModelID)
            BEGIN
                SET @ResultMessage = 'Model details already exists';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
                RETURN;
            END

            -- FK Validation
            --BEGIN
            --    SET @ResultMessage = 'Invalid ModelFamilyID';
            --    SET @ResultStatus = 0;
            --    SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
            --    RETURN;
            --END

            INSERT INTO Config_Model
            (
                ModelFamilyID,
                ModelName,
                ModelDesc
            )
            VALUES
            (
                @ModelFamilyID,
                @ModelName,
                @ModelDesc
            );

            -- HISTORY INSERT
            INSERT INTO Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue, FieldName,
                OldValue, NewValue, Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(),'Model Configuration',@ModelID,'Insert',
                ' ',' ',1,@Remark,@UserName
            );

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
        END

        -- =============================================
        -- UPDATE MODE
        -- =============================================

        ELSE IF @Mode = 2
        BEGIN
            DECLARE @OldFamilyID INT;
            DECLARE @OldName NVARCHAR(100);
            DECLARE @OldDesc NVARCHAR(300);

            IF NOT EXISTS (SELECT 1 FROM Config_Model WHERE ModelID = @ModelID)
            BEGIN
                SET @ResultMessage = 'Model details not found';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
                RETURN;
            END

            -- FK Validation
            --BEGIN
            --    SET @ResultMessage = 'Invalid ModelFamilyID';
            --    SET @ResultStatus = 0;
            --    SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
            --    RETURN;
            --END

            -- GET OLD VALUES
            SELECT
                @OldFamilyID = ModelFamilyID,
                @OldName = ModelName,
                @OldDesc = ModelDesc
            FROM Config_Model
            WHERE ModelID = @ModelID;

            -- UPDATE ONLY CHANGED VALUES
            UPDATE Config_Model
            SET
                ModelFamilyID = CASE 
                    WHEN ISNULL(ModelFamilyID,0) <> ISNULL(@ModelFamilyID,0) 
                    THEN @ModelFamilyID ELSE ModelFamilyID END,

                ModelName = CASE 
                    WHEN ISNULL(ModelName,'') <> ISNULL(@ModelName,'') 
                    THEN @ModelName ELSE ModelName END,

                ModelDesc = CASE 
                    WHEN ISNULL(ModelDesc,'') <> ISNULL(@ModelDesc,'') 
                    THEN @ModelDesc ELSE ModelDesc END
            WHERE ModelID = @ModelID;

            -- HISTORY: ModelFamilyID
            IF ISNULL(@OldFamilyID,0) <> ISNULL(@ModelFamilyID,0)
            BEGIN
                INSERT INTO Config_History
                VALUES(GETDATE(),'Model Configuration',@ModelID,'ModelFamilyID',
                CAST(ISNULL(@OldFamilyID,0) AS VARCHAR(100)),
                CAST(ISNULL(@ModelFamilyID,0) AS VARCHAR(100)),2,@Remark,@UserName);
            END

            -- HISTORY: ModelName
            IF ISNULL(@OldName,'') <> ISNULL(@ModelName,'')
            BEGIN
                INSERT INTO Config_History
                VALUES(GETDATE(),'Model Configuration',@ModelID,'ModelName',
                ISNULL(@OldName,''),ISNULL(@ModelName,''),2,@Remark,@UserName);
            END

            -- HISTORY: ModelDesc
            IF ISNULL(@OldDesc,'') <> ISNULL(@ModelDesc,'')
            BEGIN
                INSERT INTO Config_History
                VALUES(GETDATE(),'Model Configuration',@ModelID,'ModelDesc',
                ISNULL(@OldDesc,''),ISNULL(@ModelDesc,''),2,@Remark,@UserName);
            END

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
        END

        -- =============================================
        -- DELETE MODE
        -- =============================================

        ELSE IF @Mode = 3
        BEGIN
            DELETE FROM Config_Model
            WHERE ModelID = @ModelID;

            IF @@ROWCOUNT = 0
            BEGIN
                SET @ResultMessage = 'Model details not found';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
                RETURN;
            END

            INSERT INTO Config_History
            VALUES(GETDATE(),'Model Configuration',@ModelID,'Delete',
            ' ',' ',3,@Remark,@UserName);

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
        END

    END TRY

    BEGIN CATCH
        EXEC RethrowError;

        SET @ResultMessage = 'SQL ERROR';
        --SET @ResultMessage = ERROR_MESSAGE();
        SET @ResultStatus = 0;

        SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
    END CATCH
END
GO

