-- ------------------------------------------------------------------------
-- [42/376] Stored Procedure: [dbo].[BT_Config_NPD]
-- Created: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Vsihal
-- ALTER OR ALTER date : 06-07-2026
-- Description : Procedure for Add, Modify & Delete Buttons
-- =============================================
 
--***************************************************************
--Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION            |
-----------------------------------------------------------
--| 06-07-2026 | Vishal      | ALTER OR ALTERd                |
-----------------------------------------------------------
--***************************************************************/
 
CREATE     PROCEDURE [dbo].[BT_Config_NPD]
 
    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,
    @StartDate DATETIME,
    @EndDate DATETIME,
    @ShiftName NVARCHAR (10),
    @LineName NVARCHAR(50),
    @UserName NVARCHAR(20),
    @Reason NVARCHAR(200),
    @UID INT,
    @Remark NVARCHAR(300) = NULL
AS
BEGIN
    SET NOCOUNT ON;
 
    BEGIN TRY
 
        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;
 
            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END
 
        IF @Mode IN (2,3) AND ISNULL(@UID,0) = 0
        BEGIN
            SET @ResultMessage = 'Select the Data from Grid';
            SET @ResultStatus = 0;
 
            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END
 
        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode = 1
        BEGIN
            IF  ISNULL(@ShiftName,'') = ''
               OR ISNULL(@LineName,'') = ''
               OR ISNULL(@Reason,'') = ''
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;
 
                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
            
            -------------------------------------------------
            -- DUPLICATE VALIDATION
            -------------------------------------------------
            IF EXISTS
            (
                SELECT 1
                FROM dbo.Perf_PlannedShutDown
                WHERE UID = @UID
                  
            )
            BEGIN
                SET @ResultMessage = 'Data already exists';
                SET @ResultStatus = 0;
 
                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
        END
         Declare @LineID as int = ( Select LineID from Config_Line Where LineName = @LineName);
        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN
           
            INSERT INTO dbo.Perf_PlannedShutDown
            (
                Timestamp,
                LineID,
               [ProdShift]
               ,[StartDate]
              ,[EndDate]
              ,[ShutdownReason]
              ,[ShutDownStatus]
              
            )
            VALUES
            (
                GETDATE(),
                @LINEID,
                @ShiftName,
                @StartDate,
                @EndDate,
                @Reason,
                0
                );
             INSERT INTO dbo.Config_History
               VALUES
               (
                    GETDATE(), 'Perf_PlannedShutDown', @UID,
                  'Add Record', '', '',
                 1, '', @UserName
             );
            
 
 
            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;
 
            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END
 
        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN
          
            DECLARE
               @OldStartDate DATETIME,
               @OldEndDate DATETIME,
               @OldShift NVARCHAR(10),
                @OldLineID INT,
                @OldReason NVARCHAR(300);
 
            IF NOT EXISTS
            (
                SELECT 1
               FROM dbo.Perf_PlannedShutDown
               WHERE UID = @UID
           )
            BEGIN
               SET @ResultMessage = 'Record not found';
                SET @ResultStatus = 0;
 
                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
 
           SELECT
               @OldStartDate  = StartDate,
                @OldEndDate  = EndDate,
               @OldShift  = ProdShift,
               @OldLineID = LineID,
                @OldReason  = ShutdownReason
            FROM dbo.Perf_PlannedShutDown
            WHERE UID = @UID;
 
            UPDATE dbo.Perf_PlannedShutDown
            SET
                StartDate   = @StartDate,
                EndDate   = @EndDate,
                LineID   = @LineID,
                ProdShift = @ShiftName,
                ShutdownReason   = @Reason
            WHERE UID = @UID;
 
            IF ISNULL(@OldStartDate,'') <> ISNULL(@StartDate,'')
            BEGIN
                INSERT INTO dbo.Config_History
               VALUES
                (
                    GETDATE(), 'Perf_PlannedShutDown', @UID,
                    'StartDate', @OldStartDate, @StartDate,
                    2, @Remark, @UserName
                );
            END
 
            IF ISNULL(@OldEndDate,'') <> ISNULL(@EndDate,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Perf_PlannedShutDown', @UID,
                    'EndDate', @OldEndDate, @EndDate,
                    2, @Remark, @UserName
                );
            END
 
             IF ISNULL(@OldShift,'') <> ISNULL(@ShiftName,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Perf_PlannedShutDown', @UID,
                    'ProdShift', @OldShift, @ShiftName,
                    2, @Remark, @UserName
                );
            END
 
             IF ISNULL(@OldLineID,'') <> ISNULL(@LineID,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Perf_PlannedShutDown', @UID,
                    'LineID', @OldLineID, @LineID,
                    2, @Remark, @UserName
                );
            END
 
            IF ISNULL(@OldReason,'') <> ISNULL(@Reason,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Perf_PlannedShutDown', @UID,
                    'Reason', @OldReason, @Reason,
                    2, @Remark, @UserName
                );
            END
 
            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;
 
            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END
 
        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
