    @SkillID INT = NULL,
    @SkillLevelID INT = NULL,

    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)

AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
