    @ParameterID INT = NULL,
    @ParameterName NVARCHAR(100),
    @SKUID INT,
    @ParameterType NVARCHAR(100),
    @ParameterSpecification DECIMAL(5,2) = NULL,

    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)

AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF @Mode IN (2,3) AND ISNULL(@UID,0) = 0
        BEGIN
            SET @ResultMessage = 'UID is required';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode IN (1,2)
        BEGIN
            IF ISNULL(@ParameterName,'') = ''
               OR ISNULL(@SKUID,0) = 0
               OR ISNULL(@ParameterType,'') = ''
               OR @ParameterSpecification IS NULL
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            -------------------------------------------------
            -- FK VALIDATION (SKUID)
            -------------------------------------------------
            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_SKU
                WHERE SKUID = @SKUID
            )
            BEGIN
                SET @ResultMessage = 'Invalid SKUID specified';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            -------------------------------------------------
            -- DUPLICATE VALIDATION
            -- (Same ParameterName not allowed twice for the same SKU)
            -------------------------------------------------
            IF EXISTS
            (
                SELECT 1
                FROM dbo.Config_Parameter
                WHERE ParameterName = @ParameterName
                  AND SKUID = @SKUID
                  AND (@Mode = 1 OR UID <> @UID)
            )
            BEGIN
                SET @ResultMessage = 'Parameter already exists for this SKU';
