        ELSE IF @Mode = 2
        BEGIN

            DECLARE
                @OldParameterID INT,
                @OldParameterName NVARCHAR(100),
                @OldSKUID INT,
                @OldParameterType NVARCHAR(100),
                @OldParameterSpecification DECIMAL(5,2);

            IF NOT EXISTS
