                ParameterSpecification = @ParameterSpecification
            WHERE UID = @UID;

            IF ISNULL(@OldParameterID,0) <> ISNULL(@ParameterID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
