            END

            IF ISNULL(@OldParameterName,'') <> ISNULL(@ParameterName,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Parameter Configuration', @UID,
                    'ParameterName', @OldParameterName, @ParameterName,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldSKUID,0) <> ISNULL(@SKUID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Parameter Configuration', @UID,
                    'SKUID', @OldSKUID, @SKUID,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldParameterType,'') <> ISNULL(@ParameterType,'')
