CREATE     PROCEDURE [dbo].[BT_Config_PartVariant]

    @ResultMessage      NVARCHAR(MAX)   OUTPUT,
    @ResultStatus       INT             OUTPUT,
    @Mode               INT,

    @PartID             NVARCHAR(20)    = NULL,
    @EnginePartID       INT             = NULL,
    @PartName           NVARCHAR(100)   = NULL,
    @PartDesc           NVARCHAR(300)   = NULL,
    @PartInspection     INT              =NULL,
    @PartTracking       INT             = NULL,
    @PartInspectionType INT             = NULL,
    @PartInspectionFreq INT             = NULL,
    @PartSamplingLevel  INT             = NULL,
    @PartAddInspFreq    INT             = NULL,
    @PartStockAuditFreq INT             = NULL,

    @Remark             NVARCHAR(300)   = NULL,
    @UserName           NVARCHAR(100)

AS
BEGIN

    SET NOCOUNT ON;

    BEGIN TRY

        ---- PartInspection derived server-side
        --DECLARE @PartInspection INT;
        --SET @PartInspection = CASE WHEN ISNULL(@PartInspectionType, 0) = 0 THEN 0 ELSE 1 END;

        -- =============================================
        -- MODE VALIDATION
        -- =============================================

        IF @Mode NOT IN (1, 2, 3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus  = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        -- =============================================
        -- DELETE VALIDATION
        -- =============================================

        IF @Mode IN (2, 3) AND ISNULL(@PartID, '') = ''
        BEGIN
            SET @ResultMessage = 'PartID is required';
            SET @ResultStatus  = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        -- =============================================
        -- INSERT / UPDATE VALIDATION
        -- =============================================

        IF @Mode IN (1, 2)
        BEGIN

            IF (
                ISNULL(LTRIM(RTRIM(@PartID)),   '') = ''
                OR ISNULL(LTRIM(RTRIM(@PartName)), '') = ''
                OR @PartInspectionType IS NULL
            )
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            -- DUPLICATE CHECK on PartName
            IF EXISTS
            (
                SELECT 1
                FROM dbo.Config_PartVariant
                WHERE PartName = @PartName
                  AND (@Mode = 1 OR PartID <> @PartID)
            )
            BEGIN
                SET @ResultMessage = 'Part already exists';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            -- FK VALIDATION (EnginePartID)
            IF @EnginePartID IS NOT NULL
               AND NOT EXISTS
               (
                   SELECT 1 FROM dbo.Config_EnginePart
                   WHERE EnginePartID = @EnginePartID
               )
            BEGIN
                SET @ResultMessage = 'Invalid EnginePartID';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

        END

        -- =============================================
        -- INSERT MODE
        -- =============================================

        IF @Mode = 1
        BEGIN

            IF EXISTS
            (
                SELECT 1 FROM dbo.Config_PartVariant
                WHERE PartID = @PartID
            )
            BEGIN
                SET @ResultMessage = 'PartID already exists';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            INSERT INTO dbo.Config_PartVariant
            (
                PartID,
                EnginePartID,
                PartName,
                PartDesc,
                PartTracking,
                PartInspection,
                PartInspectionType,
                PartInspectionFreq,
                PartSamplingLevel,
                PartAddInspFreq,
                PartStockAuditFreq
            )
            VALUES
            (
                @PartID,
                @EnginePartID,
                @PartName,
                @PartDesc,
                @PartTracking,
                @PartInspection,
                @PartInspectionType,
                @PartInspectionFreq,
                @PartSamplingLevel,
                @PartAddInspFreq,
                @PartStockAuditFreq
            );

            INSERT INTO dbo.Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(), 'Part Configuration', @PartID,
                'Insert', '', '',
                1, @Remark, @UserName
            );

            SET @ResultMessage = 'Inserted Successfully';
            SET @ResultStatus  = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;

        END

        -- =============================================
        -- UPDATE MODE
        -- =============================================

        ELSE IF @Mode = 2
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1 FROM dbo.Config_PartVariant
                WHERE PartID = @PartID
            )
            BEGIN
                SET @ResultMessage = 'Record not found';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            DECLARE @OldEnginePartID        INT;
            DECLARE @OldPartName            NVARCHAR(100);
            DECLARE @OldPartDesc            NVARCHAR(300);
            DECLARE @OldPartTracking        INT;
            DECLARE @OldPartInspection      INT;
            DECLARE @OldPartInspectionType  INT;
            DECLARE @OldPartInspectionFreq  INT;
            DECLARE @OldPartSamplingLevel   INT;
            DECLARE @OldPartAddInspFreq     INT;
            DECLARE @OldPartStockAuditFreq  INT;

            SELECT
                @OldEnginePartID        = EnginePartID,
                @OldPartName            = PartName,
                @OldPartDesc            = PartDesc,
                @OldPartTracking        = PartTracking,
                @OldPartInspection      = PartInspection,
                @OldPartInspectionType  = PartInspectionType,
                @OldPartInspectionFreq  = PartInspectionFreq,
                @OldPartSamplingLevel   = PartSamplingLevel,
                @OldPartAddInspFreq     = PartAddInspFreq,
                @OldPartStockAuditFreq  = PartStockAuditFreq
            FROM dbo.Config_PartVariant
            WHERE PartID = @PartID;

            UPDATE dbo.Config_PartVariant
            SET
                EnginePartID        = @EnginePartID,
                PartName            = @PartName,
                PartDesc            = @PartDesc,
                PartTracking        = @PartTracking,
                PartInspection      = @PartInspection,
                PartInspectionType  = @PartInspectionType,
                PartInspectionFreq  = @PartInspectionFreq,
                PartSamplingLevel   = @PartSamplingLevel,
                PartAddInspFreq     = @PartAddInspFreq,
                PartStockAuditFreq  = @PartStockAuditFreq
            WHERE PartID = @PartID;

            -- HISTORY
            IF ISNULL(@OldEnginePartID, 0) <> ISNULL(@EnginePartID, 0)
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(),'Part Configuration',@PartID,'EnginePartID',
                 @OldEnginePartID,@EnginePartID,2,@Remark,@UserName);

            IF ISNULL(@OldPartName, '') <> ISNULL(@PartName, '')
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(),'Part Configuration',@PartID,'PartName',
                 @OldPartName,@PartName,2,@Remark,@UserName);

            IF ISNULL(@OldPartDesc, '') <> ISNULL(@PartDesc, '')
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(),'Part Configuration',@PartID,'PartDesc',
                 @OldPartDesc,@PartDesc,2,@Remark,@UserName);

            IF ISNULL(@OldPartTracking, 0) <> ISNULL(@PartTracking, 0)
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(),'Part Configuration',@PartID,'PartTracking',
                 @OldPartTracking,@PartTracking,2,@Remark,@UserName);

            IF ISNULL(@OldPartInspection, 0) <> ISNULL(@PartInspection, 0)
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(),'Part Configuration',@PartID,'PartInspection',
                 @OldPartInspection,@PartInspection,2,@Remark,@UserName);

            IF ISNULL(@OldPartInspectionType, 0) <> ISNULL(@PartInspectionType, 0)
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(),'Part Configuration',@PartID,'PartInspectionType',
                 @OldPartInspectionType,@PartInspectionType,2,@Remark,@UserName);

            IF ISNULL(@OldPartInspectionFreq, 0) <> ISNULL(@PartInspectionFreq, 0)
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(),'Part Configuration',@PartID,'PartInspectionFreq',
                 @OldPartInspectionFreq,@PartInspectionFreq,2,@Remark,@UserName);

            IF ISNULL(@OldPartSamplingLevel, 0) <> ISNULL(@PartSamplingLevel, 0)
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(),'Part Configuration',@PartID,'PartSamplingLevel',
                 @OldPartSamplingLevel,@PartSamplingLevel,2,@Remark,@UserName);

            IF ISNULL(@OldPartAddInspFreq, 0) <> ISNULL(@PartAddInspFreq, 0)
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(),'Part Configuration',@PartID,'PartAddInspFreq',
                 @OldPartAddInspFreq,@PartAddInspFreq,2,@Remark,@UserName);

            IF ISNULL(@OldPartStockAuditFreq, 0) <> ISNULL(@PartStockAuditFreq, 0)
                INSERT INTO dbo.Config_History VALUES
                (GETDATE(),'Part Configuration',@PartID,'PartStockAuditFreq',
                 @OldPartStockAuditFreq,@PartStockAuditFreq,2,@Remark,@UserName);

            SET @ResultMessage = 'Updated Successfully';
            SET @ResultStatus  = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;

        END

        -- =============================================
        -- DELETE MODE
        -- =============================================

        ELSE IF @Mode = 3
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1 FROM dbo.Config_PartVariant
                WHERE PartID = @PartID
            )
            BEGIN
                SET @ResultMessage = 'Record not found';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            DELETE FROM dbo.Config_PartVariant
            WHERE PartID = @PartID;

            INSERT INTO dbo.Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(), 'Part Configuration', @PartID,
                'Delete', '', '',
                3, @Remark, @UserName
            );

            SET @ResultMessage = 'Deleted Successfully';
            SET @ResultStatus  = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;

        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL ERROR';
        SET @ResultStatus  = 0;
        SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;

    END CATCH

END
GO

