-- [46/376] Stored Procedure: [dbo].[BT_Config_Plant]
-- Created: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 30-04-2026
-- Description : Procedure for Add, Modify & Delete Buttons. Also handles data moving to history & exception handling.
-- =============================================

--***************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION                    |
-----------------------------------------------------------
--| 30-04-2026 | Sumit      | CREATE OR ALTER OR ALTERd                        |
--| 30-04-2026 | Sumit      | Standardized as per document   |
--| 06-05-2026 | Sumit      | changed screen name and error message to sql error   |
-----------------------------------------------------------
--***************************************************************/

 CREATE       PROCEDURE [dbo].[BT_Config_Plant]
(
    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT, -- 1=ADD, 2=UPDATE, 3=DELETE

    @PlantID INT,
    @PlantName NVARCHAR(100),
    @PlantDesc NVARCHAR(300),
    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        ----------------------------------------
        -- COMMON VALIDATION
        ----------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified';
            SET @ResultStatus = 0;
            RETURN;
        END

        IF @PlantID IS NULL
        BEGIN
            SET @ResultMessage = 'Plant ID is required';
            SET @ResultStatus = 0;
            RETURN;
        END

        ----------------------------------------
        -- INSERT / UPDATE VALIDATION
        ----------------------------------------
        IF @Mode IN (1,2)
        BEGIN

         IF (
                   ISNULL(LTRIM(RTRIM(@PlantName)), '') = ''
               -- OR ISNULL(LTRIM(RTRIM(@PlantDesc)), '') = ''
               )
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END


            --IF @PlantName IS NULL OR LTRIM(RTRIM(@PlantName)) = ''
            --BEGIN
            --    SET @ResultMessage = 'Plant Name is required';
            --    SET @ResultStatus = 0;
            --    RETURN;
            --END

            --IF @PlantDesc IS NULL OR LTRIM(RTRIM(@PlantDesc)) = ''
            --BEGIN
            --    SET @ResultMessage = 'Plant Description is required';
            --    SET @ResultStatus = 0;
            --    RETURN;
            --END

            IF LEN(@PlantName) > 100
            BEGIN
                SET @ResultMessage = 'Plant Name exceeds max length (100)';
                SET @ResultStatus = 0;
                RETURN;
            END

            IF LEN(ISNULL(@PlantDesc,'')) > 300
            BEGIN
                SET @ResultMessage = 'Plant Description exceeds max length (300)';
                SET @ResultStatus = 0;
                RETURN;
            END
        END

        ----------------------------------------
        -- INSERT
        ----------------------------------------
        IF @Mode = 1
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.Config_Plant WHERE PlantID = @PlantID)
            BEGIN
                SET @ResultMessage = 'Plant details already exists';
                SET @ResultStatus = 0;
                RETURN;
            END

            INSERT INTO dbo.Config_Plant
            (
                PlantName,
                PlantDesc
            )
            VALUES
            (
                @PlantName,
                @PlantDesc
            );

            INSERT INTO dbo.Config_History
            (TimeStamp, ScreenName, PrimaryKeyValue, FieldName, OldValue, NewValue, Status, Remark, UpdatedBy)
            VALUES
            (GETDATE(), 'Plant Configuration', @PlantID, 'Add Record', '', '', 1, @Remark, @UserName);

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;
            RETURN;
        END

        ----------------------------------------
        -- UPDATE
        ----------------------------------------
        ELSE IF @Mode = 2
        BEGIN
            DECLARE 
                @OldPlantName NVARCHAR(100),
                @OldPlantDesc NVARCHAR(300);

            IF NOT EXISTS (SELECT 1 FROM dbo.Config_Plant WHERE PlantID = @PlantID)
            BEGIN
                SET @ResultMessage = 'Please select the row for updating new values';
                SET @ResultStatus = 0;
                RETURN;
            END

            SELECT
                @OldPlantName = PlantName,
                @OldPlantDesc = PlantDesc
            FROM dbo.Config_Plant
            WHERE PlantID = @PlantID;

            UPDATE dbo.Config_Plant
            SET
                PlantName = CASE 
                                WHEN ISNULL(PlantName,'') <> ISNULL(@PlantName,'') 
                                THEN @PlantName 
                                ELSE PlantName 
                            END,
                PlantDesc = CASE 
                                WHEN ISNULL(PlantDesc,'') <> ISNULL(@PlantDesc,'') 
                                THEN @PlantDesc 
                                ELSE PlantDesc 
                            END
            WHERE PlantID = @PlantID;

            -- HISTORY
            IF ISNULL(@OldPlantName,'') <> ISNULL(@PlantName,'')
            BEGIN
                INSERT INTO dbo.Config_History
                (TimeStamp,ScreenName,PrimaryKeyValue,FieldName,OldValue,NewValue,Status,Remark,UpdatedBy)
                VALUES
                (GETDATE(),'Plant Configuration',@PlantID,'PlantName',@OldPlantName,@PlantName,2,@Remark,@UserName);
            END

            IF ISNULL(@OldPlantDesc,'') <> ISNULL(@PlantDesc,'')
            BEGIN
                INSERT INTO dbo.Config_History
                (TimeStamp,ScreenName,PrimaryKeyValue,FieldName,OldValue,NewValue,Status,Remark,UpdatedBy)
                VALUES
                (GETDATE(),'Plant Configuration',@PlantID,'PlantDesc',@OldPlantDesc,@PlantDesc,2,@Remark,@UserName);
            END

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;
            RETURN;
        END

        ----------------------------------------
        -- DELETE
        ----------------------------------------
        ELSE IF @Mode = 3
        BEGIN
            DELETE FROM dbo.Config_Plant
            WHERE PlantID = @PlantID;

            IF @@ROWCOUNT = 0
            BEGIN
                SET @ResultMessage = 'Please select the row properly for deleting the record';
                SET @ResultStatus = 0;
                RETURN;
            END

            INSERT INTO dbo.Config_History
            (TimeStamp, ScreenName, PrimaryKeyValue, FieldName, OldValue, NewValue, Status, Remark, UpdatedBy)
            VALUES
            (GETDATE(), 'Plant Configuration', @PlantID, 'Delete Record', '', '', 3, @Remark, @UserName);

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;
            RETURN;
        END

    END TRY

    BEGIN CATCH
        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL ERROR';
        SET @ResultStatus = 0;
    END CATCH
END
GO

