-- [47/376] Stored Procedure: [dbo].[BT_Config_PMCheckList]
-- Created: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : <Muskan Singh>
-- CREATE OR ALTER OR ALTER date : 23-04-2026
-- Description : Procedure for Add, Modify & Delete Buttons. Also handles data moving to history & exception handling.
-- =============================================

--*************************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY     | DESCRIPTION     |
-----------------------------------------------------------
--| 23-04-2026 | <Muskan Singh>  | CREATE OR ALTER OR ALTERd         |
-----------------------------------------------------------
--*************************************************************************

CREATE       PROCEDURE [dbo].[BT_Config_PMCheckList]
    @ResultMessage VARCHAR(MAX) OUTPUT,   -- ERROR HANDLING STORED IN THIS OUTPUT VARIABLE
    @ResultStatus INT OUTPUT,             -- 0 = ERROR(RED) , 1=SUCCESS(GREEN)
    @Mode INT,                            -- 1 = ADD, 2 = UPDATE, 3 = DELETE

    /*ADD PARAMETERS RELATED TO THE GRAPHWORX SCREEN*/
    @CheckListID INT,                       -- PRIMARY KEY OF TABLE
    @CheckListName NVARCHAR(100),
	@CheckListDesc NVARCHAR(300),
    @EquipmentID INT,
    @Remark NVARCHAR(300) = NULL,        -- ON UPDATE/DELETE USER ENTERS REMARK FROM GRAPHWORX SCREEN
    @UserName NVARCHAR(100)              -- USER ID/NAME IS PASSED FROM THE GRAPHWORX SCREEN 
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        
        -- COMMON VALIDATION
        -- CHECKS WHETHER MODE IS VALID OR NOT
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        /*CHANGE PARAMETER NAME AND FIELD NAME IN THE MESSAGE*/ 
        -- CHECK PRIMARY KEY SHOULD NOT BE NULL
        IF @CheckListID IS NULL
        BEGIN
	            SET @ResultMessage = 'Check List ID is required';
				SET @ResultStatus = 0;
				SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	            RETURN;
	        END

        -- VALIDATION FOR INSERT / UPDATE ONLY
        IF @Mode IN (1,2)
        BEGIN
        IF (
            ISNULL(@EquipmentID, 0) = 0
            OR ISNULL(LTRIM(RTRIM(@CheckListName)), '') = ''
           )
			BEGIN
				SET @ResultMessage = 'Fill all mandatory fields';
				SET @ResultStatus = 0;

				SELECT
					@ResultMessage AS ResultMessage,
					@ResultStatus AS ResultStatus;
				RETURN;
			END

            /*CHANGE PARAMETER NAME AND FIELD NAME IN THE MESSAGE*/
            /*ADD ALL THE FIELDS WHICH ARE NOT NULL*/
            -- REQUIRED FIELD VALIDATION
          IF @CheckListName IS NULL OR LTRIM(RTRIM(@CheckListName)) = '' 
           BEGIN
	          SET @ResultMessage = 'Check List Name is required';
			  SET @ResultStatus = 0;
			  SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	          RETURN;
           END

   --         IF @CheckListDesc IS NULL OR LTRIM(RTRIM(@CheckListDesc)) = ''    
   --         BEGIN
   --             SET @ResultMessage = 'Check List Description is required';
			--	SET @ResultStatus = 0;
			--SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
   --             RETURN;
   --         END

			IF @EquipmentID IS NULL OR LTRIM(RTRIM(@EquipmentID)) = '' 
            BEGIN
                SET @ResultMessage = 'Equipment name is required';
				SET @ResultStatus = 0;
			SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            /*CHANGE PARAMETER NAME AND FIELD NAME IN THE MESSAGE*/
            /*ADD ALL THE FIELDS WHICH REQUIRES CHARACTER LENGTH VALIDATION*/
            /*USE THIS EXCEPTION HANDLING ONLY FOR FIELDS WITH STRING DATATYPE*/

            -- LENGTH VALIDATION
            IF LEN(@CheckListName) > 100
            BEGIN
				
                SET @ResultMessage = 'Check List Name exceeds max length (100)';
				SET @ResultStatus = 0;
				SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
				RETURN;
            END

            -- LENGTH VALIDATION FOR DESCRIPTION FIELD
            IF LEN(ISNULL(@CheckListDesc,'')) > 300
            BEGIN
                SET @ResultMessage = 'Check List Description exceeds max length (300)';
				SET @ResultStatus = 0;
				SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END
	
        END
        
        -- INSERT MODE
        IF @Mode = 1
        BEGIN
            /*RENAME TABLE COLUMN AND PARAMETERS NAME */

            -- CHECKS IF RECORD ALREADY EXISTS
            IF EXISTS (SELECT 1 FROM Config_PMCheckList WHERE CheckListID = @CheckListID)
            BEGIN
                SET @ResultMessage = 'Check List details already exists';
				SET @ResultStatus = 0;
				SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
				RETURN;
            END
	
			-- ❌ If not found
			IF @EquipmentId IS NULL
			BEGIN
				SET @ResultMessage = 'Invalid Equipment Name';
				SET @ResultStatus = 0;
				SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
				RETURN;
			END
			
            /*RENAME TABLE COLUMN AND PARAMETERS NAME */
            -- INSERT NEW RECORD
            INSERT INTO Config_PMCheckList
	            (
	                
                    EquipmentID,
	                CheckListName,
	                CheckListDesc
	            )
	            VALUES
	            (
	              
                    @EquipmentId,
	                @CheckListName,
	                @CheckListDesc
	            );

            -- INSERT HISTORY FOR ADD OPERATION
            INSERT INTO Config_History (TimeStamp, ScreenName, PrimaryKeyValue, FieldName, OldValue, NewValue, Status, Remark, UpdatedBy)
            VALUES (GETDATE(), 'PM Check List Configuration', @CheckListID, 'Add Record', ' ', ' ', 1, @Remark, @UserName);
	            

            -- SUCCESS MESSAGE
            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

        -- UPDATE MODE
        ELSE IF @Mode = 2
        BEGIN
			/*DECLARE THE PARAMETERS TO STORE THE VALUE BEFORE UPDATE*/
			DECLARE @OldCheckListID INT;
			DECLARE @OldEquipmentName VARCHAR(100);
	        DECLARE @OldCheckListName VARCHAR(100);
	       	DECLARE @OldCheckListDesc VARCHAR(300);
			DECLARE @OldEquipmentId INT;

             
        /*RENAME TABLE COLUMN AND PARAMETERS NAME */
        -- CHECK IF RECORD EXISTS
        IF NOT EXISTS (SELECT 1 FROM Config_PMCheckList WHERE CheckListId = @CheckListID)
	    BEGIN
	        SET @ResultMessage = 'Check List details not found';
	        SET @ResultStatus = 0;
			SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	        RETURN;
	    END

		/*RENAME THE DECLARED PARAMETERS AS PER YOUR PARAMETERS DECLARED ABOVE */
		-- GET OLD VALUES
		SELECT
	        @OldCheckListID = CheckListID,
            @OldEquipmentId = EquipmentID,
	        @OldCheckListName = CheckListName,
	        @OldCheckListDesc = CheckListDesc
	    FROM Config_PMCheckList
	    WHERE CheckListID = @CheckListID;
           
        /*RENAME AND ADD THE PARAMETERS AS PER YOUR TABLE*/
        -- UPDATE ONLY CHANGED VALUES
        UPDATE Config_PMCheckList
	    SET
        CheckListName = CASE 
             WHEN ISNULL(CheckListName,'') <> ISNULL(@CheckListName,'') 
             THEN @CheckListName 
             ELSE CheckListName 
        END,
		EquipmentID = CASE 
			WHEN ISNULL(EquipmentID,0) <> ISNULL(@EquipmentId,0) 
			THEN @EquipmentId
			ELSE EquipmentID
        END,

        CheckListDesc = CASE 
                    WHEN ISNULL(CheckListDesc,'') <> ISNULL(@CheckListDesc,'') 
                    THEN @CheckListDesc 
                    ELSE CheckListDesc 
	    END
	    WHERE CheckListID = @CheckListID;
	    
        /* BELOW INSERT STATEMENTS ARE USED TO MAINTAIN THE HISTORY BEFORE AND AFTER UPDATE FOR EACH COLUMN */

        -- CheckListName History
		/*RENAME AND ADD THE PARAMETERS AS PER YOUR TABLE*/
	    IF ISNULL(@OldCheckListName,'') <> ISNULL(@CheckListName,'')
	    BEGIN
	        INSERT INTO Config_History(TimeStamp,ScreenName,PrimaryKeyValue,FieldName,OldValue,NewValue,Status,Remark, UpdatedBy)
	        VALUES(GETDATE(),'PM Check List Configuration',@CheckListID,'CheckListName',ISNULL(@OldCheckListName,''),ISNULL(@CheckListName,''),2,@Remark,@UserName);
	    END
	
	    -- CheckListDesc History
		/*RENAME AND ADD THE PARAMETERS AS PER YOUR TABLE*/
	    IF ISNULL(@OldCheckListDesc,'') <> ISNULL(@CheckListDesc,'')
	    BEGIN
	        INSERT INTO Config_History(TimeStamp,ScreenName,PrimaryKeyValue,FieldName,OldValue,NewValue,Status,Remark,UpdatedBy)
	        VALUES(GETDATE(),'PM Check List Configuration',@CheckListID,'CheckListDesc',ISNULL(@OldCheckListDesc,''),ISNULL(@CheckListDesc,''),2,@Remark,@UserName);
	    END
    -- Equipment History
        IF ISNULL(@OldEquipmentId,0) <> ISNULL(@EquipmentId,0)
        BEGIN
            INSERT INTO Config_History
            (TimeStamp,ScreenName,PrimaryKeyValue,FieldName,OldValue,NewValue,Status,Remark,UpdatedBy)
            VALUES
            (GETDATE(),'PM Check List Configuration',@CheckListID,'EquipmentID',ISNULL(@OldEquipmentId,''),ISNULL(@EquipmentId,''),2,@Remark,@UserName);
        END
            -- SUCCESS MESSAGE
            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END     

        -- DELETE MODE
        ELSE IF @Mode = 3
        BEGIN
            /*RENAME THE COLUMN NAME AND TABLE NAME */

            -- DELETE RECORD
            DELETE FROM Config_PMCheckList WHERE CheckListID = @CheckListID;

            -- CHECK IF RECORD EXISTS
            IF @@ROWCOUNT = 0
	            BEGIN
	                SET @ResultMessage = 'Check List details not found';
					SET @ResultStatus = 0;
					SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	                RETURN;
	            END

            /*RENAME AND ADD THE PARAMETERS AS PER YOUR TABLE*/

            -- INSERT DELETE HISTORY
            INSERT INTO Config_History (TimeStamp, ScreenName, PrimaryKeyValue, FieldName, OldValue, NewValue, Status, Remark, UpdatedBy)
                VALUES (GETDATE(), 'PM Check List Configuration', @CheckListID, 'Delete Record', ' ', ' ', 3, @Remark, @UserName);
	           
            -- SUCCESS MESSAGE
            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

    END TRY

    BEGIN CATCH
        -- ERROR HANDLING
		EXEC RethrowError;--If procedure fails to execute, the error message will be stored in SP_ERROR_LOG

        --SET @ResultMessage = ERROR_MESSAGE();-- ERROR HANDLING MESSAGE IS SET TO THE OUTPUT VARIABLE
        SET @ResultMessage = 'SQL ERROR';
        SET @ResultStatus = 0;
        SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
    END CATCH
END
GO

