-- [48/376] Stored Procedure: [dbo].[BT_Config_PMCheckPoints]
-- Created: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Shubham Patil
-- CREATE OR ALTER OR ALTER date : 09-05-2026
-- Description : Procedure for Add, Modify & Delete PM CheckPoints
-- =============================================
 
--*************************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY     | DESCRIPTION     |
-----------------------------------------------------------
--| 09-05-2026 | Shubham Patil  | CREATE OR ALTER OR ALTERd         |
-----------------------------------------------------------
--*************************************************************************
 
CREATE       PROCEDURE [dbo].[BT_Config_PMCheckPoints]
 
    @ResultMessage VARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
 
    @Mode INT, -- 1 = ADD, 2 = UPDATE, 3 = DELETE
 
    @CheckPointId INT,
    @CheckListId INT,
    @CheckPointName NVARCHAR(100),
    @Standards NVARCHAR(50),
    @Frequency INT,
    @PlannedDuration INT,
    @Observation NVARCHAR(MAX),
 
    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)
 
AS
BEGIN
 
    SET NOCOUNT ON;
 
    BEGIN TRY
 
        -- MODE VALIDATION
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified';
            SET @ResultStatus = 0;
 
            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END
 
        -- PRIMARY KEY VALIDATION
        IF @CheckPointId IS NULL
        BEGIN
            SET @ResultMessage = 'Check Point Id is required';
            SET @ResultStatus = 0;
 
            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

            IF (TRY_CAST(@Frequency AS INT) IS NULL OR TRY_CAST(@PlannedDuration AS INT) IS NULL)
            BEGIN
                SET @ResultMessage = 'Please enter only integer values.';
                SET @ResultStatus = 0;
 
                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
 
        -- INSERT / UPDATE VALIDATION
        IF @Mode IN (1,2)
        BEGIN

        IF (
               ISNULL(@CheckListId, 0) = 0
            OR ISNULL(LTRIM(RTRIM(@CheckPointName)), '') = ''
            OR ISNULL(LTRIM(RTRIM(@Standards)), '') = ''
            OR ISNULL(@Frequency, 0) = 0
            OR ISNULL(@PlannedDuration, 0) = 0
            OR ISNULL(LTRIM(RTRIM(@Observation)), '') = ''
           )
        BEGIN
            SET @ResultMessage = 'Fill all mandatory fields';
            SET @ResultStatus = 0;

            SELECT
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

            RETURN;
        END
        
            -- FOREIGN KEY VALIDATION
            IF NOT EXISTS
            (
                SELECT 1
                FROM Config_PMCheckList
                WHERE CheckListId = @CheckListId
            )
            BEGIN
                SET @ResultMessage = 'Check List details not found';
                SET @ResultStatus = 0;
 
                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
 
            -- LENGTH VALIDATION
            IF LEN(@CheckPointName) > 100
            BEGIN
                SET @ResultMessage = 'Check Point Name exceeds max length (100)';
                SET @ResultStatus = 0;
 
                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
 
            IF LEN(@Standards) > 50
            BEGIN
                SET @ResultMessage = 'Standards exceeds max length (50)';
                SET @ResultStatus = 0;
 
                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
        END
 
        -- INSERT MODE
        IF @Mode = 1
        BEGIN
 
            -- CHECK DUPLICATE
            IF EXISTS
            (
                SELECT 1
                FROM Config_PMCheckPoints
                WHERE CheckPointId = @CheckPointId
            )
            BEGIN
                SET @ResultMessage = 'Check Point details already exists';
                SET @ResultStatus = 0;
 
                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
 
            -- INSERT RECORD
            INSERT INTO Config_PMCheckPoints
            (
                CheckListId,
                CheckPointName,
                Standards,
                Frequency,
                PlannedDuration,
                Observation
            )
            VALUES
            (
                @CheckListId,
                @CheckPointName,
                @Standards,
                @Frequency,
                @PlannedDuration,
                @Observation
            );
 
            -- HISTORY
            INSERT INTO Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'PM CheckPoints Configuration',
                @CheckPointId,
                'Add Record',
                '',
                '',
                1,
                @Remark,
                @UserName
            );
 
            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;
 
            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END
 
        -- UPDATE MODE
        ELSE IF @Mode = 2
        BEGIN
 
            DECLARE @OldCheckListId INT
            DECLARE @OldCheckPointName NVARCHAR(100)
            DECLARE @OldStandards NVARCHAR(50)
            DECLARE @OldFrequency INT
            DECLARE @OldPlannedDuration INT
            DECLARE @OldObservation NVARCHAR(MAX)
 
            -- CHECK RECORD EXISTS
            IF NOT EXISTS
            (
                SELECT 1
                FROM Config_PMCheckPoints
                WHERE CheckPointId = @CheckPointId
            )
            BEGIN
                SET @ResultMessage = 'Check Point details not found';
                SET @ResultStatus = 0;
 
                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
 
            -- OLD VALUES
            SELECT
                @OldCheckListId = CheckListId,
                @OldCheckPointName = CheckPointName,
                @OldStandards = Standards,
                @OldFrequency = Frequency,
                @OldPlannedDuration = PlannedDuration,
                @OldObservation = Observation
            FROM Config_PMCheckPoints
            WHERE CheckPointId = @CheckPointId;
 
            -- UPDATE
            UPDATE Config_PMCheckPoints
            SET
                CheckListId = @CheckListId,
                CheckPointName = @CheckPointName,
                Standards = @Standards,
                Frequency = @Frequency,
                PlannedDuration = @PlannedDuration,
                Observation = @Observation
            WHERE CheckPointId = @CheckPointId;
 
            -- HISTORY INSERTS
 
            IF ISNULL(@OldCheckPointName,'') <> ISNULL(@CheckPointName,'')
            BEGIN
                INSERT INTO Config_History
                VALUES
                (
                    GETDATE(),
                    'PM CheckPoints Configuration',
                    @CheckPointId,
                    'CheckPointName',
                    @OldCheckPointName,
                    @CheckPointName,
                    2,
                    @Remark,
                    @UserName
                );
            END
 
            IF ISNULL(@OldStandards,'') <> ISNULL(@Standards,'')
            BEGIN
                INSERT INTO Config_History
                VALUES
                (
                    GETDATE(),
                    'PM CheckPoints Configuration',
                    @CheckPointId,
                    'Standards',
                    @OldStandards,
                    @Standards,
                    2,
                    @Remark,
                    @UserName
                );
            END
 
            IF ISNULL(@OldFrequency,0) <> ISNULL(@Frequency,0)
            BEGIN
                INSERT INTO Config_History
                VALUES
                (
                    GETDATE(),
                    'PM CheckPoints Configuration',
                    @CheckPointId,
                    'Frequency',
                    @OldFrequency,
                    @Frequency,
                    2,
                    @Remark,
                    @UserName
                );
            END
 
            IF ISNULL(@OldPlannedDuration,0) <> ISNULL(@PlannedDuration,0)
            BEGIN
                INSERT INTO Config_History
                VALUES
                (
                    GETDATE(),
                    'PM CheckPoints Configuration',
                    @CheckPointId,
                    'PlannedDuration',
                    @OldPlannedDuration,
                    @PlannedDuration,
                    2,
                    @Remark,
                    @UserName
                );
            END
 
            IF ISNULL(@OldObservation,'') <> ISNULL(@Observation,'')
            BEGIN
                INSERT INTO Config_History
                VALUES
                (
                    GETDATE(),
                    'PM CheckPoints Configuration',
                    @CheckPointId,
                    'Observation',
                    @OldObservation,
                    @Observation,
                    2,
                    @Remark,
                    @UserName
                );
            END
 
            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;
 
            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END
 
        -- DELETE MODE
        ELSE IF @Mode = 3
        BEGIN
 
            DELETE FROM Config_PMCheckPoints
            WHERE CheckPointId = @CheckPointId;
 
            IF @@ROWCOUNT = 0
            BEGIN
                SET @ResultMessage = 'Check Point details not found';
                SET @ResultStatus = 0;
 
                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
 
            -- DELETE HISTORY
            INSERT INTO Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'PM CheckPoints Configuration',
                @CheckPointId,
                'Delete Record',
                '',
                '',
                3,
                @Remark,
                @UserName
            );
 
            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;
 
            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END
 
    END TRY
 
    BEGIN CATCH
 
        EXEC RethrowError;
 
        SET @ResultMessage = ERROR_MESSAGE();
        --SET @ResultMessage = 'SQL ERROR';
        SET @ResultStatus = 0;
 
        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;
 
    END CATCH
 
END
GO

-- ------------------------------------------------------------------------
-- [49/376] Stored Procedure: [dbo].[BT_Config_PMSchedule]
-- Created: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : <Muskan Singh>
-- CREATE OR ALTER OR ALTER date : 01-05-2026
-- Description : Procedure for Add, Modify & Delete Buttons. Also handles data moving to history & exception handling.
-- =============================================

--*************************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY     | DESCRIPTION     |
-----------------------------------------------------------
--| 01-05-2026 | Muskan Singh   | Altered        |
-----------------------------------------------------------
--| 23-05-2026 | Mamatha M      | Changed query for Frequency Type and its input parameter datatype from nvarchar(20) to Int|
-----------------------------------------------------------
--| 30-07-2026 | Fix            | Corrected FrequencyType validation (was using LTRIM/RTRIM on an INT param) |
--|            |                | and added missing history tracking for StartCount, FrequencyType, Alert, EstimatedDuration |
-----------------------------------------------------------
--*************************************************************************
CREATE       PROCEDURE [dbo].[BT_Config_PMSchedule]
    @ResultMessage VARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,   -- 0 = ERROR, 1 = SUCCESS
    @Mode INT,                 -- 1 = ADD, 2 = UPDATE, 3 = DELETE

    @UID INT = NULL,           -- PK (Identity for Update/Delete)
    @LineId INT,
    @CheckListId INT,
    @StartDate DATE,
    @StartCount INT,
    @FrequencyType INT,
    @FrequencyValue INT,
    @Alert INT,
    @EstimatedDuration INT,

    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

    -------------------------------------------------
    -- COMMON VALIDATION
    -------------------------------------------------
    IF @Mode NOT IN (1,2,3)
    BEGIN
        SET @ResultMessage = 'Invalid Mode specified';
        SET @ResultStatus = 0;

        SELECT
            @ResultMessage AS ResultMessage,
            @ResultStatus AS ResultStatus;

        RETURN;
    END

    -------------------------------------------------
    -- INSERT / UPDATE VALIDATION
    -------------------------------------------------
    IF @Mode IN (1,2)
    BEGIN

         IF (
               ISNULL(@LineId, 0) = 0
            OR ISNULL(@CheckListId, 0) = 0
            OR @StartDate IS NULL
            OR ISNULL(@StartCount, 0) = 0
            OR ISNULL(@FrequencyType, 0) = 0        -- FIX: was LTRIM(RTRIM(@FrequencyType)) on an INT param
            OR ISNULL(@FrequencyValue, 0) = 0
            OR ISNULL(@Alert, 0) = 0
            OR ISNULL(@EstimatedDuration, 0) = 0
            )
        BEGIN
            SET @ResultMessage = 'Fill all mandatory fields';
            SET @ResultStatus = 0;

            SELECT
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

            RETURN;
        END
    END

    -------------------------------------------------
    -- INSERT
    -------------------------------------------------
    IF @Mode = 1
    BEGIN
        INSERT INTO Config_PMSchedule
        (
            LineId,
            CheckListId,
            StartDate,
            StartCount,
            FrequencyType,
            FrequencyValue,
            Alert,
            EstimatedDuration
        )
        VALUES
        (
            @LineId,
            @CheckListId,
            CAST(@StartDate AS DATE),
            @StartCount,
            @FrequencyType,
            @FrequencyValue,
            @Alert,
            @EstimatedDuration
        );

        DECLARE @NewUID INT = SCOPE_IDENTITY();

        INSERT INTO Config_History
        (TimeStamp, ScreenName, PrimaryKeyValue, FieldName, OldValue, NewValue, Status, Remark, UpdatedBy)
        VALUES
        (GETDATE(),'PM Schedule Configuration',@NewUID,'Insert',' ',' ',1,@Remark,@UserName);

        SET @ResultMessage = 'Inserted successfully';
        SET @ResultStatus = 1;
    END

    -------------------------------------------------
    -- UPDATE
    -------------------------------------------------
    ELSE IF @Mode = 2
    BEGIN
        DECLARE 
            @OldLineId INT,
            @OldCheckListId INT,
            @OldStartDate DATE,
            @OldStartCount INT,
            @OldFrequencyType1 INT,
            @OldFrequencyValue INT,
            @OldAlert INT,
            @OldEstimatedDuration INT;

        IF NOT EXISTS (SELECT 1 FROM Config_PMSchedule WHERE UID = @UID)
        BEGIN
            SET @ResultMessage = 'Schedule details not found';
            SET @ResultStatus = 0;

            SELECT
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

            RETURN;
        END

        SELECT
            @OldLineId = LineId,
            @OldCheckListId = CheckListId,
            @OldStartDate = StartDate,
            @OldStartCount = StartCount,
            @OldFrequencyType1 = FrequencyType,
            @OldFrequencyValue = FrequencyValue,
            @OldAlert = Alert,
            @OldEstimatedDuration = EstimatedDuration
        FROM Config_PMSchedule
        WHERE UID = @UID;

        UPDATE Config_PMSchedule
        SET
            LineId = ISNULL(@LineId, LineId),
            CheckListId = ISNULL(@CheckListId, CheckListId),
            StartDate = ISNULL(@StartDate, StartDate),
            StartCount = ISNULL(@StartCount, StartCount),
            FrequencyType = ISNULL(@FrequencyType, FrequencyType),
            FrequencyValue = ISNULL(@FrequencyValue, FrequencyValue),
            Alert = ISNULL(@Alert, Alert),
            EstimatedDuration = ISNULL(@EstimatedDuration, EstimatedDuration)
        WHERE UID = @UID;

        -------------------------------------------------
        -- HISTORY TRACKING
        -------------------------------------------------

        IF ISNULL(@OldLineId,0) <> ISNULL(@LineId,0)
        INSERT INTO Config_History VALUES(GETDATE(),'PM Schedule Configuration',@UID,'LineId',
        CAST(@OldLineId AS VARCHAR),CAST(@LineId AS VARCHAR),2,@Remark,@UserName);

        IF ISNULL(@OldCheckListId,0) <> ISNULL(@CheckListId,0)
        INSERT INTO Config_History VALUES(GETDATE(),'PM Schedule Configuration',@UID,'CheckListId',
        CAST(@OldCheckListId AS VARCHAR),CAST(@CheckListId AS VARCHAR),2,@Remark,@UserName);

        IF ISNULL(@OldStartDate,'') <> ISNULL(@StartDate,'')
        INSERT INTO Config_History VALUES(GETDATE(),'PM Schedule Configuration',@UID,'StartDate',
        CAST(@OldStartDate AS VARCHAR),CAST(@StartDate AS VARCHAR),2,@Remark,@UserName);

        -- FIX: was missing (variable was captured but never compared/logged)
        IF ISNULL(@OldStartCount,0) <> ISNULL(@StartCount,0)
        INSERT INTO Config_History VALUES(GETDATE(),'PM Schedule Configuration',@UID,'StartCount',
        CAST(@OldStartCount AS VARCHAR),CAST(@StartCount AS VARCHAR),2,@Remark,@UserName);

        -- FIX: was missing (variable was captured but never compared/logged)
        IF ISNULL(@OldFrequencyType1,0) <> ISNULL(@FrequencyType,0)
        INSERT INTO Config_History VALUES(GETDATE(),'PM Schedule Configuration',@UID,'FrequencyType',
        CAST(@OldFrequencyType1 AS VARCHAR),CAST(@FrequencyType AS VARCHAR),2,@Remark,@UserName);

        IF ISNULL(@OldFrequencyValue,0) <> ISNULL(@FrequencyValue,0)
        INSERT INTO Config_History VALUES(GETDATE(),'PM Schedule Configuration',@UID,'FrequencyValue',
        CAST(@OldFrequencyValue AS VARCHAR),CAST(@FrequencyValue AS VARCHAR),2,@Remark,@UserName);

        -- FIX: was missing (variable was captured but never compared/logged)
        IF ISNULL(@OldAlert,0) <> ISNULL(@Alert,0)
        INSERT INTO Config_History VALUES(GETDATE(),'PM Schedule Configuration',@UID,'Alert',
        CAST(@OldAlert AS VARCHAR),CAST(@Alert AS VARCHAR),2,@Remark,@UserName);

        -- FIX: was missing (variable was captured but never compared/logged)
        IF ISNULL(@OldEstimatedDuration,0) <> ISNULL(@EstimatedDuration,0)
        INSERT INTO Config_History VALUES(GETDATE(),'PM Schedule Configuration',@UID,'EstimatedDuration',
        CAST(@OldEstimatedDuration AS VARCHAR),CAST(@EstimatedDuration AS VARCHAR),2,@Remark,@UserName);

        SET @ResultMessage = 'Updated successfully';
        SET @ResultStatus = 1;
    END

    -------------------------------------------------
    -- DELETE
    -------------------------------------------------
    ELSE IF @Mode = 3
    BEGIN
        DELETE FROM Config_PMSchedule WHERE UID = @UID;

        IF @@ROWCOUNT = 0
        BEGIN
            SET @ResultMessage = 'Schedule details not found';
            SET @ResultStatus = 0;

            SELECT
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

            RETURN;
        END

        INSERT INTO Config_History
        VALUES(GETDATE(),'PM Schedule Configuration',@UID,'Delete',' ',' ',3,@Remark,@UserName);

        SET @ResultMessage = 'Deleted successfully';
        SET @ResultStatus = 1;
    END

    SELECT
        @ResultMessage AS ResultMessage,
        @ResultStatus AS ResultStatus;

    END TRY

    BEGIN CATCH
        --SET @ResultMessage = ERROR_MESSAGE();
        SET @ResultMessage = 'SQL ERROR';
        SET @ResultStatus = 0;

        SELECT
            @ResultMessage AS ResultMessage,
            @ResultStatus AS ResultStatus;
    END CATCH
END
GO

-- ------------------------------------------------------------------------
-- [50/376] Stored Procedure: [dbo].[BT_Config_QADocumentList]
-- Created: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 29-05-2026
-- Description : Procedure for Add, Modify & Delete Buttons
-- =============================================
--***************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION                    |
-----------------------------------------------------------
--| 29-05-2026 | Sumit      | CREATE OR ALTER OR ALTERd                        |
-----------------------------------------------------------
--***************************************************************/
CREATE         PROCEDURE [dbo].[BT_Config_QADocumentList]

    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,

    @DocumentID INT,
    @DocumentNo INT,
    @DocumentName NVARCHAR(100),
    @Group NVARCHAR(100),
    @Revision INT,

    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)

AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF @DocumentID IS NULL
        BEGIN
            SET @ResultMessage = 'Document ID is required';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode IN (1,2)
        BEGIN         
                  IF (
                           
                           ISNULL(@DocumentNo,0) = 0
                        OR ISNULL(@Revision,0) = 0
                        OR ISNULL(LTRIM(RTRIM(@DocumentName)),'') = ''
                        OR ISNULL(LTRIM(RTRIM(@Group)),'') = ''
                        
                       )
                    BEGIN

                    SET @ResultMessage = 'Fill all mandatory fields';
                    SET @ResultStatus = 0;

                    SELECT
                    @ResultMessage AS ResultMessage,
                    @ResultStatus AS ResultStatus;

                    RETURN;

                    END

            IF @DocumentNo IS NULL
            BEGIN
                SET @ResultMessage = 'Document Number is required';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF @DocumentName IS NULL OR LTRIM(RTRIM(@DocumentName)) = ''
            BEGIN
                SET @ResultMessage = 'Document Name is required';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF @Group IS NULL OR LTRIM(RTRIM(@Group)) = ''
            BEGIN
                SET @ResultMessage = 'Group is required';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF @Revision IS NULL
            BEGIN
                SET @ResultMessage = 'Revision is required';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(@DocumentName) > 100
            BEGIN
                SET @ResultMessage = 'Document Name exceeds max length (100)';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(@Group) > 100
            BEGIN
                SET @ResultMessage = 'Group exceeds max length (100)';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

        END

        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN

            IF EXISTS (SELECT 1
                       FROM dbo.Config_QADocumentList
                       WHERE DocumentID = @DocumentID)
            BEGIN
                SET @ResultMessage = 'Document details already exists';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            INSERT INTO dbo.Config_QADocumentList
            (
                DocumentNo,
                DocumentName,
                [Group],
                Revision
            )
            VALUES
            (
                @DocumentNo,
                @DocumentName,
                @Group,
                @Revision
            );

            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'QA Document Configuration',
                @DocumentID,
                'Add Record',
                '',
                '',
                1,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;

        END

        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN

            DECLARE
                @OldDocumentNo INT,
                @OldDocumentName NVARCHAR(100),
                @OldGroup NVARCHAR(100),
                @OldRevision INT;

            IF NOT EXISTS (SELECT 1
                           FROM dbo.Config_QADocumentList
                           WHERE DocumentID = @DocumentID)
            BEGIN
                SET @ResultMessage = 'Document details not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            SELECT
                @OldDocumentNo = DocumentNo,
                @OldDocumentName = DocumentName,
                @OldGroup = [Group],
                @OldRevision = Revision
            FROM dbo.Config_QADocumentList
            WHERE DocumentID = @DocumentID;

            UPDATE dbo.Config_QADocumentList
            SET
                DocumentNo = CASE
                                WHEN ISNULL(DocumentNo,0) <> ISNULL(@DocumentNo,0)
                                THEN @DocumentNo
                                ELSE DocumentNo
                             END,

                DocumentName = CASE
                                  WHEN ISNULL(DocumentName,'') <> ISNULL(@DocumentName,'')
                                  THEN @DocumentName
                                  ELSE DocumentName
                               END,

                [Group] = CASE
                             WHEN ISNULL([Group],'') <> ISNULL(@Group,'')
                             THEN @Group
                             ELSE [Group]
                          END,

                Revision = CASE
                              WHEN ISNULL(Revision,0) <> ISNULL(@Revision,0)
                              THEN @Revision
                              ELSE Revision
                           END

            WHERE DocumentID = @DocumentID;

            IF ISNULL(@OldDocumentNo,0) <> ISNULL(@DocumentNo,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'QA Document Configuration',
                    @DocumentID,
                    'DocumentNo',
                    @OldDocumentNo,
                    @DocumentNo,
                    2,
                    @Remark,
                    @UserName
                );
            END

            IF ISNULL(@OldDocumentName,'') <> ISNULL(@DocumentName,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'QA Document Configuration',
                    @DocumentID,
                    'DocumentName',
                    @OldDocumentName,
                    @DocumentName,
                    2,
                    @Remark,
                    @UserName
                );
            END

            IF ISNULL(@OldGroup,'') <> ISNULL(@Group,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'QA Document Configuration',
                    @DocumentID,
                    'Group',
                    @OldGroup,
                    @Group,
                    2,
                    @Remark,
                    @UserName
                );
            END

            IF ISNULL(@OldRevision,0) <> ISNULL(@Revision,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'QA Document Configuration',
                    @DocumentID,
                    'Revision',
                    @OldRevision,
                    @Revision,
                    2,
                    @Remark,
                    @UserName
                );
            END

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;

        END

        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN

            DELETE FROM dbo.Config_QADocumentList
            WHERE DocumentID = @DocumentID;

            IF @@ROWCOUNT = 0
            BEGIN
                SET @ResultMessage = 'Document details not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            INSERT INTO dbo.Config_History
            VALUES
            (
                GETDATE(),
                'QA Document Configuration',
                @DocumentID,
                'Delete Record',
                '',
                '',
                3,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;

        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END CATCH

END
GO

