-- [52/376] Stored Procedure: [dbo].[BT_Config_Shop]
-- Created: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 23-04-2026
-- Description : Procedure for Add, Modify & Delete Buttons
-- =============================================

--***************************************************************
--Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION            |
-----------------------------------------------------------
--| 26-04-2026 | Sumit      | CREATE OR ALTER OR ALTERd                |
--| 30-04-2026 | Sumit      | Standardized fixes     |
--| 06-05-2026 | Sumit      | changed screen name and error message to sql error   |
-----------------------------------------------------------
--***************************************************************/

CREATE         PROCEDURE [dbo].[BT_Config_Shop]
    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,

    @ShopID INT,
    @ShopName NVARCHAR(100),
    @ShopDesc NVARCHAR(300),
    @PlantID INT,
    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        
        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF @ShopID IS NULL
        BEGIN
            SET @ResultMessage = 'ShopID is required';
            SET @ResultStatus = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode IN (1,2)
        BEGIN

             IF (
                   ISNULL(LTRIM(RTRIM(@ShopName)), '') = ''
                   OR ISNULL(LTRIM(RTRIM(@PlantID)), 0) = 0
                  
               )
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
            -- ✅ FIXED: INT validation
            IF @PlantID IS NULL OR @PlantID = 0
            BEGIN
                SET @ResultMessage = 'Plant Name is required';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF @ShopName IS NULL OR LTRIM(RTRIM(@ShopName)) = ''
            BEGIN
                SET @ResultMessage = 'Shop Name is required';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            --IF @ShopDesc IS NULL OR LTRIM(RTRIM(@ShopDesc)) = ''
            --BEGIN
            --    SET @ResultMessage = 'Shop Description is required';
            --    SET @ResultStatus = 0;
            --    SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            --    RETURN;
            --END


            IF LEN(@ShopName) > 100
            BEGIN
                SET @ResultMessage = 'Shop Name exceeds max length (100)';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(ISNULL(@ShopDesc,'')) > 300
            BEGIN
                SET @ResultMessage = 'Shop Description exceeds max length (300)';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END
        END

        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.Config_Shop WHERE ShopID = @ShopID)
            BEGIN
                SET @ResultMessage = 'Shop details already exists';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            INSERT INTO dbo.Config_Shop
            (
                PlantID,
                ShopName,
                ShopDesc
            )
            VALUES
            (
                @PlantID,
                @ShopName,
                @ShopDesc
            );

            INSERT INTO dbo.Config_History
            (TimeStamp, ScreenName, PrimaryKeyValue, FieldName, OldValue, NewValue, Status, Remark, UpdatedBy)
            VALUES
            (GETDATE(), 'Shop Configuration', @ShopID, 'Add Record', ' ', ' ', 1, @Remark, @UserName);

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN
            DECLARE 
                @OldShopName NVARCHAR(100),
                @OldShopDesc NVARCHAR(300),
                @OldPlantID INT;

            IF NOT EXISTS (SELECT 1 FROM dbo.Config_Shop WHERE ShopID = @ShopID)
            BEGIN
                SET @ResultMessage = 'Shop details not found';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            SELECT
                @OldShopName = ShopName,
                @OldShopDesc = ShopDesc,
                @OldPlantID = PlantID
            FROM dbo.Config_Shop
            WHERE ShopID = @ShopID;

            UPDATE dbo.Config_Shop
            SET
                ShopName = CASE WHEN ISNULL(ShopName,'') <> ISNULL(@ShopName,'') THEN @ShopName ELSE ShopName END,
                ShopDesc = CASE WHEN ISNULL(ShopDesc,'') <> ISNULL(@ShopDesc,'') THEN @ShopDesc ELSE ShopDesc END,
                PlantID  = CASE WHEN ISNULL(PlantID,0) <> ISNULL(@PlantID,0) THEN @PlantID ELSE PlantID END
            WHERE ShopID = @ShopID;

            IF ISNULL(@OldShopName,'') <> ISNULL(@ShopName,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES (GETDATE(),'Shop Configuration',@ShopID,'ShopName',@OldShopName,@ShopName,2,@Remark,@UserName);
            END

            IF ISNULL(@OldShopDesc,'') <> ISNULL(@ShopDesc,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES (GETDATE(),'Shop Configuration',@ShopID,'ShopDesc',@OldShopDesc,@ShopDesc,2,@Remark,@UserName);
            END

            IF ISNULL(@OldPlantID,0) <> ISNULL(@PlantID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES (GETDATE(),'Shop Configuration',@ShopID,'PlantID',@OldPlantID,@PlantID,2,@Remark,@UserName);
            END

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END     

        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN
            DELETE FROM dbo.Config_Shop
            WHERE ShopID = @ShopID;

            IF @@ROWCOUNT = 0
            BEGIN
                SET @ResultMessage = 'Shop details not found';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            INSERT INTO dbo.Config_History
            VALUES (GETDATE(),'Shop Configuration',@ShopID,'Delete Record',' ',' ',3,@Remark,@UserName);

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

    END TRY

    BEGIN CATCH
        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;
        SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
    END CATCH
END
GO

