            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

        -- UPDATE MODE
        ELSE IF @Mode = 2
        BEGIN
            /*DECLARE THE PARAMETERS TO STORE THE VALUE BEFORE UPDATE*/
             DECLARE @OldSkillLevelID INT;
	         DECLARE @OldSkillLevelName VARCHAR(100);
	         DECLARE @OldSkillLevelDesc VARCHAR(300);

            /*RENAME TABLE COLUMN AND PARAMETERS NAME */

            -- CHECK IF RECORD EXISTS
            IF NOT EXISTS (SELECT 1 FROM Config_SkillLevel WHERE SkillLevelID = @SkillLevelID)
	    BEGIN
	        SET @ResultMessage = 'Skill Level details not found';
	        SET @ResultStatus = 0;
			SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	        RETURN;
	    END

            /*RENAME THE DECLARED PARAMETERS AS PER YOUR PARAMETERS DECLARED ABOVE */

            -- GET OLD VALUES
            SELECT
	        @OldSkillLevelID = SkillLevelID,
	        @OldSkillLevelName = SkillLevelName,
	        @OldSkillLevelDesc = SkillLevelDesc
	    FROM Config_SkillLevel
	    WHERE SkillLevelID = @SkillLevelID;

            /*RENAME AND ADD THE PARAMETERS AS PER YOUR TABLE*/

            -- UPDATE ONLY CHANGED VALUES
            UPDATE Config_SkillLevel
	    SET
	        
	
	        SkillLevelName = CASE 
	                    WHEN ISNULL(SkillLevelName,'') <> ISNULL(@SkillLevelName,'') 
	                    THEN @SkillLevelName 
	                    ELSE SkillLevelName 
	                  END,
	
	        SkillLevelDesc = CASE 
	                    WHEN ISNULL(SkillLevelDesc,'') <> ISNULL(@SkillLevelDesc,'') 
	                    THEN @SkillLevelDesc 
	                    ELSE SkillLevelDesc 
	                  END
	    WHERE SkillLevelID = @SkillLevelID;
	    

            /* BELOW INSERT STATEMENTS ARE USED TO MAINTAIN THE HISTORY BEFORE AND AFTER UPDATE FOR EACH COLUMN */

            -- SkillLevelName History
		    /*RENAME AND ADD THE PARAMETERS AS PER YOUR TABLE*/
	    IF ISNULL(@OldSkillLevelName,'') <> ISNULL(@SkillLevelName,'')
	    BEGIN
	        INSERT INTO Config_History(TimeStamp,ScreenName,PrimaryKeyValue,FieldName,OldValue,NewValue,Status,Remark, UpdatedBy)
	        VALUES(GETDATE(),'Skill Level Configuration',@SkillLevelID,'SkillLevelName',ISNULL(@OldSkillLevelName,''),ISNULL(@SkillLevelName,''),2,@Remark,@UserName);
	    END
	
	    -- SkillLevelDesc History
		    /*RENAME AND ADD THE PARAMETERS AS PER YOUR TABLE*/
	    IF ISNULL(@OldSkillLevelDesc,'') <> ISNULL(@SkillLevelDesc,'')
	    BEGIN
	        INSERT INTO Config_History(TimeStamp,ScreenName,PrimaryKeyValue,FieldName,OldValue,NewValue,Status,Remark,UpdatedBy)
	        VALUES(GETDATE(),'Skill Level Configuration',@SkillLevelID,'SkillLevelDesc',ISNULL(@OldSkillLevelDesc,''),ISNULL(@SkillLevelDesc,''),2,@Remark,@UserName);
	    END

            -- SUCCESS MESSAGE
            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END     

        -- DELETE MODE
        ELSE IF @Mode = 3
        BEGIN
            /*RENAME THE COLUMN NAME AND TABLE NAME */

            -- DELETE RECORD
            DELETE FROM Config_SkillLevel
	            WHERE SkillLevelID = @SkillLevelID;

            -- CHECK IF RECORD EXISTS
            IF @@ROWCOUNT = 0
	            BEGIN
	                SET @ResultMessage = 'Skill Level details not found';
					SET @ResultStatus = 0;
					SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	                RETURN;
	            END

            /*RENAME AND ADD THE PARAMETERS AS PER YOUR TABLE*/

            -- INSERT DELETE HISTORY
            INSERT INTO Config_History (TimeStamp, ScreenName, PrimaryKeyValue, FieldName, OldValue, NewValue, Status, Remark, UpdatedBy)
                VALUES (GETDATE(), 'Skill Level Configuration', @SkillLevelID, 'Delete Record', ' ', ' ', 3, @Remark, @UserName);
	           
            -- SUCCESS MESSAGE
            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

    END TRY

    BEGIN CATCH
        -- ERROR HANDLING
	EXEC RethrowError;--If procedure fails to execute, the error message will be stored in SP_ERROR_LOG

        SET @ResultMessage = 'SQL ERROR';-- ERROR HANDLING MESSAGE IS SET TO THE OUTPUT VARIABLE
        SET @ResultStatus = 0;
        SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
    END CATCH
END
