-- ------------------------------------------------------------------------
-- [55/376] Stored Procedure: [dbo].[BT_Config_SKU]
-- Created: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Shubham Patil
-- Create date : 26-04-2026
-- Description : Procedure for Add, Modify & Delete SKU Configuration.
-- =============================================

--***************************************************************
--Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY     | DESCRIPTION                     |
-----------------------------------------------------------
--| 26-04-2026 | Shubham Patil  | Created                         |
--| 29-07-2026 | Shubham Patil  | Reformatted as per new sp template |
-----------------------------------------------------------
--***************************************************************/

CREATE       PROCEDURE [dbo].[BT_Config_SKU]

    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,

    @SKUID INT = NULL,
    @ModelID INT = NULL,
    @SKUName NVARCHAR(100),
    @SKUDescription NVARCHAR(300) = NULL,
    @SKUType INT = NULL,

    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)

AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF @Mode IN (2,3) AND ISNULL(@SKUID,0) = 0
        BEGIN
            SET @ResultMessage = 'SKUID is required';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode IN (1,2)
        BEGIN
            IF ISNULL(@SKUName,'') = ''
               OR ISNULL(@ModelID,0) = 0
               OR ISNULL(@SKUType,0) = 0
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(@SKUName) > 100
            BEGIN
                SET @ResultMessage = 'SKU Name exceeds max length (100)';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(ISNULL(@SKUDescription,'')) > 300
            BEGIN
                SET @ResultMessage = 'SKU Description exceeds max length (300)';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            -------------------------------------------------
            -- MODEL VALIDATION
            -------------------------------------------------
            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_Model
                WHERE ModelID = @ModelID
            )
            BEGIN
                SET @ResultMessage = 'Invalid ModelID';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            -------------------------------------------------
            -- DUPLICATE VALIDATION
            -------------------------------------------------
            IF EXISTS
            (
                SELECT 1
                FROM dbo.Config_SKU
                WHERE SKUName = @SKUName
                  AND (@Mode = 1 OR SKUID <> @SKUID)
            )
            BEGIN
                SET @ResultMessage = 'SKU already exists';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
        END

        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN

            INSERT INTO dbo.Config_SKU
            (
                ModelID,
                SKUName,
                SKUDesc,
                SKUType
            )
            VALUES
            (
                @ModelID,
                @SKUName,
                @SKUDescription,
                @SKUType
            );

            SET @SKUID = SCOPE_IDENTITY();

            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'SKU Configuration',
                @SKUID,
                'Add Record',
                '',
                '',
                1,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN

            DECLARE
                @OldModelID INT,
                @OldSKUName NVARCHAR(100),
                @OldSKUDesc NVARCHAR(300),
                @OldSKUType INT;

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_SKU
                WHERE SKUID = @SKUID
            )
            BEGIN
                SET @ResultMessage = 'Record not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            SELECT
                @OldModelID = ModelID,
                @OldSKUName = SKUName,
                @OldSKUDesc = SKUDesc,
                @OldSKUType = SKUType
            FROM dbo.Config_SKU
            WHERE SKUID = @SKUID;

            UPDATE dbo.Config_SKU
            SET
                ModelID = @ModelID,
                SKUName = @SKUName,
                SKUDesc = @SKUDescription,
                SKUType = @SKUType
            WHERE SKUID = @SKUID;

            IF ISNULL(@OldModelID,0) <> ISNULL(@ModelID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'SKU Configuration', @SKUID,
                    'ModelID', @OldModelID, @ModelID,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldSKUName,'') <> ISNULL(@SKUName,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'SKU Configuration', @SKUID,
                    'SKUName', @OldSKUName, @SKUName,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldSKUDesc,'') <> ISNULL(@SKUDescription,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'SKU Configuration', @SKUID,
                    'SKUDesc', @OldSKUDesc, @SKUDescription,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldSKUType,0) <> ISNULL(@SKUType,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'SKU Configuration', @SKUID,
                    'SKUType', @OldSKUType, @SKUType,
                    2, @Remark, @UserName
                );
            END

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_SKU
                WHERE SKUID = @SKUID
            )
            BEGIN
                SET @ResultMessage = 'Record not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            DELETE
            FROM dbo.Config_SKU
            WHERE SKUID = @SKUID;

            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'SKU Configuration',
                @SKUID,
                'Delete Record',
                '',
                '',
                3,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END CATCH

END
