CREATE       PROCEDURE [dbo].[BT_Config_SKU_LineTaktTime]
(
    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,

    @UID INT,
    @SKUID INT,
    @LineID INT,
    @CycleTime400 INT,
    @CycleTime600 INT,
    @CycleTime800 INT,
    @CycleTime1000 INT,
    @CycleTime1200 INT,

    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode = 1
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.Config_SKU_Line_TaktTime WHERE SKUID = @SKUID)
            BEGIN
                SET @ResultMessage = 'SKU ID already exists';
                SET @ResultStatus = 0;
                RETURN;
            END
            END
        
        IF @Mode IN (1,2)
        BEGIN

            IF @SKUID IS NULL OR @SKUID = 0
            BEGIN
                SET @ResultMessage = 'SKUID is required';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF @LineID IS NULL OR @LineID = 0
            BEGIN
                SET @ResultMessage = 'LineID is required';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

        END

        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN

            INSERT INTO dbo.Config_SKU_Line_TaktTime
            (
                SKUID,
                LineID,
                CycleTime400,
                CycleTime600,
                CycleTime800,
                CycleTime1000,
                CycleTime1200
            )
            VALUES
            (
                @SKUID,
                @LineID,
                @CycleTime400,
                @CycleTime600,
                @CycleTime800,
                @CycleTime1000,
                @CycleTime1200
            );

            DECLARE @NewUID INT;
            SET @NewUID = SCOPE_IDENTITY();

            INSERT INTO dbo.Config_History
            VALUES
            (
                GETDATE(),
                'SKU Line TaktTime Configuration',
                @NewUID,
                'Add Record',
                ' ',
                ' ',
                1,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;

        END

        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN

            DECLARE
                @OldSKUID INT,
                @OldLineID INT,
                @OldCycleTime400 INT,
                @OldCycleTime600 INT,
                @OldCycleTime800 INT,
                @OldCycleTime1000 INT,
                @OldCycleTime1200 INT;

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_SKU_Line_TaktTime
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'UID not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            SELECT
                @OldSKUID = SKUID,
                @OldLineID = LineID,
                @OldCycleTime400 = CycleTime400,
                @OldCycleTime600 = CycleTime600,
                @OldCycleTime800 = CycleTime800,
                @OldCycleTime1000 = CycleTime1000,
                @OldCycleTime1200 = CycleTime1200
            FROM dbo.Config_SKU_Line_TaktTime
            WHERE UID = @UID;

            UPDATE dbo.Config_SKU_Line_TaktTime
            SET
                SKUID = CASE
                            WHEN ISNULL(SKUID,0) <> ISNULL(@SKUID,0)
                            THEN @SKUID
                            ELSE SKUID
                        END,

                LineID = CASE
                                WHEN ISNULL(LineID,0) <> ISNULL(@LineID,0)
                                THEN @LineID
                                ELSE LineID
                            END,

                CycleTime400 = CASE
                                   WHEN ISNULL(CycleTime400,0) <> ISNULL(@CycleTime400,0)
                                   THEN @CycleTime400
                                   ELSE CycleTime400
                               END,

                CycleTime600 = CASE
                                   WHEN ISNULL(CycleTime600,0) <> ISNULL(@CycleTime600,0)
                                   THEN @CycleTime600
                                   ELSE CycleTime600
                               END,

                CycleTime800 = CASE
                                   WHEN ISNULL(CycleTime800,0) <> ISNULL(@CycleTime800,0)
                                   THEN @CycleTime800
                                   ELSE CycleTime800
                               END,

                CycleTime1000 = CASE
                                    WHEN ISNULL(CycleTime1000,0) <> ISNULL(@CycleTime1000,0)
                                    THEN @CycleTime1000
                                    ELSE CycleTime1000
                                END,

                CycleTime1200 = CASE
                                    WHEN ISNULL(CycleTime1200,0) <> ISNULL(@CycleTime1200,0)
                                    THEN @CycleTime1200
                                    ELSE CycleTime1200
                                END
            WHERE UID = @UID;

            IF ISNULL(@OldSKUID,0) <> ISNULL(@SKUID,0)
                INSERT INTO dbo.Config_History
                VALUES(GETDATE(),'SKU Line TaktTime Configuration',@UID,'SKUID',@OldSKUID,@SKUID,2,@Remark,@UserName);

            IF ISNULL(@OldLineID,0) <> ISNULL(@LineID,0)
                INSERT INTO dbo.Config_History
                VALUES(GETDATE(),'SKU Line TaktTime Configuration',@UID,'LineID',@OldLineID,@LineID,2,@Remark,@UserName);

            IF ISNULL(@OldCycleTime400,0) <> ISNULL(@CycleTime400,0)
                INSERT INTO dbo.Config_History
                VALUES(GETDATE(),'SKU Line TaktTime Configuration',@UID,'CycleTime400',@OldCycleTime400,@CycleTime400,2,@Remark,@UserName);

            IF ISNULL(@OldCycleTime600,0) <> ISNULL(@CycleTime600,0)
                INSERT INTO dbo.Config_History
                VALUES(GETDATE(),'SKU Line TaktTime Configuration',@UID,'CycleTime600',@OldCycleTime600,@CycleTime600,2,@Remark,@UserName);

            IF ISNULL(@OldCycleTime800,0) <> ISNULL(@CycleTime800,0)
                INSERT INTO dbo.Config_History
                VALUES(GETDATE(),'SKU Line TaktTime Configuration',@UID,'CycleTime800',@OldCycleTime800,@CycleTime800,2,@Remark,@UserName);

            IF ISNULL(@OldCycleTime1000,0) <> ISNULL(@CycleTime1000,0)
                INSERT INTO dbo.Config_History
                VALUES(GETDATE(),'SKU Line TaktTime Configuration',@UID,'CycleTime1000',@OldCycleTime1000,@CycleTime1000,2,@Remark,@UserName);

            IF ISNULL(@OldCycleTime1200,0) <> ISNULL(@CycleTime1200,0)
                INSERT INTO dbo.Config_History
                VALUES(GETDATE(),'SKU Line TaktTime Configuration',@UID,'CycleTime1200',@OldCycleTime1200,@CycleTime1200,2,@Remark,@UserName);

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;

        END

        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN

            DELETE FROM dbo.Config_SKU_Line_TaktTime
            WHERE UID = @UID;

            IF @@ROWCOUNT = 0
            BEGIN
                SET @ResultMessage = 'UID not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            INSERT INTO dbo.Config_History
            VALUES
            (
                GETDATE(),
                'SKU Line TaktTime Configuration',
                @UID,
                'Delete Record',
                ' ',
                ' ',
                3,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;

        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL ERROR';
        SET @ResultStatus = 0;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END CATCH

END
