            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;

        END

        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN

            DECLARE
                @OldSKUID INT,
                @OldStationID INT,
                @OldCycleTime400 INT,
                @OldCycleTime600 INT,
                @OldCycleTime800 INT,
                @OldCycleTime1000 INT,
                @OldCycleTime1200 INT;

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_SKU_Station_TaktTime
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'UID not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            SELECT
                @OldSKUID = SKUID,
                @OldStationID = StationID,
                @OldCycleTime400 = CycleTime400,
                @OldCycleTime600 = CycleTime600,
                @OldCycleTime800 = CycleTime800,
                @OldCycleTime1000 = CycleTime1000,
                @OldCycleTime1200 = CycleTime1200
            FROM dbo.Config_SKU_Station_TaktTime
            WHERE UID = @UID;

            UPDATE dbo.Config_SKU_Station_TaktTime
            SET
                SKUID = CASE
                            WHEN ISNULL(SKUID,0) <> ISNULL(@SKUID,0)
                            THEN @SKUID
                            ELSE SKUID
                        END,

                StationID = CASE
                                WHEN ISNULL(StationID,0) <> ISNULL(@StationID,0)
                                THEN @StationID
                                ELSE StationID
                            END,

                CycleTime400 = CASE
                                   WHEN ISNULL(CycleTime400,0) <> ISNULL(@CycleTime400,0)
                                   THEN @CycleTime400
                                   ELSE CycleTime400
                               END,

                CycleTime600 = CASE
                                   WHEN ISNULL(CycleTime600,0) <> ISNULL(@CycleTime600,0)
                                   THEN @CycleTime600
                                   ELSE CycleTime600
                               END,

                CycleTime800 = CASE
                                   WHEN ISNULL(CycleTime800,0) <> ISNULL(@CycleTime800,0)
                                   THEN @CycleTime800
                                   ELSE CycleTime800
                               END,

                CycleTime1000 = CASE
                                    WHEN ISNULL(CycleTime1000,0) <> ISNULL(@CycleTime1000,0)
                                    THEN @CycleTime1000
                                    ELSE CycleTime1000
                                END,

                CycleTime1200 = CASE
                                    WHEN ISNULL(CycleTime1200,0) <> ISNULL(@CycleTime1200,0)
                                    THEN @CycleTime1200
                                    ELSE CycleTime1200
                                END
            WHERE UID = @UID;

            IF ISNULL(@OldSKUID,0) <> ISNULL(@SKUID,0)
                INSERT INTO dbo.Config_History
                VALUES(GETDATE(),'SKU Station TaktTime Configuration',@UID,'SKUID',@OldSKUID,@SKUID,2,@Remark,@UserName);

            IF ISNULL(@OldStationID,0) <> ISNULL(@StationID,0)
                INSERT INTO dbo.Config_History
                VALUES(GETDATE(),'SKU Station TaktTime Configuration',@UID,'StationID',@OldStationID,@StationID,2,@Remark,@UserName);

            IF ISNULL(@OldCycleTime400,0) <> ISNULL(@CycleTime400,0)
                INSERT INTO dbo.Config_History
                VALUES(GETDATE(),'SKU Station TaktTime Configuration',@UID,'CycleTime400',@OldCycleTime400,@CycleTime400,2,@Remark,@UserName);

            IF ISNULL(@OldCycleTime600,0) <> ISNULL(@CycleTime600,0)
                INSERT INTO dbo.Config_History
                VALUES(GETDATE(),'SKU Station TaktTime Configuration',@UID,'CycleTime600',@OldCycleTime600,@CycleTime600,2,@Remark,@UserName);

            IF ISNULL(@OldCycleTime800,0) <> ISNULL(@CycleTime800,0)
                INSERT INTO dbo.Config_History
                VALUES(GETDATE(),'SKU Station TaktTime Configuration',@UID,'CycleTime800',@OldCycleTime800,@CycleTime800,2,@Remark,@UserName);

            IF ISNULL(@OldCycleTime1000,0) <> ISNULL(@CycleTime1000,0)
                INSERT INTO dbo.Config_History
                VALUES(GETDATE(),'SKU Station TaktTime Configuration',@UID,'CycleTime1000',@OldCycleTime1000,@CycleTime1000,2,@Remark,@UserName);

            IF ISNULL(@OldCycleTime1200,0) <> ISNULL(@CycleTime1200,0)
                INSERT INTO dbo.Config_History
                VALUES(GETDATE(),'SKU Station TaktTime Configuration',@UID,'CycleTime1200',@OldCycleTime1200,@CycleTime1200,2,@Remark,@UserName);

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;

        END

        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
