    @SOPPoint       NVARCHAR(MAX)   = NULL,
    @SOPType        INT             = NULL,
    @SOPLabel      INT             = NULL,

    @Remark         NVARCHAR(300)   = NULL,
    @UserName       NVARCHAR(100)

AS
BEGIN

    SET NOCOUNT ON;

    BEGIN TRY

        -- =============================================
