            IF ISNULL(LTRIM(RTRIM(@SOPPoint)), '') = ''
               OR ISNULL(@SOPType, 0) = 0
               OR ISNULL(@SOPLabel, 0) = 0
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            -- DUPLICATE CHECK
            IF EXISTS
            (
                SELECT 1
                FROM dbo.Config_SOPPoint
                WHERE SOPPoint = @SOPPoint
                  AND (@Mode = 1 OR SOPID <> @SOPID)
            )
            BEGIN
                SET @ResultMessage = 'SOP Point already exists';
                SET @ResultStatus  = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

