-- [60/376] Stored Procedure: [dbo].[BT_Config_Station]
-- Created: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:11 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE       PROCEDURE [dbo].[BT_Config_Station]
    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,

    @StationID INT,
    @StationName NVARCHAR(100),
    @StationSide NVARCHAR(100),
    @StationDesc NVARCHAR(300),
    @SubAssemblyLineID INT,
    @LineZoneID INT,
    @StationType INT,
    @StageNo INT,
    @SkillLevel INT,
    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        
        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode IN (1,2)
        BEGIN

            -------------------------------------------------
            -- Mandatory Field Validation
            -------------------------------------------------
            IF (
                   ISNULL(LTRIM(RTRIM(@StationName)), '') = ''
                OR ISNULL(LTRIM(RTRIM(@StationSide)), '') = ''
                OR ISNULL(LTRIM(RTRIM(@SubAssemblyLineID)), '') = ''
                OR ISNULL(@LineZoneID,0) = 0
                OR ISNULL(@StationType,0) = 0
                OR ISNULL(@StageNo,0) = 0
                OR ISNULL(@SkillLevel,0) = 0
               )
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            -------------------------------------------------
            -- Length Validation
            -------------------------------------------------
            IF LEN(@StationName) > 100
            BEGIN
                SET @ResultMessage = 'Station Name exceeds max length (100)';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(ISNULL(@StationDesc,'')) > 300
            BEGIN
                SET @ResultMessage = 'Station Description exceeds max length (300)';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            -------------------------------------------------
            -- Stage No Validation
            -------------------------------------------------
            IF @StageNo > 50
            BEGIN
                SET @ResultMessage = 'Stage No should be between 1-50';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
        END

        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN
            IF EXISTS (SELECT 1 
                       FROM dbo.Config_Station 
                       WHERE StationID = @StationID)
            BEGIN
                SET @ResultMessage = 'Station details already exists';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            INSERT INTO dbo.Config_Station
            (
                StationName,
                StationSide,
                StationDesc,
                SubAsslyLineID,
                LineZoneID,
                StationType,
                StageNo,
                SkillLevel
            )
            VALUES
            (
                @StationName,
                @StationSide,
                @StationDesc,
                @SubAssemblyLineID,
                @LineZoneID,
                @StationType,
                @StageNo,
                @SkillLevel
            );

            INSERT INTO dbo.Config_History
            VALUES
            (
                GETDATE(),
                'Station Configuration',
                @StationID,
                'Add Record',
                ' ',
                ' ',
                1,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN

            DECLARE 
                @OldStationName NVARCHAR(100),
                @OldStationSide NVARCHAR(100),
                @OldStationDesc NVARCHAR(300),
                @OldSubAssemblyLineID INT,
                @OldLineZoneID INT,
                @OldStationType INT,
                @OldStageNo INT,
                @OldSkillLevel INT;

            IF NOT EXISTS (SELECT 1 
                           FROM dbo.Config_Station 
                           WHERE StationID = @StationID)
            BEGIN
                SET @ResultMessage = 'Station details not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            SELECT 
                @OldStationName = StationName,
                @OldStationSide = StationSide,
                @OldStationDesc = StationDesc,
                @OldSubAssemblyLineID=SubAsslyLineID,
                @OldLineZoneID= LineZoneID,
                @OldStationType = StationType,
                @OldStageNo = StageNo,
                @OldSkillLevel = SkillLevel
            FROM dbo.Config_Station
            WHERE StationID = @StationID;

            UPDATE dbo.Config_Station
            SET
                StationName = CASE 
                                WHEN ISNULL(StationName,'') <> ISNULL(@StationName,'') 
                                THEN @StationName 
                                ELSE StationName 
                              END,

                StationSide = CASE 
                                WHEN ISNULL(StationSide,'') <> ISNULL(@StationSide,'') 
                                THEN @StationSide 
                                ELSE StationSide 
                              END,

                StationDesc = CASE 
                                WHEN ISNULL(StationDesc,'') <> ISNULL(@StationDesc,'') 
                                THEN @StationDesc 
                                ELSE StationDesc 
                              END,

                SubAsslyLineID = CASE 
                        WHEN ISNULL(SubAsslyLineID,0) <> ISNULL(@SubAssemblyLineID,0) 
                        THEN @SubAssemblyLineID 
                        ELSE SubAsslyLineID 
                        END,

                LineZoneID= CASE 
                            WHEN ISNULL(LineZoneID,0) <> ISNULL(@LineZoneID,0) 
                            THEN @LineZoneID
                            ELSE LineZoneID
                         END,

                StationType = CASE 
                                WHEN ISNULL(StationType,0) <> ISNULL(@StationType,0) 
                                THEN @StationType 
                                ELSE StationType 
                              END,

                StageNo = CASE 
                            WHEN ISNULL(StageNo,0) <> ISNULL(@StageNo,0) 
                            THEN @StageNo 
                            ELSE StageNo 
                          END,

                SkillLevel = CASE 
                                WHEN ISNULL(SkillLevel,0) <> ISNULL(@SkillLevel,0) 
                                THEN @SkillLevel 
                                ELSE SkillLevel 
                             END
            WHERE StationID = @StationID;

            IF ISNULL(@OldStationName,'') <> ISNULL(@StationName,'')
                INSERT INTO dbo.Config_History
                VALUES(GETDATE(),'Station Configuration',@StationID,'StationName',
                       @OldStationName,@StationName,2,@Remark,@UserName);

            IF ISNULL(@OldStationSide,'') <> ISNULL(@StationSide,'')
                INSERT INTO dbo.Config_History
                VALUES(GETDATE(),'Station Configuration',@StationID,'StationSide',
                       @OldStationSide,@StationSide,2,@Remark,@UserName);

            IF ISNULL(@OldStationDesc,'') <> ISNULL(@StationDesc,'')
                INSERT INTO dbo.Config_History
                VALUES(GETDATE(),'Station Configuration',@StationID,'StationDesc',
                       @OldStationDesc,@StationDesc,2,@Remark,@UserName);

            IF ISNULL(@OldSubAssemblyLineID,0) <> ISNULL(@SubAssemblyLineID,0)
            INSERT INTO dbo.Config_History
            VALUES(GETDATE(),'Station Configuration',@StationID,'SubAsslyLineID',
                    @OldSubAssemblyLineID,@SubAssemblyLineID,2,@Remark,@UserName);

            IF ISNULL(@OldLineZoneID,0) <> ISNULL(@LineZoneID,0)
                INSERT INTO dbo.Config_History
                VALUES(GETDATE(),'Station Configuration',@StationID,'LineZoneID',
                       @OldLineZoneID,@LineZoneID,2,@Remark,@UserName);

            IF ISNULL(@OldStationType,0) <> ISNULL(@StationType,0)
                INSERT INTO dbo.Config_History
                VALUES(GETDATE(),'Station Configuration',@StationID,'StationType',
                       @OldStationType,@StationType,2,@Remark,@UserName);

            IF ISNULL(@OldStageNo,0) <> ISNULL(@StageNo,0)
                INSERT INTO dbo.Config_History
                VALUES(GETDATE(),'Station Configuration',@StationID,'StageNo',
                       @OldStageNo,@StageNo,2,@Remark,@UserName);

            IF ISNULL(@OldSkillLevel,0) <> ISNULL(@SkillLevel,0)
                INSERT INTO dbo.Config_History
                VALUES(GETDATE(),'Station Configuration',@StationID,'SkillLevel',
                       @OldSkillLevel,@SkillLevel,2,@Remark,@UserName);

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN

            DELETE FROM dbo.Config_Station
            WHERE StationID = @StationID;

            IF @@ROWCOUNT = 0
            BEGIN
                SET @ResultMessage = 'Station details not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            INSERT INTO dbo.Config_History
            VALUES
            (
                GETDATE(),
                'Config_Station',
                @StationID,
                'Delete Record',
                ' ',
                ' ',
                3,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL ERROR';
        SET @ResultStatus = 0;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END CATCH

END
