CREATE       PROCEDURE [dbo].[BT_Config_Station_JHActivity_Mapping]

    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus  INT OUTPUT,
    @Mode          INT,

    @UID           INT = NULL,
    @JHActivityID  INT = NULL,
    @StationID     INT = NULL,
    @SequenceNo    INT = NULL,

    @Remark        NVARCHAR(300) = NULL,
    @UserName      NVARCHAR(100)

AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF @Mode IN (2,3) AND ISNULL(@UID,0) = 0
        BEGIN
            SET @ResultMessage = 'UID is required.';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode IN (1,2)
        BEGIN

            IF (
                   ISNULL(@JHActivityID, 0) = 0
                OR ISNULL(@StationID,    0) = 0
                OR ISNULL(@SequenceNo,   0) = 0
               )
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields.';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            -------------------------------------------------
            -- DUPLICATE VALIDATION
            -------------------------------------------------
            IF EXISTS
            (
                SELECT 1
                FROM dbo.Config_Station_JHActivity_Mapping
                WHERE JHActivityID = @JHActivityID
                  AND StationID    = @StationID
                  AND (@Mode = 1 OR UID <> @UID)
            )
            BEGIN
                SET @ResultMessage = 'Record already exists for this Station and JH Activity combination.';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

        END

        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN

            INSERT INTO dbo.Config_Station_JHActivity_Mapping
            (
                JHActivityID,
                StationID,
                SequenceNo
            )
            VALUES
            (
                @JHActivityID,
                @StationID,
                @SequenceNo
            );

            SET @UID = SCOPE_IDENTITY();

            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Station JH Activity Mapping',
                @UID,
                'Add Record',
                '',
                '',
                1,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Inserted successfully.';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;

        END

        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN

            DECLARE
                @OldJHActivityID INT,
                @OldStationID    INT,
                @OldSequenceNo   INT;

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_Station_JHActivity_Mapping
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'Record not found.';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            SELECT
                @OldJHActivityID = JHActivityID,
                @OldStationID    = StationID,
                @OldSequenceNo   = SequenceNo
            FROM dbo.Config_Station_JHActivity_Mapping
            WHERE UID = @UID;

            UPDATE dbo.Config_Station_JHActivity_Mapping
            SET
                JHActivityID = CASE
                                   WHEN ISNULL(JHActivityID,0) <> ISNULL(@JHActivityID,0)
                                   THEN @JHActivityID
                                   ELSE JHActivityID
                               END,
                StationID    = CASE
                                   WHEN ISNULL(StationID,0) <> ISNULL(@StationID,0)
                                   THEN @StationID
                                   ELSE StationID
                               END,
                SequenceNo   = CASE
                                   WHEN ISNULL(SequenceNo,0) <> ISNULL(@SequenceNo,0)
                                   THEN @SequenceNo
                                   ELSE SequenceNo
                               END
            WHERE UID = @UID;

            IF ISNULL(@OldJHActivityID,0) <> ISNULL(@JHActivityID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Station JH Activity Mapping',
                    @UID,
                    'JHActivityID',
                    @OldJHActivityID,
                    @JHActivityID,
                    2,
                    @Remark,
                    @UserName
                );
            END

            IF ISNULL(@OldStationID,0) <> ISNULL(@StationID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Station JH Activity Mapping',
                    @UID,
                    'StationID',
                    @OldStationID,
                    @StationID,
                    2,
                    @Remark,
                    @UserName
                );
            END

            IF ISNULL(@OldSequenceNo,0) <> ISNULL(@SequenceNo,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Station JH Activity Mapping',
                    @UID,
                    'SequenceNo',
                    @OldSequenceNo,
                    @SequenceNo,
                    2,
                    @Remark,
                    @UserName
                );
            END

            SET @ResultMessage = 'Updated successfully.';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;

        END

        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN

            DELETE
            FROM dbo.Config_Station_JHActivity_Mapping
            WHERE UID = @UID;

            IF @@ROWCOUNT = 0
            BEGIN
                SET @ResultMessage = 'Record not found.';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Station JH Activity Mapping',
                @UID,
                'Delete Record',
                '',
                '',
                3,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Deleted successfully.';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;

        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END CATCH

END
