CREATE         PROCEDURE [dbo].[BT_Config_StationClusterDisplayMapping]
    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,

    @ClusterDisplayID INT,
    @ClusterDisplayScreenName NVARCHAR(50),
    @IPAddress NVARCHAR(20),
    @Position1 INT = NULL,
    @Position2 INT = NULL,
    @Position3 INT = NULL,
    @Position4 INT = NULL,
    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;
           
            RETURN;
        END

        IF @ClusterDisplayID IS NULL
        BEGIN
            SET @ResultMessage = 'ClusterDisplayID is required';
            SET @ResultStatus = 0;
            
            RETURN;
        END

        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode IN (1,2)
        BEGIN
            IF (
                    ISNULL(LTRIM(RTRIM(@ClusterDisplayScreenName)), '') = ''
                    OR ISNULL(LTRIM(RTRIM(@IPAddress)), '') = ''
               )
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF @ClusterDisplayScreenName IS NULL OR LTRIM(RTRIM(@ClusterDisplayScreenName)) = ''
            BEGIN
                SET @ResultMessage = 'Cluster Display Screen Name is required';
                SET @ResultStatus = 0;
               
                RETURN;
            END

            IF @IPAddress IS NULL OR LTRIM(RTRIM(@IPAddress)) = ''
            BEGIN
                SET @ResultMessage = 'IP Address is required';
                SET @ResultStatus = 0;
               
                RETURN;
            END

            IF LEN(@ClusterDisplayScreenName) > 50
            BEGIN
                SET @ResultMessage = 'Cluster Display Screen Name exceeds max length (50)';
                SET @ResultStatus = 0;
                
                RETURN;
            END

            IF LEN(@IPAddress) > 20
            BEGIN
                SET @ResultMessage = 'IP Address exceeds max length (20)';
                SET @ResultStatus = 0;
                
                RETURN;
            END
        END

        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.Config_StationClusterDisplayMapping WHERE ClusterDisplayID = @ClusterDisplayID)
            BEGIN
                SET @ResultMessage = 'ClusterDisplayID already exists';
                SET @ResultStatus = 0;
                RETURN
                RETURN;
            END

            INSERT INTO dbo.Config_StationClusterDisplayMapping
            (
                ClusterDisplayScreenName,
                IPAddress,
                Position1,
                Position2,
                Position3,
                Position4
            )
            VALUES
            (
                @ClusterDisplayScreenName,
                @IPAddress,
                @Position1,
                @Position2,
                @Position3,
                @Position4
            );

            INSERT INTO dbo.Config_History
            VALUES (GETDATE(),'Station Cluster Display Mapping Configuration',@ClusterDisplayID,'Add Record',' ',' ',1,@Remark,@UserName);

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;
            RETURN
        END

        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN
            DECLARE
                @OldClusterDisplayScreenName NVARCHAR(50),
                @OldIPAddress NVARCHAR(20),
                @OldPosition1 INT,
                @OldPosition2 INT,
                @OldPosition3 INT,
                @OldPosition4 INT;

            IF NOT EXISTS (SELECT 1 FROM dbo.Config_StationClusterDisplayMapping WHERE ClusterDisplayID = @ClusterDisplayID)
            BEGIN
                SET @ResultMessage = 'ClusterDisplayID not found';
                SET @ResultStatus = 0;
                
                RETURN;
            END

            SELECT
                @OldClusterDisplayScreenName = ClusterDisplayScreenName,
                @OldIPAddress = IPAddress,
                @OldPosition1 = Position1,
                @OldPosition2 = Position2,
                @OldPosition3 = Position3,
                @OldPosition4 = Position4
            FROM dbo.Config_StationClusterDisplayMapping
            WHERE ClusterDisplayID = @ClusterDisplayID;

            UPDATE dbo.Config_StationClusterDisplayMapping
            SET
                ClusterDisplayScreenName = CASE WHEN ISNULL(ClusterDisplayScreenName,'') <> ISNULL(@ClusterDisplayScreenName,'') THEN @ClusterDisplayScreenName ELSE ClusterDisplayScreenName END,
                IPAddress = CASE WHEN ISNULL(IPAddress,'') <> ISNULL(@IPAddress,'') THEN @IPAddress ELSE IPAddress END,
                Position1 = CASE WHEN ISNULL(Position1,0) <> ISNULL(@Position1,0) THEN @Position1 ELSE Position1 END,
                Position2 = CASE WHEN ISNULL(Position2,0) <> ISNULL(@Position2,0) THEN @Position2 ELSE Position2 END,
                Position3 = CASE WHEN ISNULL(Position3,0) <> ISNULL(@Position3,0) THEN @Position3 ELSE Position3 END,
                Position4 = CASE WHEN ISNULL(Position4,0) <> ISNULL(@Position4,0) THEN @Position4 ELSE Position4 END
            WHERE ClusterDisplayID = @ClusterDisplayID;

            IF ISNULL(@OldClusterDisplayScreenName,'') <> ISNULL(@ClusterDisplayScreenName,'')
                INSERT INTO dbo.Config_History VALUES(GETDATE(),'Station Cluster Display Mapping Configuration',@ClusterDisplayID,'ClusterDisplayScreenName',@OldClusterDisplayScreenName,@ClusterDisplayScreenName,2,@Remark,@UserName);

            IF ISNULL(@OldIPAddress,'') <> ISNULL(@IPAddress,'')
                INSERT INTO dbo.Config_History VALUES(GETDATE(),'Station Cluster Display Mapping Configuration',@ClusterDisplayID,'IPAddress',@OldIPAddress,@IPAddress,2,@Remark,@UserName);

            IF ISNULL(@OldPosition1,0) <> ISNULL(@Position1,0)
                INSERT INTO dbo.Config_History VALUES(GETDATE(),'Station Cluster Display Mapping Configuration',@ClusterDisplayID,'Position1',@OldPosition1,@Position1,2,@Remark,@UserName);

            IF ISNULL(@OldPosition2,0) <> ISNULL(@Position2,0)
                INSERT INTO dbo.Config_History VALUES(GETDATE(),'Station Cluster Display Mapping Configuration',@ClusterDisplayID,'Position2',@OldPosition2,@Position2,2,@Remark,@UserName);

            IF ISNULL(@OldPosition3,0) <> ISNULL(@Position3,0)
                INSERT INTO dbo.Config_History VALUES(GETDATE(),'Station Cluster Display Mapping Configuration',@ClusterDisplayID,'Position3',@OldPosition3,@Position3,2,@Remark,@UserName);

            IF ISNULL(@OldPosition4,0) <> ISNULL(@Position4,0)
                INSERT INTO dbo.Config_History VALUES(GETDATE(),'Station Cluster Display Mapping Configuration',@ClusterDisplayID,'Position4',@OldPosition4,@Position4,2,@Remark,@UserName);

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;
            RETURN
        END

        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN
            DELETE FROM dbo.Config_StationClusterDisplayMapping
            WHERE ClusterDisplayID = @ClusterDisplayID;

            IF @@ROWCOUNT = 0
            BEGIN
                SET @ResultMessage = 'ClusterDisplayID not found';
                SET @ResultStatus = 0;
                RETURN
                RETURN;
            END

            INSERT INTO dbo.Config_History
            VALUES (GETDATE(),'Station Cluster Display Mapping Configuration',@ClusterDisplayID,'Delete Record',' ',' ',3,@Remark,@UserName);

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;
            RETURN
        END

    END TRY

    BEGIN CATCH
        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;
        RETURN
    END CATCH
END
