                    @Remark,
                    @UserName
                );
            END
 
            IF ISNULL(@OldAreaID,0) <> ISNULL(@AreaID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Storage Zone Configuration',
                    @StorageZoneID,
                    'AreaID',
                    @OldAreaID,
                    @AreaID,
                    2,
                    @Remark,
                    @UserName
                );
            END
 
            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;
 
            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
 
        END
 
        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN
 
            DELETE
            FROM dbo.Config_StorageZone
            WHERE StorageZoneID = @StorageZoneID;
 
            IF @@ROWCOUNT = 0
            BEGIN
 
                SET @ResultMessage = 'StorageZoneID not found';
                SET @ResultStatus = 0;
 
                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
 
            END
 
            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Storage Zone Configuration',
                @StorageZoneID,
                'Delete Record',
                '',
                '',
                3,
                @Remark,
                @UserName
            );
 
            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;
 
            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
 
        END
 
    END TRY
 
    BEGIN CATCH
 
        EXEC dbo.RethrowError;
 
        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;
 
        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;
 
    END CATCH
 
END
