                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(ISNULL(@SubAsslyLineDesc,'')) > 300
            BEGIN
                SET @ResultMessage = 'SubAssembly Description exceeds max length (300)';
