            RETURN;
        END


        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode IN (1,2)
        BEGIN

            IF ISNULL(@DepartmentID,0) = 0
               OR ISNULL(@ReasonName,'') = ''
               OR @IsPokaYoka IS NULL
               OR @IsEngineNO IS NULL
               OR @IsStationID IS NULL
               OR @IsPartID IS NULL
               OR @IsEquipmentID IS NULL
               OR @IsBreakdownID IS NULL
               OR @Priority IS NULL
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END


            -------------------------------------------------
            -- MAX LENGTH VALIDATION
            -------------------------------------------------
            IF LEN(@ReasonName) > 100
            BEGIN
                SET @ResultMessage =
                    'Reason Name cannot exceed 100 characters';

                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END


            -------------------------------------------------
            -- DUPLICATE VALIDATION
            -------------------------------------------------
            IF EXISTS
            (
                SELECT 1
                FROM dbo.Config_TicketReason
                WHERE ReasonName = @ReasonName
                  AND DepartmentID = @DepartmentID
                  AND (@Mode = 1 OR UID <> @UID)
            )
            BEGIN
                SET @ResultMessage =
                    'Ticket Reason already exists for this Department';

                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

        END


        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN

            INSERT INTO dbo.Config_TicketReason
            (
                DepartmentID,
                ReasonName,
                IsPokaYoka,
                IsEngineNO,
                IsStationID,
                IsPartID,
                IsEquipmentID,
                IsBreakdownID,
                Priority
            )
            VALUES
            (
                @DepartmentID,
                @ReasonName,
                @IsPokaYoka,
                @IsEngineNO,
                @IsStationID,
                @IsPartID,
                @IsEquipmentID,
                @IsBreakdownID,
                @Priority
            );


            SET @UID = SCOPE_IDENTITY();


            -------------------------------------------------
            -- HISTORY
            -------------------------------------------------
            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Ticket Reason Configuration',
                @UID,
                'Add Record',
                '',
                '',
                1,
                @Remark,
                @UserName
            );


            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END


        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN

            -------------------------------------------------
            -- RECORD EXISTENCE
            -------------------------------------------------
            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_TicketReason
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'Record not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END


            -------------------------------------------------
            -- OLD VALUES
            -------------------------------------------------
            DECLARE
                @OldDepartmentID INT,
                @OldReasonName NVARCHAR(100),
                @OldIsPokaYoka INT,
                @OldIsEngineNO INT,
                @OldIsStationID INT,
                @OldIsPartID INT,
                @OldIsEquipmentID INT,
                @OldIsBreakdownID INT,
                @OldPriority INT;


            SELECT
                @OldDepartmentID = DepartmentID,
                @OldReasonName = ReasonName,
                @OldIsPokaYoka = IsPokaYoka,
                @OldIsEngineNO = IsEngineNO,
                @OldIsStationID = IsStationID,
                @OldIsPartID = IsPartID,
                @OldIsEquipmentID = IsEquipmentID,
                @OldIsBreakdownID = IsBreakdownID,
                @OldPriority = Priority
            FROM dbo.Config_TicketReason
            WHERE UID = @UID;


            -------------------------------------------------
            -- UPDATE
            -------------------------------------------------
            UPDATE dbo.Config_TicketReason
            SET
                DepartmentID = @DepartmentID,
                ReasonName = @ReasonName,
                IsPokaYoka = @IsPokaYoka,
                IsEngineNO = @IsEngineNO,
                IsStationID = @IsStationID,
                IsPartID = @IsPartID,
                IsEquipmentID = @IsEquipmentID,
                IsBreakdownID = @IsBreakdownID,
                Priority = @Priority
            WHERE UID = @UID;


            -------------------------------------------------
            -- HISTORY : DEPARTMENT
            -------------------------------------------------
            IF ISNULL(@OldDepartmentID,0) <> ISNULL(@DepartmentID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Ticket Reason Configuration',
                    @UID,
                    'DepartmentID',
                    @OldDepartmentID,
                    @DepartmentID,
                    2,
                    @Remark,
                    @UserName
                );
            END


            -------------------------------------------------
            -- HISTORY : REASON NAME
            -------------------------------------------------
            IF ISNULL(@OldReasonName,'') <> ISNULL(@ReasonName,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Ticket Reason Configuration',
                    @UID,
                    'ReasonName',
                    @OldReasonName,
                    @ReasonName,
                    2,
                    @Remark,
                    @UserName
                );
            END


            -------------------------------------------------
            -- HISTORY : POKA YOKE
            -------------------------------------------------
            IF ISNULL(@OldIsPokaYoka,0) <> ISNULL(@IsPokaYoka,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Ticket Reason Configuration',
                    @UID,
                    'IsPokaYoka',
                    @OldIsPokaYoka,
                    @IsPokaYoka,
                    2,
                    @Remark,
                    @UserName
                );
            END


            -------------------------------------------------
            -- HISTORY : ENGINE NO
            -------------------------------------------------
            IF ISNULL(@OldIsEngineNO,0) <> ISNULL(@IsEngineNO,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Ticket Reason Configuration',
                    @UID,
                    'IsEngineNO',
                    @OldIsEngineNO,
                    @IsEngineNO,
                    2,
                    @Remark,
                    @UserName
                );
            END


            -------------------------------------------------
            -- HISTORY : STATION ID
            -------------------------------------------------
            IF ISNULL(@OldIsStationID,0) <> ISNULL(@IsStationID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Ticket Reason Configuration',
                    @UID,
                    'IsStationID',
                    @OldIsStationID,
                    @IsStationID,
                    2,
                    @Remark,
                    @UserName
                );
            END


            -------------------------------------------------
            -- HISTORY : PART ID
            -------------------------------------------------
            IF ISNULL(@OldIsPartID,0) <> ISNULL(@IsPartID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Ticket Reason Configuration',
                    @UID,
                    'IsPartID',
                    @OldIsPartID,
                    @IsPartID,
                    2,
                    @Remark,
                    @UserName
                );
            END


            -------------------------------------------------
            -- HISTORY : EQUIPMENT ID
            -------------------------------------------------
            IF ISNULL(@OldIsEquipmentID,0) <> ISNULL(@IsEquipmentID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Ticket Reason Configuration',
                    @UID,
                    'IsEquipmentID',
                    @OldIsEquipmentID,
                    @IsEquipmentID,
                    2,
                    @Remark,
                    @UserName
                );
            END


            -------------------------------------------------
            -- HISTORY : BREAKDOWN ID
            -------------------------------------------------
            IF ISNULL(@OldIsBreakdownID,0) <> ISNULL(@IsBreakdownID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Ticket Reason Configuration',
                    @UID,
                    'IsBreakdownID',
                    @OldIsBreakdownID,
                    @IsBreakdownID,
                    2,
                    @Remark,
                    @UserName
                );
            END


            -------------------------------------------------
            -- HISTORY : PRIORITY
            -------------------------------------------------
            IF ISNULL(@OldPriority,0) <> ISNULL(@Priority,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Ticket Reason Configuration',
                    @UID,
                    'Priority',
                    @OldPriority,
                    @Priority,
                    2,
                    @Remark,
                    @UserName
                );
            END


            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END


        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_TicketReason
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'Record not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END


            DELETE
            FROM dbo.Config_TicketReason
            WHERE UID = @UID;


            -------------------------------------------------
            -- HISTORY
            -------------------------------------------------
            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Ticket Reason Configuration',
                @UID,
                'Delete Record',
                '',
                '',
                3,
                @Remark,
                @UserName
            );


            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END CATCH

END
GO

-- ------------------------------------------------------------------------
-- [72/376] Stored Procedure: [dbo].[BT_Config_User]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : <Muskan Singh>
-- CREATE OR ALTER OR ALTER date : 23-04-2026
-- Description : Procedure for Add, Modify & Delete Buttons. Also handles data moving to history & exception handling.
-- =============================================

--*************************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY     | DESCRIPTION     |
-----------------------------------------------------------
--| 23-04-2026 | <Muskan Singh>  | CREATE OR ALTER OR ALTERd         |
-----------------------------------------------------------
--*************************************************************************
CREATE       PROCEDURE [dbo].[BT_Config_User]
    @ResultMessage VARCHAR(MAX) OUTPUT,   -- ERROR HANDLING STORED IN THIS OUTPUT VARIABLE
    @ResultStatus INT OUTPUT,             -- 0 = ERROR(RED) , 1=SUCCESS(GREEN)
    @Mode INT,                            -- 1 = ADD, 2 = UPDATE, 3 = DELETE

    /*ADD PARAMETERS RELATED TO THE GRAPHWORX SCREEN*/
    @UserID NVARCHAR(50),                       -- PRIMARY KEY OF TABLE
    @DepartmentID INT,
    @DepartmentRoleID INT,
    @UserName NVARCHAR(100),
	@EmailID NVARCHAR(100),
    @MobileNo numeric(10,0),
    @Password NVARCHAR(50),
    @AadharNo NVARCHAR(12),
    @Remark NVARCHAR(300) = NULL,        -- ON UPDATE/DELETE USER ENTERS REMARK FROM GRAPHWORX SCREEN
    @UserName1 NVARCHAR(100)              -- USER ID/NAME IS PASSED FROM THE GRAPHWORX SCREEN 
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        
        -- COMMON VALIDATION
        -- CHECKS WHETHER MODE IS VALID OR NOT
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        /*CHANGE PARAMETER NAME AND FIELD NAME IN THE MESSAGE*/ 
        -- CHECK PRIMARY KEY SHOULD NOT BE NULL
    --    IF @UserID IS NULL
    --    BEGIN
	   --         SET @ResultMessage = 'UserID is required';
				--SET @ResultStatus = 0;
				--SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	   --         RETURN;
	   --     END

        -- VALIDATION FOR INSERT / UPDATE ONLY
        IF @Mode IN (1,2)
        BEGIN
		IF (
			   ISNULL(LTRIM(RTRIM(@UserID)),'') = ''
			OR ISNULL(@DepartmentID,0) = 0
			OR ISNULL(@DepartmentRoleID,0) = 0
			OR ISNULL(LTRIM(RTRIM(@UserName)),'') = ''
			OR ISNULL(LTRIM(RTRIM(@EmailID)),'') = ''
			OR ISNULL(@MobileNo,0) = 0
			OR ISNULL(LTRIM(RTRIM(@Password)),'') = ''
			OR ISNULL(LTRIM(RTRIM(@AadharNo)),'') = ''
		   )
			BEGIN
				SET @ResultMessage = 'Fill all mandatory fields';
				SET @ResultStatus = 0;

				SELECT
				@ResultMessage AS ResultMessage,
				@ResultStatus AS ResultStatus;

				RETURN;
			END
       

            /*CHANGE PARAMETER NAME AND FIELD NAME IN THE MESSAGE*/
            /*ADD ALL THE FIELDS WHICH ARE NOT NULL*/
            -- REQUIRED FIELD VALIDATION
           IF @UserName IS NULL OR LTRIM(RTRIM(@UserName)) = '' 
            BEGIN
	                SET @ResultMessage = 'User Name is required';
					SET @ResultStatus = 0;
				SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	                RETURN;
            END

            IF @EmailID IS NULL OR LTRIM(RTRIM(@EmailID)) = '' 
	            
	            BEGIN
	                SET @ResultMessage = 'EmailID is required';
					SET @ResultStatus = 0;
				SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	                RETURN;
	            END

    IF @MobileNo IS NULL OR LTRIM(RTRIM(@MobileNo)) = '' 
	            
	            BEGIN
	                SET @ResultMessage = 'MobileNo is required';
					SET @ResultStatus = 0;
				SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	                RETURN;
	            END

    IF @Password IS NULL OR LTRIM(RTRIM(@Password)) = '' 
	            
	            BEGIN
	                SET @ResultMessage = 'Password is required';
					SET @ResultStatus = 0;
				SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	                RETURN;
	            END

	IF @AadharNo IS NULL OR LTRIM(RTRIM(@AadharNo)) = '' 
	            
	            BEGIN
	                SET @ResultMessage = 'AadharNo is required';
					SET @ResultStatus = 0;
				SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	                RETURN;
	            END
	-- CHECK DEPARTMENT EXISTS
IF NOT EXISTS (SELECT 1 FROM Config_Department WHERE DepartmentID = @DepartmentID)
BEGIN
    SET @ResultMessage = 'DepartmentID not found';
    SET @ResultStatus = 0;
    SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
    RETURN;
END
-- CHECK ROLE EXISTS
IF NOT EXISTS (SELECT 1 FROM Config_Role WHERE RoleID = @DepartmentRoleID)
BEGIN
    SET @ResultMessage = 'DepartmentRoleID not found';
    SET @ResultStatus = 0;
    SELECT @ResultMessage AS ResultMessage,@ResultStatus AS ResultStatus;
    RETURN;
END
            /*CHANGE PARAMETER NAME AND FIELD NAME IN THE MESSAGE*/
            /*ADD ALL THE FIELDS WHICH REQUIRES CHARACTER LENGTH VALIDATION*/
            /*USE THIS EXCEPTION HANDLING ONLY FOR FIELDS WITH STRING DATATYPE*/

            -- LENGTH VALIDATION
            IF LEN(@UserName) > 100
	            BEGIN
	                
	                SET @ResultMessage = 'User Name exceeds max length (100)';
					SET @ResultStatus = 0;
					SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
					RETURN;
	            END

            -- LENGTH VALIDATION FOR Email FIELD
            IF LEN(ISNULL(@EmailID,'')) > 100
	            BEGIN
	                SET @ResultMessage = 'EmailID exceeds max length (100)';
					SET @ResultStatus = 0;
					SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	                RETURN;
	            END

	-- LENGTH VALIDATION FOR MobileNo FIELD
            IF LEN(ISNULL(@MobileNo,'')) > 10
	            BEGIN
	                SET @ResultMessage = 'MobileNo exceeds max length (10)';
					SET @ResultStatus = 0;
					SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	                RETURN;
	            END
	-- LENGTH VALIDATION FOR Password FIELD
            IF LEN(ISNULL(@Password,'')) > 50
	            BEGIN
	                SET @ResultMessage = 'Password exceeds max length (50)';
					SET @ResultStatus = 0;
					SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	                RETURN;
	            END
	-- LENGTH VALIDATION FOR AadharNo FIELD
            IF LEN(ISNULL(@MobileNo,'')) > 12
	            BEGIN
	                SET @ResultMessage = 'AadharNo exceeds max length (300)';
					SET @ResultStatus = 0;
					SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	                RETURN;
	            END
        END

        -- INSERT MODE
        IF @Mode = 1
        BEGIN
            /*RENAME TABLE COLUMN AND PARAMETERS NAME */

            -- CHECKS IF RECORD ALREADY EXISTS
            IF EXISTS (SELECT 1 FROM Config_User WHERE UserID = @UserID)
	            BEGIN
	                SET @ResultMessage = 'User details already exists';
					SET @ResultStatus = 0;
					SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
					RETURN;
	            END

            /*RENAME TABLE COLUMN AND PARAMETERS NAME */

            -- INSERT NEW RECORD
            INSERT INTO Config_User
	            (
	                UserID,
	                DepartmentID,
	                DepartmentRoleID,
	                UserName,
	                EmailID,
	                MobileNo,
	                Password,
	                AadharNo
	            )
	            VALUES
	            (
	                @UserID,
	                @DepartmentID,
	                @DepartmentRoleID,
	                @UserName,
	                @EmailID,
	                @MobileNo,
	                @Password,
	                @AadharNo
	            );

            -- INSERT HISTORY FOR ADD OPERATION
            INSERT INTO Config_History (TimeStamp, ScreenName, PrimaryKeyValue, FieldName, OldValue, NewValue, Status, Remark, UpdatedBy)
            VALUES (GETDATE(), 'User Configuration', @UserID, 'Add Record', ' ', ' ', 1, @Remark, @UserName1);
	            

            -- SUCCESS MESSAGE
            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

        -- UPDATE MODE
        ELSE IF @Mode = 2
        BEGIN
            /*DECLARE THE PARAMETERS TO STORE THE VALUE BEFORE UPDATE*/
             DECLARE @OldUserID NVARCHAR(50);
			 DECLARE @OldDepartmentID INT;
			 DECLARE @OldDepartmentRoleID INT;
	         DECLARE @OldUserName VARCHAR(100);
	         DECLARE @OldEmailID VARCHAR(100);
	         DECLARE @OldMobileNo numeric(10,0);
	         DECLARE @OldPassword VARCHAR(50);
	         DECLARE @OldAadharNo VARCHAR(12);

            /*RENAME TABLE COLUMN AND PARAMETERS NAME */

            -- CHECK IF RECORD EXISTS
            IF NOT EXISTS (SELECT 1 FROM Config_User WHERE UserID = @UserID)
	    BEGIN
	        SET @ResultMessage = 'User details not found';
	        SET @ResultStatus = 0;
			SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	        RETURN;
	    END

            /*RENAME THE DECLARED PARAMETERS AS PER YOUR PARAMETERS DECLARED ABOVE */

            -- GET OLD VALUES
            SELECT
	        @OldUserID = UserID,
	        @OldDepartmentID = DepartmentID,
	        @OldDepartmentRoleID = DepartmentRoleID,
	        @OldUserName = UserName,
	        @OldEmailID = EmailID,
	        @OldMobileNo = MobileNo,
	        @OldPassword = Password,
	        @OldAadharNo = AadharNo
	    FROM Config_User
	    WHERE UserID = @UserID;

            /*RENAME AND ADD THE PARAMETERS AS PER YOUR TABLE*/

            -- UPDATE ONLY CHANGED VALUES
            UPDATE Config_User
	    SET
	        
	
	        UserName = CASE 
	                    WHEN ISNULL(UserName,'') <> ISNULL(@UserName,'') 
	                    THEN @UserName 
	                    ELSE UserName 
	                  END,
	       DepartmentID = CASE 
	                    WHEN ISNULL(DepartmentID,'') <> ISNULL(@DepartmentID,'') 
	                    THEN @DepartmentID
	                    ELSE DepartmentID 
	                  END,
	DepartmentRoleID = CASE 
	                    WHEN ISNULL(DepartmentRoleID,'') <> ISNULL(@DepartmentRoleID,'') 
	                    THEN @DepartmentRoleID
	                    ELSE DepartmentRoleID 
	                  END,
	
	        EmailID = CASE 
	                    WHEN ISNULL(EmailID,'') <> ISNULL(@EmailID,'') 
	                    THEN @EmailID
	                    ELSE EmailID 
	                  END,
	 MobileNo = CASE 
	                    WHEN ISNULL(MobileNo,'') <> ISNULL(@MobileNo,'') 
	                    THEN @MobileNo
	                    ELSE MobileNo 
	                  END,
	 Password = CASE 
	                    WHEN ISNULL(Password,'') <> ISNULL(@Password,'') 
	                    THEN @Password
	                    ELSE Password
	                  END,
	AadharNo = CASE 
	                    WHEN ISNULL(AadharNo,'') <> ISNULL(@AadharNo,'') 
	                    THEN @AadharNo
	                    ELSE AadharNo
	                  END
	    WHERE UserID = @UserID;
	    

            /* BELOW INSERT STATEMENTS ARE USED TO MAINTAIN THE HISTORY BEFORE AND AFTER UPDATE FOR EACH COLUMN */

            -- UserName History
		    /*RENAME AND ADD THE PARAMETERS AS PER YOUR TABLE*/
	    IF ISNULL(@OldUserName,'') <> ISNULL(@UserName,'')
	    BEGIN
	        INSERT INTO Config_History(TimeStamp,ScreenName,PrimaryKeyValue,FieldName,OldValue,NewValue,Status,Remark, UpdatedBy)
	        VALUES(GETDATE(),'User Configuration',@UserID,'UserName',ISNULL(@OldUserName,''),ISNULL(@UserName,''),2,@Remark,@UserName1);
	    END
	
	    -- DepartmentID History
		    /*RENAME AND ADD THE PARAMETERS AS PER YOUR TABLE*/
	    IF ISNULL(@OldDepartmentID,'') <> ISNULL(@DepartmentID,'')
	    BEGIN
	        INSERT INTO Config_History(TimeStamp,ScreenName,PrimaryKeyValue,FieldName,OldValue,NewValue,Status,Remark,UpdatedBy)
	        VALUES(GETDATE(),'User Configuration',@UserID,'DepartmentID',ISNULL(@OldDepartmentID,''),ISNULL(@DepartmentID,''),2,@Remark,@UserName1);
	    END
	-- DepartmentRoleID History
		    /*RENAME AND ADD THE PARAMETERS AS PER YOUR TABLE*/
	    IF ISNULL(@OldDepartmentRoleID,'') <> ISNULL(@DepartmentRoleID,'')
	    BEGIN
	        INSERT INTO Config_History(TimeStamp,ScreenName,PrimaryKeyValue,FieldName,OldValue,NewValue,Status,Remark,UpdatedBy)
	        VALUES(GETDATE(),'User Configuration',@UserID,'DepartmentRoleID',ISNULL(@OldDepartmentRoleID,''),ISNULL(@DepartmentRoleID,''),2,@Remark,@UserName1);
	    END
	-- EmailID History
		    /*RENAME AND ADD THE PARAMETERS AS PER YOUR TABLE*/
	    IF ISNULL(@OldEmailID,'') <> ISNULL(@EmailID,'')
	    BEGIN
	        INSERT INTO Config_History(TimeStamp,ScreenName,PrimaryKeyValue,FieldName,OldValue,NewValue,Status,Remark,UpdatedBy)
	        VALUES(GETDATE(),'User Configuration',@UserID,'EmailID',ISNULL(@OldEmailID,''),ISNULL(@EmailID,''),2,@Remark,@UserName1);
	    END
	-- MobileNo History
		    /*RENAME AND ADD THE PARAMETERS AS PER YOUR TABLE*/
	    IF ISNULL(@OldMobileNo,'') <> ISNULL(@MobileNo,'')
	    BEGIN
	        INSERT INTO Config_History(TimeStamp,ScreenName,PrimaryKeyValue,FieldName,OldValue,NewValue,Status,Remark,UpdatedBy)
	        VALUES(GETDATE(),'User Configuration',@UserID,'MobileNo',ISNULL(@OldMobileNo,''),ISNULL(@MobileNo,''),2,@Remark,@UserName1);
	    END
	-- Password History
		    /*RENAME AND ADD THE PARAMETERS AS PER YOUR TABLE*/
	    IF ISNULL(@OldPassword,'') <> ISNULL(@Password,'')
	    BEGIN
	        INSERT INTO Config_History(TimeStamp,ScreenName,PrimaryKeyValue,FieldName,OldValue,NewValue,Status,Remark,UpdatedBy)
	        VALUES(GETDATE(),'User Configuration',@UserID,'Password',ISNULL(@OldPassword,''),ISNULL(@Password,''),2,@Remark,@UserName1);
	    END
	-- AadharNo History
		    /*RENAME AND ADD THE PARAMETERS AS PER YOUR TABLE*/
	    IF ISNULL(@OldAadharNo,'') <> ISNULL(@AadharNo,'')
	    BEGIN
	        INSERT INTO Config_History(TimeStamp,ScreenName,PrimaryKeyValue,FieldName,OldValue,NewValue,Status,Remark,UpdatedBy)
	        VALUES(GETDATE(),'User Configuration',@UserID,'AadharNo',ISNULL(@OldAadharNo,''),ISNULL(@AadharNo,''),2,@Remark,@UserName1);
	    END



            -- SUCCESS MESSAGE
            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END     

        -- DELETE MODE
        ELSE IF @Mode = 3
        BEGIN
            /*RENAME THE COLUMN NAME AND TABLE NAME */

            -- DELETE RECORD
            DELETE FROM Config_User
	            WHERE UserID = @UserID;

            -- CHECK IF RECORD EXISTS
            IF @@ROWCOUNT = 0
	            BEGIN
	                SET @ResultMessage = 'User details not found';
					SET @ResultStatus = 0;
					SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
	                RETURN;
	            END

            /*RENAME AND ADD THE PARAMETERS AS PER YOUR TABLE*/

            -- INSERT DELETE HISTORY
            INSERT INTO Config_History (TimeStamp, ScreenName, PrimaryKeyValue, FieldName, OldValue, NewValue, Status, Remark, UpdatedBy)
                VALUES (GETDATE(), 'User Configuration', @UserID, 'Delete Record', ' ', ' ', 3, @Remark, @UserName1);
	           
            -- SUCCESS MESSAGE
            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

    END TRY

    BEGIN CATCH
        -- ERROR HANDLING
	EXEC RethrowError;--If procedure fails to execute, the error message will be stored in SP_ERROR_LOG

        SET @ResultMessage = ERROR_MESSAGE();-- ERROR HANDLING MESSAGE IS SET TO THE OUTPUT VARIABLE
        SET @ResultStatus = 0;
        SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
    END CATCH
END
