-- ------------------------------------------------------------------------
-- [73/376] Stored Procedure: [dbo].[BT_Config_Vendor]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 25-06-2026
-- Description : Procedure for Add, Modify & Delete Buttons
-- =============================================

--***************************************************************
--Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION                                        |
-----------------------------------------------------------
--| 25-06-2026 | Sumit      | CREATE OR ALTER OR ALTERd                                            |
--| 27-06-2026 | Sumit      | Added max length validation for VendorName & VendorDesc |
-----------------------------------------------------------
--***************************************************************/

CREATE       PROCEDURE [dbo].[BT_Config_Vendor]

    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,

    @VendorID INT = NULL,
    @VendorName NVARCHAR(100),
    @VendorCode INT = NULL,
    @VendorDesc NVARCHAR(300) = NULL,
    @VendorStatus INT,
    @VendorType INT = NULL,

    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)

AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF @Mode IN (2,3) AND ISNULL(@VendorID,0) = 0
        BEGIN
            SET @ResultMessage = 'Vendor ID is required';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode IN (1,2)
        BEGIN
            IF ISNULL(@VendorName,'') = ''
               OR ISNULL(@VendorCode,0) = 0
               --OR ISNULL(@VendorDesc,'') = ''
               OR ISNULL(@VendorType,0) = 0
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            -------------------------------------------------
            -- MAX LENGTH VALIDATION
            -------------------------------------------------
            IF LEN(@VendorName) > 100
            BEGIN
                SET @ResultMessage = 'Vendor Name cannot exceed 100 characters';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(ISNULL(@VendorDesc,'')) > 300
            BEGIN
                SET @ResultMessage = 'Vendor Description cannot exceed 300 characters';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            -------------------------------------------------
            -- DUPLICATE VALIDATION
            -------------------------------------------------
            IF EXISTS
            (
                SELECT 1
                FROM dbo.Config_Vendor
                WHERE VendorName = @VendorName
                  AND (@Mode = 1 OR VendorID <> @VendorID)
            )
            BEGIN
                SET @ResultMessage = 'Vendor already exists';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
        END

        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN

            INSERT INTO dbo.Config_Vendor
            (
                VendorName,
                VendorCode,
                VendorDesc,
                VendorStatus,
                VendorType
            )
            VALUES
            (
                @VendorName,
                @VendorCode,
                @VendorDesc,
                @VendorStatus,
                @VendorType
            );

            SET @VendorID = SCOPE_IDENTITY();

            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Vendor Configuration',
                @VendorID,
                'Add Record',
                '',
                '',
                1,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN

            DECLARE
                @OldVendorName NVARCHAR(100),
                @OldVendorCode INT,
                @OldVendorDesc NVARCHAR(300),
                @OldVendorStatus INT,
                @OldVendorType INT;

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_Vendor
                WHERE VendorID = @VendorID
            )
            BEGIN
                SET @ResultMessage = 'Record not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            SELECT
                @OldVendorName   = VendorName,
                @OldVendorCode   = VendorCode,
                @OldVendorDesc   = VendorDesc,
                @OldVendorStatus = VendorStatus,
                @OldVendorType   = VendorType
            FROM dbo.Config_Vendor
            WHERE VendorID = @VendorID;

            UPDATE dbo.Config_Vendor
            SET
                VendorName   = @VendorName,
                VendorCode   = @VendorCode,
                VendorDesc   = @VendorDesc,
                VendorStatus = @VendorStatus,
                VendorType   = @VendorType
            WHERE VendorID = @VendorID;

            IF ISNULL(@OldVendorName,'') <> ISNULL(@VendorName,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Vendor Configuration', @VendorID,
                    'VendorName', @OldVendorName, @VendorName,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldVendorCode,0) <> ISNULL(@VendorCode,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Vendor Configuration', @VendorID,
                    'VendorCode', @OldVendorCode, @VendorCode,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldVendorDesc,'') <> ISNULL(@VendorDesc,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Vendor Configuration', @VendorID,
                    'VendorDesc', @OldVendorDesc, @VendorDesc,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldVendorStatus,0) <> ISNULL(@VendorStatus,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Vendor Configuration', @VendorID,
                    'VendorStatus', @OldVendorStatus, @VendorStatus,
                    2, @Remark, @UserName
                );
            END

            IF ISNULL(@OldVendorType,0) <> ISNULL(@VendorType,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(), 'Vendor Configuration', @VendorID,
                    'VendorType', @OldVendorType, @VendorType,
                    2, @Remark, @UserName
                );
            END

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_Vendor
                WHERE VendorID = @VendorID
            )
            BEGIN
                SET @ResultMessage = 'Record not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            DELETE
            FROM dbo.Config_Vendor
            WHERE VendorID = @VendorID;

            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Vendor Configuration',
                @VendorID,
                'Delete Record',
                '',
                '',
                3,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END CATCH

END
GO

