-- [74/376] Stored Procedure: [dbo].[BT_Config_Vendor_ChecklistMetaData]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 23-04-2026
-- Description : Procedure for Add, Modify & Delete Buttons
-- =============================================

--***************************************************************
--Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION            |
-----------------------------------------------------------
--| 26-04-2026 | Sumit      | CREATE OR ALTER OR ALTERd                |
--| 30-04-2026 | Sumit      | Standardized fixes     |
--| 06-05-2026 | Sumit      | changed screen name and error message to sql error   |
-----------------------------------------------------------
--***************************************************************/

CREATE         PROCEDURE [dbo].[BT_Config_Vendor_ChecklistMetaData]
    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,

    @UID INT,
    @MetaDataName NVARCHAR(100),
    @MetaDataValue NVARCHAR(300),
    @AuditListID INT,
    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        
        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF @UID IS NULL
        BEGIN
            SET @ResultMessage = 'UID is required';
            SET @ResultStatus = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode IN (1,2)
        BEGIN
            IF (ISNULL(@AuditListID,0) = 0
            OR ISNULL(LTRIM(RTRIM(@MetaDataName)),'') = ''
            OR ISNULL(LTRIM(RTRIM(@MetaDataValue)),'') = ''
       )
            BEGIN

                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;

                RETURN;
            END
            IF @MetaDataName IS NULL OR LTRIM(RTRIM(@MetaDataName)) = ''
            BEGIN
                SET @ResultMessage = 'MetaData Name is required';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF @MetaDataValue IS NULL OR LTRIM(RTRIM(@MetaDataValue)) = ''
            BEGIN
                SET @ResultMessage = 'MetaData Value is required';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
               RETURN;
            END

            -- ✅ FIXED: INT validation
            IF @AuditListID IS NULL OR @AuditListID = 0
            BEGIN
                SET @ResultMessage = 'AuditList Name is required';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(@MetaDataName) > 100
            BEGIN
                SET @ResultMessage = 'MetaData Name exceeds max length (100)';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(ISNULL(@MetaDataValue,'')) > 300
            BEGIN
                SET @ResultMessage = 'MetaData Value exceeds max length (300)';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END
        END

        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.Config_Vendor_ChecklistMetaData WHERE UID = @UID)
            BEGIN
                SET @ResultMessage = 'UID already exists';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            INSERT INTO dbo.Config_Vendor_ChecklistMetaData
            (
                AuditListID,
                MetaDataName,
                MetaDataValue
            )
            VALUES
            (
                @AuditListID,
                @MetaDataName,
                @MetaDataValue
            );

            INSERT INTO dbo.Config_History
            (TimeStamp, ScreenName, PrimaryKeyValue, FieldName, OldValue, NewValue, Status, Remark, UpdatedBy)
            VALUES
            (GETDATE(), 'MetaData Configuration', @UID, 'Add Record', ' ', ' ', 1, @Remark, @UserName);

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN
            DECLARE 
                @OldMetaDataName NVARCHAR(100),
                @OldMetaDataValue NVARCHAR(300),
                @OldAuditListID INT;

            IF NOT EXISTS (SELECT 1 FROM dbo.Config_Vendor_ChecklistMetaData WHERE UID = @UID)
            BEGIN
                SET @ResultMessage = 'UID not found';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            SELECT
                @OldMetaDataName = MetaDataName,
                @OldMetaDataValue = MetaDataValue,
                @OldAuditListID = AuditListID
            FROM dbo.Config_Vendor_ChecklistMetaData
            WHERE UID = @UID;

            UPDATE dbo.Config_Vendor_ChecklistMetaData
            SET
                MetaDataName = CASE WHEN ISNULL(MetaDataName,'') <> ISNULL(@MetaDataName,'') THEN @MetaDataName ELSE MetaDataName END,
                MetaDataValue = CASE WHEN ISNULL(MetaDataValue,'') <> ISNULL(@MetaDataValue,'') THEN @MetaDataValue ELSE MetaDataValue END,
                AuditListID  = CASE WHEN ISNULL(AuditListID,0) <> ISNULL(@AuditListID,0) THEN @AuditListID ELSE AuditListID END
            WHERE UID = @UID;

            IF ISNULL(@OldMetaDataName,'') <> ISNULL(@MetaDataName,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES (GETDATE(),'MetaData Configuration',@UID,'MetaDataName',@OldMetaDataName,@MetaDataName,2,@Remark,@UserName);
            END

            IF ISNULL(@OldMetaDataValue,'') <> ISNULL(@MetaDataValue,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES (GETDATE(),'MetaData Configuration',@UID,'MetaDataValue',@OldMetaDataValue,@MetaDataValue,2,@Remark,@UserName);
            END

            IF ISNULL(@OldAuditListID,0) <> ISNULL(@AuditListID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES (GETDATE(),'MetaData Configuration',@UID,'AuditListID',@OldAuditListID,@AuditListID,2,@Remark,@UserName);
            END

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END     

        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN
            DELETE FROM dbo.Config_Vendor_ChecklistMetaData
            WHERE UID = @UID;

            IF @@ROWCOUNT = 0
            BEGIN
                SET @ResultMessage = 'UID not found';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            INSERT INTO dbo.Config_History
            VALUES (GETDATE(),'MetaData Configuration',@UID,'Delete Record',' ',' ',3,@Remark,@UserName);

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

    END TRY

    BEGIN CATCH
        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;
        SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
    END CATCH
END
GO

-- ------------------------------------------------------------------------
-- [75/376] Stored Procedure: [dbo].[BT_Config_Vendor_InspectionAuditPoint]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 01-06-2026
-- Description : Procedure for Add, Modify & Delete
--               Vendor Inspection Audit Point Configuration.
-- =============================================

--*************************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION                 |
-----------------------------------------------------------
--| 04-06-2026 | Sumit      | CREATE OR ALTER OR ALTERd                     |
--| 19-06-2026 | Sumit      | Fixed to standard           |
--|            |            | soft insert pattern         |
-----------------------------------------------------------
--*************************************************************************

CREATE       PROCEDURE [dbo].[BT_Config_Vendor_InspectionAuditPoint]

    @ResultMessage  NVARCHAR(MAX)    OUTPUT,
    @ResultStatus   INT             OUTPUT,
    @Mode           INT,

    @UID            INT             = NULL,
    @AuditListID    INT             = NULL,
    @AuditPointId   INT             = NULL,
    @AuditPointName NVARCHAR(100)   = NULL,
    @LowerLimit     DECIMAL(5,2)    = NULL,
    @UpperLimit     DECIMAL(5,2)    = NULL,
    @Specification  NVARCHAR(100)   = NULL,
    @CheckingMethod NVARCHAR(100)   = NULL,
    @Status         INT             = 1,
    @Revision       INT             = NULL,
    @DocumentID     INT             = NULL,

    @Remark         NVARCHAR(300)   = NULL,
    @UserName       NVARCHAR(100)

AS
BEGIN

    SET NOCOUNT ON;

    BEGIN TRY

        -- =============================================
        -- MODE VALIDATION
        -- =============================================

        IF @Mode NOT IN (1, 2, 3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus  = 0;
            
            RETURN;
        END

        -- =============================================
        -- DELETE VALIDATION
        -- =============================================

        IF @Mode = 3
        BEGIN
            IF ISNULL(@UID, 0) = 0
            BEGIN
                SET @ResultMessage = 'UID is required';
                SET @ResultStatus  = 0;
               
                RETURN;
            END
        END

        -- =============================================
        -- INSERT / UPDATE VALIDATION
        -- =============================================

        IF @Mode IN (1, 2)
        BEGIN

            IF (
                ISNULL(@AuditListID,  0) = 0
                OR ISNULL(@AuditPointId, 0) = 0
                OR ISNULL(LTRIM(RTRIM(@AuditPointName)), '') = ''
                OR ISNULL(@LowerLimit, 0) = 0
                OR ISNULL(@UpperLimit, 0) = 0
                OR ISNULL(LTRIM(RTRIM(@Specification)),  '') = ''
                OR ISNULL(LTRIM(RTRIM(@CheckingMethod)), '') = ''
                OR ISNULL(@Status,   0) = 0
                OR ISNULL(@Revision, 0) = 0
            )
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus  = 0;
               
                RETURN;
            END

            -- ✅ NULL guard added
            IF @LowerLimit IS NOT NULL AND @UpperLimit IS NOT NULL
            BEGIN
                IF @LowerLimit > @UpperLimit
                BEGIN
                    SET @ResultMessage = 'Lower Limit cannot be greater than Upper Limit';
                    SET @ResultStatus  = 0;
                  
                    RETURN;
                END
            END

            IF @Status NOT IN (1, 2)
            BEGIN
                SET @ResultMessage = 'Invalid Status value';
                SET @ResultStatus  = 0;
                
                RETURN;
            END

        END

        -- =============================================
        -- DOCUMENT REVISION CALCULATION
        -- =============================================

        DECLARE @DocumentNumber NVARCHAR(50);
        SET @DocumentNumber = (
            SELECT DISTINCT DocumentNo
            FROM Config_QADocumentList
            WHERE DocumentID = @DocumentID
        );

        DECLARE @NewRevision INT;
        SET @NewRevision = (
            SELECT MAX(Revision) + 1
            FROM Config_QADocumentList
            WHERE DocumentNo = @DocumentNumber
        );

        -- =============================================
        -- INSERT MODE (Add)
        -- =============================================

        IF @Mode = 1
        BEGIN

            -- DUPLICATE CHECK
            IF EXISTS
            (
                SELECT 1
                FROM dbo.Config_Vendor_InspectionAuditPoint
                WHERE AuditListID  = @AuditListID
                  AND AuditPointId = @AuditPointId
                  AND Status       = 1
            )
            BEGIN
                SET @ResultMessage = 'Record already exists';
                SET @ResultStatus  = 0;
              
                RETURN;
            END

            -- INSERT new row
            INSERT INTO dbo.Config_Vendor_InspectionAuditPoint
            (
                AuditListID,
                AuditPointId,
                AuditPointName,
                LowerLimit,
                UpperLimit,
                Specification,
                CheckingMethod,
                [Status],
                Revision
            )
            VALUES
            (
                @AuditListID,
                @AuditPointId,
                @AuditPointName,
                @LowerLimit,
                @UpperLimit,
                @Specification,
                @CheckingMethod,
                @Status,
                @NewRevision
            );

            -- ✅ SCOPE_IDENTITY immediately after INSERT
            DECLARE @NewUID INT;
            SET @NewUID = SCOPE_IDENTITY();

            -- Update document revision
            UPDATE dbo.Config_QADocumentList
            SET    Revision = @NewRevision
            WHERE  DocumentID = @DocumentID;

            -- History log
            INSERT INTO dbo.Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(), 'Vendor Inspection Audit Point', @NewUID,
                'Insert', '', '',
                1, @Remark, @UserName
            );

            SET @ResultMessage = 'Inserted Successfully';
            SET @ResultStatus  = 1;
            RETURN;

        END

        -- =============================================
        -- MODIFY MODE
        -- Soft INSERT new row with updated values + @NewRevision
        -- =============================================

        ELSE IF @Mode = 2
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1 FROM dbo.Config_Vendor_InspectionAuditPoint
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'UID not found';
                SET @ResultStatus  = 0;
                
                RETURN;
            END

            -- INSERT new row with updated values and new revision
            INSERT INTO dbo.Config_Vendor_InspectionAuditPoint
            (
                AuditListID,
                AuditPointId,
                AuditPointName,
                LowerLimit,
                UpperLimit,
                Specification,
                CheckingMethod,
                [Status],
                Revision
            )
            VALUES
            (
                @AuditListID,
                @AuditPointId,
                @AuditPointName,
                @LowerLimit,
                @UpperLimit,
                @Specification,
                @CheckingMethod,
                @Status,
                @NewRevision
            );

            DECLARE @ModifiedUID INT;
            SET @ModifiedUID = SCOPE_IDENTITY();

            -- Update document revision
            UPDATE dbo.Config_QADocumentList
            SET    Revision = @NewRevision
            WHERE  DocumentID = @DocumentID;

            -- History log
            INSERT INTO dbo.Config_History
            (
                TimeStamp, ScreenName, PrimaryKeyValue,
                FieldName, OldValue, NewValue,
                Status, Remark, UpdatedBy
            )
            VALUES
            (
                GETDATE(), 'Vendor Inspection Audit Point', @ModifiedUID,
                'Modify', '', '',
                2, @Remark, @UserName
            );

            SET @ResultMessage = 'Updated Successfully';
            SET @ResultStatus  = 1;
            RETURN;

        END

        -- =============================================
        -- DELETE MODE
        -- Soft INSERT new row with Status=2 + @NewRevision
        -- =============================================

        ELSE IF @Mode = 3
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1 FROM dbo.Config_Vendor_InspectionAuditPoint
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'UID not found';
                SET @ResultStatus  = 0;
            
                RETURN;
            END

            -- Fetch existing row values to carry forward
            DECLARE @ExistingAuditListID    INT;
            DECLARE @ExistingAuditPointId   INT;
            DECLARE @ExistingAuditPointName NVARCHAR(100);
            DECLARE @ExistingLowerLimit     DECIMAL(5,2);
            DECLARE @ExistingUpperLimit     DECIMAL(5,2);
            DECLARE @ExistingSpecification  NVARCHAR(100);
            DECLARE @ExistingCheckingMethod NVARCHAR(100);

            SELECT
                @ExistingAuditListID    = AuditListID,
                @ExistingAuditPointId   = AuditPointId,
                @ExistingAuditPointName = AuditPointName,
                @ExistingLowerLimit     = LowerLimit,
                @ExistingUpperLimit     = UpperLimit,
                @ExistingSpecification  = Specification,
                @ExistingCheckingMethod = CheckingMethod
            FROM dbo.Config_Vendor_InspectionAuditPoint
            WHERE UID = @UID;

            -- INSERT new row as disabled (Status = 2)
            INSERT INTO dbo.Config_Vendor_InspectionAuditPoint
            (
                AuditListID,
                AuditPointId,
                AuditPointName,
                LowerLimit,
                UpperLimit,
                Specification,
                CheckingMethod,
                [Status],
                Revision
            )
            VALUES
            (
                @ExistingAuditListID,
                @ExistingAuditPointId,
                @ExistingAuditPointName,
                @ExistingLowerLimit,
                @ExistingUpperLimit,
                @ExistingSpecification,
                @ExistingCheckingMethod,
                2,              -- disabled
                @NewRevision
            );

            DECLARE @DeletedUID INT;
            SET @DeletedUID = SCOPE_IDENTITY();

            -- Update document revision
