-- ------------------------------------------------------------------------
CREATE         PROCEDURE [dbo].[BT_Config_VendorPartMapping]

    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,

    @UID INT = NULL,
    @PartID NVARCHAR(20),
    @VendorID INT,
    @Priority INT = NULL,
    @Status INT = NULL,
    @PartLevel INT = NULL,

    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)

AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF @Mode IN (2,3) AND ISNULL(@UID,0) = 0
        BEGIN
            SET @ResultMessage = 'UID is required';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode IN (1,2)
        BEGIN
            IF ISNULL(@PartID,'') = ''
               OR ISNULL(@VendorID,0) = 0
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            -------------------------------------------------
            -- DUPLICATE VALIDATION
            -------------------------------------------------
            IF EXISTS
            (
                SELECT 1
                FROM dbo.Config_Vendor_Part_Mapping
                WHERE PartID = @PartID
                  AND VendorID = @VendorID
                  AND (@Mode = 1 OR UID <> @UID)
            )
            BEGIN
                SET @ResultMessage = 'Vendor Part Mapping already exists';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
        END

        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN

            INSERT INTO dbo.Config_Vendor_Part_Mapping
            (
                PartID,
                VendorID,
                Priority,
                Status,
                PartLevel
            )
            VALUES
            (
                @PartID,
                @VendorID,
                @Priority,
                @Status,
                @PartLevel
            );

            SET @UID = SCOPE_IDENTITY();

            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Vendor Part Mapping Configuration',
                @UID,
                'Add Record',
                '',
                '',
                1,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN

            DECLARE
                @OldPartID NVARCHAR(20),
                @OldVendorID INT,
                @OldPriority INT,
                @OldStatus INT,
                @OldPartLevel INT;

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_Vendor_Part_Mapping
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'Record not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            SELECT
                @OldPartID = PartID,
                @OldVendorID = VendorID,
                @OldPriority = Priority,
                @OldStatus = Status,
                @OldPartLevel = PartLevel
            FROM dbo.Config_Vendor_Part_Mapping
            WHERE UID = @UID;

            UPDATE dbo.Config_Vendor_Part_Mapping
            SET
                PartID = @PartID,
                VendorID = @VendorID,
                Priority = @Priority,
                Status = @Status,
                PartLevel = @PartLevel
            WHERE UID = @UID;

            IF ISNULL(@OldPartID,'') <> ISNULL(@PartID,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Vendor Part Mapping Configuration',
                    @UID,
                    'PartID',
                    @OldPartID,
                    @PartID,
                    2,
                    @Remark,
                    @UserName
                );
            END

            IF ISNULL(@OldVendorID,0) <> ISNULL(@VendorID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Vendor Part Mapping Configuration',
                    @UID,
                    'VendorID',
                    @OldVendorID,
                    @VendorID,
                    2,
                    @Remark,
                    @UserName
                );
            END

            IF ISNULL(@OldPriority,0) <> ISNULL(@Priority,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Vendor Part Mapping Configuration',
                    @UID,
                    'Priority',
                    @OldPriority,
                    @Priority,
                    2,
                    @Remark,
                    @UserName
                );
            END

            IF ISNULL(@OldStatus,0) <> ISNULL(@Status,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Vendor Part Mapping Configuration',
                    @UID,
                    'Status',
                    @OldStatus,
                    @Status,
                    2,
                    @Remark,
                    @UserName
                );
            END

            IF ISNULL(@OldPartLevel,0) <> ISNULL(@PartLevel,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES
                (
                    GETDATE(),
                    'Vendor Part Mapping Configuration',
                    @UID,
                    'PartLevel',
                    @OldPartLevel,
                    @PartLevel,
                    2,
                    @Remark,
                    @UserName
                );
            END

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN

            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Config_Vendor_Part_Mapping
                WHERE UID = @UID
            )
            BEGIN
                SET @ResultMessage = 'Record not found';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            DELETE
            FROM dbo.Config_Vendor_Part_Mapping
            WHERE UID = @UID;

            INSERT INTO dbo.Config_History
            (
                TimeStamp,
                ScreenName,
                PrimaryKeyValue,
                FieldName,
                OldValue,
                NewValue,
                Status,
                Remark,
                UpdatedBy
            )
            VALUES
            (
                GETDATE(),
                'Vendor Part Mapping Configuration',
                @UID,
                'Delete Record',
                '',
                '',
                3,
                @Remark,
                @UserName
            );

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

    END TRY

    BEGIN CATCH

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END CATCH

END
