            IF @SubAsslyLineID IS NULL OR @SubAsslyLineID = 0
            BEGIN
                SET @ResultMessage = 'Sub Assembly Line Name is required';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF @LineZoneName IS NULL OR LTRIM(RTRIM(@LineZoneName)) = ''
            BEGIN
                SET @ResultMessage = 'Line Zone Name is required';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            --IF @ZoneDesc IS NULL OR LTRIM(RTRIM(@ZoneDesc)) = ''
            --BEGIN
            --    SET @ResultMessage = 'Zone Description is required';
            --    SET @ResultStatus = 0;
            --    SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            --    RETURN;
            --END

            IF LEN(@LineZoneName) > 100
            BEGIN
                SET @ResultMessage = 'Line Zone Name exceeds max length (100)';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF LEN(ISNULL(@LineZoneDesc,'')) > 300
            BEGIN
                SET @ResultMessage = 'Line Zone Description exceeds max length (300)';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END
        END

        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN
            IF EXISTS (SELECT 1 FROM dbo.Config_Zone WHERE LineZoneID = @LineZoneID)
            BEGIN
                SET @ResultMessage = 'Zone details already exists';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            INSERT INTO dbo.Config_Zone
            (
                SubAsslyLineID,
                LineZoneName,
                LineZoneDesc
            )
            VALUES
            (
                @SubAsslyLineID,
                @LineZoneName,
                @LineZoneDesc
            );

            INSERT INTO dbo.Config_History
            (TimeStamp, ScreenName, PrimaryKeyValue, FieldName, OldValue, NewValue, Status, Remark, UpdatedBy)
            VALUES
            (GETDATE(), 'Zone Configuration', @LineZoneID, 'Add Record', ' ', ' ', 1, @Remark, @UserName);

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        ELSE IF @Mode = 2
        BEGIN
            DECLARE 
                @OldZoneName NVARCHAR(100),
                @OldZoneDesc NVARCHAR(300),
                @OldSubAsslyLineID INT;

            IF NOT EXISTS (SELECT 1 FROM dbo.Config_Zone WHERE LineZoneID = @LineZoneID)
            BEGIN
                SET @ResultMessage = 'Line Zone details not found';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            SELECT
                @OldZoneName = LineZoneName,
                @OldZoneDesc = LineZoneDesc,
                @OldSubAsslyLineID = SubAsslyLineID
            FROM dbo.Config_Zone
            WHERE LineZoneID = @LineZoneID;

            UPDATE dbo.Config_Zone
            SET
                LineZoneName = CASE WHEN ISNULL(LineZoneName,'') <> ISNULL(@LineZoneName,'') THEN @LineZoneName ELSE LineZoneName END,
                LineZoneDesc = CASE WHEN ISNULL(LineZoneDesc,'') <> ISNULL(@LineZoneDesc,'') THEN @LineZoneDesc ELSE LineZoneDesc END,
                SubAsslyLineID = CASE WHEN ISNULL(SubAsslyLineID,0) <> ISNULL(@SubAsslyLineID,0) THEN @SubAsslyLineID ELSE SubAsslyLineID END
            WHERE LineZoneID = @LineZoneID;

            IF ISNULL(@OldZoneName,'') <> ISNULL(@LineZoneName,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES (GETDATE(),'Zone Configuration',@LineZoneID,'Line ZoneName',@OldZoneName,@LineZoneName,2,@Remark,@UserName);
            END

            IF ISNULL(@OldZoneDesc,'') <> ISNULL(@LineZoneDesc,'')
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES (GETDATE(),'Zone Configuration',@LineZoneID,'Line ZoneDesc',@OldZoneDesc,@LineZoneDesc,2,@Remark,@UserName);
            END

            IF ISNULL(@OldSubAsslyLineID,0) <> ISNULL(@SubAsslyLineID,0)
            BEGIN
                INSERT INTO dbo.Config_History
                VALUES (GETDATE(),'Zone Configuration',@LineZoneID,'SubAsslyLineID',@OldSubAsslyLineID,@SubAsslyLineID,2,@Remark,@UserName);
            END

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END     

        -------------------------------------------------
        -- DELETE MODE
        -------------------------------------------------
        ELSE IF @Mode = 3
        BEGIN
            DELETE FROM dbo.Config_Zone
            WHERE LineZoneID = @LineZoneID;

            IF @@ROWCOUNT = 0
            BEGIN
                SET @ResultMessage = 'Zone details not found';
                SET @ResultStatus = 0;
                SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
                RETURN;
            END

            INSERT INTO dbo.Config_History
            VALUES (GETDATE(),'Zone Configuration',@LineZoneID,'Delete Record',' ',' ',3,@Remark,@UserName);

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

    END TRY

    BEGIN CATCH
        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;
        SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
    END CATCH
END
GO

-- ------------------------------------------------------------------------
-- [82/376] Stored Procedure: [dbo].[BT_ConfigPMSchedule]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : <Muskan Singh>
-- CREATE OR ALTER OR ALTER date : 01-05-2026
-- Description : Procedure for Add, Modify & Delete Buttons. Also handles data moving to history & exception handling.
-- =============================================
 
--*************************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY     | DESCRIPTION     |
-----------------------------------------------------------
--| 01-05-2026 | <Muskan Singh>  | Altered        |
-----------------------------------------------------------
--*************************************************************************
CREATE       PROCEDURE [dbo].[BT_ConfigPMSchedule]
    @ResultMessage VARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,   -- 0 = ERROR, 1 = SUCCESS
    @Mode INT,                 -- 1 = ADD, 2 = UPDATE, 3 = DELETE
 
    @UID INT = NULL,           -- PK (Identity for Update/Delete)
    @LineId INT,
    @CheckListId INT,
    @StartDate DATE,
    @StartCount INT,
    @FrequencyType NVARCHAR(20),
    @FrequencyValue INT,
    @Alert INT,
    @EstimatedDuration INT,
 
    @Remark NVARCHAR(300) = NULL,
    @UserName NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @FrequencyType1 INT;

 
    -- Fetch InspectionPointType1
    SET @FrequencyType1 =
        CASE 
            WHEN LOWER(@FrequencyType) = 'Days' THEN 1
            WHEN LOWER(@FrequencyType) = 'Count' THEN 2
            ELSE NULL
        END;
    BEGIN TRY
 
    -------------------------------------------------
    -- COMMON VALIDATION
    -------------------------------------------------
    IF @Mode NOT IN (1,2,3)
    BEGIN
        SET @ResultMessage = 'Invalid Mode specified';
        SET @ResultStatus = 0;
        RETURN;
    END
 
    -------------------------------------------------
    -- INSERT / UPDATE VALIDATION
    -------------------------------------------------
    IF @Mode IN (1,2)
    BEGIN
        IF @LineId IS NULL
        BEGIN
            SET @ResultMessage = 'LineId is required';
            SET @ResultStatus = 0;
            RETURN;
        END
 
        IF @CheckListId IS NULL
        BEGIN
            SET @ResultMessage = 'CheckListId is required';
            SET @ResultStatus = 0;
            RETURN;
        END
 
        IF @StartDate IS NULL
        BEGIN
            SET @ResultMessage = 'StartDate is required';
            SET @ResultStatus = 0;
            RETURN;
        END
 
        IF @FrequencyType IS NULL OR @FrequencyValue IS NULL
        BEGIN
            SET @ResultMessage = 'Frequency details are required';
            SET @ResultStatus = 0;
            RETURN;
        END
    END
 
    -------------------------------------------------
    -- INSERT
    -------------------------------------------------
    IF @Mode = 1
    BEGIN
        INSERT INTO Config_PMSchedule
        (
            LineId,
            CheckListId,
            StartDate,
            StartCount,
            FrequencyType,
            FrequencyValue,
            Alert,
            EstimatedDuration
        )
        VALUES
        (
            @LineId,
            @CheckListId,
            @StartDate,
            @StartCount,
            @FrequencyType1,
            @FrequencyValue,
            @Alert,
            @EstimatedDuration
        );
 
        DECLARE @NewUID INT = SCOPE_IDENTITY();
 
        INSERT INTO Config_History
        (TimeStamp, ScreenName, PrimaryKeyValue, FieldName, OldValue, NewValue, Status, Remark, UpdatedBy)
        VALUES
        (GETDATE(),'PM Schedule Configuration',@NewUID,'Insert',' ',' ',1,@Remark,@UserName);
 
        SET @ResultMessage = 'Inserted successfully';
        SET @ResultStatus = 1;
    END
 
    -------------------------------------------------
    -- UPDATE
    -------------------------------------------------
    ELSE IF @Mode = 2
    BEGIN
        DECLARE 
            @OldLineId INT,
            @OldCheckListId INT,
            @OldStartDate DATE,
            @OldStartCount INT,
            @OldFrequencyType1 INT,
            @OldFrequencyValue INT,
            @OldAlert INT,
            @OldEstimatedDuration INT;
 
        IF NOT EXISTS (SELECT 1 FROM Config_PMSchedule WHERE UID = @UID)
        BEGIN
            SET @ResultMessage = 'UID not found';
            SET @ResultStatus = 0;
            RETURN;
        END
 
        SELECT
            @OldLineId = LineId,
            @OldCheckListId = CheckListId,
            @OldStartDate = StartDate,
            @OldStartCount = StartCount,
            @OldFrequencyType1 = FrequencyType,
            @OldFrequencyValue = FrequencyValue,
            @OldAlert = Alert,
            @OldEstimatedDuration = EstimatedDuration
        FROM Config_PMSchedule
        WHERE UID = @UID;
 
        UPDATE Config_PMSchedule
        SET
            LineId = ISNULL(@LineId, LineId),
            CheckListId = ISNULL(@CheckListId, CheckListId),
            StartDate = ISNULL(@StartDate, StartDate),
            StartCount = ISNULL(@StartCount, StartCount),
            FrequencyType = ISNULL(@FrequencyType1, FrequencyType),
            FrequencyValue = ISNULL(@FrequencyValue, FrequencyValue),
            Alert = ISNULL(@Alert, Alert),
            EstimatedDuration = ISNULL(@EstimatedDuration, EstimatedDuration)
        WHERE UID = @UID;
 
        -------------------------------------------------
        -- HISTORY TRACKING
        -------------------------------------------------
 
        IF ISNULL(@OldLineId,0) <> ISNULL(@LineId,0)
        INSERT INTO Config_History VALUES(GETDATE(),'PM Schedule Configuration',@UID,'LineId',
        CAST(@OldLineId AS VARCHAR),CAST(@LineId AS VARCHAR),2,@Remark,@UserName);
 
        IF ISNULL(@OldCheckListId,0) <> ISNULL(@CheckListId,0)
        INSERT INTO Config_History VALUES(GETDATE(),'PM Schedule Configuration',@UID,'CheckListId',
        CAST(@OldCheckListId AS VARCHAR),CAST(@CheckListId AS VARCHAR),2,@Remark,@UserName);
 
        IF ISNULL(@OldStartDate,'') <> ISNULL(@StartDate,'')
        INSERT INTO Config_History VALUES(GETDATE(),'PM Schedule Configuration',@UID,'StartDate',
        CAST(@OldStartDate AS VARCHAR),CAST(@StartDate AS VARCHAR),2,@Remark,@UserName);
 
        IF ISNULL(@OldFrequencyValue,0) <> ISNULL(@FrequencyValue,0)
        INSERT INTO Config_History VALUES(GETDATE(),'PM Schedule Configuration',@UID,'FrequencyValue',
        CAST(@OldFrequencyValue AS VARCHAR),CAST(@FrequencyValue AS VARCHAR),2,@Remark,@UserName);
 
        SET @ResultMessage = 'Updated successfully';
        SET @ResultStatus = 1;
    END
 
    -------------------------------------------------
    -- DELETE
    -------------------------------------------------
    ELSE IF @Mode = 3
    BEGIN
        DELETE FROM Config_PMSchedule WHERE UID = @UID;
 
        IF @@ROWCOUNT = 0
        BEGIN
            SET @ResultMessage = 'UID not found';
            SET @ResultStatus = 0;
            RETURN;
        END
 
        INSERT INTO Config_History
        VALUES(GETDATE(),'PM Schedule Configuration',@UID,'Delete',' ',' ',3,@Remark,@UserName);
 
        SET @ResultMessage = 'Deleted successfully';
        SET @ResultStatus = 1;
    END
 
    END TRY
 
    BEGIN CATCH
        SET @ResultMessage = ERROR_MESSAGE();
        SET @ResultStatus = 0;
    END CATCH
END
GO

