-- [83/376] Stored Procedure: [dbo].[BT_DaywiseNoProduction]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Vsihal
-- CREATE OR ALTER OR ALTER OR ALTER date : 29-06-2026
-- Description : Procedure for Add, Modify & Delete Buttons
-- =============================================
 
--***************************************************************
--Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION            |
-----------------------------------------------------------
--| 29-06-2026 | Vishal      | CREATE OR ALTER OR ALTER OR ALTERd                |
-----------------------------------------------------------
--***************************************************************/
 
CREATE       PROCEDURE [dbo].[BT_DaywiseNoProduction]
 
    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,
    @StartDate DATE,
    @EndDate DATE,
    @ShiftName NVARCHAR (10),
    @UserID NVARCHAR(10),
    @UserName NVARCHAR(100),
    @AllUser as int,
    @NoProduction as int,
    @UserStatus as NVARCHAR(20)
 
AS
BEGIN
    SET NOCOUNT ON;
 
    BEGIN TRY
 
        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;
 
            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END
 
      
 
        -------------------------------------------------
       --No Production UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode = 2
        BEGIN
            IF ISNULL(@StartDate,'') = ''
               OR ISNULL(@EndDate,'') = ''
               OR ISNULL(@ShiftName,'') = ''
               OR ISNULL(@AllUser,0) = 0
               OR ISNULL(@NoProduction,0) = 0
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;
 
                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END         
 
            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Prod_DailyOperatorPlan
                WHERE ProdDate between @StartDate and @EndDate and ProdShift=@ShiftName
            )
            BEGIN
                SET @ResultMessage = 'Record not found';
                SET @ResultStatus = 0;
 
                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
 
            UPDATE dbo.Prod_DailyOperatorPlan
            SET
                UserStatus   = 3,
                LastUpdatedTime   = GETDATE(),
                LastUpdatedBy  = @UserName
               WHERE ProdDate between @StartDate and @EndDate

            SET @ResultMessage = 'No Production Updated Successfully';
            SET @ResultStatus = 1;
 
            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            END
 
       -------------------------------------------------
       --User Status UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode = 3
        BEGIN
            IF ISNULL(@StartDate,'') = ''
               OR ISNULL(@EndDate,'') = ''
               OR ISNULL(@ShiftName,'') = ''
               OR ISNULL(@UserID,'') = ''
               OR ISNULL(@UserStatus,'') = ''
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;
 
                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END         
 
            IF NOT EXISTS
            (
                SELECT 1
                FROM dbo.Prod_DailyOperatorPlan
                WHERE ProdDate between @StartDate and @EndDate and ProdShift=@ShiftName and UserID = @UserID
            )
            BEGIN
                SET @ResultMessage = 'Record not found';
                SET @ResultStatus = 0;
 
                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
 
            UPDATE dbo.Prod_DailyOperatorPlan
            SET
                
                UserStatus   = CASE
                WHEN @UserStatus = 'Available' THEN 1
                WHEN @UserStatus = 'On Leave' THEN 2
                WHEN @UserStatus = 'No Production' THEN 3
                WHEN @UserStatus = 'Assigned' THEN 4
                ELSE 0
                END,
                LastUpdatedTime   = GETDATE(),
                LastUpdatedBy  = @UserName
               WHERE ProdDate between @StartDate and @EndDate

            SET @ResultMessage = 'User Status Updated Successfully';
            SET @ResultStatus = 1;
 
            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            END
 
    END TRY
 
    BEGIN CATCH
 
        EXEC dbo.RethrowError;
 
        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;
 
        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;
 
    END CATCH
 
END
GO

