-- Description : Procedure for Barcode Print and Reprint
-- =============================================

--***************************************************************
--Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION            |
-----------------------------------------------------------
--| 22-09-2026 | Vishal      | ALTER OR ALTERd                |

-----------------------------------------------------------
--***************************************************************/

 CREATE    PROCEDURE [dbo].[BT_EngineBarcodePrint]
    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,
    @EngineNo NVARCHAR(14),
    @User as NVARCHAR(20),
    @Remark as NVARCHAR(200) = NULL
   

    
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        
        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF @EngineNo IS NULL
        BEGIN
            SET @ResultMessage = 'EngineNo is required';
            SET @ResultStatus = 0;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
            RETURN;
        END
        -------------------------------------------------
        -- Print MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN
            Update SAP_Engine_SKU_Data set Status = 2 Where [EngineNo] = @EngineNo
            
            SET @ResultMessage = ' Barcode Printed successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

        -------------------------------------------------
        -- Reprint MODE
        -------------------------------------------------
           IF @Mode = 2
            BEGIN
            Insert Into Prod_BarcodeReprintLog ([EngineNo],[UserID],[TimeStamp],[Remark])
            Values (@EngineNo,@User, GETDATE(),@Remark)
            SET @ResultMessage = ' Barcode Printed successfully';
            SET @ResultStatus = 1;
            SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
        END

   END TRY

    BEGIN CATCH
        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL Error';
        SET @ResultStatus = 0;
        SELECT @ResultMessage AS ResultMessage, @ResultStatus AS ResultStatus;
    END CATCH
END
GO

-- ------------------------------------------------------------------------
-- [85/376] Stored Procedure: [dbo].[BT_LoggedChangeUser]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Shubham Patil
-- CREATE OR ALTER OR ALTER Date : 23-07-2026
-- Description : Change Shift Operator Assignment
-- =============================================

CREATE         PROCEDURE [dbo].[BT_LoggedChangeUser]
(
      @OldUserID INT
    , @NewUserID INT
    , @Reason NVARCHAR(300)
    , @ResultMessage NVARCHAR(MAX) OUTPUT
    , @ResultStatus INT OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        BEGIN TRANSACTION;

        ---------------------------------------------------------
        -- Validation
        ---------------------------------------------------------
        IF NOT EXISTS
        (
            SELECT 1
            FROM Prod_ShiftOperatorAssignment
            WHERE UserID = @OldUserID
        )
        BEGIN
            SET @ResultMessage = 'Old User Assignment Not Found.';
            SET @ResultStatus = 0;

            ROLLBACK TRANSACTION;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        ---------------------------------------------------------
        -- Assignment History
        ---------------------------------------------------------
        INSERT INTO Prod_ShiftOperatorAssignmentHistory
        (
            LineID,
            StationID,
            ProdDate,
            ProdShift,
            UserID,
            UserStatus,
            AssignmentTimestamp,
            LoggedInTimeStamp
        )
        SELECT
            LineID,
            StationID,
            ProdDate,
            ProdShift,
            UserID,
            UserStatus,
            GetDate(),
            LoggedInTimeStamp
        FROM Prod_ShiftOperatorAssignment
        WHERE UserID = @OldUserID;

        ---------------------------------------------------------
        -- User Change History
        ---------------------------------------------------------
        INSERT INTO Prod_ShiftOperatorChangeHistory
        (
            Timestamp,
            LineID,
            StationID,
            ProdDate,
            ProdShift,
            OldUserID,
            NewUserID,
            Reason
        )
        SELECT
            GETDATE(),
            LineID,
            StationID,
            ProdDate,
            ProdShift,
            UserID,
            @NewUserID,
            @Reason
        FROM Prod_ShiftOperatorAssignment
        WHERE UserID = @OldUserID;

        ---------------------------------------------------------
        -- Update Assignment
        ---------------------------------------------------------
        UPDATE Prod_ShiftOperatorAssignment
        SET
            UserID = @NewUserID,
            UserStatus = 4,                 -- Assigned
            AssignmentTimestamp = GETDATE(),
            LoggedInTimeStamp = NULL
        WHERE UserID = @OldUserID;

        COMMIT TRANSACTION;

        SET @ResultMessage = 'Operator changed successfully.';
        SET @ResultStatus = 1;

        SELECT
            @ResultMessage AS ResultMessage,
            @ResultStatus AS ResultStatus;

    END TRY

    BEGIN CATCH

        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        EXEC dbo.RethrowError;

        SET @ResultMessage = ERROR_MESSAGE();
        SET @ResultStatus = 0;

        SELECT
            @ResultMessage AS ResultMessage,
            @ResultStatus AS ResultStatus;

    END CATCH
END
GO

