        (@User37),
        (@User38),
        (@User39),
        (@User40),
        (@User41),
        (@User42),
        (@User43),
        (@User44),
        (@User45),
        (@User46),
        (@User47),
        (@User48),
        (@User49),
        (@User50),
        (@User51),
        (@User52),
        (@User53),
        (@User54),
        (@User55),
        (@User56),
        (@User57),
        (@User58),
        (@User59),
        (@User60),
        (@User61),
        (@User62),
        (@User63),
        (@User64),
        (@User65),
        (@User66),
        (@User67),
        (@User68),
        (@User69),
        (@User70)
        ) AS X(v)
        WHERE v IS NOT NULL AND v <> 0;

        IF NOT EXISTS (SELECT 1 FROM @UserIDList)
        BEGIN
            SET @ResultMessage = 'No UserID provided (all slots were 0)';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        DECLARE @TotalCount INT = (SELECT COUNT(*) FROM @UserIDList);
        DECLARE @UpdatedCount INT;

        UPDATE A
        SET A.UserStatus = 1
        FROM Prod_ShiftOperatorAssignment AS A
        JOIN @UserIDList AS L
            ON A.UserID = L.UserID;

        SET @UpdatedCount = @@ROWCOUNT;

        SET @ResultMessage = CAST(@UpdatedCount AS VARCHAR(10)) + ' of ' + CAST(@TotalCount AS VARCHAR(10)) + ' users logged in successfully';
        SET @ResultStatus = 1;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END TRY

    BEGIN CATCH

        EXEC RethrowError;

        SET @ResultMessage = ERROR_MESSAGE();
        SET @ResultStatus = 0;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END CATCH

END
