-- ------------------------------------------------------------------------
-- [87/376] Stored Procedure: [dbo].[BT_Operator_LoginLogout]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Shubham Patil
-- CREATE OR ALTER OR ALTER date : 06-07-2026
-- Description : Toggle Login / Logout for an Operator on
--               Prod_ShiftOperatorAssignment, identified by UserID.
--               UserStatus: 0 = Not Logged In, 1 = Logged In,
--                           2 = Logged Out.
--               Logic: if current status is 0 or 2 -> set to 1 (Login)
--                      if current status is 1        -> set to 2 (Logout)
-- =============================================

--*************************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY     | DESCRIPTION                              |
-----------------------------------------------------------
--| 06-07-2026 | Shubham Patil  | Removed @Mode, switched from @UID to     |
--|            |                | @UserID with auto status toggle logic.   |
--| 06-07-2026 | Shubham Patil  | Removed ProdDate/ProdShift disambig -    |
--|            |                | UserID is unique per row in real data.   |
-----------------------------------------------------------
--*************************************************************************

CREATE          PROCEDURE [dbo].[BT_Operator_LoginLogout]

    @ResultMessage VARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,   -- 0 = ERROR , 1 = SUCCESS

    @UserID INT = NULL

AS
BEGIN

    SET NOCOUNT ON;

    DECLARE @UID INT
    DECLARE @OldStatus INT

    BEGIN TRY

        -- =============================================
        -- VALIDATION
        -- =============================================

        IF @UserID IS NULL
        BEGIN
            SET @ResultMessage = 'UserID is required';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF NOT EXISTS (SELECT 1 FROM Prod_ShiftOperatorAssignment WHERE UserID = @UserID)
        BEGIN
            SET @ResultMessage = 'No assignment found for this UserID';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        SELECT
            @UID = UID,
            @OldStatus = UserStatus
        FROM Prod_ShiftOperatorAssignment
        WHERE UserID = @UserID;

        -- =============================================
        -- TOGGLE STATUS
        -- 0 or 2 -> 1 (Login)
        -- 1      -> 2 (Logout)
        -- =============================================

        IF @OldStatus IN (0,2)
        BEGIN

            UPDATE Prod_ShiftOperatorAssignment
            SET UserStatus = 1
            WHERE UID = @UID;

            SET @ResultMessage = 'User logged in successfully';
            SET @ResultStatus = 1;

        END
        ELSE IF @OldStatus = 1
        BEGIN

            UPDATE Prod_ShiftOperatorAssignment
            SET UserStatus = 2
            WHERE UID = @UID;

            SET @ResultMessage = 'User logged out successfully';
            SET @ResultStatus = 1;

        END

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END TRY

    BEGIN CATCH

        EXEC RethrowError;

        SET @ResultMessage = ERROR_MESSAGE();
        SET @ResultStatus = 0;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END CATCH

END
GO

-- ------------------------------------------------------------------------
-- [88/376] Stored Procedure: [dbo].[BT_Operator_LoginLogoutAbsent]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Shubham Patil
-- CREATE OR ALTER OR ALTER date : 06-07-2026
-- Description : Operator Login / Logout / Absent
--
-- Mode
-- 1 = Login / Logout
-- 2 = Mark Operator On Leave (Absent)
--
-- UserStatus
-- 1 = Available
-- 2 = On Leave
-- 3 = No Production
-- 4 = Assigned
-- 5 = Login
-- 6 = Logout
-- =============================================

--*************************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY     | DESCRIPTION                              |
-----------------------------------------------------------
--| 06-07-2026 | Shubham Patil  | Initial Version                          |
--| 18-07-2026 | Shubham Patil  | Added Login/Logout and Absent Mode       |
-----------------------------------------------------------
--*************************************************************************

CREATE         PROCEDURE [dbo].[BT_Operator_LoginLogoutAbsent]

      @Mode INT,
      @UserID INT,

      @ResultMessage VARCHAR(MAX) OUTPUT,
      @ResultStatus INT OUTPUT

AS
BEGIN

    SET NOCOUNT ON;

    DECLARE @OldStatus INT;

    BEGIN TRY

        -- =============================================
        -- VALIDATION
        -- =============================================

        IF @Mode NOT IN (1,2)
        BEGIN
            SET @ResultMessage = 'Invalid Mode';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF @UserID IS NULL
        BEGIN
            SET @ResultMessage = 'UserID is required';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF NOT EXISTS
        (
            SELECT 1
            FROM Prod_ShiftOperatorAssignment
            WHERE UserID = @UserID
        )
        BEGIN
            SET @ResultMessage = 'Operator Assignment not found';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END


        SELECT
            @OldStatus = UserStatus
        FROM Prod_ShiftOperatorAssignment
        WHERE UserID = @UserID;


        -- =============================================
        -- MODE 1 : LOGIN / LOGOUT
        -- =============================================

        IF @Mode = 1
        BEGIN

            -- Login
            IF @OldStatus IN (1,6)
            BEGIN

                UPDATE Prod_ShiftOperatorAssignment
                SET UserStatus = 5
                WHERE UserID = @UserID;

                UPDATE Prod_DailyOperatorPlan
                SET UserStatus = 5
                WHERE UserID = @UserID;

                SET @ResultMessage = 'User logged in successfully';
                SET @ResultStatus = 1;

            END

            -- Logout
            ELSE IF @OldStatus = 5
            BEGIN

                UPDATE Prod_ShiftOperatorAssignment
                SET UserStatus = 6
                WHERE UserID = @UserID;

                UPDATE Prod_DailyOperatorPlan
                SET UserStatus = 6
                WHERE UserID = @UserID;

                SET @ResultMessage = 'User logged out successfully';
                SET @ResultStatus = 1;

            END

            ELSE
            BEGIN

                SET @ResultMessage = 'Login/Logout is not allowed for current status.';
                SET @ResultStatus = 0;

            END

        END


        -- =============================================
        -- MODE 2 : MARK OPERATOR ON LEAVE (ABSENT)
        -- =============================================

        ELSE IF @Mode = 2
        BEGIN

            UPDATE Prod_ShiftOperatorAssignment
            SET UserStatus = 2
            WHERE UserID = @UserID;

            UPDATE Prod_DailyOperatorPlan
            SET UserStatus = 2
            WHERE UserID = @UserID;

            SET @ResultMessage = 'Operator marked as On Leave successfully';
            SET @ResultStatus = 1;

        END


        -- =============================================
        -- RESULT
        -- =============================================

        SELECT
            @ResultMessage AS ResultMessage,
            @ResultStatus AS ResultStatus;

    END TRY

    BEGIN CATCH

        EXEC RethrowError;

        SET @ResultMessage = ERROR_MESSAGE();
        SET @ResultStatus = 0;

        SELECT
            @ResultMessage AS ResultMessage,
            @ResultStatus AS ResultStatus;

    END CATCH

END
GO

-- ------------------------------------------------------------------------
-- [89/376] Stored Procedure: [dbo].[BT_Prod_JHActivity_Log]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE     PROCEDURE [dbo].[BT_Prod_JHActivity_Log]
(
    @ResultMessage  NVARCHAR(MAX) OUTPUT,
    @ResultStatus   INT OUTPUT,
    @StationID INT = NULL,
    @Remark         NVARCHAR(MAX) = NULL,
    @Mode           INT
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE
        @ProdDate  DATE,
        @ProdShift NVARCHAR(10);

    BEGIN TRY

        /*==============================================================
          Get Current Production Date
        ==============================================================*/
        SELECT @ProdDate = ParameterValue
        FROM dbo.ApplicationSetting
        WHERE ParameterID = 1;


        /*==============================================================
          Get Current Production Shift
        ==============================================================*/
        SELECT @ProdShift = ParameterValue
        FROM dbo.ApplicationSetting
        WHERE ParameterID = 2;


        /*==============================================================
          MODE 1
          Insert NOK record for given StationID
        ==============================================================*/
        IF @Mode = 1
        BEGIN

            INSERT INTO dbo.Prod_JHActivity_Log
            (
                [StationID],
                [ProdDate],
                [ProdShift],
                [Status],
                [Remark]
            )
            VALUES
            (
                @StationID,
                @ProdDate,
                @ProdShift,
                2,
                @Remark
            );

            SET @ResultStatus  = 1;
            SET @ResultMessage = 'Updated Successfully';

            SELECT
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

            RETURN;
        END


        /*==============================================================
          MODE 2
          
          Insert only those StationID records from
          Config_Station_JHActivity_Mapping which are not already
          available in Prod_JHActivity_Log for the current
          ProdDate and ProdShift.
        ==============================================================*/
        IF @Mode = 2
        BEGIN

            INSERT INTO dbo.Prod_JHActivity_Log
            (
                [StationID],
                [ProdDate],
                [ProdShift],
                [Status],
                [Remark]
            )
            SELECT DISTINCT
                M.[StationID],
                @ProdDate,
                @ProdShift,
                1,
                ''
            FROM dbo.Config_Station_JHActivity_Mapping M
            WHERE NOT EXISTS
            (
                SELECT 1
                FROM dbo.Prod_JHActivity_Log L
                WHERE L.[StationID] = M.[StationID]
                  AND L.[ProdDate]  = @ProdDate
                  AND L.[ProdShift] = @ProdShift
            );

            SET @ResultStatus  = 1;
            SET @ResultMessage = 'Rest OK Updated Successfully';

            SELECT
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

            RETURN;
        END


        /*==============================================================
          MODE 3
          
          First check whether ANY record already exists for the
          current ProdDate and ProdShift.

          If record exists:
              Do NOT insert.
              Return "Please do the Rest OK"

          If no record exists:
              Insert ALL StationID records from
              Config_Station_JHActivity_Mapping.
        ==============================================================*/
        IF @Mode = 3
        BEGIN

            /*----------------------------------------------------------
              Check whether records already exist for current
              Production Date and Shift
            ----------------------------------------------------------*/
            IF EXISTS
            (
                SELECT 1
                FROM dbo.Prod_JHActivity_Log
                WHERE [ProdDate]  = @ProdDate
                  AND [ProdShift] = @ProdShift
            )
            BEGIN

                SET @ResultStatus  = 0;
                SET @ResultMessage = 'Please do the Rest OK';

                SELECT
                    @ResultMessage AS ResultMessage,
                    @ResultStatus AS ResultStatus;

                RETURN;
            END


            /*----------------------------------------------------------
              No records exist.
              Insert ALL StationID records from mapping table.
            ----------------------------------------------------------*/
            INSERT INTO dbo.Prod_JHActivity_Log
            (
                [StationID],
                [ProdDate],
                [ProdShift],
                [Status],
                [Remark]
            )
            SELECT DISTINCT
                M.[StationID],
                @ProdDate,
                @ProdShift,
                1,
                ''
            FROM dbo.Config_Station_JHActivity_Mapping M;


            SET @ResultStatus  = 1;
            SET @ResultMessage = 'ALL OK Updated Successfully';

            SELECT
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

            RETURN;
        END


        /*==============================================================
          Invalid Mode
        ==============================================================*/
        SET @ResultStatus  = 0;
        SET @ResultMessage = 'Invalid Mode';

        SELECT
            @ResultMessage AS ResultMessage,
            @ResultStatus AS ResultStatus;


    END TRY

    BEGIN CATCH

        SET @ResultStatus  = 0;
        SET @ResultMessage = ERROR_MESSAGE();

        SELECT
            @ResultMessage AS ResultMessage,
            @ResultStatus AS ResultStatus;

    END CATCH
END
GO

-- ------------------------------------------------------------------------
-- [90/376] Stored Procedure: [dbo].[BT_ProdEngineTakeIn]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Shubham Patil
-- Create Date : 27-07-2026
-- Description : Engine Take In Process
-- =============================================

CREATE   PROCEDURE [dbo].[BT_ProdEngineTakeIn]
(
      @ResultMessage       NVARCHAR(MAX) OUTPUT,
      @ResultStatus        INT OUTPUT,

      @EngineNo            NVARCHAR(14),
      @TakeInStationID     INT,

      @UserName            NVARCHAR(100)
)
AS
BEGIN

    SET NOCOUNT ON;

    BEGIN TRY

        -------------------------------------------------
        -- MANDATORY FIELD VALIDATION
        -------------------------------------------------

        IF
        (
               ISNULL(LTRIM(RTRIM(@EngineNo)), '') = ''
            OR ISNULL(@TakeInStationID, 0) = 0
            OR ISNULL(LTRIM(RTRIM(@UserName)), '') = ''
        )
        BEGIN

            SET @ResultMessage = 'Fill all mandatory fields';
            SET @ResultStatus = 0;

            SELECT
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

            RETURN;

        END

        -------------------------------------------------
        -- DECLARE VARIABLES
        -------------------------------------------------

        DECLARE
              @UserID     NVARCHAR(50)
            , @PlanID     INT
            , @LineID     INT
            , @SKUID      INT
            , @ProdDate   DATE
            , @ProdShift  NVARCHAR(10);

        -------------------------------------------------
        -- GET USER ID
        -------------------------------------------------

        SELECT
            @UserID = UserID
        FROM dbo.Config_User
        WHERE UserName = @UserName;

        IF ISNULL(@UserID, '') = ''
        BEGIN

            SET @ResultMessage = 'Invalid User Name';
            SET @ResultStatus = 0;

            SELECT
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

            RETURN;

        END

        -------------------------------------------------
        -- GET ENGINE DETAILS
        -------------------------------------------------

        SELECT
              @PlanID    = EW.PlanID
            , @LineID    = EW.LineID
            , @SKUID     = EW.SKUID
            , @ProdDate  = PP.ProdDate
            , @ProdShift = PP.ProdShift
        FROM dbo.Prod_Engine_WIP EW
        INNER JOIN dbo.Prod_Plan PP
            ON EW.PlanID = PP.PlanID
        WHERE EW.EngineNo = @EngineNo;

        IF @PlanID IS NULL
        BEGIN

            SET @ResultMessage = 'Engine not found.';
            SET @ResultStatus = 0;

            SELECT
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

            RETURN;

        END

        -------------------------------------------------
        -- START TRANSACTION
        -------------------------------------------------

        BEGIN TRAN;

        -------------------------------------------------
        -- UPDATE PROD_INSPECTION_LOG
        -------------------------------------------------

        UPDATE dbo.Prod_Inspection_Log
        SET
              Result = 1                  -- OK
            , InspectedBy = @UserID
        WHERE EngineNo = @EngineNo;

        -------------------------------------------------
        -- CLOSE OPEN DEFECT
        -------------------------------------------------

        UPDATE dbo.Prod_Defect_Log
        SET
              DefectStatus = 1            -- OK / Closed
            , UpdatedBy = @UserID
            , LastUpdatedTime = GETDATE()
        WHERE EngineNo = @EngineNo
          AND DefectStatus = 2;            -- Open / Hold

        -------------------------------------------------
        -- UPDATE PROD_ENGINE_WIP
        -------------------------------------------------

        UPDATE dbo.Prod_Engine_WIP
        SET
              Status = 1                  -- Running
            , NotOkStation = NULL
            , ReEntryStation = @TakeInStationID
        WHERE EngineNo = @EngineNo;

        IF @@ROWCOUNT = 0
        BEGIN

            ROLLBACK TRAN;

            SET @ResultMessage = 'Engine not found in WIP.';
            SET @ResultStatus = 0;

            SELECT
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

            RETURN;

        END

        -------------------------------------------------
        -- UPDATE PROD_ENGINEPLANEXECUTION
        -------------------------------------------------

        UPDATE dbo.Prod_EnginePlanExecution
        SET
              --Status = 1,                 -- Running
              ENGTakeOut_Qty =
                    CASE
                        WHEN ISNULL(ENGTakeOut_Qty, 0) > 0
                        THEN ENGTakeOut_Qty - 1
                        ELSE 0
                    END
        WHERE PlanID = @PlanID
          AND LineID = @LineID
          AND SKUID = @SKUID
          AND ProdDate = @ProdDate
          AND ProdShift = @ProdShift;

        -------------------------------------------------
        -- INSERT STATION GENEOLOGY
        -------------------------------------------------

        INSERT INTO dbo.Prod_Station_Geneology
        (
            Timestamp,
            EngineNo,
            StationID,
            Status,
            UserID
        )
        VALUES
        (
            GETDATE(),
            @EngineNo,
            @TakeInStationID,
            1,                  -- Running
            @UserID
        );

        -------------------------------------------------
        -- INSERT STATUS GENEOLOGY
        -------------------------------------------------

        INSERT INTO dbo.Prod_Status_Geneology
        (
            Timestamp,
            EngineNo,
            Status,
            ProdDate,
            ProdShift
        )
        VALUES
        (
            GETDATE(),
            @EngineNo,
            1,                  -- Running
            @ProdDate,
            @ProdShift
        );

        -------------------------------------------------
        -- COMMIT TRANSACTION
        -------------------------------------------------

        COMMIT TRAN;

        SET @ResultMessage = 'Engine Take In completed successfully.';
        SET @ResultStatus = 1;

        SELECT
            @ResultMessage AS ResultMessage,
            @ResultStatus AS ResultStatus;

    END TRY

    BEGIN CATCH

        IF @@TRANCOUNT > 0
            ROLLBACK TRAN;

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL ERROR';
        SET @ResultStatus = 0;

        SELECT
            @ResultMessage AS ResultMessage,
            @ResultStatus AS ResultStatus;

    END CATCH

END
GO

-- ------------------------------------------------------------------------
-- [91/376] Stored Procedure: [dbo].[BT_ProdEngineTakeOut]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Shubham Patil
-- Create Date : 27-07-2026
-- Description : Engine Take Out Process
-- =============================================

CREATE   PROCEDURE [dbo].[BT_ProdEngineTakeOut]
(
      @ResultMessage       NVARCHAR(MAX) OUTPUT,
      @ResultStatus        INT OUTPUT,

      @EngineNo            NVARCHAR(14),
      @InspectionPointID   INT,
      @DefectID            INT,
      @Remark              NVARCHAR(500),
      @TakeOutStationID    INT,
      @EngineStatus        INT,
      @UserName            NVARCHAR(100)
)
AS
BEGIN

    SET NOCOUNT ON;

    BEGIN TRY

        -------------------------------------------------
        -- MANDATORY FIELD VALIDATION
        -------------------------------------------------

        IF
        (
               ISNULL(LTRIM(RTRIM(@EngineNo)), '') = ''
            OR ISNULL(@InspectionPointID, 0) = 0
            OR ISNULL(@DefectID, 0) = 0
            OR ISNULL(@TakeOutStationID, 0) = 0
            OR ISNULL(LTRIM(RTRIM(@UserName)), '') = ''
            OR ISNULL(@EngineStatus, 0) = 0
        )
        BEGIN

            SET @ResultMessage = 'Fill all mandatory fields';
            SET @ResultStatus = 0;

            SELECT
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

            RETURN;

        END

        -------------------------------------------------
        -- DECLARE VARIABLES
        -------------------------------------------------

        DECLARE
              @UserID     NVARCHAR(50)
            , @PlanID     INT
            , @LineID     INT
            , @SKUID      INT
            , @ProdDate   DATE
            , @ProdShift  NVARCHAR(10);

        -------------------------------------------------
        -- GET USER ID
        -------------------------------------------------

        SELECT
            @UserID = UserID
        FROM dbo.Config_User
        WHERE UserName = @UserName;

        IF ISNULL(@UserID, '') = ''
        BEGIN

            SET @ResultMessage = 'Invalid User Name';
            SET @ResultStatus = 0;

            SELECT
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

            RETURN;

        END

        -------------------------------------------------
        -- GET ENGINE DETAILS
        -------------------------------------------------

        SELECT
              @PlanID    = EW.PlanID
            , @LineID    = EW.LineID
            , @SKUID     = EW.SKUID
            , @ProdDate  = PP.ProdDate
            , @ProdShift = PP.ProdShift
        FROM dbo.Prod_Engine_WIP EW
        INNER JOIN dbo.Prod_Plan PP
            ON EW.PlanID = PP.PlanID
        WHERE EW.EngineNo = @EngineNo;

        IF @PlanID IS NULL
        BEGIN

            SET @ResultMessage = 'Engine not found.';
            SET @ResultStatus = 0;

            SELECT
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

            RETURN;

        END

        -------------------------------------------------
        -- VALIDATE INSPECTION POINT
        -------------------------------------------------

        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Config_Inspection_Point
            WHERE InspectionPointID = @InspectionPointID
        )
        BEGIN

            SET @ResultMessage = 'Invalid Inspection Point.';
            SET @ResultStatus = 0;

            SELECT
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

            RETURN;

        END

        -------------------------------------------------
        -- VALIDATE DEFECT
        -------------------------------------------------

        IF NOT EXISTS
        (
            SELECT 1
            FROM dbo.Config_Inspection_Defect
            WHERE DefectID = @DefectID
        )
        BEGIN

            SET @ResultMessage = 'Invalid Defect.';
            SET @ResultStatus = 0;

            SELECT
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

            RETURN;

        END

        -------------------------------------------------
        -- START TRANSACTION
        -------------------------------------------------

        BEGIN TRAN;

        -------------------------------------------------
        -- INSERT INTO PROD_INSPECTION_LOG
        -------------------------------------------------

        INSERT INTO dbo.Prod_Inspection_Log
        (
            Timestamp,
            InspectionPointID,
            EngineNo,
            Result,
            InspectedBy
        )
        VALUES
        (
            GETDATE(),
            @InspectionPointID,
            @EngineNo,
            2,                  -- NOK
            @UserID
        );

        -------------------------------------------------
        -- INSERT INTO PROD_DEFECT_LOG
        -------------------------------------------------

        INSERT INTO dbo.Prod_Defect_Log
        (
            TimeStamp,
            InspectionRefID,
            DefectRefID,
            EngineNo,
            Remark,
            EngineStatus,
            DefectStatus,
            UpdatedBy,
            LastUpdatedTime
        )
        VALUES
        (
            GETDATE(),
            @InspectionPointID,
            @DefectID,
            @EngineNo,
            @Remark,
            @EngineStatus,
            2,                  -- NOK
            @UserID,
            GETDATE()
        );

        -------------------------------------------------
        -- UPDATE PROD_ENGINE_WIP
        -------------------------------------------------

        UPDATE dbo.Prod_Engine_WIP
        SET
              Status         = @EngineStatus       
            , NotOkStation   = @TakeOutStationID
            , ReEntryStation = NULL
        WHERE EngineNo = @EngineNo;

        IF @@ROWCOUNT = 0
        BEGIN

            ROLLBACK TRAN;

            SET @ResultMessage = 'Engine not found in WIP.';
            SET @ResultStatus = 0;

            SELECT
                @ResultMessage AS ResultMessage,
                @ResultStatus AS ResultStatus;

            RETURN;

        END

        -------------------------------------------------
        -- UPDATE PROD_ENGINEPLANEXECUTION STATUS
        -------------------------------------------------

        --UPDATE dbo.Prod_EnginePlanExecution
        --SET
        --    Status = @EngineStatus              -- Hold
        --WHERE PlanID = @PlanID
        --  AND LineID = @LineID
        --  AND SKUID = @SKUID
        --  AND ProdDate = @ProdDate
        --  AND ProdShift = @ProdShift;

        -------------------------------------------------
        -- UPDATE PROD_ENGINEPLANEXECUTION TAKE OUT QTY
        -------------------------------------------------

        UPDATE dbo.Prod_EnginePlanExecution
        SET
            ENGTakeOut_Qty = ISNULL(ENGTakeOut_Qty, 0) + 1
        WHERE PlanID = @PlanID
          AND LineID = @LineID
          AND SKUID = @SKUID
          AND ProdDate = @ProdDate
          AND ProdShift = @ProdShift;

        -------------------------------------------------
        -- INSERT STATION GENEOLOGY
        -------------------------------------------------

        INSERT INTO dbo.Prod_Station_Geneology
        (
            Timestamp,
            EngineNo,
            StationID,
            Status,
            UserID
        )
        VALUES
        (
            GETDATE(),
            @EngineNo,
            @TakeOutStationID,
            2,
            @UserID
        );

        -------------------------------------------------
        -- INSERT STATUS GENEOLOGY
        -------------------------------------------------

        INSERT INTO dbo.Prod_Status_Geneology
        (
            Timestamp,
            EngineNo,
            Status,
            ProdDate,
            ProdShift
        )
        VALUES
        (
            GETDATE(),
            @EngineNo,
            2,
            @ProdDate,
            @ProdShift
        );

        -------------------------------------------------
        -- COMMIT TRANSACTION
        -------------------------------------------------

        COMMIT TRAN;

        SET @ResultMessage = 'Engine Take Out completed successfully.';
        SET @ResultStatus = 1;

        SELECT
            @ResultMessage AS ResultMessage,
            @ResultStatus AS ResultStatus;

    END TRY

    BEGIN CATCH

        IF @@TRANCOUNT > 0
            ROLLBACK TRAN;

        EXEC dbo.RethrowError;

        SET @ResultMessage = 'SQL ERROR';
        SET @ResultStatus = 0;

        SELECT
            @ResultMessage AS ResultMessage,
            @ResultStatus AS ResultStatus;

    END CATCH

END
