-- [92/376] Stored Procedure: [dbo].[BT_ProdShiftPlan]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Shubham Patil
-- CREATE OR ALTER OR ALTER date : 07-05-2026
-- Description : Procedure for Add, Modify & Delete Production Shift Plan
-- =============================================

 

--*************************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY     | DESCRIPTION     |
-----------------------------------------------------------
--| 07-05-2026 | Shubham Patil  | CREATE OR ALTER OR ALTERd         |
-----------------------------------------------------------
--*************************************************************************

 

CREATE        PROCEDURE [dbo].[BT_ProdShiftPlan]
    @ResultMessage VARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT, -- 0 = ERROR , 1 = SUCCESS
    @Mode INT,                -- 1 = ADD, 2 = UPDATE, 3 = DELETE

 

    -- PARAMETERS FROM GRAPHWORX
    @PlanID INT = NULL,
    @LineID INT = NULL,
    @SKUID INT = NULL,
    @ProdDate DATE = NULL,
    @ProdShift NVARCHAR(10) = NULL,
    @PlanQty INT = NULL,
    @Status INT = NULL,
    @Priority INT = NULL,
    @Source INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

 

    BEGIN TRY

 

        -- =============================================
        -- COMMON VALIDATION
        -- =============================================

 

        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;

 

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

 

        -- =============================================
        -- INSERT / UPDATE VALIDATION
        -- =============================================

 

        IF @Mode IN (1,2)
        BEGIN
            IF @LineID IS NULL
            BEGIN
                SET @ResultMessage = 'LineID is required';
                SET @ResultStatus = 0;

 

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

 

            IF @SKUID IS NULL
            BEGIN
                SET @ResultMessage = 'SKUID is required';
                SET @ResultStatus = 0;

 

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

 

            IF @ProdDate IS NULL
            BEGIN
                SET @ResultMessage = 'ProdDate is required';
                SET @ResultStatus = 0;

 

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

 

            IF @ProdShift IS NULL OR LTRIM(RTRIM(@ProdShift)) = ''
            BEGIN
                SET @ResultMessage = 'ProdShift is required';
                SET @ResultStatus = 0;

 

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

 

            IF LEN(@ProdShift) > 10
            BEGIN
                SET @ResultMessage = 'ProdShift exceeds max length (10)';
                SET @ResultStatus = 0;

 

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

 

            IF @PlanQty IS NULL OR @PlanQty <= 0
            BEGIN
                SET @ResultMessage = 'Valid PlanQty is required';
                SET @ResultStatus = 0;

 

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

 

            IF @Status NOT IN (1,2,3,4,5)
            BEGIN
                SET @ResultMessage = 'Invalid Status';
                SET @ResultStatus = 0;

 

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

 

            IF @Source NOT IN (1,2,3)
            BEGIN
                SET @ResultMessage = 'Invalid Source';
                SET @ResultStatus = 0;

 

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

 

            IF NOT EXISTS (SELECT 1 FROM Config_Line WHERE LineID = @LineID)
            BEGIN
                SET @ResultMessage = 'Invalid LineID';
                SET @ResultStatus = 0;

 

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

 

            IF NOT EXISTS (SELECT 1 FROM Config_SKU WHERE SKUID = @SKUID)
            BEGIN
                SET @ResultMessage = 'Invalid SKUID';
                SET @ResultStatus = 0;

 

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
        END

 

        -- =============================================
        -- INSERT MODE
        -- =============================================

 

        IF @Mode = 1
        BEGIN
            INSERT INTO Prod_Shift_Plan
            (
                LineID,
                SKUID,
                ProdDate,
                ProdShift,
                PlanQty,
                Status,
                Priority,
                Source
            )
            VALUES
            (
                @LineID,
                @SKUID,
                @ProdDate,
                @ProdShift,
                @PlanQty,
                @Status,
                @Priority,
                @Source
            );

 

            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;

 

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

 

        -- =============================================
        -- UPDATE MODE
        -- =============================================

 

        ELSE IF @Mode = 2
        BEGIN
            IF @PlanID IS NULL
            BEGIN
                SET @ResultMessage = 'PlanID is required';
                SET @ResultStatus = 0;

 

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

 

            IF NOT EXISTS (SELECT 1 FROM Prod_Shift_Plan WHERE PlanID = @PlanID)
            BEGIN
                SET @ResultMessage = 'PlanID not found';
                SET @ResultStatus = 0;

 

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

 

            UPDATE Prod_Shift_Plan
            SET
                LineID = CASE WHEN ISNULL(LineID,0) <> ISNULL(@LineID,0)
                              THEN @LineID ELSE LineID END,

 

                SKUID = CASE WHEN ISNULL(SKUID,0) <> ISNULL(@SKUID,0)
                             THEN @SKUID ELSE SKUID END,

 

                ProdDate = CASE WHEN ISNULL(ProdDate,'1900-01-01') <> ISNULL(@ProdDate,'1900-01-01')
                                THEN @ProdDate ELSE ProdDate END,

 

                ProdShift = CASE WHEN ISNULL(ProdShift,'') <> ISNULL(@ProdShift,'')
                                 THEN @ProdShift ELSE ProdShift END,

 

                PlanQty = CASE WHEN ISNULL(PlanQty,0) <> ISNULL(@PlanQty,0)
                               THEN @PlanQty ELSE PlanQty END,

 

                Status = CASE WHEN ISNULL(Status,0) <> ISNULL(@Status,0)
                              THEN @Status ELSE Status END,

 

                Priority = CASE WHEN ISNULL(Priority,0) <> ISNULL(@Priority,0)
                                THEN @Priority ELSE Priority END,

 

                Source = CASE WHEN ISNULL(Source,0) <> ISNULL(@Source,0)
                              THEN @Source ELSE Source END
            WHERE PlanID = @PlanID;

 

            SET @ResultMessage = 'Updated successfully';
            SET @ResultStatus = 1;

 

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

 

        -- =============================================
        -- DELETE MODE
        -- =============================================

 

        ELSE IF @Mode = 3
        BEGIN
            IF @PlanID IS NULL
            BEGIN
                SET @ResultMessage = 'PlanID is required';
                SET @ResultStatus = 0;

 

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

 

            IF NOT EXISTS (SELECT 1 FROM Prod_Shift_Plan WHERE PlanID = @PlanID)
            BEGIN
                SET @ResultMessage = 'PlanID not found';
                SET @ResultStatus = 0;

 

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

 

            DELETE FROM Prod_Shift_Plan
            WHERE PlanID = @PlanID;

 

            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;

 

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END

 

    END TRY

 

    BEGIN CATCH

 

        EXEC RethrowError;

 

        SET @ResultMessage = ERROR_MESSAGE();
        SET @ResultStatus = 0;

 

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

 

    END CATCH
END
GO

-- ------------------------------------------------------------------------
-- [93/376] Stored Procedure: [dbo].[BT_ProdShiftPlan_Execution]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Shubham Patil
-- ALTER OR ALTER date : 06-07-2026
-- Description : Procedure to manage Engine Plan Execution
--               (Start / Hold / Short Close / Modify Line Speed)
--               Reprioritize logic moved to BT_ProdShiftPlan_ExecutionPriority
-- =============================================

--*************************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY     | DESCRIPTION                              |
-----------------------------------------------------------
--| 06-07-2026 | Shubham Patil  | ALTER OR ALTERd     |
--|            |                |             |
--|            |                |             |
-----------------------------------------------------------
--*************************************************************************

CREATE       PROCEDURE [dbo].[BT_ProdShiftPlan_Execution]

    @ResultMessage VARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,   -- 0 = ERROR , 1 = SUCCESS

    @Mode INT,                  -- 1 = START
                                 -- 2 = HOLD
                                 -- 3 = SHORT CLOSE
                                 -- 4 = MODIFY LINE SPEED

    -- PARAMETERS FROM GRAPHWORX
    @PlanID INT = NULL,
    @PlanQty INT = NULL,
    @LineSpeed INT = NULL,
    @UpdatedBy NVARCHAR(100) = NULL

AS
BEGIN

    SET NOCOUNT ON;

    DECLARE @OldStatus INT

    BEGIN TRY

        -- =============================================
        -- COMMON VALIDATION
        -- =============================================

        IF @Mode NOT IN (1,2,3,4)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF @PlanID IS NULL
        BEGIN
            SET @ResultMessage = 'PlanID is required';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF NOT EXISTS (SELECT 1 FROM Prod_EnginePlanExecution WHERE PlanID = @PlanID)
        BEGIN
            SET @ResultMessage = 'PlanID not found';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        SELECT @OldStatus = Status
        FROM Prod_EnginePlanExecution
        WHERE PlanID = @PlanID

        -- =============================================
        -- MODE 1 : START
        -- Only a Plan in Status = 1 (Plan) can be started.
        -- Allows confirming final PlanQty / LineSpeed at start time.
        -- =============================================

        IF @Mode = 1
        BEGIN

            IF @OldStatus <> 1
            BEGIN
                SET @ResultMessage = 'Only Plan status can be started';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            UPDATE Prod_EnginePlanExecution
            SET
                Status = 2,

                PlanQty = CASE
                            WHEN @PlanQty IS NOT NULL
                            THEN @PlanQty
                            ELSE PlanQty
                          END,

                LineSpeed = CASE
                            WHEN @LineSpeed IS NOT NULL
                            THEN @LineSpeed
                            ELSE LineSpeed
                          END
            WHERE PlanID = @PlanID;

            SET @ResultMessage = 'Plan started successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;

        END

        -- =============================================
        -- MODE 2 : HOLD
        -- Allowed only from Running (2) or All Started (3)
        -- =============================================

        ELSE IF @Mode = 2
        BEGIN

            IF @OldStatus NOT IN (2,3)
            BEGIN
                SET @ResultMessage = 'Only Running / All Started plan can be put on Hold';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            UPDATE Prod_EnginePlanExecution
            SET Status = 4
            WHERE PlanID = @PlanID;

            SET @ResultMessage = 'Plan put on Hold successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;

        END

        -- =============================================
        -- MODE 3 : SHORT CLOSE
        -- Allowed from Running (2), All Started (3), or Hold (4)
        -- =============================================

        ELSE IF @Mode = 3
        BEGIN

            IF @OldStatus NOT IN (2,3,4)
            BEGIN
                SET @ResultMessage = 'Plan cannot be Short Closed from its current status';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            UPDATE Prod_EnginePlanExecution
            SET Status = 5
            WHERE PlanID = @PlanID;

            SET @ResultMessage = 'Plan Short Closed successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;

        END

        -- =============================================
        -- MODE 4 : MODIFY LINE SPEED
        -- Line Speed can be changed live, regardless of status,
        -- as long as the plan is not already Short Closed / Completed.
        -- =============================================

        ELSE IF @Mode = 4
        BEGIN

            IF @LineSpeed IS NULL
            BEGIN
                SET @ResultMessage = 'LineSpeed is required';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            IF @OldStatus IN (5,6)
            BEGIN
                SET @ResultMessage = 'Line Speed cannot be modified for a Short Closed / Completed plan';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            UPDATE Prod_EnginePlanExecution
            SET LineSpeed = @LineSpeed
            WHERE PlanID = @PlanID;

            SET @ResultMessage = 'Line Speed updated successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;

        END

    END TRY

    BEGIN CATCH

        EXEC RethrowError;

        SET @ResultMessage = ERROR_MESSAGE();
        SET @ResultStatus = 0;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END CATCH

END
GO

-- ------------------------------------------------------------------------
-- [94/376] Stored Procedure: [dbo].[BT_ProdShiftPlan_ExecutionPriority]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Shubham Patil
-- CREATE OR ALTER OR ALTER OR ALTER date : 06-07-2026
-- Description : Procedure to Move Up / Move Down the Priority of an
--               Engine Plan Execution record (swap with adjacent plan)
--               Only allowed while the plan is in Status = 1 (Plan)
-- =============================================

--*************************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY     | DESCRIPTION                              |
-----------------------------------------------------------
--| 06-07-2026 | Shubham Patil  | CREATE OR ALTER OR ALTER OR ALTERd, based on BT_ProdShiftPlanPriority|
--|            |                | pattern (Move Up / Move Down with swap). |
-----------------------------------------------------------
--*************************************************************************

CREATE        PROCEDURE [dbo].[BT_ProdShiftPlan_ExecutionPriority]

    @ResultMessage VARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,

    @PlanID INT,
    @Mode INT        -- 1 = MOVE UP
                     -- 2 = MOVE DOWN

AS
BEGIN

    SET NOCOUNT ON;

    BEGIN TRY

        DECLARE @CurrentPriority INT
        DECLARE @TargetPriority INT
        DECLARE @CurrentStatus INT

        DECLARE @ProdDate DATE
        DECLARE @ProdShift NVARCHAR(10)

        DECLARE @SwapPlanID INT
        DECLARE @MaxPriority INT

        -- =============================================
        -- VALIDATION
        -- =============================================

        IF @Mode NOT IN (1,2)
        BEGIN
            SET @ResultMessage = 'Invalid Mode';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF NOT EXISTS
        (
            SELECT 1
            FROM Prod_EnginePlanExecution
            WHERE PlanID = @PlanID
        )
        BEGIN
            SET @ResultMessage = 'PlanID not found';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        -- =============================================
        -- GET CURRENT DATA
        -- =============================================

        SELECT
            @CurrentPriority = Priority,
            @CurrentStatus   = Status,
            @ProdDate        = ProdDate,
            @ProdShift       = ProdShift
        FROM Prod_EnginePlanExecution
        WHERE PlanID = @PlanID;

        -- =============================================
        -- ONLY PLAN STATUS CAN BE REPRIORITIZED
        -- =============================================

        IF @CurrentStatus <> 1
        BEGIN
            SET @ResultMessage = 'Only Plan status can be reprioritized';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        -- =============================================
        -- MOVE UP
        -- =============================================

        IF @Mode = 1
        BEGIN

            -- already top
            IF @CurrentPriority <= 1
            BEGIN
                SET @ResultMessage = 'Already highest priority';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            SET @TargetPriority = @CurrentPriority - 1;

        END

        -- =============================================
        -- MOVE DOWN
        -- =============================================

        IF @Mode = 2
        BEGIN

            SELECT @MaxPriority = MAX(Priority)
            FROM Prod_EnginePlanExecution
            WHERE ProdDate = @ProdDate
            AND ProdShift = @ProdShift;

            -- already lowest
            IF @CurrentPriority >= @MaxPriority
            BEGIN
                SET @ResultMessage = 'Already lowest priority';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            SET @TargetPriority = @CurrentPriority + 1;

        END

        -- =============================================
        -- FIND SWAP RECORD
        -- =============================================

        SELECT @SwapPlanID = PlanID
        FROM Prod_EnginePlanExecution
        WHERE ProdDate = @ProdDate
        AND ProdShift = @ProdShift
        AND Priority = @TargetPriority;

        -- =============================================
        -- SWAP PRIORITIES
        -- =============================================

        UPDATE Prod_EnginePlanExecution
        SET Priority = @TargetPriority
        WHERE PlanID = @PlanID;

        UPDATE Prod_EnginePlanExecution
        SET Priority = @CurrentPriority
        WHERE PlanID = @SwapPlanID;

        IF @Mode = 1
        BEGIN
            SET @ResultMessage = 'Priority increased successfully';
        END
        ELSE IF @Mode = 2
        BEGIN
            SET @ResultMessage = 'Priority decreased successfully';
        END

        SET @ResultStatus = 1;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END TRY

    BEGIN CATCH

        EXEC RethrowError;

        SET @ResultMessage = ERROR_MESSAGE();
        SET @ResultStatus = 0;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END CATCH

END
GO

-- ------------------------------------------------------------------------
-- [95/376] Stored Procedure: [dbo].[BT_ProdShiftPlan_SendToLine]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Shubham Patil
-- ALTER OR ALTER date : 08-06-2026
-- Description : Procedure to Send a Production Shift Plan to the Line
--               (extracted from BT_ProdShiftPlan, Mode = 4)
-- =============================================

--*************************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY     | DESCRIPTION                              |
-----------------------------------------------------------
--|            |                |                             |
--|            |                |                             |
--|            |                |                             |
--|            |                |                             |
-----------------------------------------------------------
--*************************************************************************

CREATE     PROCEDURE [dbo].[BT_ProdShiftPlan_SendToLine]

    @ResultMessage VARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT, -- 0 = ERROR , 1 = SUCCESS

    @PlanID INT = NULL

AS
BEGIN

    SET NOCOUNT ON;

    DECLARE @CurrentDate DATE = CAST(GETDATE() AS DATE)
    DECLARE @CurrentTime TIME
    DECLARE @RunningShift NVARCHAR(10)

    DECLARE @OldStatus INT
    DECLARE @OldProdDate DATE
    DECLARE @ProdShift NVARCHAR(10)

    BEGIN TRY

        -- =============================================
        -- VALIDATION
        -- =============================================

        IF @PlanID IS NULL
        BEGIN
            SET @ResultMessage = 'PlanID is required';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF NOT EXISTS (SELECT 1 FROM Prod_Plan WHERE PlanID = @PlanID)
        BEGIN
            SET @ResultMessage = 'PlanID not found';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        SELECT
            @OldStatus = Status,
            @OldProdDate = ProdDate,
            @ProdShift = ProdShift
        FROM Prod_Plan
        WHERE PlanID = @PlanID

        -- =============================================
        -- ONLY CURRENT DAY PLAN CAN SEND TO LINE
        -- =============================================

        IF @OldProdDate <> @CurrentDate
        BEGIN
            SET @ResultMessage = 'Only current day plan can be sent to line';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        -- =============================================
        -- RUNNING SHIFT VALIDATION
        -- =============================================

        SET @CurrentTime = CAST(GETDATE() AS TIME)

        SET @RunningShift =
        CASE
            WHEN @CurrentTime >= '06:00:00'
                 AND @CurrentTime < '15:30:00'
            THEN 'A'

            WHEN @CurrentTime >= '15:51:00'
                 AND @CurrentTime < '22:00:00'
            THEN 'B'

            ELSE 'C'
        END

        IF @ProdShift <> @RunningShift
        BEGIN
            SET @ResultMessage = 'Only running shift plan can send to line';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        -- =============================================
        -- ALREADY SENT VALIDATION
        -- =============================================

        IF @OldStatus = 2
        BEGIN
            SET @ResultMessage = 'Plan already sent to line';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        UPDATE Prod_Plan
        SET Status = 2
        WHERE PlanID = @PlanID

        SET @ResultMessage = 'Plan sent to line successfully';
        SET @ResultStatus = 1;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END TRY

    BEGIN CATCH

        EXEC RethrowError;

        SET @ResultMessage = ERROR_MESSAGE();
        SET @ResultStatus = 0;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END CATCH

END
GO

