        -- =============================================
        -- MOVE UP
        -- =============================================
 
        IF @Mode = 1
        BEGIN
 
            -- already top
            IF @CurrentPriority <= 1
            BEGIN
                SET @ResultMessage = 'Already highest priority';
                SET @ResultStatus = 0;
 
                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
 
            SET @TargetPriority = @CurrentPriority - 1;
 
        END
 
        -- =============================================
        -- MOVE DOWN
        -- =============================================
 
        IF @Mode = 2
        BEGIN
 
            SELECT @MaxPriority = MAX(Priority)
            FROM Prod_Shift_Plan
            WHERE ProdDate = @ProdDate
            AND ProdShift = @ProdShift;
 
            -- already lowest
            IF @CurrentPriority >= @MaxPriority
            BEGIN
                SET @ResultMessage = 'Already lowest priority';
                SET @ResultStatus = 0;
 
                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
 
            SET @TargetPriority = @CurrentPriority + 1;
 
        END
 
        -- =============================================
        -- FIND SWAP RECORD
        -- =============================================
 
        SELECT @SwapPlanID = PlanID
        FROM Prod_Shift_Plan
        WHERE ProdDate = @ProdDate
        AND ProdShift = @ProdShift
        AND Priority = @TargetPriority;
 
        -- =============================================
        -- SWAP PRIORITIES
        -- =============================================
 
        UPDATE Prod_Shift_Plan
        SET Priority = @TargetPriority
        WHERE PlanID = @PlanID;
 
        UPDATE Prod_Shift_Plan
        SET Priority = @CurrentPriority
        WHERE PlanID = @SwapPlanID;
 
IF @Mode = 1
BEGIN
    SET @ResultMessage = 'Priority increased successfully';
END
ELSE IF @Mode = 2
BEGIN
    SET @ResultMessage = 'Priority decreased successfully';
END

SET @ResultStatus = 1;

SELECT @ResultMessage AS ResultMessage,
       @ResultStatus AS ResultStatus;       
       SET @ResultStatus = 1;
 
        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;
 
    END TRY
 
    BEGIN CATCH
 
        SET @ResultMessage = ERROR_MESSAGE();
        SET @ResultStatus = 0;
 
        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;
 
    END CATCH
 
END
GO

-- ------------------------------------------------------------------------
-- [97/376] Stored Procedure: [dbo].[BT_PY_Bypass_Log_Insert]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE       PROCEDURE [dbo].[BT_PY_Bypass_Log_Insert]
(
    @ActivityID INT,
    @Status INT,
    @Remark NVARCHAR(300),
    @UserID NVARCHAR(50)
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        -- Validate Pokayoke ID
        IF @ActivityID NOT BETWEEN 1 AND 500
        BEGIN
            RAISERROR('Invalid Pokayoke ID. Pokayoke ID must be between 1 and 500.', 16, 1);
            RETURN;
        END

        -- Validate Status
        -- 0 = Bypass
        -- 1 = Enable
        IF @Status NOT IN (0, 1)
        BEGIN
            RAISERROR('Invalid Status. Status must be 0 or 1.', 16, 1);
            RETURN;
        END

        -- Validate Reason
        IF ISNULL(LTRIM(RTRIM(@Remark)), '') = ''
        BEGIN
            RAISERROR('Reason is mandatory.', 16, 1);
            RETURN;
        END

        -- Validate User
        IF ISNULL(LTRIM(RTRIM(@UserID)), '') = ''
        BEGIN
            RAISERROR('User ID is mandatory.', 16, 1);
            RETURN;
        END

        IF @Status = 1
        begin
        set @Status = 0;
        END
        ELSE
        begin
        Set @Status = 1
        end;

        -- Insert Pokayoke action into log
        INSERT INTO dbo.Prod_PY_Bypass_Log
        (
            [Timestamp],
            ActivityID,
            Status,
            Remark,
            UserID
        )
        VALUES
        (
            GETDATE(),
            @ActivityID,
            @Status,
            @Remark,
            @UserID
        );

        -- Success response
        SELECT
            1 AS ResultStatus,
            'Pokayoke status updated successfully.' AS ResultMessage;

    END TRY

    BEGIN CATCH
        EXEC dbo.RethrowError;
    END CATCH
END
GO

-- ------------------------------------------------------------------------
-- [98/376] Stored Procedure: [dbo].[BT_SA_PlanExecution]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Vishal Verma
-- Created OR ALTER date : 25-08-2026
-- Description : Procedure to manage SA Plan Execution
--               (Start)
--               
-- =============================================

--*************************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY     | DESCRIPTION                              |
-----------------------------------------------------------
--| 25-08-2026 | Vishal Verma  | ALTER OR ALTERd     |
--|            |                |             |
--|            |                |             |
-----------------------------------------------------------
--*************************************************************************

Create   PROCEDURE [dbo].[BT_SA_PlanExecution]

    @ResultMessage VARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,   -- 0 = ERROR , 1 = SUCCESS

    @Mode INT,                  -- 1 = START
                                 

    -- PARAMETERS FROM GRAPHWORX
    @PlanID INT = NULL,
    @SubAssemblyID INT =NULL,
   
    @UpdatedBy NVARCHAR(100) = NULL

AS
BEGIN

    SET NOCOUNT ON;

    DECLARE @OldStatus INT;
    DECLARE @CurrentDate DATE;
    DECLARE @RunningShift NVARCHAR(10);
    DECLARE @OldProdDate DATE;
    DECLARE @ProdShift NVARCHAR(10);
    DECLARE @Priority INT;
    DECLARE @LeastPriority INT;


    BEGIN TRY

        -- =============================================
        -- COMMON VALIDATION
        -- =============================================

        IF @Mode NOT IN (1)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF @PlanID IS NULL
        BEGIN
            SET @ResultMessage = 'PlanID is required';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END

        IF NOT EXISTS (SELECT 1 FROM Prod_SA_PlanExecution WHERE PlanID = @PlanID and SubAsslyLineID = @SubAssemblyID)
        BEGIN
            SET @ResultMessage = 'PlanID not found';
            SET @ResultStatus = 0;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END
        Select  top(1) @CurrentDate = ParameterValue from ApplicationSetting Where LineID= 1 and
        ParameterID=1;
        Select  top(1) @RunningShift = ParameterValue from ApplicationSetting Where LineID= 1 and
        ParameterID=2;
        Select @OldStatus = Status, @Priority = Priority,@OldProdDate = ProdDate,@ProdShift = ProdShift from Prod_SA_PlanExecution
        Where PlanID = @PlanID and SubAsslyLineID = @SubAssemblyID
        
        SELECT  Top (1) @LeastPriority = MIN(Priority) FROM Prod_SA_PlanExecution 
        WHERE Status = 1 AND SubAsslyLineID = @SubAssemblyID
        AND ProdDate = @CurrentDate AND ProdShift = @RunningShift

        -- =============================================
        -- MODE 1 : START
        -- Only a Plan in Status = 1 (Plan) can be started.
        -- Allows confirming final PlanQty / LineSpeed at start time.
        -- =============================================

        IF @Mode = 1
        BEGIN
        IF (((@OldProdDate <> @CurrentDate) or (@ProdShift <> @RunningShift)))
         BEGIN
                SET @ResultMessage = 'This Plan can not be start in this Shift';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

        --BEGIN

            IF @OldStatus  in(2,3,5,6)
            BEGIN
                SET @ResultMessage = 'Only Plan or Hold status can be started';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
            IF (@Priority != @LeastPriority)
            BEGIN
                SET @ResultMessage = 'Plese Resequence this Plan first';
                SET @ResultStatus = 0;

                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END

            UPDATE Prod_SA_PlanExecution 
            SET
                Status = 2 WHERE PlanID = @PlanID AND SubAsslyLineID = @SubAssemblyID;

            SET @ResultMessage = 'Plan started successfully';
            SET @ResultStatus = 1;

            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;

        END


        END

     TRY

    BEGIN CATCH

        EXEC RethrowError;

        SET @ResultMessage = ERROR_MESSAGE();
        SET @ResultStatus = 0;

        SELECT @ResultMessage AS ResultMessage,
               @ResultStatus AS ResultStatus;

    END CATCH

END
GO

