-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE   PROCEDURE [dbo].[BT_UPD_Downtime]

    @DowntimeID BIGINT,
    @4MLossID INT,
    @LossID INT,
    @SubLossID INT,
    @Reason NVARCHAR(MAX),
    @User NVARCHAR (20),
    @ResultStatus INT OUTPUT,
    @ResultMessage NVARCHAR(200) OUTPUT

AS
BEGIN
    SET NOCOUNT ON;

    UPDATE Perf_Downtime
    SET
        [4MLossID] = @4MLossID,
        LossID     = @LossID,
        SubLossID  = @SubLossID,
        Reason     = @Reason,
        UserID     = @User
    WHERE DowntimeID = @DowntimeID;

    IF @@ROWCOUNT > 0
    BEGIN
        SET @ResultStatus = 1;
        SET @ResultMessage = 'Downtime updated successfully.';
    END
    ELSE
    BEGIN
        SET @ResultStatus = 0;
        SET @ResultMessage = 'No record found to update.';
    END
END
GO

