CREATE     PROCEDURE [dbo].[BT_WeeklyOperatorPlan]
 
    @ResultMessage NVARCHAR(MAX) OUTPUT,
    @ResultStatus INT OUTPUT,
    @Mode INT,
    @StartDate DATE,
    @EndDate DATE,
    @ShiftName NVARCHAR (10),
    @UserID NVARCHAR(10),
    @UserName NVARCHAR(100)
 
AS
BEGIN
    SET NOCOUNT ON;
 
    BEGIN TRY
 
        -------------------------------------------------
        -- COMMON VALIDATION
        -------------------------------------------------
        IF @Mode NOT IN (1,2,3)
        BEGIN
            SET @ResultMessage = 'Invalid Mode specified.';
            SET @ResultStatus = 0;
 
            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END
 
        IF @Mode IN (2,3) AND ISNULL(@UserID,'') = ''
        BEGIN
            SET @ResultMessage = 'UserID is required';
            SET @ResultStatus = 0;
 
            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
            RETURN;
        END
 
        -------------------------------------------------
        -- INSERT / UPDATE VALIDATION
        -------------------------------------------------
        IF @Mode IN (1,2)
        BEGIN
            IF ISNULL(@UserID,'') = ''
               OR ISNULL(@ShiftName,'') = ''
            BEGIN
                SET @ResultMessage = 'Fill all mandatory fields';
                SET @ResultStatus = 0;
 
                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
 
            -------------------------------------------------
            -- DUPLICATE VALIDATION
            -------------------------------------------------
            IF EXISTS
            (
                SELECT 1
                FROM dbo.Prod_WeeklyOperatorPlan
                WHERE UserID = @UserID
                  AND ProdShift = @ShiftName
                  And StartDate <= @EndDate
                  And EndDate >= @StartDate
            )
            BEGIN
                SET @ResultMessage = 'Operator already exists';
                SET @ResultStatus = 0;
 
                SELECT @ResultMessage AS ResultMessage,
                       @ResultStatus AS ResultStatus;
                RETURN;
            END
        END
 
        -------------------------------------------------
        -- INSERT MODE
        -------------------------------------------------
        IF @Mode = 1
        BEGIN
 
            INSERT INTO dbo.Prod_WeeklyOperatorPlan
            (
               [ProdShift]
               ,[StartDate]
              ,[EndDate]
              ,[UserID]
              ,[LastUpdatedTime]
              ,[LastUpdatedBy]
            )
            VALUES
            (
                @ShiftName,
                @StartDate,
                @EndDate,
                @UserID,
                GETDATE(),
                @UserName

            );
 
            
 
            ;WITH DateRange AS
(
    SELECT @StartDate AS ProdDate

    UNION ALL

    SELECT DATEADD(DAY,1,ProdDate)
    FROM DateRange
    WHERE ProdDate < @EndDate
)

        INSERT INTO dbo.Prod_DailyOperatorPlan
        (
            UserID,
            ProdDate,
            ProdShift,
            UserStatus,
            LastUpdatedTime,
            LastUpdatedBy
        )
        SELECT
            @UserID,
            D.ProdDate,
            @ShiftName,
            1,
            GETDATE(),
            @UserName
        FROM DateRange D
        WHERE NOT EXISTS
        (
            SELECT 1
            FROM dbo.Prod_DailyOperatorPlan P
            WHERE P.UserID = @UserID
              AND P.ProdDate = D.ProdDate
              AND P.ProdShift = @ShiftName
        )
        OPTION (MAXRECURSION 32767);
 
            SET @ResultMessage = 'Inserted successfully';
            SET @ResultStatus = 1;
 
            SELECT @ResultMessage AS ResultMessage,
                   @ResultStatus AS ResultStatus;
        END
 
        -------------------------------------------------
        -- UPDATE MODE
        -------------------------------------------------
        --ELSE IF @Mode = 2
        --BEGIN
 
        --    DECLARE
        --        @OldVendorName NVARCHAR(100),
        --        @OldVendorCode INT,
        --        @OldVendorDesc NVARCHAR(300),
        --        @OldVendorStatus INT,
        --        @OldVendorType INT;
 
