                       @ResultStatus AS ResultStatus;
                RETURN;
            END
 
            DELETE
            FROM dbo.Prod_WeeklyOperatorPlan
            WHERE UserID = @UserID AND ProdShift = @ShiftName AND StartDate = @StartDate
            AND EndDate = @EndDate
            DELETE
            FROM dbo.Prod_DailyOperatorPlan
            WHERE UserID = @UserID AND ProdShift = @ShiftName AND ProdDate Between @StartDate
            AND @EndDate
            
 
            SET @ResultMessage = 'Deleted successfully';
            SET @ResultStatus = 1;
 
