-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE     PROCEDURE [dbo].[DD_Config_Station_Position1]
AS
BEGIN
    SET NOCOUNT ON;

    SELECT DISTINCT
        StationID,
        StationName
    FROM dbo.Config_Station
    ORDER BY StationName;
END
GO

-- ------------------------------------------------------------------------
-- [113/376] Stored Procedure: [dbo].[DD_Config_Station_Position2]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE     PROCEDURE [dbo].[DD_Config_Station_Position2]
    @Position1 INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT DISTINCT
        StationID,
        StationName
    FROM dbo.Config_Station
    WHERE (@Position1 IS NULL OR StationID <> @Position1)
    ORDER BY StationName;
END
GO

-- ------------------------------------------------------------------------
-- [114/376] Stored Procedure: [dbo].[DD_Config_Station_Position3]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE     PROCEDURE [dbo].[DD_Config_Station_Position3]
    @Position1 INT = NULL,
    @Position2 INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT DISTINCT
        StationID,
        StationName
    FROM dbo.Config_Station
    WHERE StationID NOT IN (
        SELECT Val FROM (VALUES (@Position1), (@Position2)) AS X(Val)
        WHERE Val IS NOT NULL
    )
    ORDER BY StationName;
END
GO

-- ------------------------------------------------------------------------
-- [115/376] Stored Procedure: [dbo].[DD_Config_Station_Position4]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE     PROCEDURE [dbo].[DD_Config_Station_Position4]
    @Position1 INT = NULL,
    @Position2 INT = NULL,
    @Position3 INT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    SELECT DISTINCT
        StationID,
        StationName
    FROM dbo.Config_Station
    WHERE StationID NOT IN (
        SELECT Val FROM (VALUES (@Position1), (@Position2), (@Position3)) AS X(Val)
        WHERE Val IS NOT NULL
    )
    ORDER BY StationName;
END
GO

