-- ------------------------------------------------------------------------
-- [130/376] Stored Procedure: [dbo].[DD_Filter_UserID]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE         PROCEDURE [dbo].[DD_Filter_UserID]
(
    @StationID INT
)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT DISTINCT
        CU.UserID,
        CU.UserName
    FROM Config_User CU
    INNER JOIN Prod_OperatorStationMapping OSM
        ON CU.UserID = OSM.UserID
    INNER JOIN Prod_DailyOperatorPlan DOP
        ON CU.UserID = DOP.UserID
    WHERE
        OSM.StationID = @StationID
        AND DOP.ProdDate = CAST(GETDATE() AS DATE)
        AND DOP.UserStatus = 4      -- Assigned
    ORDER BY
        CU.UserName;
END
GO

