-- ------------------------------------------------------------------------
-- [139/376] Stored Procedure: [dbo].[DD_HardCoded]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author     :	Mamatha M
-- CREATE OR ALTER OR ALTER date: 17-07-2026
-- Description:	Hard coded dropdown fetched data from Config_Dropdown table
-- =============================================
--*************************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY     | DESCRIPTION     |
-----------------------------------------------------------
--| 17-07-2026 | Mamatha M      | CREATE OR ALTER OR ALTERd         |
-----------------------------------------------------------
--*************************************************************************
CREATE       PROCEDURE [dbo].[DD_HardCoded]
@TableName  NVARCHAR(100),
@FieldName  NVARCHAR(100)
AS
BEGIN
	SELECT DISTINCT 
		FieldValue,
		FieldDesc, 
		(
			SELECT COUNT(DISTINCT FieldValue) 
			FROM [dbo].[Config_DropDown]
			WHERE TableName=@TableName AND FieldName=@FieldName
		) as TotalCount
	
	FROM [dbo].[Config_DropDown]
	WHERE TableName=@TableName AND FieldName=@FieldName
