-- ------------------------------------------------------------------------
-- [169/376] Stored Procedure: [dbo].[DD_RealtimeStatusDashboard_SKU]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE       PROCEDURE [dbo].[DD_RealtimeStatusDashboard_SKU]
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        DECLARE @ProdDate DATE;
        DECLARE @ProdShift NVARCHAR(50);

        /* GET CURRENT PRODUCTION DATE */
        SELECT TOP (1)
            @ProdDate = TRY_CONVERT(DATE, ParameterValue)
        FROM dbo.ApplicationSetting
        WHERE ParameterName = 'ProdDate'
        ORDER BY UID DESC;


        /* GET CURRENT PRODUCTION SHIFT */
        SELECT TOP (1)
            @ProdShift = ParameterValue
        FROM dbo.ApplicationSetting
        WHERE ParameterName = 'ProdShift'
        ORDER BY UID DESC;


        /* ALL SKU */
        SELECT
            0 AS SKUID,
            'All' AS SKUName,

            (
                SELECT COUNT(DISTINCT PE.SKUID)
                FROM dbo.Prod_SA_PlanExecution PE
                WHERE PE.ProdDate = @ProdDate
                  AND PE.ProdShift = @ProdShift
            ) + 1 AS TotalCount


        UNION ALL


        /* AVAILABLE SKUs */
        SELECT DISTINCT
            PE.SKUID,
            CS.SKUName,

            (
                SELECT COUNT(DISTINCT PE1.SKUID)
                FROM dbo.Prod_SA_PlanExecution PE1
                WHERE PE1.ProdDate = @ProdDate
                  AND PE1.ProdShift = @ProdShift
            ) + 1 AS TotalCount

        FROM dbo.Prod_SA_PlanExecution PE

        INNER JOIN dbo.Config_SKU CS
            ON PE.SKUID = CS.SKUID

        WHERE PE.ProdDate = @ProdDate
          AND PE.ProdShift = @ProdShift

        ORDER BY
            SKUID;

    END TRY

    BEGIN CATCH
        EXEC dbo.RethrowError;
    END CATCH

END
GO

