-- ------------------------------------------------------------------------
-- [171/376] Stored Procedure: [dbo].[DD_ShiftDashboard_SKU]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE       PROCEDURE [dbo].[DD_ShiftDashboard_SKU]
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @ProdDate DATE,
            @ProdShift NVARCHAR(10);

    -- Get Current Production Date
    SELECT TOP (1)
        @ProdDate = ParameterValue
    FROM ApplicationSetting
    WHERE ParameterID = 1
    ORDER BY UID DESC;

    -- Get Current Shift
    SELECT TOP (1)
        @ProdShift = ParameterValue
    FROM ApplicationSetting
    WHERE ParameterID = 2
    ORDER BY UID DESC;

    SELECT
        0 AS SKUID,
        'All' AS SKUName,
        (
            SELECT COUNT(DISTINCT PE.SKUID)
            FROM Prod_EnginePlanExecution PE
            WHERE PE.ProdDate = @ProdDate
              AND PE.ProdShift = @ProdShift
              
        ) + 1 AS TotalCount

    UNION ALL

    SELECT DISTINCT
        PE.SKUID,
        CS.SKUName,
        (
            SELECT COUNT(DISTINCT PE1.SKUID)
            FROM Prod_EnginePlanExecution PE1
            WHERE PE1.ProdDate = @ProdDate
              AND PE1.ProdShift = @ProdShift
              
        ) + 1 AS TotalCount
    FROM Prod_EnginePlanExecution PE
    INNER JOIN Config_SKU CS
        ON PE.SKUID = CS.SKUID
    WHERE PE.ProdDate = @ProdDate
      AND PE.ProdShift = @ProdShift
      

    ORDER BY SKUID;
END
GO

