-- ------------------------------------------------------------------------
-- [205/376] Stored Procedure: [dbo].[DS_QA_AuditMonitoringKPI]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE     PROCEDURE [dbo].[DS_QA_AuditMonitoringKPI]
AS
BEGIN
    SET NOCOUNT ON;

    SELECT

        -- Notification Counts
        SUM(CASE WHEN Notification = 1 THEN 1 ELSE 0 END) AS NormalCount,
        SUM(CASE WHEN Notification = 2 THEN 1 ELSE 0 END) AS AlertCount,
        SUM(CASE WHEN Notification = 3 THEN 1 ELSE 0 END) AS WarningCount,
        SUM(CASE WHEN Notification = 4 THEN 1 ELSE 0 END) AS AlarmCount,

        -- Status Counts
        SUM(CASE WHEN Status = 0 THEN 1 ELSE 0 END) AS NotScheduleCount,
        SUM(CASE WHEN Status = 1 THEN 1 ELSE 0 END) AS PlanCount,
        SUM(CASE WHEN Status = 2 THEN 1 ELSE 0 END) AS InProcessCount,
        SUM(CASE WHEN Status = 3 THEN 1 ELSE 0 END) AS CompletedCount,
        SUM(CASE WHEN Status = 4 THEN 1 ELSE 0 END) AS BypassCount,
        SUM(CASE WHEN Status = 5 THEN 1 ELSE 0 END) AS NotDoneCount,
        SUM(CASE WHEN Status = 6 THEN 1 ELSE 0 END) AS AdditionalTestCount,

        -- Total Records
        COUNT(*) AS TotalCount

    FROM QA_AuditMonitoring;
END
GO

-- ------------------------------------------------------------------------
-- [206/376] Stored Procedure: [dbo].[DS_ShiftDashboard_CCLH]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author:        Sumit
-- Create date: 08 July 2026
-- Description:  Shift Dashboard CCLH Details
-- =============================================

CREATE     PROCEDURE [dbo].[DS_ShiftDashboard_CCLH]
(
      @SKUID INT = 0
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        DECLARE @ProdDate DATE,
                @ProdShift NVARCHAR(10);

        -- Current Production Date
        SELECT TOP (1)
            @ProdDate = CONVERT(DATE, ParameterValue, 105)
        FROM dbo.Prod_ShiftInformation
        WHERE ParameterName = 'ProdDate'
        ORDER BY UID DESC;

        -- Current Production Shift
        SELECT TOP (1)
            @ProdShift = ParameterValue
        FROM dbo.Prod_ShiftInformation
        WHERE ParameterName = 'ProdShift'
        ORDER BY UID DESC;

        SELECT

            SUM(ISNULL(C.Planned,0))    AS OrderStarted,
            SUM(ISNULL(C.Completed,0))  AS OrderCompleted,
            SUM(ISNULL(C.InProcess,0))  AS NotOK,
            SUM(ISNULL(C.Married,0))    AS Married

        FROM dbo.Prod_CCLH_PlanExecution C
        INNER JOIN dbo.Prod_Shift_Plan P
            ON C.PlanID = P.PlanID

        WHERE
            P.ProdDate = @ProdDate
            AND P.ProdShift = @ProdShift
            AND
            (
                @SKUID = 0
                OR P.SKUID = @SKUID
            );

    END TRY

    BEGIN CATCH
        EXEC dbo.RethrowError;
    END CATCH

END
GO

