-- ------------------------------------------------------------------------
-- [211/376] Stored Procedure: [dbo].[EngineWIP_StatusDashboard]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE     PROCEDURE [dbo].[EngineWIP_StatusDashboard]
(
    @SKUID INT = 0
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE
        @ProdDate  DATE,
        @ProdShift NVARCHAR(10);

    /* Get Current Production Date */
    SELECT TOP 1
        @ProdDate = TRY_CONVERT(DATE, ParameterValue)
    FROM dbo.ApplicationSetting
    WHERE ParameterID = 1
    AND LineID=1
    ORDER BY UID DESC;

    /* Get Current Production Shift */
    SELECT TOP 1
        @ProdShift = TRY_CONVERT(nvarchar(10), ParameterValue)
    FROM dbo.ApplicationSetting
    WHERE ParameterID = 2
    AND LineID=1
    ORDER BY UID DESC;


    ;WITH PlanData AS
    (
        SELECT
            ISNULL(SUM(PlanQty), 0) AS PlanQty,
            ISNULL(SUM(KitAssembly_Qty), 0) AS OrderStarted
        FROM dbo.Prod_EnginePlanExecution
        WHERE ProdDate = @ProdDate
          AND ProdShift = @ProdShift
          AND (@SKUID = 0 OR SKUID = @SKUID)
    ),

    WIPData AS
    (
        SELECT
            ISNULL(SUM(CASE WHEN W.Status = 1  THEN 1 ELSE 0 END), 0) AS [Plan],
            ISNULL(SUM(CASE WHEN W.Status = 2  THEN 1 ELSE 0 END), 0) AS [KitStarted],
            ISNULL(SUM(CASE WHEN W.Status = 3  THEN 1 ELSE 0 END), 0) AS [KitInspected],
            ISNULL(SUM(CASE WHEN W.Status = 4  THEN 1 ELSE 0 END), 0) AS [VREngineOnMainLine],
            ISNULL(SUM(CASE WHEN W.Status = 5  THEN 1 ELSE 0 END), 0) AS [EngineOnMainLine],
            ISNULL(SUM(CASE WHEN W.Status = 6  THEN 1 ELSE 0 END), 0) AS [NotOK],
            ISNULL(SUM(CASE WHEN W.Status = 7  THEN 1 ELSE 0 END), 0) AS [NotOKBypass],
            ISNULL(SUM(CASE WHEN W.Status = 8  THEN 1 ELSE 0 END), 0) AS [OKBypass],
            ISNULL(SUM(CASE WHEN W.Status = 9  THEN 1 ELSE 0 END), 0) AS [CompletedEngine],
            ISNULL(SUM(CASE WHEN W.Status = 10 THEN 1 ELSE 0 END), 0) AS [FGEngine],
            ISNULL(SUM(CASE WHEN W.Status = 11 THEN 1 ELSE 0 END), 0) AS [EngineScrapped],
            ISNULL(SUM(CASE WHEN W.Status = 12 THEN 1 ELSE 0 END), 0) AS [MaterialHold],
            ISNULL(SUM(CASE WHEN W.Status = 13 THEN 1 ELSE 0 END), 0) AS [MaterialHoldCleared],
            ISNULL(SUM(CASE WHEN W.Status = 14 THEN 1 ELSE 0 END), 0) AS [ForRework],
            ISNULL(SUM(CASE WHEN W.Status = 15 THEN 1 ELSE 0 END), 0) AS [ProdReworkOK],
            ISNULL(SUM(CASE WHEN W.Status = 16 THEN 1 ELSE 0 END), 0) AS [ProdHold],
            ISNULL(SUM(CASE WHEN W.Status = 17 THEN 1 ELSE 0 END), 0) AS [ProdHoldCleared],
            ISNULL(SUM(CASE WHEN W.Status = 18 THEN 1 ELSE 0 END), 0) AS [ProdRejected],
            ISNULL(SUM(CASE WHEN W.Status = 19 THEN 1 ELSE 0 END), 0) AS [ForIPQCRework],
            ISNULL(SUM(CASE WHEN W.Status = 20 THEN 1 ELSE 0 END), 0) AS [IPQCReworkOK],
            ISNULL(SUM(CASE WHEN W.Status = 21 THEN 1 ELSE 0 END), 0) AS [IPQCHold],
            ISNULL(SUM(CASE WHEN W.Status = 22 THEN 1 ELSE 0 END), 0) AS [IPQCHoldCleared],
            ISNULL(SUM(CASE WHEN W.Status = 23 THEN 1 ELSE 0 END), 0) AS [IPQCRejected],
            ISNULL(SUM(CASE WHEN W.Status = 24 THEN 1 ELSE 0 END), 0) AS [FQCRework],
            ISNULL(SUM(CASE WHEN W.Status = 25 THEN 1 ELSE 0 END), 0) AS [FGReworkOK],
            ISNULL(SUM(CASE WHEN W.Status = 26 THEN 1 ELSE 0 END), 0) AS [FQCHold],
            ISNULL(SUM(CASE WHEN W.Status = 27 THEN 1 ELSE 0 END), 0) AS [FQCHoldCleared],
            ISNULL(SUM(CASE WHEN W.Status = 28 THEN 1 ELSE 0 END), 0) AS [FGRejected]

        FROM dbo.Prod_Engine_WIP W
        WHERE (@SKUID = 0 OR W.SKUID = @SKUID)
          AND EXISTS
          (
              SELECT 1
              FROM dbo.Prod_EnginePlanExecution P
              WHERE P.PlanID = W.PlanID
                AND P.ProdDate = @ProdDate
                AND P.ProdShift = @ProdShift
                AND (@SKUID = 0 OR P.SKUID = @SKUID)
          )
    )

       SELECT
        @ProdDate AS ProdDate,
        @ProdShift AS ProdShift,
        @SKUID AS SKUID,
        P.PlanQty,
        P.OrderStarted,

        W.[Plan],
        W.KitStarted,
        W.KitInspected,
        W.VREngineOnMainLine,
        W.EngineOnMainLine,
        W.NotOK,
        W.NotOKBypass,
        W.OKBypass,
        W.CompletedEngine,
        W.FGEngine,
        W.EngineScrapped,
        W.MaterialHold,
        W.MaterialHoldCleared,
        W.ForRework,
        W.ProdReworkOK,
        W.ProdHold,
        W.ProdHoldCleared,
        W.ProdRejected,
        W.ForIPQCRework,
        W.IPQCReworkOK,
        W.IPQCHold,
        W.IPQCHoldCleared,
        W.IPQCRejected,
        W.FQCRework,
        W.FGReworkOK,
        W.FQCHold,
        W.FQCHoldCleared,
        W.FGRejected

    FROM PlanData P
    CROSS JOIN WIPData W;

END
GO

-- ------------------------------------------------------------------------
-- [212/376] Stored Procedure: [dbo].[GetActiveAlarmDashboard]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================================================
-- Procedure Name : sp_GetActiveAlarmDashboard
-- Description    : Displays active machine/station alarms per stage for the 
--                  maintenance dashboard. Pulls from Config_Station, 
--                  Config_Equipment, Config_Alarm, and Maint_ActiveAlarm.
--                  All stations show even without an active alarm (LEFT JOIN).
-- =============================================================================
-- History:
-- Date         Author          Description
-- -----------  --------------  ---------------------------------------------
-- 2026-07-08   Sumit   Initial creation of stored procedure.
-- =============================================================================

CREATE         PROCEDURE [dbo].[GetActiveAlarmDashboard]
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        CS.StageNo                                   AS Stage,
        CE.EquipmentName                             AS Machine,
        CA.AlarmDesc                                 AS AlarmDesc,
        CA.DepartmentID                              AS DepartmentID,
        COALESCE(MA.Priority, CA.Priority)           AS Priority,
        CASE 
            WHEN MA.AlarmID IS NOT NULL THEN 'Active' 
            ELSE NULL 
        END                                           AS AlarmStatus,
        MA.TimeStamp                                 AS AlarmTime
    FROM
        Config_Station CS
        LEFT JOIN Maint_ActiveAlarm MA ON CS.StationID = MA.StationID
        LEFT JOIN Config_Alarm      CA ON MA.AlarmID   = CA.AlarmID
        LEFT JOIN Config_Equipment  CE ON CA.EquipmentID = CE.EquipmentID
    ORDER BY
        CS.StageNo;
END
GO

