-- [214/376] Stored Procedure: [dbo].[GV_ActivityMonitoring_ActivityStatus]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE       PROCEDURE [dbo].[GV_ActivityMonitoring_ActivityStatus]
(
    @EngineNo NVARCHAR(100),
    @StageNo INT,
    @ActivityID INT
)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT TOP 1
        PAL.EINNO AS EngineNo,
        PAL.ActivityID,

        PAL.Activity_Data_Val AS NoOfActivity,
        PAL.Activity_Status AS StationStatus,

        PAL.TimeStamp

    FROM dbo.Prod_Activity_Data_Log PAL

    WHERE PAL.EINNO = @EngineNo
      AND PAL.StageNo = @StageNo
      AND PAL.ActivityID = @ActivityID

    ORDER BY
        PAL.TimeStamp DESC,
        PAL.RowID DESC;
END
GO

-- ------------------------------------------------------------------------
-- [215/376] Stored Procedure: [dbo].[GV_ActivityMonitoring_Pivoted]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 23-09-2026
-- Description : Activity Monitoring - Column Pivoted View
--               Stage columns are built DYNAMICALLY from the distinct
--               StageNo values actually present in dbo.Config_Activity
--               (between @FromStage and @ToStage), instead of a
--               hardcoded Stage-1..Stage-40 list.
--               Activity ID / Ref Data / Activity Data shown as rows.
--               Maximum 5 activities per Stage
-- =============================================

CREATE       PROCEDURE [dbo].[GV_ActivityMonitoring_Pivoted]
(
    @FromStage INT = 1,
    @ToStage   INT = 40
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @StageCols   NVARCHAR(MAX);
    DECLARE @SQL         NVARCHAR(MAX);

    /* -----------------------------------------------------------
       1. Build the stage column list dynamically, e.g.
          [Stage-1],[Stage-2],[Stage-3], ... up to whatever
          distinct StageNo values exist in range, in StageNo order.
       ----------------------------------------------------------- */
    SELECT @StageCols = STRING_AGG(QUOTENAME('Stage-' + CAST(StageNo AS VARCHAR(10))), ',')
                        WITHIN GROUP (ORDER BY StageNo)
    FROM (
        SELECT DISTINCT StageNo
        FROM dbo.Config_Activity
        WHERE StageNo BETWEEN @FromStage AND @ToStage
    ) AS DistinctStages;

    IF @StageCols IS NULL
    BEGIN
        RAISERROR('No stages found in the given range.', 16, 1);
        RETURN;
    END

    /* -----------------------------------------------------------
       2. Build the executable SQL text using that column list.
          NOTE: this entire block is one N'...' string literal, so
          every literal single quote inside it is doubled ('') to
          escape it -- that was the bug in the previous version.
       ----------------------------------------------------------- */
    SET @SQL = N'
    ;WITH ActivityCTE AS
    (
        SELECT
            ROW_NUMBER() OVER
            (
                PARTITION BY StageNo
                ORDER BY SequenceNo, ActivityID
            ) AS ActivityNo,

            StageNo,
            ActivityID,
            ActivityDesc,
            SequenceNo,

            Ref01,
            Ref02,
            Ref03,
            Ref04,
            Ref05

        FROM dbo.Config_Activity
        WHERE StageNo BETWEEN @FromStage AND @ToStage
    ),

    StagePivot AS
    (
        SELECT
            StageNo,

            MAX(CASE WHEN ActivityNo = 1 THEN ActivityID END) AS ActivityID1,
            MAX(CASE WHEN ActivityNo = 1 THEN ActivityDesc END) AS ActivityDesc1,
            MAX(CASE WHEN ActivityNo = 1 THEN
                    ISNULL(CAST(Ref01 AS VARCHAR(100)), '''') + ''|'' +
                    ISNULL(CAST(Ref02 AS VARCHAR(100)), '''') + ''|'' +
                    ISNULL(CAST(Ref03 AS VARCHAR(100)), '''') + ''|'' +
                    ISNULL(CAST(Ref04 AS VARCHAR(100)), '''') + ''|'' +
                    ISNULL(CAST(Ref05 AS VARCHAR(100)), '''')
                END) AS Activity1_RefData,
            MAX(CASE WHEN ActivityNo = 2 THEN ActivityID END) AS ActivityID2,
            MAX(CASE WHEN ActivityNo = 2 THEN ActivityDesc END) AS ActivityDesc2,
            MAX(CASE WHEN ActivityNo = 2 THEN
                    ISNULL(CAST(Ref01 AS VARCHAR(100)), '''') + ''|'' +
                    ISNULL(CAST(Ref02 AS VARCHAR(100)), '''') + ''|'' +
                    ISNULL(CAST(Ref03 AS VARCHAR(100)), '''') + ''|'' +
                    ISNULL(CAST(Ref04 AS VARCHAR(100)), '''') + ''|'' +
                    ISNULL(CAST(Ref05 AS VARCHAR(100)), '''')
                END) AS Activity2_RefData,
            MAX(CASE WHEN ActivityNo = 3 THEN ActivityID END) AS ActivityID3,
            MAX(CASE WHEN ActivityNo = 3 THEN ActivityDesc END) AS ActivityDesc3,
            MAX(CASE WHEN ActivityNo = 3 THEN
                    ISNULL(CAST(Ref01 AS VARCHAR(100)), '''') + ''|'' +
                    ISNULL(CAST(Ref02 AS VARCHAR(100)), '''') + ''|'' +
                    ISNULL(CAST(Ref03 AS VARCHAR(100)), '''') + ''|'' +
                    ISNULL(CAST(Ref04 AS VARCHAR(100)), '''') + ''|'' +
                    ISNULL(CAST(Ref05 AS VARCHAR(100)), '''')
                END) AS Activity3_RefData,
            MAX(CASE WHEN ActivityNo = 4 THEN ActivityID END) AS ActivityID4,
            MAX(CASE WHEN ActivityNo = 4 THEN ActivityDesc END) AS ActivityDesc4,
            MAX(CASE WHEN ActivityNo = 4 THEN
                    ISNULL(CAST(Ref01 AS VARCHAR(100)), '''') + ''|'' +
                    ISNULL(CAST(Ref02 AS VARCHAR(100)), '''') + ''|'' +
                    ISNULL(CAST(Ref03 AS VARCHAR(100)), '''') + ''|'' +
                    ISNULL(CAST(Ref04 AS VARCHAR(100)), '''') + ''|'' +
                    ISNULL(CAST(Ref05 AS VARCHAR(100)), '''')
                END) AS Activity4_RefData,
            MAX(CASE WHEN ActivityNo = 5 THEN ActivityID END) AS ActivityID5,
            MAX(CASE WHEN ActivityNo = 5 THEN ActivityDesc END) AS ActivityDesc5,
            MAX(CASE WHEN ActivityNo = 5 THEN
                    ISNULL(CAST(Ref01 AS VARCHAR(100)), '''') + ''|'' +
                    ISNULL(CAST(Ref02 AS VARCHAR(100)), '''') + ''|'' +
                    ISNULL(CAST(Ref03 AS VARCHAR(100)), '''') + ''|'' +
                    ISNULL(CAST(Ref04 AS VARCHAR(100)), '''') + ''|'' +
                    ISNULL(CAST(Ref05 AS VARCHAR(100)), '''')
                END) AS Activity5_RefData

        FROM ActivityCTE
        WHERE ActivityNo <= 5
        GROUP BY StageNo
    ),

    UnpivotData AS
    (
        SELECT
            sp.StageNo,
            v.AttributeName,
            v.AttributeValue,
            v.AttributeOrder
        FROM StagePivot sp
        CROSS APPLY (VALUES
        (''Activity ID 1'', CAST(ActivityID1 AS VARCHAR(200)), 1),
        (''Activity ID 1 Ref. Data'', Activity1_RefData, 2),
        (''Activity 1 Data'', ActivityDesc1, 3),
        (''Activity ID 2'', CAST(ActivityID2 AS VARCHAR(200)), 4),
        (''Activity ID 2 Ref. Data'', Activity2_RefData, 5),
        (''Activity 2 Data'', ActivityDesc2, 6),
        (''Activity ID 3'', CAST(ActivityID3 AS VARCHAR(200)), 7),
        (''Activity ID 3 Ref. Data'', Activity3_RefData, 8),
        (''Activity 3 Data'', ActivityDesc3, 9),
        (''Activity ID 4'', CAST(ActivityID4 AS VARCHAR(200)), 10),
        (''Activity ID 4 Ref. Data'', Activity4_RefData, 11),
        (''Activity 4 Data'', ActivityDesc4, 12),
        (''Activity ID 5'', CAST(ActivityID5 AS VARCHAR(200)), 13),
        (''Activity ID 5 Ref. Data'', Activity5_RefData, 14),
        (''Activity 5 Data'', ActivityDesc5, 15)
        ) AS v(AttributeName, AttributeValue, AttributeOrder)
    ),

    SourceForPivot AS
    (
        SELECT
            ''Stage-'' + CAST(StageNo AS VARCHAR(10)) AS StageCol,
            AttributeName,
            AttributeValue,
            AttributeOrder
        FROM UnpivotData
    )

    SELECT
        AttributeName,
        ' + @StageCols + N'
    FROM
    (
        SELECT StageCol, AttributeName, AttributeValue, AttributeOrder
        FROM SourceForPivot
    ) AS src
    PIVOT
    (
        MAX(AttributeValue)
        FOR StageCol IN (' + @StageCols + N')
    ) AS pvt
    ORDER BY AttributeOrder;
    ';

    /* -----------------------------------------------------------
       3. Execute, passing @FromStage/@ToStage through safely.
       ----------------------------------------------------------- */
    EXEC sp_executesql
        @SQL,
        N'@FromStage INT, @ToStage INT',
        @FromStage = @FromStage,
        @ToStage   = @ToStage;

END
GO

