-- [216/376] Stored Procedure: [dbo].[GV_ApplicationSetting]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 12-08-2026
-- Description : Grid Viewer for Application Setting Configuration
-- =============================================

--| DATE       | CHANGED BY | DESCRIPTION                  |

CREATE       PROCEDURE [dbo].[GV_ApplicationSetting]
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        ;WITH CTE AS
        (
            SELECT
                ROW_NUMBER() OVER (ORDER BY A.UID DESC) AS RowNo,
                A.UID,
                A.LineID,
                L.LineName,
                A.ParameterID,
                A.ParameterName,
                A.ParameterValue,
                A.ParameterType,
                DD.FieldDesc AS ParameterTypeDesc
            FROM dbo.ApplicationSetting AS A

            INNER JOIN dbo.Config_Line AS L
                ON L.LineID = A.LineID

            LEFT JOIN dbo.Config_DropDown AS DD
                ON DD.TableName = 'ApplicationSetting'
                AND DD.FieldName = 'ParameterType'
                AND DD.FieldValue = A.ParameterType
        )

        SELECT
            RowNo,
            CASE
                WHEN RowNo % 2 = 0 THEN 'Even'
                ELSE 'Odd'
            END AS RowType,
            UID,
            LineID,
            LineName,
            ParameterID,
            ParameterName,
            ParameterValue,
            ParameterType,
            ParameterTypeDesc
        FROM CTE
        ORDER BY RowNo;

    END TRY

    BEGIN CATCH
        EXEC dbo.RethrowError;
    END CATCH
END
GO

