-----------------------------------------------------------
--| 02-07-2026 | Sumit      | CREATE OR ALTER OR ALTERd                      |
--| 31-07-2026 | Sumit      | Added Alternate row pattern colour |
-----------------------------------------------------------
--***************************************************************

CREATE     PROCEDURE [dbo].[GV_Config_Activity_SOP_Mapping]
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        ;WITH CTE AS
        (
            SELECT
                ROW_NUMBER() OVER (ORDER BY A.UID DESC) AS RowNo,

                A.UID,

                A.StationID,
                ST.StationName,

                A.ActivityID,
                ACT.Description AS ActivityName,

                A.SOPID,
                SOP.DocumentName,

                A.ModelFamilyID,
                MF.ModelFamilyName,

                A.ModelID,
                M.ModelName,

                A.SKUID,
                SKU.SKUName,

                A.SequenceNo

            FROM dbo.Config_Activity_SOP_Mapping AS A

            LEFT JOIN dbo.Config_Station AS ST
                ON A.StationID = ST.StationID

            LEFT JOIN dbo.Config_JHActivity AS ACT
                ON A.ActivityID = ACT.JHActivityID

            LEFT JOIN dbo.Config_QADocumentList AS SOP
                ON A.SOPID = SOP.DocumentID

            LEFT JOIN dbo.Config_ModelFamily AS MF
                ON A.ModelFamilyID = MF.ModelFamilyID

            LEFT JOIN dbo.Config_Model AS M
                ON A.ModelID = M.ModelID

            LEFT JOIN dbo.Config_SKU AS SKU
                ON A.SKUID = SKU.SKUID
        )

        SELECT
            RowNo,
            CASE
                WHEN RowNo % 2 = 0 THEN 'Even'
                ELSE 'Odd'
            END AS RowType,

            UID,

            StationID,
            StationName,

            ActivityID,
            ActivityName,

            SOPID,
            DocumentName,

            ModelFamilyID,
            ModelFamilyName,

            ModelID,
            ModelName,

            SKUID,
            SKUName,

            SequenceNo

        FROM CTE
        ORDER BY RowNo;

    END TRY
    BEGIN CATCH
        EXEC dbo.RethrowError;
    END CATCH
END
GO

