-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION                      |
-----------------------------------------------------------
--| 17-07-2026 | Sumit      | CREATE OR ALTER OR ALTERd                          |
--| 17-07-2026 | Sumit      | Added Alternate row pattern colour |
--| 20-07-2026 | Sumit      | Standardized as per GV template  |
-----------------------------------------------------------
--***************************************************************/

CREATE       PROCEDURE [dbo].[GV_Config_Alarm]
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        ;WITH CTE AS
        (
            SELECT
                ROW_NUMBER() OVER (ORDER BY A.AlarmID DESC) AS RowNo,

                A.AlarmID,
                A.AlarmMessage,
                A.AlarmDesc,

                A.AlarmType,
                DDAT.FieldDesc AS AlarmTypeDesc,

                A.Priority,
                DDP.FieldDesc AS PriorityDesc,

                A.DepartmentID,
                D.DepartmentName,

                A.EquipmentID,
                E.EquipmentName

            FROM dbo.Config_Alarm AS A

            INNER JOIN dbo.Config_Department AS D
                ON A.DepartmentID = D.DepartmentID

            INNER JOIN dbo.Config_Equipment AS E
                ON A.EquipmentID = E.EquipmentID

            LEFT JOIN dbo.Config_DropDown AS DDAT
                ON DDAT.TableName = 'Config_Alarm'
               AND DDAT.FieldName = 'AlarmType'
               AND DDAT.FieldValue = A.AlarmType

            LEFT JOIN dbo.Config_DropDown AS DDP
                ON DDP.TableName = 'Config_Alarm'
               AND DDP.FieldName = 'Priority'
               AND DDP.FieldValue = A.Priority
        )

        SELECT
            RowNo,
            CASE
                WHEN RowNo % 2 = 0 THEN 'Even'
                ELSE 'Odd'
            END AS RowType,

            AlarmID,
            AlarmMessage,
            AlarmDesc,

            AlarmType,
            AlarmTypeDesc,

            Priority,
            PriorityDesc,

            DepartmentID,
            DepartmentName,

            EquipmentID,
            EquipmentName

        FROM CTE
        ORDER BY RowNo;

    END TRY
    BEGIN CATCH
        EXEC dbo.RethrowError;
    END CATCH
END
GO

