-- [221/376] Stored Procedure: [dbo].[GV_Config_AuditList]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 20-06-2026
-- Description : Grid Viewer for Audit List Configuration
-- =============================================

--***************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION                  |
-----------------------------------------------------------
--| 20-06-2026 | Sumit      | CREATE OR ALTER OR ALTERd                      |
--| 17-07-2026 | Sumit      | Added Alternate row pattern colour |
-----------------------------------------------------------
--***************************************************************/

CREATE         PROCEDURE [dbo].[GV_Config_AuditList]
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        ;WITH CTE AS
        (
            SELECT
                ROW_NUMBER() OVER (ORDER BY al.AuditListID DESC) AS RowNo,
                al.AuditListID,
                al.AuditListName,
                al.DocumentID,
                qdl.DocumentNo,
                qdl.DocumentName,
                al.ModelFamilyID,
                mf.ModelFamilyName,
                al.ModelID,
                m.ModelName,
                al.SKUID,
                s.SKUName,
                al.PartID,
                p.PartName
            FROM dbo.Config_AuditList AS al
            LEFT JOIN dbo.Config_QADocumentList AS qdl
                ON qdl.DocumentID = al.DocumentID
            LEFT JOIN dbo.Config_ModelFamily AS mf
                ON mf.ModelFamilyID = al.ModelFamilyID
            LEFT JOIN dbo.Config_Model AS m
                ON m.ModelID = al.ModelID
            LEFT JOIN dbo.Config_SKU AS s
                ON s.SKUID = al.SKUID
            LEFT JOIN dbo.Config_PartVariant AS p
                ON p.PartID = al.PartID
        )

        SELECT
            RowNo,
            CASE
                WHEN RowNo % 2 = 0 THEN 'Even'
                ELSE 'Odd'
            END AS RowType,
            AuditListID,
            AuditListName,
            DocumentID,
            DocumentNo,
            DocumentName,
            ModelFamilyID,
            ModelFamilyName,
            ModelID,
            ModelName,
            SKUID,
            SKUName,
            PartID,
            PartName
        FROM CTE
        ORDER BY RowNo;

    END TRY

    BEGIN CATCH
        EXEC dbo.RethrowError;
    END CATCH
END
GO

-- ------------------------------------------------------------------------
-- [222/376] Stored Procedure: [dbo].[GV_Config_AuditPointLinking]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 05-08-2026
-- Description : Grid Viewer for Audit Point Linking Configuration
-- =============================================

--***************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION                  |
-----------------------------------------------------------
--| 04-08-2026 | Sumit      | CREATE OR ALTER OR ALTERd                      |
--| 03-09-2026 | Sumit      | Added SOPID / Config_SOPPoint|
--|            |            | join                          |
-----------------------------------------------------------
--***************************************************************/

CREATE       PROCEDURE [dbo].[GV_Config_AuditPointLinking]
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        ;WITH CTE AS
        (
            SELECT
                ROW_NUMBER() OVER (ORDER BY A.UID DESC) AS RowNo,

                A.UID,

                A.DocumentID,
                DOC.DocumentName,

                A.AuditListID,
                B.AuditListName,

                A.AuditPointID,

                A.StationID,
                ST.StationName,

                A.SubAsslyLineID,
                SL.SubAsslyLineName,

                A.PartID,
                PT.PartName,

                A.EnginePartID,
                EP.EnginePartDesc,

                A.ActivityID,
                C.ActivityDesc,

                A.ParameterID,
                PM.ParameterName,

                A.SOPID,
                SP.SOPPoint

            FROM dbo.Config_AuditPointLinking AS A

            INNER JOIN dbo.Config_QADocumentList AS DOC
                ON A.DocumentID = DOC.DocumentID

            INNER JOIN dbo.Config_AuditList AS B
                ON A.AuditListID = B.AuditListID

            INNER JOIN dbo.Config_Station AS ST
                ON A.StationID = ST.StationID

            LEFT JOIN dbo.Config_SubAssemblyLine AS SL
                ON A.SubAsslyLineID = SL.SubAsslyLineID

            LEFT JOIN dbo.Config_PartVariant AS PT
                ON A.PartID = PT.PartID

            LEFT JOIN dbo.Config_EnginePart AS EP
                ON A.EnginePartID = EP.EnginePartID

            LEFT JOIN
            (
                SELECT DISTINCT
                    ActivityID,
                    ActivityDesc
                FROM dbo.Config_Activity
            ) AS C
                ON A.ActivityID = C.ActivityID

            LEFT JOIN dbo.Config_Parameter AS PM
                ON A.ParameterID = PM.ParameterID

            LEFT JOIN dbo.Config_SOPPoint AS SP
                ON A.SOPID = SP.SOPID
        )

        SELECT
            RowNo,
            CASE
                WHEN RowNo % 2 = 0 THEN 'Even'
                ELSE 'Odd'
            END AS RowType,

            UID,

            DocumentID,
            DocumentName,

            AuditListID,
            AuditListName,

            AuditPointID,

            StationID,
            StationName,

            SubAsslyLineID,
            SubAsslyLineName,

            PartID,
            PartName,

            EnginePartID,
            EnginePartDesc,

            ActivityID,
            ActivityDesc,

            ParameterID,
            ParameterName,

            SOPID,
            SOPPoint

        FROM CTE
        ORDER BY RowNo;

    END TRY

    BEGIN CATCH
        EXEC dbo.RethrowError;
    END CATCH
END
GO

