-- [223/376] Stored Procedure: [dbo].[GV_Config_AuditSchedule]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 21-07-2026
-- Description : Grid Viewer for Audit Schedule Configuration
-- =============================================

--***************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION                  |
-----------------------------------------------------------
--| 21-07-2026 | Sumit      | CREATE OR ALTER OR ALTERd                      |
--| 07-09-2026 | Sumit      | Added FrequencyType and Notification descriptions from Config_DropDown |
-----------------------------------------------------------
--***************************************************************/

CREATE       PROCEDURE [dbo].[GV_Config_AuditSchedule]
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        ;WITH CTE AS
        (
            SELECT
                ROW_NUMBER() OVER (ORDER BY A.UID DESC) AS RowNo,

                A.UID,

                A.LineID,
                L.LineName,

                A.DocumentID,
                D.DocumentName,

                A.AuditInstanceID,

                A.StartDateTime,
                A.NextDueDate,

                A.FrequencyType,
                DDFREQ.FieldDesc AS FrequencyTypeDesc,
                A.FrequencyValue,

                A.Notification,
                DDNOTIF.FieldDesc AS NotificationDesc,
                A.Status

            FROM dbo.Config_AuditSchedule A

            INNER JOIN dbo.Config_Line L
                ON A.LineID = L.LineID

            INNER JOIN dbo.Config_QADocumentList D
                ON A.DocumentID = D.DocumentID

            LEFT JOIN dbo.Config_DropDown AS DDFREQ
                ON DDFREQ.TableName = 'Config_AuditSchedule'
               AND DDFREQ.FieldName = 'FrequencyType'
               AND DDFREQ.FieldValue = A.FrequencyType

            LEFT JOIN dbo.Config_DropDown AS DDNOTIF
                ON DDNOTIF.TableName = 'Config_AuditSchedule'
               AND DDNOTIF.FieldName = 'Notification'
               AND DDNOTIF.FieldValue = A.Notification
        )

        SELECT
            RowNo,

            CASE
                WHEN RowNo % 2 = 0 THEN 'Even'
                ELSE 'Odd'
            END AS RowType,

            UID,

            LineID,
            LineName,

            DocumentID,
            DocumentName,

            AuditInstanceID,

            StartDateTime,
            NextDueDate,

            FrequencyType,
            FrequencyTypeDesc,
            FrequencyValue,

            Notification,
            NotificationDesc,
            Status

        FROM CTE
        ORDER BY RowNo;

    END TRY

    BEGIN CATCH
        EXEC dbo.RethrowError;
    END CATCH
END
GO

-- ------------------------------------------------------------------------
-- [224/376] Stored Procedure: [dbo].[GV_Config_BOM]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE     PROCEDURE [dbo].[GV_Config_BOM]
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        ;WITH CTE AS
        (
            SELECT
                ROW_NUMBER() OVER (ORDER BY B.UID DESC) AS RowNo,

                B.UID,

                B.SKUID,
                S.SKUName,

                B.PartID,
                B.PartDesc,

                B.PartLevel,
                DD.FieldDesc AS PartLevelDesc,

                B.PartQuantity,

                B.ParentID,

                B.AlternatePartFlag,
                CASE
                    WHEN B.AlternatePartFlag = 1 THEN 'Yes'
                    ELSE 'No'
                END AS AlternatePartFlagText,

                B.StationID,
                ST.StationName,

                B.PreferredPartID,

                B.MaterialMoveType,
                DM.FieldDesc AS MaterialMoveTypeDesc

            FROM dbo.Config_BOM AS B

            LEFT JOIN dbo.Config_SKU AS S
                ON B.SKUID = S.SKUID

            LEFT JOIN dbo.Config_Station AS ST
                ON B.StationID = ST.StationID

            -- Part Level description
            LEFT JOIN dbo.Config_DropDown AS DD
                ON DD.TableName = 'Config_BOM'
               AND DD.FieldName = 'PartLevel'
               AND DD.FieldValue = B.PartLevel

            -- Material Move Type description
            LEFT JOIN dbo.Config_DropDown AS DM
                ON DM.TableName = 'Config_BOM'
               AND DM.FieldName = 'MaterialMoveType'
               AND DM.FieldValue = B.MaterialMoveType
        )

        SELECT
            RowNo,

            CASE
                WHEN RowNo % 2 = 0 THEN 'Even'
                ELSE 'Odd'
            END AS RowType,

            UID,

            SKUID,
            SKUName,

            PartID,
            PartDesc,

            PartLevel,
            PartLevelDesc,

            PartQuantity,

            ParentID,

            AlternatePartFlag,
            AlternatePartFlagText,

            StationID,
            StationName,

            PreferredPartID,

            MaterialMoveType,
            MaterialMoveTypeDesc

        FROM CTE
        ORDER BY RowNo;

    END TRY

    BEGIN CATCH
        EXEC dbo.RethrowError;
    END CATCH
END
GO

