CREATE     PROCEDURE [dbo].[GV_Config_History]
    @ScreenName NVARCHAR(100)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        ;WITH CTE AS
        (
            SELECT
                ROW_NUMBER() OVER (ORDER BY UID DESC) AS RowNo,
                *
            FROM dbo.Config_History
            WHERE ScreenName = @ScreenName
        )

        SELECT
            CASE
                WHEN RowNo % 2 = 0 THEN 'Even'
                ELSE 'Odd'
            END AS RowType,
            *
        FROM CTE
        ORDER BY RowNo;

    END TRY

    BEGIN CATCH
        EXEC dbo.RethrowError;
    END CATCH
END
