-- ------------------------------------------------------------------------
-- [237/376] Stored Procedure: [dbo].[GV_Config_InspectionPoint]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 17-07-2026
-- Description : Inspection Point Grid Viewer
-- =============================================
--***************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION                  |
-----------------------------------------------------------
--| 17-07-2026 | Sumit       | CREATE OR ALTER OR ALTERd
--| 21-07-2026 | Sumit       | Standardized as per GV template
--| 31-07-2026 | Sumit       | Reformatted to match GV template layout
-----------------------------------------------------------
--***************************************************************

CREATE       PROCEDURE [dbo].[GV_Config_InspectionPoint]
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        ;WITH CTE AS
        (
            SELECT
                ROW_NUMBER() OVER (ORDER BY IP.UID DESC) AS RowNo,
                IP.UID,
                IP.InspectionPointID,
                IP.InspectionStationID,
                ISN.InspectionStationName,
                IP.ModelFamilyID,
                MF.ModelFamilyName,
                IP.ModelID,
                M.ModelName,
                IP.SKUID,
                S.SKUName,
                IP.InspectionPointName,
                IP.InspectionPointDes,
                IP.InspectionPointType,
                DDTYPE.FieldDesc AS InspectionPointTypeDesc,
                IP.InspectionPointAction,
                DDACTION.FieldDesc AS InspectionPointActionDesc
            FROM dbo.Config_Inspection_Point AS IP
            INNER JOIN dbo.Config_Inspection_Station AS ISN
                ON ISN.InspectionStationID = IP.InspectionStationID
            INNER JOIN dbo.Config_ModelFamily AS MF
                ON MF.ModelFamilyID = IP.ModelFamilyID
            INNER JOIN dbo.Config_Model AS M
                ON M.ModelID = IP.ModelID
            INNER JOIN dbo.Config_SKU AS S
                ON S.SKUID = IP.SKUID
            LEFT JOIN dbo.Config_DropDown AS DDTYPE
                ON DDTYPE.TableName = 'Config_Inspection_Point'
               AND DDTYPE.FieldName = 'InspectionPointType'
               AND DDTYPE.FieldValue = IP.InspectionPointType
            LEFT JOIN dbo.Config_DropDown AS DDACTION
                ON DDACTION.TableName = 'Config_Inspection_Point'
               AND DDACTION.FieldName = 'InspectionPointAction'
               AND DDACTION.FieldValue = IP.InspectionPointAction
        )

        SELECT
            RowNo,
            CASE
                WHEN RowNo % 2 = 0 THEN 'Even'
                ELSE 'Odd'
            END AS RowType,
            UID,
            InspectionPointID,
            InspectionStationID,
            InspectionStationName,
            ModelFamilyID,
            ModelFamilyName,
            ModelID,
            ModelName,
            SKUID,
            SKUName,
            InspectionPointName,
            InspectionPointDes,
            InspectionPointType,
            InspectionPointTypeDesc,
            InspectionPointAction,
            InspectionPointActionDesc
        FROM CTE
        ORDER BY RowNo;

    END TRY
    BEGIN CATCH
        EXEC dbo.RethrowError;
    END CATCH
END
GO

