-- CREATE OR ALTER OR ALTER date : 29-05-2026
-- Description : QA Document List Grid Viewer
-- =============================================
--***************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION                      |
-----------------------------------------------------------
--| 29-05-2026 | Sumit      | CREATE OR ALTER OR ALTERd                          |
--| 17-07-2026 | Sumit      | Added Alternate row pattern colour |
--| 20-07-2026 | Sumit      | Standardized as per GV template  |
-----------------------------------------------------------
--***************************************************************/

CREATE         PROCEDURE [dbo].[GV_Config_QADocumentList]
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        ;WITH CTE AS
        (
            SELECT
                ROW_NUMBER() OVER (ORDER BY QD.DocumentID DESC) AS RowNo,

                QD.DocumentID,
                QD.DocumentNo,
                QD.DocumentName,
                DD.FieldValue AS GroupID,

                QD.[Group],
                DD.FieldDesc AS GroupDesc,

                QD.Revision

            FROM dbo.Config_QADocumentList AS QD

           LEFT JOIN dbo.Config_DropDown AS DD
                ON DD.TableName = 'Config_QADocumentList'
               AND DD.FieldName = 'Group'
               AND DD.FieldDesc = DD.FieldDesc

        )

        SELECT
            RowNo,
            CASE
                WHEN RowNo % 2 = 0 THEN 'Even'
                ELSE 'Odd'
            END AS RowType,

            DocumentID,
            DocumentNo,
            DocumentName,
            GroupID,
            [Group],
            GroupDesc,

            Revision

        FROM CTE
        ORDER BY RowNo;

    END TRY
    BEGIN CATCH
        EXEC dbo.RethrowError;
    END CATCH
END


SELECT * FROM dbo.Config_DropDown
WHERE TableName = 'Config_QADocumentList'
  AND FieldName = 'Group';
GO

-- ------------------------------------------------------------------------
-- [262/376] Stored Procedure: [dbo].[GV_Config_QADocumentList_Revision]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE         PROCEDURE [dbo].[GV_Config_QADocumentList_Revision]
    @DocumentNo INT
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        SELECT
            QD.DocumentID,
            QD.DocumentNo,
            QD.DocumentName,
            QD.Revision,

            AL.AuditListID,
            AL.AuditListName,

            ADM.AuditListScreen

        FROM dbo.Config_QADocumentList QD

         JOIN dbo.Config_AuditList AL
            ON QD.DocumentID = AL.DocumentID

         INNER JOIN dbo.Config_AuditDocumentMapping ADM
            ON AL.AuditListID = ADM.AuditListID

        WHERE QD.DocumentNo = @DocumentNo

        ORDER BY AL.AuditListID, ADM.AuditListScreen

    END TRY
    BEGIN CATCH
        EXEC dbo.RethrowError;
    END CATCH

END
GO

