-- ------------------------------------------------------------------------
-- [268/376] Stored Procedure: [dbo].[GV_Config_SKU_LineTaktTime]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE         PROCEDURE [dbo].[GV_Config_SKU_LineTaktTime]
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        ;WITH CTE AS
        (
            SELECT
                ROW_NUMBER() OVER (ORDER BY A.UID DESC) AS RowNo,

                A.UID,

                A.SKUID,
                SKU.SKUName,

                M.ModelFamilyID,
                MF.ModelFamilyName,
                M.ModelID,
                M.ModelName,

                A.LineID,
                L.LineName,

                A.CycleTime400,
                A.CycleTime600,
                A.CycleTime800,
                A.CycleTime1000,
                A.CycleTime1200

            FROM dbo.Config_SKU_Line_TaktTime AS A

            INNER JOIN dbo.Config_SKU AS SKU
                ON A.SKUID = SKU.SKUID

            INNER JOIN dbo.Config_Model AS M
                ON SKU.ModelID = M.ModelID

            INNER JOIN dbo.Config_ModelFamily AS MF
                ON M.ModelFamilyID = MF.ModelFamilyID

            INNER JOIN dbo.Config_Line AS L
                ON A.LineID = L.LineID
        )

        SELECT
            RowNo,
            CASE
                WHEN RowNo % 2 = 0 THEN 'Even'
                ELSE 'Odd'
            END AS RowType,

            UID,

            SKUID,
            SKUName,

            ModelFamilyID,
            ModelFamilyName,
            ModelID,
            ModelName,

            LineID,
            LineName,

            CycleTime400,
            CycleTime600,
            CycleTime800,
            CycleTime1000,
            CycleTime1200

        FROM CTE
        ORDER BY RowNo;

    END TRY
    BEGIN CATCH
        EXEC dbo.RethrowError;
    END CATCH
END
GO

