AS
BEGIN

    SET NOCOUNT ON;

    BEGIN TRY

        SELECT
            a.UID,
            a.SKUID,
            b.SKUName,
            a.StationID,
            c.StationName,
            a.CycleTime400,
            a.CycleTime600,
            a.CycleTime800,
            a.CycleTime1000,
            a.CycleTime1200

        FROM dbo.Config_SKU_Station_TaktTime AS a

