-- ------------------------------------------------------------------------
-- [270/376] Stored Procedure: [dbo].[GV_Config_Station]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 26-04-2026
-- Description : Station Grid Viewer
-- =============================================
--***************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION                  |
-----------------------------------------------------------
--| 26-04-2026 | Sumit      | CREATE OR ALTER OR ALTERd                      |
--| 30-04-2026 | Sumit      | Standardized as per PPT      |
--| 17-07-2026 | Sumit      | Added Alternate row pattern colour |
--| 18-07-2026 | Mamatha M  | Joined Station Type values from Config_Dropdown table |
-----------------------------------------------------------
-----------------------------------------------------------
--***************************************************************/
CREATE         PROCEDURE [dbo].[GV_Config_Station]
AS
BEGIN
    SET NOCOUNT ON;
   BEGIN TRY
    ;WITH CTE AS
    (
        SELECT
            ROW_NUMBER() OVER (ORDER BY S.StationID DESC) AS RowNo,
            S.StationID,
            S.SubAsslyLineID,
            SUB.SubAsslyLineName,
            S.LineZoneID,
            Z.LineZoneName,
            S.StationName,
            S.StationDesc,
            S.StationType,
            DD.FieldDesc        AS StationTypeDesc,
            S.StationSide,
            S.StageNo,
            S.SkillLevel,
            SL.SkillLevelName
        FROM dbo.Config_Station AS S
        INNER JOIN dbo.Config_SubAssemblyLine AS SUB
            ON SUB.SubAsslyLineID = S.SubAsslyLineID
        INNER JOIN dbo.Config_Zone AS Z
            ON Z.LineZoneID = S.LineZoneID
        INNER JOIN dbo.Config_SkillLevel AS SL
            ON S.SkillLevel = SL.SkillLevelID
        LEFT JOIN dbo.Config_DropDown AS DD
            ON DD.TableName  = 'Config_Station'
           AND DD.FieldName  = 'Station Type'
           AND DD.FieldValue = S.StationType
    )
    SELECT
        RowNo,
        CASE
            WHEN RowNo % 2 = 0 THEN 'Even'
            ELSE 'Odd'
        END AS RowType,
        StationID,
        SubAsslyLineID,
        SubAsslyLineName,
        LineZoneID,
        LineZoneName,
        StationName,
        StationDesc,
        StationType,
        StationTypeDesc,
        StationSide,
        StageNo,
        SkillLevel,
        SkillLevelName
    FROM CTE
    ORDER BY RowNo ;

END TRY
BEGIN CATCH
    EXEC dbo.RethrowError;
END CATCH
END
GO

