--| 25-06-2026 | Sumit      | CREATE OR ALTER OR ALTERd                      |
--| 16-07-2026 | Sumit      | Added Alternate row pattern colour |
-----------------------------------------------------------
--***************************************************************/

CREATE       PROCEDURE [dbo].[GV_Config_StorageRack]
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        ;WITH CTE AS
        (
            SELECT
                ROW_NUMBER() OVER (ORDER BY sr.RackID DESC) AS RowNo,
                sr.RackID,
                sr.RackName,
                sr.StorageZoneID,
                sz.StorageZoneName
            FROM dbo.Config_StorageRack AS sr
            INNER JOIN dbo.Config_StorageZone AS sz
                ON sr.StorageZoneID = sz.StorageZoneID
        )

        SELECT
            RowNo,
            CASE
                WHEN RowNo % 2 = 0 THEN 'Even'
                ELSE 'Odd'
            END AS RowType,
            RackID,
            RackName,
            StorageZoneID,
            StorageZoneName
        FROM CTE
        ORDER BY RowNo;

    END TRY

    BEGIN CATCH
        EXEC dbo.RethrowError;
    END CATCH
END
GO

