-- ------------------------------------------------------------------------
-- [281/376] Stored Procedure: [dbo].[GV_Config_TicketReason]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Sumit
-- CREATE OR ALTER OR ALTER date : 21-09-2026
-- Description : Ticket Reason Grid Viewer
-- =============================================

CREATE     PROCEDURE [dbo].[GV_Config_TicketReason]
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        TR.UID,
        TR.DepartmentID,
        D.DepartmentName AS DepartmentName,
        TR.ReasonName,

        -- Original values for GENESIS mapping
        TR.IsPokaYoka,
        TR.IsEngineNO,
        TR.IsStationID,
        TR.IsPartID,
        TR.IsEquipmentID,
        TR.IsBreakdownID,

        -- Display values
        CASE
            WHEN TR.IsPokaYoka = 1 THEN 'YES'
            ELSE 'NO'
        END AS IsPokaYokaText,

        CASE
            WHEN TR.IsEngineNO = 1 THEN 'YES'
            ELSE 'NO'
        END AS IsEngineNOText,

        CASE
            WHEN TR.IsStationID = 1 THEN 'YES'
            ELSE 'NO'
        END AS IsStationIDText,

        CASE
            WHEN TR.IsPartID = 1 THEN 'YES'
            ELSE 'NO'
        END AS IsPartIDText,

        CASE
            WHEN TR.IsEquipmentID = 1 THEN 'YES'
            ELSE 'NO'
        END AS IsEquipmentIDText,

        CASE
            WHEN TR.IsBreakdownID = 1 THEN 'YES'
            ELSE 'NO'
        END AS IsBreakdownIDText,

        DD.FieldDesc AS Priority

    FROM dbo.Config_TicketReason TR

    LEFT JOIN dbo.Config_Department D
        ON D.DepartmentID = TR.DepartmentID

    LEFT JOIN dbo.Config_DropDown DD
        ON DD.TableName = 'Config_TicketReason'
       AND DD.FieldName = 'Priority'
       AND DD.FieldValue = TR.Priority

    ORDER BY TR.UID DESC;

END
GO

