--***************************************************************
-- Change History
-----------------------------------------------------------
--| DATE       | CHANGED BY | DESCRIPTION                  |
-----------------------------------------------------------
--| 29-07-2026 | Sumit      | CREATE OR ALTER OR ALTERd                      |
--| 29-07-2026 | Sumit      | Standardized as per PPT      |
--| 29-07-2026 | Sumit      | Added Alternate row pattern colour |
-----------------------------------------------------------
--***************************************************************

CREATE       PROCEDURE [dbo].[GV_Config_Zone]
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        ;WITH CTE AS
        (
            SELECT
                ROW_NUMBER() OVER (ORDER BY a.LineZoneID DESC) AS RowNo,
                a.LineZoneID,
                a.LineZoneName,
                a.SubAsslyLineID,
                b.SubAsslyLineName,
                a.LineZoneDesc
            FROM dbo.Config_Zone AS a
            INNER JOIN dbo.Config_SubAssemblyLine AS b
                ON a.SubAsslyLineID = b.SubAsslyLineID
        )
        SELECT
            RowNo,
            CASE
                WHEN RowNo % 2 = 0 THEN 'Even'
                ELSE 'Odd'
            END AS RowType,
            LineZoneID,
            LineZoneName,
            SubAsslyLineID,
            SubAsslyLineName,
            LineZoneDesc
        FROM CTE
        ORDER BY RowNo;

    END TRY

    BEGIN CATCH
        EXEC dbo.RethrowError;
    END CATCH
END
GO

