Create  PROCEDURE [dbo].[GV_CurrnetandLastEngine]

 

AS
BEGIN
Declare @CurrentEngineNo as NVARCHAR(14), @LastEngineNo as NVARCHAR(14);
 

    SELECT top(1)  @CurrentEngineNo = EngineNo from [dbo].[SAP_Engine_SKU_Data] 
    where Status = 1 Order by UID asc
