CREATE         PROCEDURE [dbo].[GV_MachineAlarmMonitoring]
AS
BEGIN

    SELECT

        S.StationName AS Machine,

        MA.AlarmMessage AS AlarmDesc,

        CASE
            WHEN MA.AlarmType = 1 THEN 1
