-- ------------------------------------------------------------------------
-- [301/376] Stored Procedure: [dbo].[GV_Maint_Breakdown_Monitoring]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE     PROCEDURE [dbo].[GV_Maint_Breakdown_Monitoring]
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        B.BreakdownID,
        B.BDTicketType,
        B.RefBreakdownID,

        S.StationName,
        E.EquipmentName,

        B.LossID,
        B.AlarmID,
        B.SubLossID,
        B.ProdDate,
        B.ProdShift,
        B.BDStartTime,
        B.BDEndTime,
        B.BDMaintTicket,
        B.BDRemark,
        B.BDTicketOpenTime,
        B.BDTicketCloseTime,
        B.BDDuration,
        B.TotalBDTime,
        B.TotalBDCount,

        B.AssignedUserID,
        U.UserName AS AssignedUserName,

        B.BDAssignOpenTime,
        B.BDAssignCloseTime,
        B.BDResolutionType,
        B.BDActionTaken,
        B.BDPermanentActionPlan,
        B.BDStatus

    FROM dbo.Maint_Breakdown_Log B

    LEFT JOIN dbo.Config_Station S
        ON B.StationID = S.StationID

    LEFT JOIN dbo.Config_Equipment E
        ON B.EquipmentID = E.EquipmentID

    LEFT JOIN dbo.Config_User U
        ON B.AssignedUserID = U.UserID

    WHERE B.BDStatus = 1

    ORDER BY B.BDStartTime DESC;

END
GO

