-- ------------------------------------------------------------------------
-- [303/376] Stored Procedure: [dbo].[GV_PartInspectionType]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE         PROCEDURE [dbo].[GV_PartInspectionType]
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        ID,
        Value,
        ROW_NUMBER() OVER (ORDER BY ID) AS [Count]
    FROM
    (
        SELECT 0 AS ID, 'Not Applicable' AS Value
        UNION ALL
        SELECT 1, 'Shift'
        UNION ALL
        SELECT 2, 'Days'
        UNION ALL
        SELECT 3, 'Count'
    ) AS T;
END
GO

-- ------------------------------------------------------------------------
-- [304/376] Stored Procedure: [dbo].[GV_Perf_Downtime]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE       PROCEDURE [dbo].[GV_Perf_Downtime]
AS
BEGIN
    SET NOCOUNT ON;

    SELECT TOP (2000)
        PD.DowntimeID,
        PD.TimeStamp,
        PD.SubAsslyLineID,
        SAL.SubAsslyLineName,
        PD.StationID,
        CS.StationName,
        PD.ProdDate,
        PD.ProdShift,
        PD.StartTime,
        PD.EndTime,
        PD.CurrentDT,
        PD.TotalDT,
        PD.LossID,
        CL.LossName,
        PD.SubLossID,
        CSL.SubLossName,
        PD.[4MLossID],
        C4M.[4MLossName],
        PD.UserID,
        CU.UserName,
        PD.Reason,
        PD.LastUpdatedTime
    FROM dbo.Perf_Downtime PD

    LEFT JOIN dbo.Config_SubAssemblyLine SAL
        ON PD.SubAsslyLineID = SAL.SubAsslyLineID

    LEFT JOIN dbo.Config_Station CS
        ON PD.StationID = CS.StationID

    LEFT JOIN dbo.Config_LossCategory CL
        ON PD.LossID = CL.LossID

    LEFT JOIN dbo.Config_SubLossCategory CSL
        ON PD.SubLossID = CSL.SubLossID

    LEFT JOIN dbo.Config_4M_LossCategory C4M
        ON PD.[4MLossID] = C4M.[4MLossID]

    LEFT JOIN dbo.Config_User CU
        ON PD.UserID = CU.UserID

    WHERE PD.CurrentDT > 180

    ORDER BY PD.TimeStamp DESC;
END
GO

