-- [306/376] Stored Procedure: [dbo].[GV_Prod_DailyOperatorPlan]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE     Procedure [dbo].[GV_Prod_DailyOperatorPlan]
@UserID as nvarchar(20)
As
Begin
SELECT  [UID]
      ,a.[UserID]
      ,b.UserName
      ,[ProdDate]
      ,[ProdShift]
      ,[UserStatus]
      ,CASE UserStatus
        WHEN 1 THEN 'Available'
        WHEN 2 THEN 'On Leave'
        WHEN 3 THEN 'No Production'
        WHEN 4 THEN 'Assigned'
        ELSE 'Unknown'
    END AS User_status
      ,a.[LastUpdatedTime]
      ,a.[LastUpdatedBy]
  FROM [PPMS_BajajPant].[dbo].[Prod_DailyOperatorPlan] as a join Config_User as b
  on a.UserID = b.UserID Where a.UserID = @UserID order by UID asc
  End
GO

-- ------------------------------------------------------------------------
-- [307/376] Stored Procedure: [dbo].[GV_ProdEngineTakeIn]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author      : Shubham Patil
-- Create Date : 27-07-2026
-- Description : Get Engine Take In List
-- =============================================

CREATE     PROCEDURE [dbo].[GV_ProdEngineTakeIn]
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
          DL.DefectLogID AS UID
        , EW.EngineNo
        , CS.StationName AS Stage
        , CID.DefectName AS Defect
        , DL.TimeStamp
        , CU.UserName AS [User]
    FROM Prod_Engine_WIP EW
    left JOIN Prod_Defect_Log DL
        ON EW.EngineNo = DL.EngineNo
    left JOIN Config_Inspection_Defect CID
        ON DL.DefectRefID = CID.DefectID
    LEFT JOIN Config_Station CS
        ON DL.InspectionRefID = CS.StationID
    LEFT JOIN Config_User CU
        ON DL.UpdatedBy = CU.UserID
    WHERE EW.Status = 2

    UNION ALL

    SELECT
          DL.DefectLogID AS UID
        , WH.EngineNo
        , CS.StationName AS Stage
        , CID.DefectName AS Defect
        , DL.TimeStamp
        , CU.UserName AS [User]
    FROM Prod_Engine_WIPHistory WH
    left JOIN Prod_Defect_Log DL
        ON WH.EngineNo = DL.EngineNo
    left JOIN Config_Inspection_Defect CID
        ON DL.DefectRefID = CID.DefectID
    LEFT JOIN Config_Station CS
        ON DL.InspectionRefID = CS.StationID
    LEFT JOIN Config_User CU
        ON DL.UpdatedBy = CU.UserID
    WHERE WH.Status = 2
      AND NOT EXISTS
      (
          SELECT 1
          FROM Prod_Engine_WIP W
          WHERE W.EngineNo = WH.EngineNo
      )

    ORDER BY TimeStamp DESC;
END
GO

-- ------------------------------------------------------------------------
-- [308/376] Stored Procedure: [dbo].[GV_ProdShiftPlan]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author:      Shubham Patil
-- CREATE OR ALTER OR ALTER date: 07 May 2026
-- Description: Production Shift Plan Grid
-- =============================================

 

CREATE         PROCEDURE [dbo].[GV_ProdShiftPlan]

 

AS
BEGIN

 

    SELECT
        A.PlanID,
        A.LineID,
        B.LineName,
        A.SKUID,
        C.SKUName,
        A.ProdDate,
        A.ProdShift,
        A.PlanQty,
        A.Status,
        CASE
            WHEN A.Status = 1 THEN 'Plan'
            WHEN A.Status = 2 THEN 'Hold'
            WHEN A.Status = 3 THEN 'Short Close'
            WHEN A.Status = 4 THEN 'Completed'
            WHEN A.Status = 5 THEN 'Inprocess'
        END AS StatusName,
        A.Priority,
        A.Source,
        CASE
            WHEN A.Source = 1 THEN 'Manual'
            WHEN A.Source = 2 THEN 'Excel'
            WHEN A.Source = 3 THEN 'SAP'
        END AS SourceName

 

    FROM Prod_Shift_Plan AS A

 

    JOIN Config_Line AS B
        ON A.LineID = B.LineID

 

    JOIN Config_SKU AS C
        ON A.SKUID = C.SKUID

 

    ORDER BY A.PlanID DESC

 

END
GO

-- ------------------------------------------------------------------------
-- [309/376] Stored Procedure: [dbo].[GV_ProdShiftPlan_Execution]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author:      Shubham Patil
-- CREATE OR ALTER OR ALTER OR ALTER date: 06 Jul 2026
-- Description: Production Shift Plan Execution Grid
-- =============================================

CREATE        PROCEDURE [dbo].[GV_ProdShiftPlan_Execution]

AS
BEGIN

    SELECT
        A.PlanID,
        A.LineID,
        B.LineName,
        A.SKUID,
        C.SKUName,
        A.ProdDate,
        A.ProdShift,
        A.Priority,
        A.PlanQty,
        A.KitAssembly_Qty,
        A.KitInspected_Qty,
        A.ENGMainLine_Qty,
        A.ENGNotOK_Qty,
        A.ENGNotOKBypass_Qty,
        A.ENGTakeOut_Qty,
        A.ENGReworkOK_Qty,
        A.ENGCompleted_Qty,
        A.ENGMaterialHold_Qty,
        A.ENGQualityHold_Qty,
        A.ENGScrapped_Qty,
        A.Status,
        CASE
            WHEN A.Status = 1 THEN 'Plan'
            WHEN A.Status = 2 THEN 'Running'
            WHEN A.Status = 3 THEN 'All Started'
            WHEN A.Status = 4 THEN 'Hold'
            WHEN A.Status = 5 THEN 'Short Close'
            WHEN A.Status = 6 THEN 'Completed'
        END AS StatusName,
        D.ModelName,
        E.ModelFamilyName,
        A.LineSpeed,
        CASE
            WHEN A.LineSpeed = 1 THEN 1200
            WHEN A.LineSpeed = 2 THEN 1000
            WHEN A.LineSpeed = 3 THEN 800
            WHEN A.LineSpeed = 4 THEN 600
            WHEN A.LineSpeed = 5 THEN 400
        END AS LineSpeedValue

    FROM Prod_EnginePlanExecution AS A

    JOIN Config_Line AS B
        ON A.LineID = B.LineID

    JOIN Config_SKU AS C
        ON A.SKUID = C.SKUID

    JOIN Config_Model AS D
    ON C.ModelID = D.ModelID

    JOIN Config_ModelFamily AS E
    ON D.ModelFamilyID = E.ModelFamilyID

    ORDER BY A.ProdDate, A.ProdShift, A.LineID, A.Priority

END
GO

-- ------------------------------------------------------------------------
-- [310/376] Stored Procedure: [dbo].[GV_QA_AuditMonitoring]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE     PROCEDURE [dbo].[GV_QA_AuditMonitoring]
AS
BEGIN
    SET NOCOUNT ON;

    SELECT

        QAM.UID,

        CL.LineID,
        CL.LineName,

        CAL.AuditListID,

        QAM.AuditInstanceID,

        QAM.StartDateTime,
        QAM.EndDateTime,

        QAM.ActualStartDateTime,
        QAM.ActualEndDateTime,

        CASE QAM.Notification
            WHEN 1 THEN 'Normal'
            WHEN 2 THEN 'Alert'
            WHEN 3 THEN 'Warning'
            WHEN 4 THEN 'Alarm'
           
        END AS Notification,

        CASE QAM.Status
            WHEN 0 THEN 'Not Scheduled'
            WHEN 1 THEN 'Plan'
            WHEN 2 THEN 'In Process'
            WHEN 3 THEN 'Completed'
            WHEN 4 THEN 'Bypass'
            WHEN 5 THEN 'Not Done'
            WHEN 6 THEN 'Additional Test'
            
        END AS Status

    FROM QA_AuditMonitoring QAM

    INNER JOIN Config_Line CL
        ON QAM.LineID = CL.LineID

    INNER JOIN Config_AuditList CAL
        ON QAM.AuditListID = CAL.AuditListID

    ORDER BY
        QAM.Status,
        QAM.StartDateTime;

END
GO

-- ------------------------------------------------------------------------
-- [311/376] Stored Procedure: [dbo].[GV_SA_PlanExecution]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author:      Vishal Verma
-- CREATE OR ALTER date: 25 Aug 2026
-- Description: Production SA Plan Execution Grid
-- =============================================

Create   PROCEDURE [dbo].[GV_SA_PlanExecution]

@SubAssemblyID as int

AS
BEGIN

    SELECT

        A.PlanID,
        B.LineID,
        C.LineName,
        A.SKUID,
        D.SKUName,
        A.ProdDate,
        A.ProdShift,
        A.Priority,
        A.PlanQty,
        A.[InProcessQty],
        A.[CompletedQty],
        A.[MarriedQty],
        A.[RejectedQty],
        A.Status,
        CASE
            WHEN A.Status = 1 THEN 'Plan'
            WHEN A.Status = 2 THEN 'Running'
            WHEN A.Status = 3 THEN 'All Started'
            WHEN A.Status = 4 THEN 'Hold'
            WHEN A.Status = 5 THEN 'Short Close'
            WHEN A.Status = 6 THEN 'Completed'
        END AS StatusName,
        E.ModelName,
        F.ModelFamilyName,
        B.LineSpeed AS LineSpeedValue,
        A.SubAsslyLineID
        From Prod_SA_PlanExecution As A 
        Join Prod_EnginePlanExecution AS B ON A.PlanID = B.PlanID

    JOIN Config_Line AS C
        ON B.LineID = B.LineID

    JOIN Config_SKU AS D
        ON A.SKUID = D.SKUID

    JOIN Config_Model AS E
    ON D.ModelID = E.ModelID

    JOIN Config_ModelFamily AS F
    ON E.ModelFamilyID = F.ModelFamilyID Where A.SubAsslyLineID = @SubAssemblyID
   ORDER BY B.ProdDate, B.ProdShift, B.LineID, B.Priority

END
GO

