-- ------------------------------------------------------------------------
-- [314/376] Stored Procedure: [dbo].[GV_TorqueData]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE       PROCEDURE [dbo].[GV_TorqueData]
AS
BEGIN
    SET NOCOUNT ON;
 
    BEGIN TRY
 
        ;WITH LatestTorque AS
        (
            SELECT
                T.RowID,
                T.[Timestamp],
                T.ActivityID,
                T.ActivityValue,
                T.UpperLimit,
                T.LowerLimit,
 
                ROW_NUMBER() OVER
                (
                    PARTITION BY T.ActivityID
                    ORDER BY T.[Timestamp] DESC, T.RowID DESC
                ) AS RowNo
 
            FROM dbo.Prod_TorqueData_Log T
        )
 
        SELECT
            S.StationID,
            S.StationName,
            T.ActivityID,
            T.UpperLimit,
            T.LowerLimit,
            T.ActivityValue,
 
            CASE
                WHEN T.ActivityValue > T.LowerLimit
                 AND T.ActivityValue < T.UpperLimit
                THEN 'OK'
                ELSE 'NOT OK'
            END AS [Status]
 
        FROM LatestTorque T
 
        INNER JOIN dbo.Config_Activity A
            ON A.ActivityID = T.ActivityID
 
        INNER JOIN dbo.Config_Station S
            ON S.StationID = A.StationID
 
        WHERE T.RowNo = 1
 
        ORDER BY
            S.StationID,
            T.ActivityID;
 
    END TRY
 
    BEGIN CATCH
        THROW;
    END CATCH
 
END
GO

-- ------------------------------------------------------------------------
-- [315/376] Stored Procedure: [dbo].[GV_TorqueSummary]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE       PROCEDURE [dbo].[GV_TorqueSummary]
AS
BEGIN
    SET NOCOUNT ON;
 
    BEGIN TRY
 
        ;WITH LatestTorque AS
        (
            SELECT
                T.RowID,
                T.ActivityID,
                T.ActivityValue,
                T.UpperLimit,
                T.LowerLimit,
 
                ROW_NUMBER() OVER
                (
                    PARTITION BY T.ActivityID
                    ORDER BY T.[Timestamp] DESC, T.RowID DESC
                ) AS RowNo
 
            FROM dbo.Prod_TorqueData_Log T
        ),
 
        TorqueStatus AS
        (
            SELECT
                ActivityID,
                CASE
                    WHEN ActivityValue >= LowerLimit
                     AND ActivityValue <= UpperLimit
                    THEN 1
                    ELSE 0
                END AS IsOK
            FROM LatestTorque
            WHERE RowNo = 1
        )
 
        SELECT
            COUNT(*) AS TotalFasteners,
 
            SUM(CASE
                    WHEN IsOK = 1 THEN 1
                    ELSE 0
                END) AS OKCount,
 
            SUM(CASE
                    WHEN IsOK = 0 THEN 1
                    ELSE 0
                END) AS NOKCount,
 
            CAST(
                CASE
                    WHEN COUNT(*) = 0 THEN 0
                    ELSE
                        (SUM(CASE
                            WHEN IsOK = 1 THEN 1
                            ELSE 0
                        END) * 100.0) / COUNT(*)
                END
                AS DECIMAL(5,2)
            ) AS TorqueAccuracy
 
        FROM TorqueStatus;
 
    END TRY
 
    BEGIN CATCH
        THROW;
    END CATCH
 
END
GO

