-- ------------------------------------------------------------------------
-- [319/376] Stored Procedure: [dbo].[Prod_AlarmLog]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
-- =============================================
-- Author:        Vishal
-- Create Date:  27-Jul-2026
-- Description:  Alarm Data Logging
-- =============================================

CREATE   PROCEDURE [dbo].[Prod_AlarmLog]
(
    @I_AlarmID      INT,
    @I_AlarmVal     INT,
    @I_TimeStamp_YY INT,
    @I_TimeStamp_Mo INT,
    @I_TimeStamp_DD INT,
    @I_TimeStamp_hh INT,
    @I_TimeStamp_mm INT,
    @I_TimeStamp_ss INT,
    @O_ReturnValue  INT OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        DECLARE @DateTime DATETIME;

        SET @DateTime = DATETIMEFROMPARTS
        (
            @I_TimeStamp_YY,   -- 26 -> 2026
            @I_TimeStamp_Mo,
            @I_TimeStamp_DD,
            @I_TimeStamp_hh,
            @I_TimeStamp_mm,
            @I_TimeStamp_ss,
            0
        );

        INSERT INTO dbo.Maint_AlarmLog
        (
            AlarmID,
            AlarmVal,
            TimeStamp
        )
        VALUES
        (
            @I_AlarmID,
            @I_AlarmVal,
            @DateTime
        );

        SET @O_ReturnValue = 1;

        SELECT @O_ReturnValue AS ResultStatus;

    END TRY
    BEGIN CATCH

        SET @O_ReturnValue = 2;

        EXEC dbo.RethrowError;

        SELECT @O_ReturnValue AS ResultStatus;

    END CATCH
END
GO

-- ------------------------------------------------------------------------
-- [320/376] Stored Procedure: [dbo].[Prod_GenealogyDataLog]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE     PROCEDURE [dbo].[Prod_GenealogyDataLog]
(
    @I_EngineNo        NVARCHAR(14),
    @I_ActivityID      INT,
    @I_AvtivityValue   NVARCHAR(50),
    @I_ActivityStatus  INT,
    @I_Count            INT,
    @I_TimeStamp_YY INT,
    @I_TimeStamp_Mo INT,
    @I_TimeStamp_DD INT,
    @I_TimeStamp_hh INT,
    @I_TimeStamp_mm INT,
    @I_TimeStamp_ss INT
)
AS
BEGIN
    SET NOCOUNT ON;
     DECLARE @DateTime DATETIME;

        SET @DateTime = DATETIMEFROMPARTS
        (
            @I_TimeStamp_YY,   -- 26 -> 2026
            @I_TimeStamp_Mo,
            @I_TimeStamp_DD,
            @I_TimeStamp_hh,
            @I_TimeStamp_mm,
            @I_TimeStamp_ss,
            0
        );

    DECLARE
        @PlanID INT = 0,
        @StationID INT,
        @SubAssemblyID INT;

    SELECT TOP (1)
        @StationID = StationID,
        @SubAssemblyID = SubAsslyLineID
    FROM Config_Activity
    WHERE ActivityID = @I_ActivityID;

    IF @SubAssemblyID <> 7 or @SubAssemblyID <> 1 
    BEGIN
        SELECT TOP (1)
            @PlanID = ISNULL(PlanID, 0)
        FROM Prod_SA_PlanExecution
        WHERE Status = 2
          AND SubAsslyLineID = @SubAssemblyID;
    IF @SubAssemblyID = 1
        SELECT TOP (1)
            @PlanID = ISNULL(PlanID, 0)
        FROM Prod_EnginePlanExecution
        WHERE Status = 2
          

    -- No active plan
    IF @PlanID = 0
    BEGIN
        RETURN 2;
    END;
    END;

    -- Engine Genealogy
    IF @SubAssemblyID = 7
    BEGIN
        INSERT INTO Prod_Engine_Activity_Log
        (
            [Timestamp],
            [EngineNo],
            [StationID],
            [ActivityID],
            [ActivityValue],
            [Count],
            [Status],
            [UserID]
        )
        VALUES
        (
            @DateTime,
            @I_EngineNo,
            @StationID,
            @I_ActivityID,
            @I_AvtivityValue,
            @I_Count,
            @I_ActivityStatus,
            1
        );
    END
    ELSE
    BEGIN
        -- Sub-Assembly Genealogy
        INSERT INTO Prod_SA_Geneology
        (
            [Timestamp],
            [SA_SerialNo],
            [PlanID],
            [StationID],
            [ActivityID],
            [ActivityValue],
            [Status],
            [UsersID]
        )
        VALUES
        (
            @DateTime,
            @I_EngineNo,
            @PlanID,
            @StationID,
            @I_ActivityID,
            @I_AvtivityValue,
            @I_ActivityStatus,
            1
        );
    END;

    -- Success
    RETURN 1;
END;
GO

-- ------------------------------------------------------------------------
-- [321/376] Stored Procedure: [dbo].[Prod_KittingOrderDownload]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE     PROCEDURE [dbo].[Prod_KittingOrderDownload]
(
    @I_AutoManualMode INT,
    @I_KITID NVARCHAR(10),
    @I_TrackingId NVARCHAR(10),
    @O_ReturnValue INT OUTPUT,
    @O_TrackingID NVARCHAR(10) OUTPUT,
    @O_ModelCode NVARCHAR(10) OUTPUT,
    @O_SKUCode NVARCHAR(10) OUTPUT,
    @O_LocationID INT OUTPUT,
    @O_ModelID INT OUTPUT,
    @O_SKUID INT OUTPUT,
    @O_PlanBelow24 INT OUTPUT,
    @O_NoPlan INT OUTPUT,
    @O_KitID NVARCHAR(10) OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE
        @ProdDate DATE,
        @Shift NVARCHAR(10),
        @PlanID INT,
        @KitAssemblyQty INT,
        @PlanQty INT,
        @LeastPriority INT,
        @ModelID INT,
        @SKUID INT,
        @LineID INT,
        @ModelCode NVARCHAR(20),
        @SKUCode NVARCHAR(20),
        @Gap INT,
        @PlanBelow INT,
        @NoPlan INT = 0,
        @Prefix NVARCHAR(10),
        @Number INT;

    -----------------------------------------
    -- Get Production Date & Shift
    -----------------------------------------
    SELECT @ProdDate = ParameterValue
    FROM ApplicationSetting
    WHERE ParameterID = 1;

    SELECT @Shift = ParameterValue
    FROM ApplicationSetting
    WHERE ParameterID = 2;

    -----------------------------------------
    -- Get Current Active Plan
    -----------------------------------------
    SELECT TOP (1)
        @PlanID = ISNULL(PE.PlanID,0),
        @KitAssemblyQty = ISNULL(PE.KitAssembly_Qty,0),
        @PlanQty = ISNULL(PE.PlanQty,0),
        @SKUID = ISNULL(PE.SKUID,0),
        @LineID = ISNULL(PE.LineID,0),
        @ModelCode = ISNULL(CM.ModelName,''),
        @ModelID = ISNULL(CM.ModelID,0),
        @SKUCode = ISNULL(CS.SKUName,'')
    FROM Prod_EnginePlanExecution PE
    INNER JOIN Config_SKU CS
        ON PE.SKUID = CS.SKUID
    INNER JOIN Config_Model CM
        ON CS.ModelID = CM.ModelID
    WHERE PE.Status = 2
      AND PE.ProdDate = @ProdDate
      AND PE.ProdShift = @Shift;

    -----------------------------------------
    -- No Active Plan
    -----------------------------------------
    IF @PlanID IS NULL
    BEGIN
        SELECT
            @O_ReturnValue = 2,
            @O_TrackingID = '',
            @O_ModelCode = '',
            @O_SKUCode = '',
            @O_LocationID = 0,
            @O_ModelID = 0,
            @O_SKUID = 0,
            @O_PlanBelow24 = 0,
            @O_NoPlan = 1,
            @O_KitID = @I_KITID;

        RETURN;
    END;

    -----------------------------------------
    -- Calculate Gap
    -----------------------------------------
    SET @Gap = @PlanQty - @KitAssemblyQty;

    SET @PlanBelow =
        CASE
            WHEN @Gap < 24 THEN 1
            ELSE 0
        END;

    -----------------------------------------
    -- Generate Tracking ID
    -----------------------------------------
    SET @Prefix = LEFT(@I_TrackingId,2);
    SET @Number = CAST(RIGHT(@I_TrackingId,8) AS INT);

    SET @Number = @Number + 1;

    SET @O_TrackingID = @Prefix + RIGHT('00000000' + CAST(@Number AS VARCHAR(8)),8);
    -----------------------------------------
-- Check Duplicate Tracking ID
-----------------------------------------
IF EXISTS
(
    SELECT 1
    FROM Prod_Engine_WIP
    WHERE VREngineNo = @O_TrackingID
)
BEGIN
    -- Return without inserting or updating quantity
    SELECT
        @O_ReturnValue = 1,
        @O_TrackingID = @O_TrackingID,
        @O_ModelCode = @ModelCode,
        @O_SKUCode = @SKUCode,
        @O_LocationID = @LineID,
        @O_ModelID = @ModelID,
        @O_SKUID = @SKUID,
        @O_PlanBelow24 = @PlanBelow,
        @O_NoPlan = @NoPlan,
        @O_KitID = @I_KITID;

    RETURN;
END;

    -----------------------------------------
    -- Insert WIP
    -----------------------------------------
    INSERT INTO Prod_Engine_WIP
    (
        VREngineNo,
        KITID,
        PlanID,
        SKUID,
        LineID,
        StartTime,
        EndTime,
        Status
    )
    VALUES
    (
        @O_TrackingID,
        @I_KITID,
        @PlanID,
        @SKUID,
        @LineID,
        GETDATE(),
        NULL,
        1
    );

    Insert into [Prod_Status_Geneology] ([Timestamp],[EngineNo],[Status],[ProdDate],[ProdShift])
     Values (GETDATE(),@O_TrackingID,1,@ProdDate, @Shift) 
      
    -----------------------------------------
    -- Update Quantity
    -----------------------------------------
    UPDATE Prod_EnginePlanExecution
    SET KitAssembly_Qty = KitAssembly_Qty + 1
    WHERE PlanID = @PlanID;

    SET @KitAssemblyQty = @KitAssemblyQty + 1;

    -----------------------------------------
    -- Plan Completed
    -----------------------------------------
    IF @KitAssemblyQty >= @PlanQty
    BEGIN
        UPDATE Prod_EnginePlanExecution
        SET Status = 3
        WHERE PlanID = @PlanID;

        IF @I_AutoManualMode = 1
        BEGIN
            SELECT @LeastPriority = MIN(Priority)
            FROM Prod_EnginePlanExecution
            WHERE ProdDate = @ProdDate
              AND ProdShift = @Shift
              AND Status = 1;

            UPDATE Prod_EnginePlanExecution
            SET Status = 2
            WHERE ProdDate = @ProdDate
              AND ProdShift = @Shift
              AND Status = 1
              AND Priority = @LeastPriority;
        END;
    END;

    -----------------------------------------
    -- Get Current Active Plan Again
    -----------------------------------------
    SELECT TOP (1)
        @PlanID = ISNULL(PE.PlanID,0),
        @KitAssemblyQty = ISNULL(PE.KitAssembly_Qty,0),
        @PlanQty = ISNULL(PE.PlanQty,0),
        @SKUID = ISNULL(PE.SKUID,0),
        @LineID = ISNULL(PE.LineID,0),
        @ModelCode = ISNULL(CM.ModelName,''),
        @ModelID = ISNULL(CM.ModelID,0),
        @SKUCode = ISNULL(CS.SKUName,'')
    FROM Prod_EnginePlanExecution PE
    INNER JOIN Config_SKU CS
        ON PE.SKUID = CS.SKUID
    INNER JOIN Config_Model CM
        ON CS.ModelID = CM.ModelID
    WHERE PE.Status = 2
      AND PE.ProdDate = @ProdDate
      AND PE.ProdShift = @Shift;

    SET @Gap = ISNULL(@PlanQty,0) - ISNULL(@KitAssemblyQty,0);

    SET @PlanBelow =
        CASE
            WHEN @Gap < 24 THEN 1
            ELSE 0
        END;

    SET @NoPlan =
        CASE
            WHEN @PlanID IS NULL THEN 1
            ELSE 0
        END;

    -----------------------------------------
    -- Final Output
    -----------------------------------------
    SELECT
        @O_ReturnValue = 1,
        @O_TrackingID = @O_TrackingID,
        @O_ModelCode = @ModelCode,
        @O_SKUCode = @SKUCode,
        @O_LocationID = @LineID,
        @O_ModelID = @ModelID,
        @O_SKUID = @SKUID,
        @O_PlanBelow24 = @PlanBelow,
        @O_NoPlan = @NoPlan,
        @O_KitID = @I_KITID;
END
GO

-- ------------------------------------------------------------------------
-- [322/376] Stored Procedure: [dbo].[Prod_SAOrderDownload]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE     PROCEDURE [dbo].[Prod_SAOrderDownload]
(
    @I_AutoManualMode INT,
    @I_SubassemblyID INT,
    @I_TrackingId NVARCHAR(10),
    @O_ReturnValue INT OUTPUT,
    @O_TrackingID NVARCHAR(10) OUTPUT,
    @O_ModelCode NVARCHAR(10) OUTPUT,
    @O_SKUCode NVARCHAR(10) OUTPUT,
    @O_LocationID INT OUTPUT,
    @O_ModelID INT OUTPUT,
    @O_SKUID INT OUTPUT,
    @O_PlanBelow24 INT OUTPUT,
    @O_NoPlan INT OUTPUT,
    @O_ProgramNo INT OUTPUT
    
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE
        @ProdDate DATE,
        @Shift NVARCHAR(10),
        @PlanID INT,
        @StartedQty INT,
        @PlanQty INT,
        @LeastPriority INT,
        @ModelID INT,
        @SKUID INT,
        @SubassemblyID INT,
        @ModelCode NVARCHAR(20),
        @SKUCode NVARCHAR(20),
        @Gap INT,
        @PlanBelow INT,
        @NoPlan INT = 0,
        @Prefix NVARCHAR(10),
        @Number INT,
        @NewPlan INT,
        @ProgramNo INT;

    -----------------------------------------
    -- Get Production Date & Shift
    -----------------------------------------
    SELECT @ProdDate = ParameterValue
    FROM ApplicationSetting
    WHERE ParameterID = 1;

    SELECT @Shift = ParameterValue
    FROM ApplicationSetting
    WHERE ParameterID = 2;

    -----------------------------------------
    -- Get Current Active Plan
    -----------------------------------------
    SELECT TOP (1)
        @PlanID = ISNULL(PE.PlanID,0),
        @StartedQty= ISNULL(PE.InProcessQty,0),
        @PlanQty = ISNULL(PE.PlanQty,0),
        @SKUID = ISNULL(PE.SKUID,0),
        @SubassemblyID = ISNULL(PE.SubAsslyLineID,0),
        @ModelCode = ISNULL(CM.ModelName,''),
        @ModelID = ISNULL(CM.ModelID,0),
        @SKUCode = ISNULL(CS.SKUName,'')
        FROM Prod_SA_PlanExecution PE
    INNER JOIN Config_SKU CS
        ON PE.SKUID = CS.SKUID
    INNER JOIN Config_Model CM
        ON CS.ModelID = CM.ModelID
     WHERE PE.Status = 2
      AND PE.SubAsslyLineID = @I_SubassemblyID
      AND PE.ProdDate = @ProdDate
      AND PE.ProdShift = @Shift;
      Select Top(1) @ProgramNo = ISNULL(ProgramNo,0) from Config_SKUProgramMapping 
      WHERE SubAsslyLineID= @SubassemblyID and SKUID = @SKUID

    -----------------------------------------
    -- No Active Plan
    -----------------------------------------
    IF @PlanID IS NULL
    BEGIN
        SELECT
            @O_ReturnValue = 2,
            @O_TrackingID = '',
            @O_ModelCode = '',
            @O_SKUCode = '',
            @O_LocationID = 0,
            @O_ModelID = 0,
            @O_SKUID = 0,
            @O_PlanBelow24 = 0,
            @O_NoPlan = 1,
            @O_ProgramNo = 0;
           

        RETURN;
    END;

    -----------------------------------------
    -- Calculate Gap
    -----------------------------------------
    SET @Gap = @PlanQty - @StartedQty;

    SET @PlanBelow =
        CASE
            WHEN @Gap < 24 THEN 1
            ELSE 0
        END;

    -----------------------------------------
    -- Generate Tracking ID
    -----------------------------------------
    SET @Prefix = LEFT(@I_TrackingId,2);
    SET @Number = CAST(RIGHT(@I_TrackingId,8) AS INT);

    SET @Number = @Number + 1;

    SET @O_TrackingID = @Prefix + RIGHT('00000000' + CAST(@Number AS VARCHAR(8)),8);
    -----------------------------------------
-- Check Duplicate Tracking ID
-----------------------------------------
IF EXISTS
(
    SELECT 1
    FROM Prod_SA_WIP
    WHERE VSA_SerialNo = @O_TrackingID and SubAsslyLineID = @I_SubassemblyID
)
BEGIN
    -- Return without inserting or updating quantity
    SELECT
        @O_ReturnValue = 1,
        @O_TrackingID = @O_TrackingID,
        @O_ModelCode = @ModelCode,
        @O_SKUCode = @SKUCode,
        @O_LocationID = @SubassemblyID,
        @O_ModelID = @ModelID,
        @O_SKUID = @SKUID,
        @O_PlanBelow24 = @PlanBelow,
        @O_NoPlan = @NoPlan,
        @O_ProgramNo = @ProgramNo;
       

    RETURN;
END;

    -----------------------------------------
    -- Insert WIP
    -----------------------------------------
    INSERT INTO Prod_SA_WIP
    (
        VSA_SerialNo,
        SA_SerialNo,
        PlanID,
        SKUID,
        SubAsslyLineID,
        StartTime,
        EndTime,
        Status
    )
    VALUES
    (
        @O_TrackingID,
        '',
        @PlanID,
        @SKUID,
        @SubassemblyID,
        GETDATE(),
        NULL,
        1
    );

    -----------------------------------------
    -- Update Quantity
    -----------------------------------------
    UPDATE Prod_SA_PlanExecution
    SET InProcessQty = InProcessQty + 1
    WHERE PlanID = @PlanID and SubAsslyLineID = @SubassemblyID ;

    SET @StartedQty = @StartedQty + 1;

    -----------------------------------------
    -- Plan Completed
    -----------------------------------------
    IF @StartedQty >= @PlanQty
    BEGIN
        UPDATE Prod_SA_PlanExecution
        SET Status = 3
        WHERE PlanID = @PlanID and SubAsslyLineID = @SubassemblyID;

        IF @I_AutoManualMode = 1
        BEGIN
            SELECT TOP (1)
               @LeastPriority = Priority,
               @NewPlan = PlanID
               FROM Prod_SA_PlanExecution 
               WHERE ProdDate = @ProdDate
                AND ProdShift = @Shift
                AND Status = 1 
                AND SubAsslyLineID = @SubassemblyID
                ORDER BY Priority ASC, PlanID ASC;

            UPDATE Prod_SA_PlanExecution
            SET Status = 2
            WHERE PlanID = @NewPlan
              AND Status = 1
              AND Priority = @LeastPriority
              AND SubAsslyLineID = @SubassemblyID;
        END;
    END;

    -----------------------------------------
    -- Get Current Active Plan Again
    -----------------------------------------
    SELECT TOP (1)
        @PlanID = ISNULL(PE.PlanID,0),
        @StartedQty= ISNULL(PE.InProcessQty,0),
        @PlanQty = ISNULL(PE.PlanQty,0),
        @SKUID = ISNULL(PE.SKUID,0),
        @SubassemblyID = ISNULL(PE.SubAsslyLineID,0),
        @ModelCode = ISNULL(CM.ModelName,''),
        @ModelID = ISNULL(CM.ModelID,0),
        @SKUCode = ISNULL(CS.SKUName,'')
    FROM Prod_SA_PlanExecution PE
    INNER JOIN Config_SKU CS
        ON PE.SKUID = CS.SKUID
    INNER JOIN Config_Model CM
        ON CS.ModelID = CM.ModelID
    WHERE PE.Status = 2
      AND PE.SubAsslyLineID = @I_SubassemblyID
      AND PE.ProdDate = @ProdDate
      AND PE.ProdShift = @Shift;
      Select Top(1) @ProgramNo = ISNULL(ProgramNo,0) from Config_SKUProgramMapping 
      WHERE SubAsslyLineID= @SubassemblyID and SKUID = @SKUID

    SET @Gap = ISNULL(@PlanQty,0) - ISNULL(@StartedQty,0);

    SET @PlanBelow =
        CASE
            WHEN @Gap < 24 THEN 1
            ELSE 0
        END;

    SET @NoPlan =
        CASE
            WHEN @PlanID IS NULL THEN 1
            ELSE 0
        END;

    -----------------------------------------
    -- Final Output
    -----------------------------------------
    SELECT
        @O_ReturnValue = 1,
        @O_TrackingID = @O_TrackingID,
        @O_ModelCode = @ModelCode,
        @O_SKUCode = @SKUCode,
        @O_LocationID = @SubassemblyID,
        @O_ModelID = @ModelID,
        @O_SKUID = @SKUID,
        @O_PlanBelow24 = @PlanBelow,
        @O_NoPlan = @NoPlan,
        @O_ProgramNo = @ProgramNo;
       
END
GO

-- ------------------------------------------------------------------------
-- [323/376] Stored Procedure: [dbo].[Prod_TrackingValidation]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
Create PROCEDURE [dbo].[Prod_TrackingValidation]
(
    @I_SubassemblyID INT,
    @I_QRType        INT,
    @I_KitQR         NVARCHAR(10),

    @O_ReturnValue   INT OUTPUT,
    @O_TrackingID    NVARCHAR(10) OUTPUT,
    @O_ModelCode     NVARCHAR(10) OUTPUT,
    @O_SKUCode       NVARCHAR(10) OUTPUT,
    @O_LocationID    INT OUTPUT,
    @O_ModelID       INT OUTPUT,
    @O_SKUID         INT OUTPUT,
    @O_Status        INT OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    ------------------------------------------------------------
    -- Initialize local variables
    ------------------------------------------------------------
    DECLARE
        @ModelID       INT = 0,
        @SKUID         INT = 0,
        @SubassemblyID INT = 0,
        @ModelCode     NVARCHAR(20) = N'',
        @SKUCode       NVARCHAR(20) = N'',
        @VREngineNo    NVARCHAR(20) = N'',
        @Status        INT = 0;

    ------------------------------------------------------------
    -- Get Current Active Plan
    ------------------------------------------------------------
    IF @I_SubassemblyID = 1
    BEGIN

        SELECT TOP (1)
            @VREngineNo    = ISNULL(PE.VREngineNo, N''),
            @SKUID         = ISNULL(PE.SKUID, 0),
            @SubassemblyID = @I_SubassemblyID,
            @ModelCode     = ISNULL(CM.ModelName, N''),
            @ModelID       = ISNULL(CM.ModelID, 0),
            @SKUCode       = ISNULL(CS.SKUName, N''),
            @Status        = ISNULL(PE.Status, 0)
        FROM Prod_Engine_WIP AS PE
        INNER JOIN Config_SKU AS CS
            ON PE.SKUID = CS.SKUID
        INNER JOIN Config_Model AS CM
            ON CS.ModelID = CM.ModelID
        WHERE PE.KITID = @I_KitQR;

    END
    ELSE
    BEGIN

        SELECT TOP (1)
            @VREngineNo    = ISNULL(PS.VSA_SerialNo, N''),
            @SKUID         = ISNULL(PS.SKUID, 0),
            @SubassemblyID = @I_SubassemblyID,
            @ModelCode     = ISNULL(CM.ModelName, N''),
            @ModelID       = ISNULL(CM.ModelID, 0),
            @SKUCode       = ISNULL(CS.SKUName, N''),
            @Status        = ISNULL(PS.Status, 0)
        FROM Prod_SA_WIP AS PS
        INNER JOIN Config_SKU AS CS
            ON PS.SKUID = CS.SKUID
        INNER JOIN Config_Model AS CM
            ON CS.ModelID = CM.ModelID
        WHERE PS.SA_SerialNo = @I_KitQR
          AND PS.SubAsslyLineID = @I_SubassemblyID;

    END;

    ------------------------------------------------------------
    -- No Active Plan / Invalid QR
    ------------------------------------------------------------
    IF @SKUID = 0
    BEGIN
        SELECT
            @O_ReturnValue = 2,
            @O_TrackingID = N'',
            @O_ModelCode  = N'',
            @O_SKUCode   = N'',
            @O_LocationID = 0,
            @O_ModelID    = 0,
            @O_SKUID      = 0,
            @O_Status     = 0

        RETURN;
    END;

    ------------------------------------------------------------
    -- Final Output
    ------------------------------------------------------------
    SELECT
        @O_ReturnValue = 1,
        @O_TrackingID = @VREngineNo,
        @O_ModelCode  = @ModelCode,
        @O_SKUCode    = @SKUCode,
        @O_LocationID = @SubassemblyID,
        @O_ModelID    = @ModelID,
        @O_SKUID      = @SKUID,
        @O_Status     = @Status

END;
GO

-- ------------------------------------------------------------------------
-- [324/376] Stored Procedure: [dbo].[Prod_WIPStatusUpdate]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE     PROCEDURE [dbo].[Prod_WIPStatusUpdate]
(
    @Status INT,
    @I_SubassemblyID INT,
    @I_TrackingId NVARCHAR(14)
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @PlanID INT;

    -- Get Plan ID for the given WIP
    SELECT @PlanID = PlanID
    FROM Prod_SA_WIP
    WHERE VSA_SerialNo = @I_TrackingId
      AND SubAsslyLineID = @I_SubassemblyID;
Declare @CompletedQty as int;
Select @CompletedQty = CompletedQty from Prod_SA_PlanExecution 
Where SubAsslyLineID = @I_SubassemblyID and PlanID = @PlanID

    ---------------------------------------------------------
    -- Update WIP Status
    ---------------------------------------------------------
    IF @Status = 1
    BEGIN
        UPDATE Prod_SA_WIP
        SET
            Status = 2,
            StartTime = GETDATE()
        WHERE VSA_SerialNo = @I_TrackingId
          AND SubAsslyLineID = @I_SubassemblyID;
    END
    ELSE IF @Status = 2
    BEGIN
        UPDATE Prod_SA_WIP
        SET
            Status = 3,
            EndTime = GETDATE()
        WHERE VSA_SerialNo = @I_TrackingId
          AND SubAsslyLineID = @I_SubassemblyID;


        -----------------------------------------------------
        -- Update Quantity
        -----------------------------------------------------
        UPDATE Prod_SA_PlanExecution
        SET CompletedQty = ISNULL(@CompletedQty, 0) + 1
        WHERE PlanID = @PlanID
          AND SubAsslyLineID = @I_SubassemblyID;
    END
END
GO

