    @I_TrackingId NVARCHAR(14)
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @PlanID INT,@ProdDate DATE,@Shift NVARCHAR(10);
       -----------------------------------------
    -- Get Production Date & Shift
    -----------------------------------------
    SELECT @ProdDate = ParameterValue
    FROM ApplicationSetting
    WHERE ParameterID = 1;

    SELECT @Shift = ParameterValue
    FROM ApplicationSetting
    WHERE ParameterID = 2;
 
    -- Get Plan ID for the given WIP
    SELECT @PlanID = PlanID
    FROM [dbo].[Prod_Engine_WIP]
    WHERE VREngineNo = @I_TrackingId
     
Declare @CompletedQty as int;
Select @CompletedQty = KitInspected_Qty from [dbo].[Prod_EnginePlanExecution]
Where PlanID = @PlanID
 ---------------------------------------------------------
    -- Update WIP Status
    ---------------------------------------------------------
    IF @Status = 1
