     Insert into [Prod_Status_Geneology] ([Timestamp],[EngineNo],[Status],[ProdDate],[ProdShift])
     Values (GETDATE(),@I_TrackingId,2,@ProdDate, @Shift) 

    END
    ELSE IF @Status = 2
    BEGIN
