-- [326/376] Stored Procedure: [dbo].[RethrowError]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE         PROCEDURE [dbo].[RethrowError]
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE
        @ErrorMessage    NVARCHAR(4000),
        @ErrorNumber     INT,
        @ErrorSeverity   INT,
        @ErrorState      INT,
        @ErrorLine       INT,
        @ErrorProcedure  NVARCHAR(200);

    SELECT
        @ErrorNumber = ERROR_NUMBER(),
        @ErrorSeverity = ERROR_SEVERITY(),
        @ErrorState = ERROR_STATE(),
        @ErrorLine = ERROR_LINE(),
        @ErrorProcedure = ISNULL(ERROR_PROCEDURE(), '-'),
        @ErrorMessage = ERROR_MESSAGE();

    BEGIN
        INSERT INTO SP_Error_Log
        (
            ErrorTimestamp,
            ErrorNumber,
            ErrorState,
            ErrorSeverity,
            ErrorLine,
            ErrorProc,
            ErrorMsg
        )
        VALUES
        (
            GETDATE(),
            @ErrorNumber,
            @ErrorState,
            @ErrorSeverity,
            @ErrorLine,
            @ErrorProcedure,
            @ErrorMessage
        );
    END
END
GO

