-- ------------------------------------------------------------------------
-- [330/376] Stored Procedure: [dbo].[SP_NPDUpdate]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE     PROCEDURE [dbo].[SP_NPDUpdate]
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @CurrentTime DATETIME = GETDATE();

    -- Get Production Date
    DECLARE @ProdDate DATE = (
        SELECT TOP 1 [ParameterValue]
        FROM dbo.ApplicationSetting
        WHERE ParameterID = 1
    );

    -- Get Production Shift
    DECLARE @Shift NVARCHAR(10) = (
        SELECT TOP 1 [ParameterValue]
        FROM dbo.ApplicationSetting
        WHERE ParameterID = 2
    );

    ;WITH LatestNPD AS
    (
        SELECT
            NPD.UID,
            NPD.LineID,
            NPD.StartDate,
            NPD.EndDate,
            ROW_NUMBER() OVER
            (
                PARTITION BY NPD.LineID
                ORDER BY NPD.UID DESC
            ) AS rn
        FROM dbo.Perf_PlannedShutDown NPD
        WHERE CAST(NPD.StartDate AS DATE) <= @ProdDate
          AND CAST(NPD.EndDate AS DATE) >= @ProdDate
          AND NPD.ProdShift = @Shift
    )
    UPDATE C
    SET ShutDownStatus =
        CASE
            WHEN @CurrentTime > L.StartDate
                 AND @CurrentTime < L.EndDate THEN 1
            WHEN @CurrentTime > L.EndDate THEN 2
            ELSE 0
        END
    FROM LatestNPD L
    INNER JOIN dbo.Perf_PlannedShutDown C
        ON C.UID = L.UID
    WHERE L.rn = 1;

    -- Update Shift Information
    UPDATE PSI
    SET PSI.[ParameterValue] =
        CASE
            WHEN C.ShutDownStatus = 1 THEN 1
            ELSE 0
        END
    FROM dbo.ApplicationSetting PSI
    INNER JOIN dbo.Perf_PlannedShutDown C
        ON C.LineID = 1
    WHERE C.ProdShift = @Shift
      AND CAST(C.StartDate AS DATE) <= @ProdDate
      AND CAST(C.EndDate AS DATE) >= @ProdDate
      AND PSI.ParameterID = 5;

    -- Mark expired shutdowns
    UPDATE dbo.Perf_PlannedShutDown
    SET ShutDownStatus = 2
    WHERE EndDate < @CurrentTime;

END
GO

-- ------------------------------------------------------------------------
-- [331/376] Stored Procedure: [dbo].[SP_ProcessSAPMaterialReceiving]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE     PROCEDURE [dbo].[SP_ProcessSAPMaterialReceiving]
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @JobTime DATETIME = GETDATE();
    DECLARE @JobTimeOnly TIME = CAST(@JobTime AS TIME);

    DECLARE
        @SAPUID INT,
        @ReceivingQty INT,
        @ValidatedQty INT,
        @EDINumber NVARCHAR(20),
        @VendorID INT,
        @PartID NVARCHAR(20),
        @SAPTimestamp DATETIME,

        @PartInspection INT,
        @MaterialReceivingUID INT,

        @CurrentShiftStart DATETIME,
        @CurrentShiftEnd DATETIME;


    /* ============================================================
       1. FIND CURRENT SHIFT
       
       Shift 1 : 07:00 - 15:50
       Shift 2 : 16:00 - 00:50
       Shift 3 : 00:50 - 07:00

       NOTE:
       15:50 - 16:00 is currently treated as Shift 3.
       ============================================================ */


    IF @JobTimeOnly >= '07:00'
       AND @JobTimeOnly < '15:50'
    BEGIN

        -- Shift 1
        SET @CurrentShiftStart =
            DATEADD(
                MINUTE,
                420,
                CAST(CAST(@JobTime AS DATE) AS DATETIME)
            );

        SET @CurrentShiftEnd =
            DATEADD(
                MINUTE,
                950,
                CAST(CAST(@JobTime AS DATE) AS DATETIME)
            );

    END

    ELSE IF @JobTimeOnly >= '16:00'
    BEGIN

        -- Shift 2
        SET @CurrentShiftStart =
            DATEADD(
                MINUTE,
                960,
                CAST(CAST(@JobTime AS DATE) AS DATETIME)
            );

        SET @CurrentShiftEnd =
            DATEADD(
                MINUTE,
                50,
                DATEADD(
                    DAY,
                    1,
                    CAST(CAST(@JobTime AS DATE) AS DATETIME)
                )
            );

    END

    ELSE
    BEGIN

        -- Shift 3
        SET @CurrentShiftStart =
            DATEADD(
                MINUTE,
                50,
                CAST(CAST(@JobTime AS DATE) AS DATETIME)
            );

        SET @CurrentShiftEnd =
            DATEADD(
                MINUTE,
                420,
                CAST(CAST(@JobTime AS DATE) AS DATETIME)
            );

    END;


    PRINT '==============================================';
    PRINT 'SAP MATERIAL RECEIVING JOB STARTED';
    PRINT 'Job Time       : ' + CONVERT(VARCHAR(30), @JobTime, 121);
    PRINT 'Shift Start    : ' + CONVERT(VARCHAR(30), @CurrentShiftStart, 121);
    PRINT 'Shift End      : ' + CONVERT(VARCHAR(30), @CurrentShiftEnd, 121);
    PRINT '==============================================';


    /* ============================================================
       2. GET UNPROCESSED SAP RECORDS

       Record must NOT exist in:

       A. Material_Receiving
       B. Material_Receiving_History

       Matching:
       EDI Number
       VendorID
       PartID
       Receiving Quantity
       Timestamp
       ============================================================ */


    DECLARE SAP_CURSOR CURSOR LOCAL FAST_FORWARD FOR

        SELECT
            S.UID,
            S.[ReceivingQty],
            S.[ValidatedQty],
            S.[EDINumber],
            S.VendorID,
            S.[PartID],
            S.[Timestamp]

        FROM SAP_Table S

        WHERE NOT EXISTS
        (
            SELECT 1
            FROM Material_Receiving MR
            WHERE MR.EDINumber = S.[EDINumber]
              AND MR.VendorID = S.VendorID
              AND MR.PartID = S.[PartID]
              AND MR.Quantity = S.[ReceivingQty]
              AND MR.[Timestamp] = S.[Timestamp]
        )

        AND NOT EXISTS
        (
            SELECT 1
            FROM Material_Receiving_History MRH
            WHERE MRH.EDINumber = S.[EDINumber]
              AND MRH.VendorID = S.VendorID
              AND MRH.PartID = S.[PartID]
              AND MRH.Quantity = S.[ReceivingQty]
              AND MRH.[Timestamp] = S.[Timestamp]
        );


    OPEN SAP_CURSOR;


    FETCH NEXT FROM SAP_CURSOR
    INTO
        @SAPUID,
        @ReceivingQty,
        @ValidatedQty,
        @EDINumber,
        @VendorID,
        @PartID,
        @SAPTimestamp;


    WHILE @@FETCH_STATUS = 0
    BEGIN

        BEGIN TRY

            BEGIN TRANSACTION;


            PRINT
                'Processing SAP UID = '
                + CAST(@SAPUID AS VARCHAR(20))
                + ', EDI = '
                + ISNULL(@EDINumber, 'NULL')
                + ', PartID = '
                + CAST(@PartID AS VARCHAR(20));


            /* ====================================================
               CASE 1
               
               SAP does NOT contain Validated Quantity
               
               Status = 1
               ==================================================== */


            IF @ValidatedQty IS NULL
            BEGIN

                INSERT INTO Material_Receiving
                (
                    EDINumber,
                    VendorID,
                    PartID,
                    Quantity,
                    [Timestamp],
                    ValidatedQty,
                    OKQty,
                    RejectedQty,
                    HoldQty,
                    ValidatedBy,
                    SampleQty,
                    SampleLevel,
                    Status,
                    BatchID,
                    Remark
                )
                VALUES
                (
                    @EDINumber,
                    @VendorID,
                    @PartID,
                    @ReceivingQty,
                    @SAPTimestamp,
                    NULL,
                    0,
                    0,
                    0,
                    NULL,
                    0,
                    NULL,
                    1,
                    NULL,
                    NULL
                );


                SET @MaterialReceivingUID =
                    CONVERT(INT, SCOPE_IDENTITY());


                /* Geneology Status 1 */

                INSERT INTO Material_Receiving_Geneology
                (
                    EDINumber,
                    PartID,
                    Status,
                    LastUpdatedBy,
                    LastUpdatedTime
                )
                VALUES
                (
                    @EDINumber,
                    @PartID,
                    1,
                    NULL,
                    @JobTime
                );


                PRINT 'Inserted Material_Receiving Status = 1';

            END


            /* ====================================================
               CASE 2
               
               SAP contains Validated Quantity
               ==================================================== */

            ELSE
            BEGIN

                /* =================================================
                   Get PartInspection
                   ================================================= */

                SET @PartInspection = NULL;


                SELECT
                    @PartInspection = PartInspection
                FROM Config_PartVariant
                WHERE PartID = @PartID;


                IF @PartInspection IS NULL
                BEGIN

                    THROW 50001,
                          'PartInspection configuration not found for PartID.',
                          1;

                END;


                /* =================================================
                   PART INSPECTION = 1
                   ================================================= */

                IF @PartInspection = 1
                BEGIN

                    /* =============================================
                       Check Status 6 in CURRENT JOB SHIFT
                       ============================================= */

                    IF EXISTS
                    (
                        SELECT 1
                        FROM Material_Receiving MR
                        WHERE MR.PartID = @PartID
                          AND MR.Status = 6
                          AND MR.[Timestamp] >= @CurrentShiftStart
                          AND MR.[Timestamp] < @CurrentShiftEnd
                    )
                    BEGIN

                        /* =========================================
                           Already validated in current shift

                           Status = 4
                           StoreQty += ReceivingQty
                           ========================================= */

                        INSERT INTO Material_Receiving
                        (
                            EDINumber,
                            VendorID,
                            PartID,
                            Quantity,
                            [Timestamp],
                            ValidatedQty,
                            OKQty,
                            RejectedQty,
                            HoldQty,
                            ValidatedBy,
                            SampleQty,
                            SampleLevel,
                            Status,
                            BatchID,
                            Remark
                        )
                        VALUES
                        (
                            @EDINumber,
                            @VendorID,
                            @PartID,
                            @ReceivingQty,
                            @SAPTimestamp,
                            @ValidatedQty,
                            0,
                            0,
                            0,
                            NULL,
                            0,
                            NULL,
                            4,
                            NULL,
                            NULL
                        );


                        SET @MaterialReceivingUID =
                            CONVERT(INT, SCOPE_IDENTITY());


                        /* ONLY StoreQty is updated */

                        UPDATE Material_Stock
                        SET StoreQty =
                            ISNULL(StoreQty, 0) + @ReceivingQty
                        WHERE PartID = @PartID;


                        /* Geneology Status 4 */

                        INSERT INTO Material_Receiving_Geneology
                        (
                            EDINumber,
                            PartID,
                            Status,
                            LastUpdatedBy,
                            LastUpdatedTime
                        )
                        VALUES
                        (
                            @EDINumber,
                            @PartID,
                            4,
                            NULL,
                            @JobTime
                        );


                        PRINT 'PartInspection = 1';
                        PRINT 'Current shift already validated';
                        PRINT 'Status = 4';
                        PRINT 'StoreQty updated';

                    END
                    ELSE
                    BEGIN

                        /* =========================================
                           NOT validated in current shift

                           Status = 3
                           IncomingQty += ReceivingQty
                           ========================================= */

                        INSERT INTO Material_Receiving
                        (
                            EDINumber,
                            VendorID,
                            PartID,
                            Quantity,
                            [Timestamp],
                            ValidatedQty,
                            OKQty,
                            RejectedQty,
                            HoldQty,
                            ValidatedBy,
                            SampleQty,
                            SampleLevel,
                            Status,
                            BatchID,
                            Remark
                        )
                        VALUES
                        (
                            @EDINumber,
                            @VendorID,
                            @PartID,
                            @ReceivingQty,
                            @SAPTimestamp,
                            @ValidatedQty,
                            0,
                            0,
                            0,
                            1,
                            0,
                            NULL,
                            3,
                            @EDINumber,
                            NULL
                        );


                        SET @MaterialReceivingUID =
                            CONVERT(INT, SCOPE_IDENTITY());


                        /* ONLY IncomingQty is updated */

                        UPDATE Material_Stock
                        SET IncomingQty =
                            ISNULL(IncomingQty, 0) + @ReceivingQty
                        WHERE PartID = @PartID;


                        /* Geneology Status 3 */

                        INSERT INTO Material_Receiving_Geneology
                        (
                            EDINumber,
                            PartID,
                            Status,
                            LastUpdatedBy,
                            LastUpdatedTime
                        )
                        VALUES
                        (
                            @EDINumber,
                            @PartID,
                            3,
                            1,
                            @JobTime
                        );


                        PRINT 'PartInspection = 1';
                        PRINT 'Current shift NOT validated';
                        PRINT 'Status = 3';
                        PRINT 'IncomingQty updated';

                    END;

                END


                /* =================================================
                   PART INSPECTION = 2
                   ================================================= */

                ELSE IF @PartInspection = 2
                BEGIN

                    /* =============================================
                       Insert Status 3
                       ============================================= */

                    INSERT INTO Material_Receiving
                    (
                        EDINumber,
                        VendorID,
                        PartID,
                        Quantity,
                        [Timestamp],
                        ValidatedQty,
                        OKQty,
                        RejectedQty,
                        HoldQty,
                        ValidatedBy,
                        SampleQty,
                        SampleLevel,
                        Status,
                        BatchID,
                        Remark
                    )
                    VALUES
                    (
                        @EDINumber,
                        @VendorID,
                        @PartID,
                        @ReceivingQty,
                        @SAPTimestamp,
                        @ValidatedQty,
                        0,
                        0,
                        0,
                        NULL,
                        0,
                        NULL,
                        3,
                        @EDINumber,
                        'Part inspection not required'
                    );


                    SET @MaterialReceivingUID =
                        CONVERT(INT, SCOPE_IDENTITY());


                    /* Geneology Status 3 */

                    INSERT INTO Material_Receiving_Geneology
                    (
                        EDINumber,
                        PartID,
                        Status,
                        LastUpdatedBy,
                        LastUpdatedTime
                    )
                    VALUES
                    (
                        @EDINumber,
                        @PartID,
                        3,
                        NULL,
                        @JobTime
                    );


                    /* =============================================
                       ONLY StoreQty is updated
                       ============================================= */

                    UPDATE Material_Stock
                    SET StoreQty =
                        ISNULL(StoreQty, 0) + @ReceivingQty
                    WHERE PartID = @PartID;


                    /* =============================================
                       Status 3 → 9
                       ============================================= */

                    UPDATE Material_Receiving
                    SET Status = 9
                    WHERE UID = @MaterialReceivingUID;


                    /* Geneology Status 9 */

                    INSERT INTO Material_Receiving_Geneology
                    (
                        EDINumber,
                        PartID,
                        Status,
                        LastUpdatedBy,
                        LastUpdatedTime
                    )
                    VALUES
                    (
                        @EDINumber,
                        @PartID,
                        9,
                        1,
                        @JobTime
                    );


                    PRINT 'PartInspection = 2';
                    PRINT 'Status 3 -> 9';
                    PRINT 'StoreQty updated';

                END


                /* =================================================
                   INVALID CONFIGURATION
                   ================================================= */

                ELSE
                BEGIN

                    THROW 50002,
                          'Invalid PartInspection value. Expected 1 or 2.',
                          1;

                END;

            END;


            COMMIT TRANSACTION;


            PRINT
                'SUCCESS: SAP UID = '
                + CAST(@SAPUID AS VARCHAR(20));


        END TRY

        BEGIN CATCH

            IF @@TRANCOUNT > 0
                ROLLBACK TRANSACTION;


            PRINT '==============================================';
            PRINT 'ERROR PROCESSING SAP RECORD';
            PRINT 'SAP UID   : ' + ISNULL(CAST(@SAPUID AS VARCHAR(20)), 'NULL');
            PRINT 'EDI Number: ' + ISNULL(@EDINumber, 'NULL');
            PRINT 'PartID    : ' + ISNULL(CAST(@PartID AS VARCHAR(20)), 'NULL');
            PRINT 'Error     : ' + ERROR_MESSAGE();
            PRINT '==============================================';

        END CATCH;


        FETCH NEXT FROM SAP_CURSOR
        INTO
            @SAPUID,
            @ReceivingQty,
            @ValidatedQty,
            @EDINumber,
            @VendorID,
            @PartID,
            @SAPTimestamp;

    END;


    CLOSE SAP_CURSOR;
    DEALLOCATE SAP_CURSOR;


    PRINT '==============================================';
    PRINT 'SAP MATERIAL RECEIVING JOB COMPLETED';
    PRINT '==============================================';

END;
GO

-- ------------------------------------------------------------------------
-- [332/376] Stored Procedure: [dbo].[SP_Prod_EngineNo_SKU]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE   PROCEDURE [dbo].[SP_Prod_EngineNo_SKU]
(
    @I_CCLH_Barcode  VARCHAR(12),
    @O_CCLH_Barcode  VARCHAR(12) OUTPUT,
    @O_SKUCode       VARCHAR(10) OUTPUT,
    @O_SKUID         INT OUTPUT
)
AS
BEGIN
    SET NOCOUNT ON;

    -- Initialize output parameters
    SET @O_CCLH_Barcode = NULL;
    SET @O_SKUCode = NULL;
    SET @O_SKUID = NULL;

    SELECT TOP 1
        @O_CCLH_Barcode = E.EngineNo,
        @O_SKUCode      = E.SKUName,
        @O_SKUID        = S.SKUID
    FROM dbo.Prod_Engine_SKU_Execution E
    INNER JOIN dbo.Config_SKU S
        ON E.SKUName = S.SKUName
    WHERE E.EngineNo = @I_CCLH_Barcode
      AND E.Status = 1;

    -- Return output
    SELECT
        @O_CCLH_Barcode AS O_CCLH_Barcode,
        @O_SKUCode      AS O_SKUCode,
        @O_SKUID        AS O_SKUID;
END
GO

