-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE     Procedure [dbo].[SP_Update_ShiftInformation]
@ProdDate DATE,
@ProdShift NVARCHAR(10),
@SessionID INT
AS
BEGIN
Update Prod_ShiftInformation Set [ParameterValue] = @ProdDate Where ParameterID=1 and LineID=1;
Update Prod_ShiftInformation Set [ParameterValue] = @ProdShift Where ParameterID=2 and LineID=1;
Update Prod_ShiftInformation Set [ParameterValue] = @SessionID Where ParameterID=3 and LineID=1;
END
