-- ------------------------------------------------------------------------
-- [334/376] Stored Procedure: [dbo].[SubAssembly_RealtimeStatusDashboard]
-- Created: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:12 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE     PROCEDURE [dbo].[SubAssembly_RealtimeStatusDashboard]
(
    @SKUID INT = 0
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        DECLARE 
            @ProdShift NVARCHAR(10),
            @ProdDate DATE;

        --------------------------------------------------------------------------------
        -- 1. Read Current Running Date and Shift
        --------------------------------------------------------------------------------

        SELECT TOP (1) 
            @ProdDate = ParameterValue 
        FROM dbo.ApplicationSetting
        WHERE ParameterID = 1
          AND LineID = 1
        ORDER BY UID DESC;

        SELECT TOP (1) 
            @ProdShift = ParameterValue
        FROM dbo.ApplicationSetting 
        WHERE ParameterID = 2
          AND LineID = 1
        ORDER BY UID DESC;


        /*========================================================
          2. KITTING DATA
        ========================================================*/

        SELECT
            SUM(ISNULL(E.PlanQty, 0))           AS PlanQty,
            SUM(ISNULL(E.KitAssembly_Qty, 0))   AS InProcessQty,
            SUM(ISNULL(E.KitInspected_Qty, 0))  AS CompletedQty

        INTO #KittingData

        FROM dbo.Prod_EnginePlanExecution E

        WHERE E.ProdDate = @ProdDate
          AND E.ProdShift = @ProdShift
          AND
          (
              @SKUID = 0
              OR E.SKUID = @SKUID
          );


        /*========================================================
          3. SUB-ASSEMBLY PRODUCTION DATA
        ========================================================*/

        SELECT
            P.SubAsslyLineID,

            SUM(ISNULL(P.PlanQty, 0))       AS PlanQty,
            SUM(ISNULL(P.InProcessQty, 0))  AS InProcessQty,
            SUM(ISNULL(P.CompletedQty, 0))  AS CompletedQty,
            SUM(ISNULL(P.MarriedQty, 0))    AS MarriedQty,
            SUM(ISNULL(P.RejectedQty, 0))   AS RejectedQty

        INTO #SAData

        FROM dbo.Prod_SA_PlanExecution P

        WHERE P.ProdDate = @ProdDate
          AND P.ProdShift = @ProdShift
          AND
          (
              @SKUID = 0
              OR P.SKUID = @SKUID
          )

        GROUP BY
            P.SubAsslyLineID;


        /*========================================================
          4. GET BUFFER STOCK
        ========================================================*/

        SELECT
            B.SubAsslyLineID,
            SUM(ISNULL(B.Quantity, 0)) AS BufferQty

        INTO #BufferData

        FROM dbo.Prod_SA_Buffer B

        WHERE
        (
            @SKUID = 0
            OR B.SKUID = @SKUID
        )

        GROUP BY
            B.SubAsslyLineID;


        /*========================================================
          5. SUB-ASSEMBLY LIST
        ========================================================*/

        ;WITH SALines AS
        (
            SELECT 1 AS SubAsslyLineID
            UNION ALL SELECT 2
            UNION ALL SELECT 3
            UNION ALL SELECT 4
            UNION ALL SELECT 5
            UNION ALL SELECT 6
            UNION ALL SELECT 8
            UNION ALL SELECT 9
            UNION ALL SELECT 10
            UNION ALL SELECT 11
        ),

        StatusList AS
        (
            SELECT 'Plan' AS Status, 1 AS SortOrder
            UNION ALL
            SELECT 'Order Started', 2
            UNION ALL
            SELECT 'Order Completed', 3
            UNION ALL
            SELECT 'Married', 4
            UNION ALL
            SELECT 'NotOk', 5
            UNION ALL
            SELECT 'Buffer Stock', 6
        ),

        DashboardData AS
        (
            SELECT
                S.Status,
                S.SortOrder,
                L.SubAsslyLineID,

                CASE S.Status

                    WHEN 'Plan'
                        THEN
                            CASE
                                WHEN L.SubAsslyLineID = 1
                                    THEN ISNULL(K.PlanQty, 0)
                                ELSE ISNULL(A.PlanQty, 0)
                            END

                    WHEN 'Order Started'
                        THEN
                            CASE
                                WHEN L.SubAsslyLineID = 1
                                    THEN ISNULL(K.InProcessQty, 0)
                                ELSE ISNULL(A.InProcessQty, 0)
                            END

                    WHEN 'Order Completed'
                        THEN
                            CASE
                                WHEN L.SubAsslyLineID = 1
                                    THEN ISNULL(K.CompletedQty, 0)
                                ELSE ISNULL(A.CompletedQty, 0)
                            END

                    WHEN 'Married'
                        THEN
                            CASE
                                WHEN L.SubAsslyLineID = 1
                                    THEN 0
                                ELSE ISNULL(A.MarriedQty, 0)
                            END

                    WHEN 'NotOk'
                        THEN
                            CASE
                                WHEN L.SubAsslyLineID = 1
                                    THEN 0
                                ELSE ISNULL(A.RejectedQty, 0)
                            END

                    WHEN 'Buffer Stock'
                        THEN ISNULL(B.BufferQty, 0)

                    ELSE 0

                END AS Qty

            FROM StatusList S

            CROSS JOIN SALines L

            CROSS JOIN #KittingData K

            LEFT JOIN #SAData A
                ON A.SubAsslyLineID = L.SubAsslyLineID

            LEFT JOIN #BufferData B
                ON B.SubAsslyLineID = L.SubAsslyLineID
        ),

        /*========================================================
          6. FINAL DATA + ALTERNATE ROW NUMBER
        ========================================================*/

        FinalData AS
        (
            SELECT
                @ProdDate AS ProdDate,
                @ProdShift AS ProdShift,
                Status,

                /* Alternate row number */
                ROW_NUMBER() OVER
                (
                    ORDER BY SortOrder
                ) AS RowNo,

                MAX(CASE
                    WHEN SubAsslyLineID = 1
                    THEN Qty ELSE 0
                END) AS Kitting,

                MAX(CASE
                    WHEN SubAsslyLineID = 2
                    THEN Qty ELSE 0
                END) AS CCLH,

                MAX(CASE
                    WHEN SubAsslyLineID = 3
                    THEN Qty ELSE 0
                END) AS CCRH,

                MAX(CASE
                    WHEN SubAsslyLineID = 4
                    THEN Qty ELSE 0
                END) AS BodyBalancer,

                MAX(CASE
                    WHEN SubAsslyLineID = 6
                    THEN Qty ELSE 0
                END) AS Intake,

                MAX(CASE
                    WHEN SubAsslyLineID = 5
                    THEN Qty ELSE 0
                END) AS CylinderHead,

                MAX(CASE
                    WHEN SubAsslyLineID = 8
                    THEN Qty ELSE 0
                END) AS SHIM_MC,

                MAX(CASE
                    WHEN SubAsslyLineID = 9
                    THEN Qty ELSE 0
                END) AS GearRolling,

                MAX(CASE
                    WHEN SubAsslyLineID = 10
                    THEN Qty ELSE 0
                END) AS HubPressing,

                MAX(CASE
                    WHEN SubAsslyLineID = 11
                    THEN Qty ELSE 0
                END) AS SpringPressing

            FROM DashboardData

            GROUP BY
                Status,
                SortOrder
        )

        /*========================================================
          7. FINAL RESULT
        ========================================================*/

        SELECT
            ProdDate,
            ProdShift,
            Status,
            RowNo,

            /* 0 = first color, 1 = alternate color */
            RowNo % 2 AS AlternateRow,

            Kitting,
            CCLH,
            CCRH,
            BodyBalancer,
            Intake,
            CylinderHead,
            SHIM_MC,
            GearRolling,
            HubPressing,
            SpringPressing

        FROM FinalData

        ORDER BY
            RowNo;


        /*========================================================
          8. CLEANUP
        ========================================================*/

        DROP TABLE #KittingData;
        DROP TABLE #SAData;
        DROP TABLE #BufferData;


    END TRY

    BEGIN CATCH

        IF OBJECT_ID('tempdb..#KittingData') IS NOT NULL
            DROP TABLE #KittingData;

        IF OBJECT_ID('tempdb..#SAData') IS NOT NULL
            DROP TABLE #SAData;

        IF OBJECT_ID('tempdb..#BufferData') IS NOT NULL
            DROP TABLE #BufferData;

        EXEC dbo.RethrowError;

    END CATCH

END
GO

-- ------------------------------------------------------------------------
-- [335/376] Stored Procedure: [dbo].[SubAssembly-RealtimeStatusDashboard]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE     PROCEDURE [dbo].[SubAssembly-RealtimeStatusDashboard]
(
    @SKUID INT = 0
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        DECLARE @ProdDate DATE;
        DECLARE @ProdShift NVARCHAR(50);

        /*========================================================
          1. GET LATEST PRODUCTION DATE AND SHIFT
        ========================================================*/

        SELECT
            @ProdDate =
                MAX
                (
                    CASE
                        WHEN ParameterName = 'ProdDate'
                        THEN TRY_CONVERT(DATE, ParameterValue)
                    END
                ),

            @ProdShift =
                MAX
                (
                    CASE
                        WHEN ParameterName = 'ProdShift'
                        THEN ParameterValue
                    END
                )
        FROM
        (
            SELECT
                ParameterName,
                ParameterValue,

                ROW_NUMBER() OVER
                (
                    PARTITION BY ParameterName
                    ORDER BY UID DESC
                ) AS RN

            FROM dbo.ApplicationSetting

            WHERE ParameterName IN
            (
                'ProdDate',
                'ProdShift'
            )

        ) AS LatestValues

        WHERE RN = 1;


        /*========================================================
          2. GET SUB-ASSEMBLY PRODUCTION DATA
        ========================================================*/

        SELECT
            P.SubAsslyLineID,

            SUM(ISNULL(P.PlanQty, 0))      AS PlanQty,
            SUM(ISNULL(P.InProcessQty, 0)) AS InProcessQty,
            SUM(ISNULL(P.CompletedQty, 0)) AS CompletedQty,
            SUM(ISNULL(P.MarriedQty, 0))   AS MarriedQty,
            SUM(ISNULL(P.RejectedQty, 0))  AS RejectedQty

        INTO #SAData

        FROM dbo.Prod_SA_PlanExecution P

        WHERE P.ProdDate = @ProdDate

          AND P.ProdShift = @ProdShift

          AND
          (
              @SKUID = 0
              OR P.SKUID = @SKUID
          )

        GROUP BY
            P.SubAsslyLineID;


        /*========================================================
          3. GET BUFFER STOCK
        ========================================================*/

        SELECT
            B.SubAsslyLineID,

            SUM(ISNULL(B.Quantity, 0)) AS BufferQty

        INTO #BufferData

        FROM dbo.Prod_SA_Buffer B

        WHERE
            (
                @SKUID = 0
                OR B.SKUID = @SKUID
            )

        GROUP BY
            B.SubAsslyLineID;


        /*========================================================
          4. SUB-ASSEMBLY LIST
        ========================================================*/

        ;WITH SALines AS
        (
            SELECT 1 AS SubAsslyLineID
            UNION ALL SELECT 2
            UNION ALL SELECT 3
            UNION ALL SELECT 4
            UNION ALL SELECT 5
            UNION ALL SELECT 6
            UNION ALL SELECT 8
            UNION ALL SELECT 9
            UNION ALL SELECT 10
            UNION ALL SELECT 11
        ),

        StatusList AS
        (
            SELECT 'Plan' AS Status, 1 AS SortOrder
            UNION ALL
            SELECT 'Order Started', 2
            UNION ALL
            SELECT 'Order Completed', 3
            UNION ALL
            SELECT 'Married', 4
            UNION ALL
            SELECT 'NotOk', 5
            UNION ALL
            SELECT 'Buffer Stock', 6
        ),

        DashboardData AS
        (
            SELECT
                S.Status,
                S.SortOrder,
                L.SubAsslyLineID,

                CASE S.Status

                    WHEN 'Plan'
                        THEN ISNULL(A.PlanQty, 0)

                    WHEN 'Order Started'
                        THEN ISNULL(A.InProcessQty, 0)

                    WHEN 'Order Completed'
                        THEN ISNULL(A.CompletedQty, 0)

                    WHEN 'Married'
                        THEN ISNULL(A.MarriedQty, 0)

                    WHEN 'NotOk'
                        THEN ISNULL(A.RejectedQty, 0)

                    WHEN 'Buffer Stock'
                        THEN ISNULL(B.BufferQty, 0)

                    ELSE 0

                END AS Qty

            FROM StatusList S

            CROSS JOIN SALines L

            LEFT JOIN #SAData A
                ON A.SubAsslyLineID = L.SubAsslyLineID

            LEFT JOIN #BufferData B
                ON B.SubAsslyLineID = L.SubAsslyLineID
        )


        /*========================================================
          5. FINAL DASHBOARD RESULT
        ========================================================*/

        SELECT

            Status,

            MAX(CASE
                WHEN SubAsslyLineID = 1
                THEN Qty ELSE 0
            END) AS Kitting,

            MAX(CASE
                WHEN SubAsslyLineID = 2
                THEN Qty ELSE 0
            END) AS CCLH,

            MAX(CASE
                WHEN SubAsslyLineID = 3
                THEN Qty ELSE 0
            END) AS CCRH,

            MAX(CASE
                WHEN SubAsslyLineID = 4
                THEN Qty ELSE 0
            END) AS BodyBalancer,

            MAX(CASE
                WHEN SubAsslyLineID = 6
                THEN Qty ELSE 0
            END) AS Intake,

            MAX(CASE
                WHEN SubAsslyLineID = 5
                THEN Qty ELSE 0
            END) AS CylinderHead,

            MAX(CASE
                WHEN SubAsslyLineID = 8
                THEN Qty ELSE 0
            END) AS SHIM_MC,

            MAX(CASE
                WHEN SubAsslyLineID = 9
                THEN Qty ELSE 0
            END) AS GearRolling,

            MAX(CASE
                WHEN SubAsslyLineID = 10
                THEN Qty ELSE 0
            END) AS HubPressing,

            MAX(CASE
                WHEN SubAsslyLineID = 11
                THEN Qty ELSE 0
            END) AS SpringPressing

        FROM DashboardData

        GROUP BY
            Status,
            SortOrder

        ORDER BY
            SortOrder;


        /*========================================================
          6. CLEANUP
        ========================================================*/

        DROP TABLE #SAData;
        DROP TABLE #BufferData;

    END TRY

    BEGIN CATCH

        IF OBJECT_ID('tempdb..#SAData') IS NOT NULL
            DROP TABLE #SAData;

        IF OBJECT_ID('tempdb..#BufferData') IS NOT NULL
            DROP TABLE #BufferData;

        EXEC dbo.RethrowError;

    END CATCH

END
