-- ------------------------------------------------------------------------
-- [336/376] Stored Procedure: [dbo].[Tab_Q_ApproveIPQCAudit]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
create PROCEDURE [dbo].[Tab_Q_ApproveIPQCAudit]
(
    @AuditListID INT,
    @AuditInstanceID BIGINT,
    @ApprovedBy NVARCHAR(100),
    @ApprovedByRemark NVARCHAR(500) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        BEGIN TRANSACTION;


        -----------------------------------------
        -- Validation : Audit must exist
        -- Status 3 = Waiting For Approval - OK
        -- Status 4 = Waiting For Approval - NOK
        -----------------------------------------
        IF NOT EXISTS
        (
            SELECT 1
            FROM QA_Execute_IPQC_AuditList_History
            WHERE AuditListID = @AuditListID
              AND AuditInstanceID = @AuditInstanceID
              AND Status IN (3, 4)
        )
        BEGIN
            ROLLBACK TRANSACTION;

            SELECT
                0 AS Success,
                'IPQC Audit not found or audit is not waiting for approval.' AS Message;

            RETURN;
        END;


        -----------------------------------------
        -- Validation : All raised tickets
        -- must be closed before approval
        -----------------------------------------
        IF EXISTS
        (
            SELECT 1
            FROM QA_Execute_IPQC_AuditPoint_History H
            INNER JOIN TicketManagement T
                ON H.TicketID = T.TicketID
            WHERE H.AuditListID = @AuditListID
              AND H.AuditInstanceID = @AuditInstanceID
              AND H.TicketID IS NOT NULL
              AND T.TicketStatus = 1
        )
        BEGIN
            ROLLBACK TRANSACTION;

            SELECT
                0 AS Success,
                'One or more tickets are still open. Please close all tickets before approving the audit.' AS Message;

            RETURN;
        END;


        -----------------------------------------
        -- Approve IPQC Audit
        --
        -- Status 3 = Waiting For Approval - OK
        -- Status 4 = Waiting For Approval - NOK
        --
        -- Status 6 = Approved - OK
        -- Status 7 = Approved - NOK
        -----------------------------------------
        UPDATE QA_Execute_IPQC_AuditList_History
        SET
            Status =
                CASE
                    WHEN Status = 3 THEN 6
                    WHEN Status = 4 THEN 7
                    ELSE Status
                END,
            ApprovedBy = @ApprovedBy,
            ApprovedTime = GETDATE(),
            ApprovedByRemark = @ApprovedByRemark
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID
          AND Status IN (3, 4);


        COMMIT TRANSACTION;


        -----------------------------------------
        -- Success Response
        -----------------------------------------
        SELECT
            1 AS Success,
            @AuditListID AS AuditListID,
            @AuditInstanceID AS AuditInstanceID,
            'IPQC Audit Approved Successfully' AS Message;


    END TRY

    BEGIN CATCH

        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        SELECT
            0 AS Success,
            ERROR_MESSAGE() AS Message;

    END CATCH
END
GO

-- ------------------------------------------------------------------------
-- [337/376] Stored Procedure: [dbo].[Tab_Q_FQC_Approve_AuditList]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE   PROCEDURE [dbo].[Tab_Q_FQC_Approve_AuditList]
(
    @AuditListID INT,
    @AuditInstanceID BIGINT,
    @ApprovedBy NVARCHAR(100),
    @ApprovedByRemark NVARCHAR(500) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        BEGIN TRANSACTION;

        DECLARE @DocumentID INT;

        -----------------------------------------
        -- Get DocumentID
        -----------------------------------------
        SELECT TOP 1
            @DocumentID = A.DocumentID
        FROM QA_Execute_FQC_AuditList_History H
        INNER JOIN Config_AuditList A
            ON H.AuditListID = A.AuditListID
        WHERE H.AuditListID = @AuditListID
          AND H.AuditInstanceID = @AuditInstanceID;


        -----------------------------------------
        -- Validate Audit Exists
        -----------------------------------------
        IF @DocumentID IS NULL
        BEGIN
            ROLLBACK TRANSACTION;

            SELECT
                0 AS Success,
                'FQC Audit not found for the given AuditListID and AuditInstanceID.' AS Message;

            RETURN;
        END;


        -----------------------------------------
        -- Validation : All raised tickets
        -- must be closed
        -----------------------------------------

        -- FQC Engine Inbuilt
        IF @DocumentID IN (10, 12, 13)
        BEGIN

            IF EXISTS
            (
                SELECT 1
                FROM QA_Execute_FQC_EngInbuiltAuditPoint_History H
                INNER JOIN TicketManagement T
                    ON H.TicketID = T.TicketID
                WHERE H.AuditListID = @AuditListID
                  AND H.AuditInstanceID = @AuditInstanceID
                  AND H.TicketID IS NOT NULL
                  AND T.TicketStatus = 1
            )
            BEGIN
                ROLLBACK TRANSACTION;

                SELECT
                    0 AS Success,
                    'One or more tickets are still open. Please close all tickets before approving the audit.' AS Message;

                RETURN;
            END;

        END;


        -- FQC Engine Performance
        ELSE IF @DocumentID = 11
        BEGIN

            IF EXISTS
            (
                SELECT 1
                FROM QA_Execute_FQC_EngPerformanceAuditPoint_History H
                INNER JOIN TicketManagement T
                    ON H.TicketID = T.TicketID
                WHERE H.AuditListID = @AuditListID
                  AND H.AuditInstanceID = @AuditInstanceID
                  AND H.TicketID IS NOT NULL
                  AND T.TicketStatus = 1
            )
            BEGIN
                ROLLBACK TRANSACTION;

                SELECT
                    0 AS Success,
                    'One or more tickets are still open. Please close all tickets before approving the audit.' AS Message;

                RETURN;
            END;

        END;


        -----------------------------------------
        -- Update FQC Audit History
        -----------------------------------------
        UPDATE QA_Execute_FQC_AuditList_History
        SET
            Status = 2,
            ApprovedBy = @ApprovedBy,
            ApprovedTime = GETDATE(),
            ApprovedByRemark = @ApprovedByRemark
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID
          AND Status = 1;


        -----------------------------------------
        -- Check whether audit was actually
        -- pending for approval
        -----------------------------------------
        IF @@ROWCOUNT = 0
        BEGIN
            ROLLBACK TRANSACTION;

            SELECT
                0 AS Success,
                'FQC Audit is not in pending approval status.' AS Message;

            RETURN;
        END;


        -----------------------------------------
        -- Update Audit Schedule
        -----------------------------------------
        UPDATE Config_AuditSchedule
        SET
            Status = 4,
            Notification = 1
        WHERE DocumentID = @DocumentID
          AND Status = 3;


        -----------------------------------------
        -- Update Audit Monitoring
        -----------------------------------------
        UPDATE QA_AuditMonitoring
        SET
            Status = 4,
            Notification = 1
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID
          AND Status = 3;


        -----------------------------------------
        -- Commit Transaction
        -----------------------------------------
        COMMIT TRANSACTION;


        -----------------------------------------
        -- Success Response
        -----------------------------------------
        SELECT
            1 AS Success,
            'FQC Audit Approved Successfully' AS Message;

    END TRY

    BEGIN CATCH

        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        SELECT
            0 AS Success,
            ERROR_MESSAGE() AS Message;

    END CATCH
END
GO

-- ------------------------------------------------------------------------
-- [338/376] Stored Procedure: [dbo].[Tab_Q_FQC_EngInbuiltAuditPoint_Submit]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE   PROCEDURE [dbo].[Tab_Q_FQC_EngInbuiltAuditPoint_Submit]
(
    @AuditListID INT,
    @AuditInstanceID BIGINT,
    @ExecutedByRemark NVARCHAR(MAX) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY

        BEGIN TRANSACTION;

        DECLARE @PendingCount INT = 0;
        DECLARE @DocumentID INT;

        --------------------------------------------------------
        -- Get Document ID
        --------------------------------------------------------
        SELECT
            @DocumentID = DocumentID
        FROM Config_AuditList
        WHERE AuditListID = @AuditListID;

        IF @DocumentID IS NULL
        BEGIN
            RAISERROR('Audit not found.', 16, 1);
            RETURN;
        END

        --------------------------------------------------------
        -- Validate Pending Checkpoints
        --------------------------------------------------------
        SELECT
            @PendingCount = COUNT(*)
        FROM QA_Execute_FQC_EngInbuiltAuditPoint
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID
          AND ISNULL(Result, 0) = 0;

        IF @PendingCount > 0
        BEGIN
            RAISERROR(
                'Please complete all FQC Engine Inbuilt checkpoints before submit.',
                16,
                1
            );
            RETURN;
        END

        --------------------------------------------------------
        -- Update FQC Audit Header
        --------------------------------------------------------
        UPDATE QA_Execute_FQC_AuditList
        SET
           
            ExecutedEndTime = GETDATE(),
            ExecutedByRemark = @ExecutedByRemark
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID;

        --------------------------------------------------------
        -- Update Audit Schedule
        --------------------------------------------------------
        UPDATE Config_AuditSchedule
        SET
            Status = 3
        WHERE DocumentID = @DocumentID
          AND AuditInstanceID = @AuditInstanceID
          AND Status = 2;

        --------------------------------------------------------
        -- Update Audit Monitoring
        --------------------------------------------------------
        UPDATE QA_AuditMonitoring
        SET
            Status = 3,
            ActualEndDateTime = GETDATE()
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID
          AND Status = 2;

        --------------------------------------------------------
        -- Move FQC Audit Header to History
        --------------------------------------------------------
        INSERT INTO QA_Execute_FQC_AuditList_History
        (
            AuditListID,
            Status,
            ProdDate,
            ProdShift,
            AuditInstanceID,
            SampleLevel,
            SampleSize,
            NokSample,
            ExecutedStartTime,
            ExecutedBy,
            ExecutedEndTime,
            ExecutedByRemark,
            ApprovedBy,
            ApprovedTime,
            ApprovedByRemark,
            ReviewBy,
            ReviewTime,
            ReviewByRemark,
            Revision
        )
        SELECT
            AuditListID,
            1,
            ProdDate,
            ProdShift,
            AuditInstanceID,
            SampleLevel,
            CASE
                WHEN SampleLevel = 1 THEN 5
                WHEN SampleLevel = 2 THEN 25
                WHEN SampleLevel = 3 THEN 50
                ELSE NULL
            END,
            NokSample,
            ExecutedStartTime,
            ExecutedBy,
            ExecutedEndTime,
            ExecutedByRemark,
            ApprovedBy,
            ApprovedTime,
            ApprovedByRemark,
            ReviewBy,
            ReviewTime,
            ReviewByRemark,
            Revision
        FROM QA_Execute_FQC_AuditList
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID;

        --------------------------------------------------------
        -- Move Inbuilt Checkpoints to History
        --------------------------------------------------------
        INSERT INTO QA_Execute_FQC_EngInbuiltAuditPoint_History
        (
            AuditPointID,
            AuditListID,
            SampleLevel,
            SampleNo,
            EngineNo,
            ObservationValue,
            Result,
            Remark,
            [Timestamp],
            AuditInstanceID,
            Revision,
            TicketID
        )
        SELECT
            AuditPointID,
            AuditListID,
            SampleLevel,
            SampleNo,
            EngineNo,
            ObservationValue,
            Result,
            Remark,
            [Timestamp],
            AuditInstanceID,
            Revision,
            TicketID
        FROM QA_Execute_FQC_EngInbuiltAuditPoint
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID;

        --------------------------------------------------------
        -- Delete Inbuilt Checkpoints from Execution
        --------------------------------------------------------
        DELETE
        FROM QA_Execute_FQC_EngInbuiltAuditPoint
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID;

        --------------------------------------------------------
        -- Delete FQC Audit Header
        --------------------------------------------------------
        DELETE
        FROM QA_Execute_FQC_AuditList
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID;

        --------------------------------------------------------
        -- Move Document to History
        --------------------------------------------------------
        INSERT INTO QA_Execute_DocumentList_History
        (
            DocumentID,
            DocumentNo,
            DocumentName,
            AuditGroup,
            Revision,
            AuditInstanceID
        )
        SELECT
            DocumentID,
            DocumentNo,
            DocumentName,
            AuditGroup,
            Revision,
            AuditInstanceID
        FROM QA_Execute_DocumentList
        WHERE AuditInstanceID = @AuditInstanceID;

        --------------------------------------------------------
        -- Delete Document
        --------------------------------------------------------
        DELETE
        FROM QA_Execute_DocumentList
        WHERE AuditInstanceID = @AuditInstanceID;

        --------------------------------------------------------
        -- Commit
        --------------------------------------------------------
        COMMIT TRANSACTION;

        SELECT
            1 AS Success,
            @AuditListID AS AuditListID,
            @AuditInstanceID AS AuditInstanceID,
            'FQC Engine Inbuilt Audit Submitted Successfully' AS Message;

    END TRY

    BEGIN CATCH

        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        SELECT
            0 AS Success,
            ERROR_MESSAGE() AS Message;

    END CATCH
END
GO

