        INSERT INTO QA_Execute_FQC_AuditList_History
        (
            AuditListID,
            Status,
            ProdDate,
            ProdShift,
            AuditInstanceID,
            SampleLevel,
            SampleSize,
            NokSample,
            ExecutedStartTime,
            ExecutedBy,
            ExecutedEndTime,
            ExecutedByRemark,
            ApprovedBy,
            ApprovedTime,
