-- ------------------------------------------------------------------------
-- [340/376] Stored Procedure: [dbo].[Tab_Q_FQC_GetApprovedFQCAuditList]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[Tab_Q_FQC_GetApprovedFQCAuditList]
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        H.UID,

        H.AuditListID,
        AL.AuditListName,

        MF.ModelFamilyID,
        MF.ModelFamilyName,

        M.ModelID,
        M.ModelName,

        SK.SKUID,
        SK.SKUName,

        H.Status,

        CASE H.Status
            WHEN 1 THEN 'Waiting for Approval'
            WHEN 2 THEN 'Approved'
            WHEN 3 THEN 'Rejected'
            ELSE 'Unknown'
        END AS StatusName,

        H.ProdDate,
        H.ProdShift,

        H.AuditInstanceID,

        H.SampleLevel,
        H.SampleSize,
        H.NokSample,

        H.ExecutedStartTime,
        H.ExecutedBy,

        H.ExecutedEndTime,
        H.ExecutedByRemark,

        H.ApprovedBy,
        H.ApprovedTime,
        H.ApprovedByRemark,

        H.ReviewBy,
        H.ReviewTime,
        H.ReviewByRemark,

        H.Revision,

        SCH.FrequencyType,

        CASE SCH.FrequencyType
            WHEN 1 THEN 'Day'
            WHEN 2 THEN 'Count'
            WHEN 3 THEN 'Hourly'
            ELSE ''
        END AS FrequencyTypeName,

        SCH.FrequencyValue,

        SCH.StartDateTime,
        SCH.NextDueDate

    FROM QA_Execute_FQC_AuditList_History H

    INNER JOIN Config_AuditList AL
        ON H.AuditListID = AL.AuditListID

    LEFT JOIN Config_ModelFamily MF
        ON AL.ModelFamilyID = MF.ModelFamilyID

    LEFT JOIN Config_Model M
        ON AL.ModelID = M.ModelID

    LEFT JOIN Config_SKU SK
        ON AL.SKUID = SK.SKUID

    LEFT JOIN Config_AuditSchedule SCH
        ON SCH.DocumentID = AL.DocumentID
       AND SCH.AuditInstanceID = H.AuditInstanceID

    WHERE H.Status = 2

    ORDER BY H.ExecutedEndTime DESC;

END
GO

-- ------------------------------------------------------------------------
-- [341/376] Stored Procedure: [dbo].[Tab_Q_FQC_GetEngInbuiltCheckpointDetails_ForExecute]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE   PROCEDURE [dbo].[Tab_Q_FQC_GetEngInbuiltCheckpointDetails_ForExecute]
(
    @AuditListID INT,
    @SampleLevel INT = NULL,
    @SampleNo INT = NULL,
    @AuditInstanceID BIGINT = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        E.UID,
        E.AuditPointID,
        E.AuditListID,
        E.SampleLevel,
        E.SampleNo,
        E.EngineNo,
        E.ObservationValue,
        E.Result,
        E.Remark,
        E.[Timestamp],
        E.AuditInstanceID,
        E.Revision,
        E.TicketID,

        /* Configuration Details */
        C.UID AS ConfigUID,
        C.AuditPointId AS ConfigAuditPointID,
        C.ModelID,
        C.SKUID,
        C.Category,
        C.AuditPointName,
        C.AuditPointProcess,
        C.LowerLimit,
        C.UpperLimit,
        C.CheckingMethod,
        C.Status AS ConfigStatus,
        C.Revision AS ConfigRevision,

        /* Model / SKU Details */
        M.ModelName,
        S.SKUName

    FROM dbo.QA_Execute_FQC_EngInbuiltAuditPoint E

    LEFT JOIN dbo.Config_FQC_EngInbuiltAuditPoint C
        ON E.AuditListID = C.AuditListID
        AND E.AuditPointID = C.UID

    LEFT JOIN dbo.Config_Model M
        ON C.ModelID = M.ModelID

    LEFT JOIN dbo.Config_SKU S
        ON C.SKUID = S.SKUID

    WHERE E.AuditListID = @AuditListID

      AND
      (
          @SampleLevel IS NULL
          OR E.SampleLevel = @SampleLevel
      )

      AND
      (
          @SampleNo IS NULL
          OR E.SampleNo = @SampleNo
      )

      AND
      (
          @AuditInstanceID IS NULL
          OR E.AuditInstanceID = @AuditInstanceID
      )

    ORDER BY
        E.AuditPointID,
        E.SampleLevel,
        E.SampleNo;

END
GO

-- ------------------------------------------------------------------------
-- [342/376] Stored Procedure: [dbo].[Tab_Q_FQC_GetEngPerformanceCheckpointDetails_ForExecute]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[Tab_Q_FQC_GetEngPerformanceCheckpointDetails_ForExecute]
(
    @AuditListID INT,
    @SampleLevel INT = NULL,
