        ----------------------------------------------------
        -- Execution Identification
        ----------------------------------------------------
        E.UID,
        E.AuditPointID,
        E.AuditListID,
        E.SampleLevel,
        E.SampleNo,
        E.EngineNo,

        ----------------------------------------------------
        -- Power Details
        ----------------------------------------------------
        E.PowerRPM,
