        E.ULPowerValue,

        E.ObservationPowerRPMValue,
        E.ObservationPowerValue,
        E.ObservationPowerValueResult,

        CASE E.ObservationPowerValueResult
            WHEN 1 THEN 'OK'
            WHEN 2 THEN 'NOK'
            ELSE 'Unknown'
        END AS ObservationPowerValueResultName,

        ----------------------------------------------------
        -- Torque Details
        ----------------------------------------------------
        E.TorqueRPM,
        E.LLTorqueValue,
        E.ULTorqueValue,

        E.ObservationTorqueRPMValue,
        E.ObservationTorqueValue,
        E.ObservationTorqueValueResult,

        CASE E.ObservationTorqueValueResult
            WHEN 1 THEN 'OK'
            WHEN 2 THEN 'NOK'
            ELSE 'Unknown'
        END AS ObservationTorqueValueResultName,

        ----------------------------------------------------
        -- Common Remark
        ----------------------------------------------------
        E.ObservationRemark,

        ----------------------------------------------------
        -- Execution Details
        ----------------------------------------------------
        E.[Timestamp],
        E.AuditInstanceID,
        E.Revision,
        E.TicketID

        ----------------------------------------------------
        -- Configuration Details
        ----------------------------------------------------
        --C.UID AS ConfigUID,
        --C.AuditPointId AS ConfigAuditPointID,
        --C.LLPowerValue AS ConfigLLPowerValue,
        --C.ULPowerValue AS ConfigULPowerValue,
        --C.PowerRPM AS ConfigPowerRPM,
        --C.LLTorqueValue AS ConfigLLTorqueValue,
        --C.ULTorqueValue AS ConfigULTorqueValue,
        --C.TorqueRPM AS ConfigTorqueRPM,
        --C.Status AS ConfigStatus,
        --C.Revision AS ConfigRevision

    FROM dbo.QA_Execute_FQC_EngPerformanceAuditPoint E

    LEFT JOIN dbo.Config_FQC_EngPerformanceAuditPoint C
        ON E.AuditListID = C.AuditListID
        AND E.AuditPointID = C.AuditPointId

    WHERE
        E.AuditListID = @AuditListID

        AND
        (
            @SampleLevel IS NULL
            OR E.SampleLevel = @SampleLevel
        )

        AND
        (
            @SampleNo IS NULL
            OR E.SampleNo = @SampleNo
        )

        AND
        (
            @AuditInstanceID IS NULL
            OR E.AuditInstanceID = @AuditInstanceID
        )

    ORDER BY
        E.AuditPointID,
        E.SampleLevel,
        E.SampleNo;

END
GO

-- ------------------------------------------------------------------------
-- [343/376] Stored Procedure: [dbo].[Tab_Q_FQC_GetExecuted_EngInbuilt_CheckpointDetails]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
