-- ------------------------------------------------------------------------
-- [345/376] Stored Procedure: [dbo].[Tab_Q_FQC_GetScheduledAuditList]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[Tab_Q_FQC_GetScheduledAuditList]
(
    @Group NVARCHAR(100)
)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        ---------------------------------------------------------
        -- Schedule Table Fields
        ---------------------------------------------------------
        SCH.UID,
        SCH.LineID,
        SCH.DocumentID,
        SCH.AuditInstanceID,
        SCH.StartDateTime,
        SCH.NextDueDate,

        SCH.FrequencyType,

        CASE SCH.FrequencyType
            WHEN 1 THEN 'Day'
            WHEN 2 THEN 'Count'
            WHEN 3 THEN 'Hourly'
            ELSE 'Unknown'
        END AS FrequencyTypeName,

        SCH.FrequencyValue,
        SCH.Notification,

        CASE SCH.Notification
            WHEN 1 THEN 'Alert'
            WHEN 2 THEN 'Warning'
            WHEN 3 THEN 'Alarm'
            WHEN 4 THEN 'Critical'
            ELSE 'Unknown'
        END AS NotificationName,

        SCH.Status,

        CASE SCH.Status
            WHEN 1 THEN 'Plan'
            WHEN 2 THEN 'In Process'
			WHEN 3 THEN 'Waiting For Approval'
            ELSE 'Unknown'
        END AS StatusName,

        ---------------------------------------------------------
        -- Audit List Details
        ---------------------------------------------------------
        AL.AuditListID,
        AL.AuditListName,
        AL.ModelFamilyID,
        AL.ModelID,
        AL.SKUID,
        AL.PartID,

        ---------------------------------------------------------
        -- Document Details
        ---------------------------------------------------------
        D.DocumentNo,
        D.DocumentName,
        D.[Group],
        D.Revision,

        ---------------------------------------------------------
        -- Master Names
        ---------------------------------------------------------
        MF.ModelFamilyName,
        M.ModelName,
        SKU.SKUName,

        ---------------------------------------------------------
        -- Audit Monitoring Details
        ---------------------------------------------------------
        AM.UID AS MonitoringUID,
        AM.StartDateTime AS MonitoringStartDateTime,
        AM.EndDateTime AS MonitoringEndDateTime,
        AM.ActualStartDateTime,
        AM.ActualEndDateTime,
        AM.Notification AS MonitoringNotification,
        AM.Status AS MonitoringStatus,

        CASE AM.Status
            WHEN 1 THEN 'Plan'
            WHEN 2 THEN 'In Process'
            ELSE 'Unknown'
        END AS MonitoringStatusName,

        CASE AM.Notification
            WHEN 1 THEN 'Alert'
            WHEN 2 THEN 'Warning'
            WHEN 3 THEN 'Alarm'
            WHEN 4 THEN 'Critical'
            ELSE 'Unknown'
        END AS MonitoringNotificationName

    FROM Config_AuditSchedule SCH

    ---------------------------------------------------------
    -- Document
    ---------------------------------------------------------
    INNER JOIN Config_QADocumentList D
        ON SCH.DocumentID = D.DocumentID

    ---------------------------------------------------------
    -- Audit List
    ---------------------------------------------------------
    LEFT JOIN Config_AuditList AL
        ON SCH.DocumentID = AL.DocumentID

    ---------------------------------------------------------
    -- Model Family
    ---------------------------------------------------------
    LEFT JOIN Config_ModelFamily MF
        ON AL.ModelFamilyID = MF.ModelFamilyID

    ---------------------------------------------------------
    -- Model
    ---------------------------------------------------------
    LEFT JOIN Config_Model M
        ON AL.ModelID = M.ModelID

    ---------------------------------------------------------
    -- SKU
    ---------------------------------------------------------
    LEFT JOIN Config_SKU SKU
        ON AL.SKUID = SKU.SKUID

    ---------------------------------------------------------
    -- Audit Monitoring
    ---------------------------------------------------------
    LEFT JOIN QA_AuditMonitoring AM
        ON AM.AuditListID = AL.AuditListID
       AND AM.AuditInstanceID = SCH.AuditInstanceID

    ---------------------------------------------------------
    -- Group Filter
    ---------------------------------------------------------
    WHERE D.[Group] = @Group

      ---------------------------------------------------------
      -- Active Schedule
      ---------------------------------------------------------
      AND SCH.Status IN (1, 2)

      ---------------------------------------------------------
      -- Active Notification
      ---------------------------------------------------------
      AND SCH.Notification IN (2, 3, 4)

      ---------------------------------------------------------
      -- Active Audit Monitoring
      ---------------------------------------------------------
      AND EXISTS
      (
          SELECT 1
          FROM QA_AuditMonitoring AM2
          WHERE AM2.AuditListID = AL.AuditListID
            AND AM2.AuditInstanceID = SCH.AuditInstanceID
            AND AM2.Status IN (1, 2)
            AND AM2.Notification IN (2, 3, 4)
      )

    ORDER BY
        SCH.StartDateTime DESC,
        SCH.DocumentID,
        AL.AuditListID;


    ---------------------------------------------------------
    -- No Data
    ---------------------------------------------------------
    IF @@ROWCOUNT = 0
    BEGIN
        SELECT
            0 AS Status,
            'No Active Schedule Found For The Given Group' AS Message;
    END

END
GO

-- ------------------------------------------------------------------------
-- [346/376] Stored Procedure: [dbo].[Tab_Q_FQC_GetWaitingForApprovalFQCAuditList]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[Tab_Q_FQC_GetWaitingForApprovalFQCAuditList]
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        ---------------------------------------------------------
        -- History
        ---------------------------------------------------------
        H.UID,

        H.AuditListID,
        AL.AuditListName,

        ---------------------------------------------------------
        -- Document Details
        ---------------------------------------------------------
        D.DocumentID,
        D.DocumentNo,
        D.DocumentName,
        D.[Group],
        D.Revision AS DocumentRevision,

        ---------------------------------------------------------
        -- Model Family
        ---------------------------------------------------------
        MF.ModelFamilyID,
        MF.ModelFamilyName,

        ---------------------------------------------------------
        -- Model
        ---------------------------------------------------------
        M.ModelID,
        M.ModelName,

        ---------------------------------------------------------
        -- SKU
        ---------------------------------------------------------
        SK.SKUID,
        SK.SKUName,

        ---------------------------------------------------------
        -- Audit Status
        ---------------------------------------------------------
        H.Status,

        CASE H.Status
            WHEN 1 THEN 'Waiting for Approval'
            WHEN 2 THEN 'Approved'
            WHEN 3 THEN 'Rejected'
            ELSE 'Unknown'
        END AS StatusName,

        ---------------------------------------------------------
        -- Production Details
        ---------------------------------------------------------
        H.ProdDate,
        H.ProdShift,

        H.AuditInstanceID,

        ---------------------------------------------------------
        -- Sample Details
        ---------------------------------------------------------
        H.SampleLevel,
        H.SampleSize,
        H.NokSample,

        ---------------------------------------------------------
        -- Execution Details
        ---------------------------------------------------------
        H.ExecutedStartTime,
        H.ExecutedBy,

        H.ExecutedEndTime,
        H.ExecutedByRemark,

        ---------------------------------------------------------
        -- Approval Details
        ---------------------------------------------------------
        H.ApprovedBy,
        H.ApprovedTime,
        H.ApprovedByRemark,

        ---------------------------------------------------------
        -- Review Details
        ---------------------------------------------------------
        H.ReviewBy,
        H.ReviewTime,
        H.ReviewByRemark,

        H.Revision,

        ---------------------------------------------------------
        -- Schedule Details
        ---------------------------------------------------------
        SCH.FrequencyType,

        CASE SCH.FrequencyType
            WHEN 1 THEN 'Day'
            WHEN 2 THEN 'Count'
            WHEN 3 THEN 'Hourly'
            ELSE ''
        END AS FrequencyTypeName,

        SCH.FrequencyValue,
        SCH.StartDateTime,
        SCH.NextDueDate

    FROM QA_Execute_FQC_AuditList_History H

    ---------------------------------------------------------
    -- Audit List
    ---------------------------------------------------------
    INNER JOIN Config_AuditList AL
        ON H.AuditListID = AL.AuditListID

    ---------------------------------------------------------
    -- Document
    ---------------------------------------------------------
    INNER JOIN Config_QADocumentList D
        ON AL.DocumentID = D.DocumentID

    ---------------------------------------------------------
    -- Model Family
    ---------------------------------------------------------
    LEFT JOIN Config_ModelFamily MF
        ON AL.ModelFamilyID = MF.ModelFamilyID

    ---------------------------------------------------------
    -- Model
    ---------------------------------------------------------
    LEFT JOIN Config_Model M
        ON AL.ModelID = M.ModelID

    ---------------------------------------------------------
    -- SKU
    ---------------------------------------------------------
    LEFT JOIN Config_SKU SK
        ON AL.SKUID = SK.SKUID

    ---------------------------------------------------------
    -- Schedule
    ---------------------------------------------------------
    LEFT JOIN Config_AuditSchedule SCH
        ON SCH.DocumentID = AL.DocumentID
       AND SCH.AuditInstanceID = H.AuditInstanceID

    ---------------------------------------------------------
    -- ONLY WAITING FOR APPROVAL
    ---------------------------------------------------------
    WHERE H.Status = 1

    ORDER BY H.ExecutedEndTime DESC;

END
GO

-- ------------------------------------------------------------------------
-- [347/376] Stored Procedure: [dbo].[Tab_Q_FQC_GetWaitingForApprovalFQCAuditPoints]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[Tab_Q_FQC_GetWaitingForApprovalFQCAuditPoints]
(
    @DocumentID INT,
    @AuditListID INT,
    @AuditInstanceID BIGINT
)
AS
BEGIN
    SET NOCOUNT ON;
 
 
    ---------------------------------------------------------
    -- FQC Engine Inbuilt
    -- DocumentID = 10, 12, 13
    -- Data from History Table
    ---------------------------------------------------------
    IF @DocumentID IN (9 ,11, 12)
    BEGIN
 
        SELECT
 
            C.Category,
            C.AuditPointName,
            C.AuditPointProcess,
            C.LowerLimit,
            C.UpperLimit,
            C.CheckingMethod,
 
            H.SampleLevel,
            H.SampleNo,
            H.EngineNo,
 
            H.ObservationValue,
 
            H.Result,
 
            CASE H.Result
                WHEN 1 THEN 'OK'
                WHEN 2 THEN 'NOK'
                ELSE ''
            END AS ResultName,
 
            H.Remark,
            H.Timestamp,
 
            H.AuditInstanceID,
            H.Revision,
 
            H.TicketID,
 
            TM.TicketStatus,
 
            CASE TM.TicketStatus
                WHEN 1 THEN 'Open'
                WHEN 2 THEN 'Close'
                ELSE ''
            END AS TicketStatusName,
 
            -------------------------------------------------
            -- Audit List
            -------------------------------------------------
            AL.AuditListName
 
        FROM QA_Execute_FQC_EngInbuiltAuditPoint_History H
 
        INNER JOIN Config_FQC_EngInbuiltAuditPoint C
            ON H.AuditPointID = C.UID
 
        INNER JOIN Config_AuditList AL
            ON H.AuditListID = AL.AuditListID
 
        OUTER APPLY
        (
            SELECT TOP (1)
                TM.TicketStatus
            FROM TicketManagement TM
            WHERE TM.TicketID = H.TicketID
            ORDER BY TM.UID DESC
        ) TM
 
        WHERE H.AuditListID = @AuditListID
          AND H.AuditInstanceID = @AuditInstanceID;
 
    END
 
 
    ---------------------------------------------------------
    -- FQC Engine Performance
    -- DocumentID = 11
    -- Data from History Table
    ---------------------------------------------------------
    ELSE IF @DocumentID = 10
    BEGIN
 
        SELECT
 
            H.SampleLevel,
            H.SampleNo,
            H.EngineNo,
 
            -------------------------------------------------
            -- Power
            -------------------------------------------------
            H.PowerRPM,
            H.LLPowerValue,
            H.ULPowerValue,
 
            H.ObservationPowerRPMValue,
 
            H.ObservationPowerValue,
 
            H.ObservationPowerValueResult,
 
            CASE H.ObservationPowerValueResult
                WHEN 1 THEN 'OK'
                WHEN 2 THEN 'NOK'
                ELSE ''
            END AS ObservationPowerValueResultName,
 
 
            -------------------------------------------------
            -- Torque
            -------------------------------------------------
            H.TorqueRPM,
            H.LLTorqueValue,
            H.ULTorqueValue,
 
            H.ObservationTorqueRPMValue,
 
            H.ObservationTorqueValue,
 
            H.ObservationTorqueValueResult,
 
            CASE H.ObservationTorqueValueResult
                WHEN 1 THEN 'OK'
                WHEN 2 THEN 'NOK'
                ELSE ''
            END AS ObservationTorqueValueResultName,
 
 
            -------------------------------------------------
            -- Common Remark
            -------------------------------------------------
            H.ObservationRemark,
 
 
            -------------------------------------------------
            -- Common fields
            -------------------------------------------------
            H.Timestamp,
            H.AuditInstanceID,
            H.Revision,
 
            H.TicketID,
 
            TM.TicketStatus,
 
            CASE TM.TicketStatus
                WHEN 1 THEN 'Open'
                WHEN 2 THEN 'Close'
                ELSE ''
            END AS TicketStatusName,
 
 
            -------------------------------------------------
            -- Audit List
            -------------------------------------------------
            AL.AuditListName
 
        FROM QA_Execute_FQC_EngPerformanceAuditPoint_History H
 
        INNER JOIN Config_FQC_EngPerformanceAuditPoint C
            ON H.AuditPointID = C.UID
 
        INNER JOIN Config_AuditList AL
            ON H.AuditListID = AL.AuditListID
 
        OUTER APPLY
        (
            SELECT TOP (1)
                TM.TicketStatus
            FROM TicketManagement TM
            WHERE TM.TicketID = H.TicketID
            ORDER BY TM.UID DESC
        ) TM
 
        WHERE H.AuditListID = @AuditListID
          AND H.AuditInstanceID = @AuditInstanceID;
 
    END
 
END
GO

-- ------------------------------------------------------------------------
-- [348/376] Stored Procedure: [dbo].[Tab_Q_FQC_MonitoringScreenInspectBtn]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE   PROCEDURE [dbo].[Tab_Q_FQC_MonitoringScreenInspectBtn]
(
    @DocumentID INT,
    @AuditListID INT,
    @ExecutedBy NVARCHAR(100)
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
 
    BEGIN TRY
 
        DECLARE @AuditInstanceID BIGINT;
        DECLARE @ProdDate DATE;
        DECLARE @ProdShift NVARCHAR(50);
 
        /* =========================================================
           1. CHECK IF AUDIT IS ALREADY IN PROGRESS
        ========================================================= */
 
        IF EXISTS
        (
            SELECT 1
            FROM QA_Execute_FQC_AuditList
            WHERE AuditListID = @AuditListID
              AND ExecutedEndTime IS NULL
        )
        BEGIN
            RAISERROR('Audit already in progress.', 16, 1);
            RETURN;
        END;
 
 
        /* =========================================================
           2. GET AUDIT INSTANCE ID FROM AUDIT SCHEDULE
        ========================================================= */
 
        SELECT TOP 1
            @AuditInstanceID = AuditInstanceID
        FROM Config_AuditSchedule
        WHERE DocumentID = @DocumentID
        ORDER BY UID DESC;
 
 
        IF @AuditInstanceID IS NULL
        BEGIN
            RAISERROR('Audit Schedule not found.', 16, 1);
            RETURN;
        END;
 
 
        /* =========================================================
           3. GET CURRENT PRODUCTION DATE
              DATE FORMAT IN TABLE = DD-MM-YYYY
        ========================================================= */
 
        SELECT TOP 1
            @ProdDate = TRY_CONVERT(DATE, [ParameterValue], 105)
        FROM ApplicationSetting
        WHERE [ParameterName] = 'ProdDate'
        ORDER BY UID DESC;
 
 
        /* =========================================================
           4. GET CURRENT PRODUCTION SHIFT
        ========================================================= */
 
        SELECT TOP 1
            @ProdShift = [ParameterValue]
        FROM ApplicationSetting
        WHERE [ParameterName] = 'ProdShift'
        ORDER BY UID DESC;
 
 
        IF @ProdDate IS NULL
        BEGIN
            RAISERROR(
                'Production Date not found or invalid in ApplicationSetting.',
                16,
                1
            );
            RETURN;
        END;
 
 
        IF @ProdShift IS NULL
           OR LTRIM(RTRIM(@ProdShift)) = ''
        BEGIN
            RAISERROR(
                'Production Shift not found in ApplicationSetting.',
                16,
                1
            );
            RETURN;
        END;
 
 
        /* =========================================================
           5. VALIDATE AUDIT LIST
        ========================================================= */
 
        IF NOT EXISTS
        (
            SELECT 1
            FROM Config_AuditList
            WHERE AuditListID = @AuditListID
              AND DocumentID = @DocumentID
        )
        BEGIN
            RAISERROR(
                'Invalid AuditListID for the selected DocumentID.',
                16,
                1
            );
            RETURN;
        END;
 
 
        /* =========================================================
           6. TRANSACTION START
        ========================================================= */
 
        BEGIN TRANSACTION;
 
 
        /* =========================================================
           7. INSERT EXECUTION DOCUMENT
        ========================================================= */
 
        INSERT INTO QA_Execute_DocumentList
        (
            DocumentID,
            DocumentNo,
            DocumentName,
            AuditGroup,
            Revision,
            AuditInstanceID
        )
        SELECT
            DocumentID,
            DocumentNo,
            DocumentName,
            [Group],
            Revision,
            @AuditInstanceID
        FROM Config_QADocumentList
        WHERE DocumentID = @DocumentID;
 
 
        /* =========================================================
           8. INSERT FQC AUDIT HEADER
           SampleLevel = 1
           Initial sample range = 1 to 5
        ========================================================= */
 
        INSERT INTO QA_Execute_FQC_AuditList
        (
            AuditListID,
            Status,
            ProdDate,
            ProdShift,
            AuditInstanceID,
            SampleLevel,
            NokSample,
            ExecutedStartTime,
            ExecutedBy
        )
        VALUES
        (
            @AuditListID,
            1,
            @ProdDate,
            @ProdShift,
            @AuditInstanceID,
            1,
            0,
            GETDATE(),
            @ExecutedBy
        );
 
 
        /* =========================================================
           9. FQC ENGINE INBUILT
           DocumentID = 10, 12, 13
 
           Create:
              Every checkpoint
              ×
              5 samples
 
           Example:
              5 checkpoints × 5 samples = 25 rows
        ========================================================= */
 
        IF @DocumentID IN (9, 11, 12)
        BEGIN
 
            INSERT INTO QA_Execute_FQC_EngInbuiltAuditPoint
            (
                AuditPointID,
                AuditListID,
                SampleLevel,
                SampleNo,
                EngineNo,
                ObservationValue,
                Result,
                Remark,
                [Timestamp],
                AuditInstanceID,
                Revision,
                TicketID
            )
            SELECT
                C.UID AS AuditPointID,
                C.AuditListID,
                1 AS SampleLevel,
                S.SampleNo,
                NULL AS EngineNo,
                NULL AS ObservationValue,
                NULL AS Result,
                NULL AS Remark,
                GETDATE() AS [Timestamp],
                @AuditInstanceID,
                C.Revision,
                NULL AS TicketID
            FROM Config_FQC_EngInbuiltAuditPoint C
            CROSS JOIN
            (
                SELECT 1 AS SampleNo
                UNION ALL SELECT 2
                UNION ALL SELECT 3
                UNION ALL SELECT 4
                UNION ALL SELECT 5
            ) S
            WHERE C.AuditListID = @AuditListID
              AND C.Status = 1;
 
        END;
 
 
        /* =========================================================
           10. FQC ENGINE PERFORMANCE
           DocumentID = 11
 
           Create:
              Every checkpoint
              ×
              5 samples
 
           Example:
              5 checkpoints × 5 samples = 25 rows
        ========================================================= */
 
  ELSE IF @DocumentID = 10
BEGIN
 
    INSERT INTO QA_Execute_FQC_EngPerformanceAuditPoint
    (
        AuditPointID,
        AuditListID,
        SampleLevel,
        SampleNo,
        EngineNo,
 
        PowerRPM,
        LLPowerValue,
        ULPowerValue,
        ObservationPowerRPMValue,
        ObservationPowerValue,
        ObservationPowerValueResult,
 
        TorqueRPM,
        LLTorqueValue,
        ULTorqueValue,
        ObservationTorqueRPMValue,
        ObservationTorqueValue,
        ObservationTorqueValueResult,
 
        ObservationRemark,
 
        [Timestamp],
        AuditInstanceID,
        Revision,
        TicketID
    )
    SELECT
        C.AuditPointId AS AuditPointID,
        C.AuditListID,
        1 AS SampleLevel,
        S.SampleNo,
        NULL AS EngineNo,
 
        ----------------------------------------------------
        -- Power
        ----------------------------------------------------
        C.PowerRPM,
        C.LLPowerValue,
        C.ULPowerValue,
        NULL AS ObservationPowerRPMValue,
        NULL AS ObservationPowerValue,
        NULL AS ObservationPowerValueResult,
 
        ----------------------------------------------------
        -- Torque
        ----------------------------------------------------
        C.TorqueRPM,
        C.LLTorqueValue,
        C.ULTorqueValue,
        NULL AS ObservationTorqueRPMValue,
        NULL AS ObservationTorqueValue,
        NULL AS ObservationTorqueValueResult,
 
        ----------------------------------------------------
        -- Common Remark
        ----------------------------------------------------
        NULL AS ObservationRemark,
 
        ----------------------------------------------------
        -- Common
        ----------------------------------------------------
        GETDATE() AS [Timestamp],
        @AuditInstanceID,
        C.Revision,
        NULL AS TicketID
 
    FROM Config_FQC_EngPerformanceAuditPoint C
 
    CROSS JOIN
    (
        SELECT 1 AS SampleNo
        UNION ALL SELECT 2
        UNION ALL SELECT 3
        UNION ALL SELECT 4
        UNION ALL SELECT 5
    ) S
 
    WHERE
        C.AuditListID = @AuditListID
        AND C.Status = 1;
 
END;
 
 
        /* =========================================================
           11. INVALID DOCUMENT ID
        ========================================================= */
 
        ELSE
        BEGIN
            RAISERROR('Invalid FQC DocumentID.', 16, 1);
            RETURN;
        END;
 
 
        /* =========================================================
           12. UPDATE AUDIT SCHEDULE
        ========================================================= */
 
        UPDATE Config_AuditSchedule
        SET Status = 2
        WHERE DocumentID = @DocumentID
          AND Status = 1;
 
 
        /* =========================================================
           13. UPDATE AUDIT MONITORING
        ========================================================= */
 
        UPDATE QA_AuditMonitoring
        SET
            Status = 2,
            ActualStartDateTime = GETDATE(),
            AuditInstanceID = @AuditInstanceID
        WHERE AuditListID = @AuditListID
          AND Status = 1;
 
 
        /* =========================================================
           14. COMMIT TRANSACTION
        ========================================================= */
 
        COMMIT TRANSACTION;
 
 
        /* =========================================================
           15. SUCCESS RESPONSE
        ========================================================= */
 
        SELECT
            1 AS Success,
            'FQC Audit Executed Successfully' AS Message,
            @AuditInstanceID AS AuditInstanceID,
            @ProdDate AS ProdDate,
            @ProdShift AS ProdShift;
 
 
    END TRY
 
    BEGIN CATCH
 
        /* =========================================================
           ROLLBACK IF ERROR
        ========================================================= */
 
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
 
 
        SELECT
            0 AS Success,
            ERROR_MESSAGE() AS Message,
            ERROR_NUMBER() AS ErrorNumber,
            ERROR_LINE() AS ErrorLine;
 
    END CATCH
 
END
GO

-- ------------------------------------------------------------------------
-- [349/376] Stored Procedure: [dbo].[Tab_Q_FQC_MoveToNextSampleLevel_EngInbuilt]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE   PROCEDURE [dbo].[Tab_Q_FQC_MoveToNextSampleLevel_EngInbuilt]
(
    @AuditListID INT,
    @AuditInstanceID BIGINT
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY

        BEGIN TRANSACTION;

        DECLARE
            @CurrentLevel INT,
            @NextLevel INT,
            @NextSampleQty INT,
            @StartSampleNo INT,
            @EndSampleNo INT,
            @ExistingCount INT;


        /* ============================================================
           1. VALIDATE PARAMETERS
           ============================================================ */

        IF @AuditListID IS NULL OR @AuditListID <= 0
        BEGIN
            RAISERROR(
                'AuditListID is required.',
                16,
                1
            );

            ROLLBACK TRANSACTION;
            RETURN;
        END;


        IF @AuditInstanceID IS NULL OR @AuditInstanceID <= 0
        BEGIN
            RAISERROR(
                'AuditInstanceID is required.',
                16,
                1
            );

            ROLLBACK TRANSACTION;
            RETURN;
        END;


        /* ============================================================
           2. FIND CURRENT LEVEL
           
           Level 1 = Samples 1-5
           Level 2 = Samples 6-30
           Level 3 = Samples 31-80
           ============================================================ */

        SELECT
            @CurrentLevel = MAX(SampleLevel)
        FROM [dbo].[QA_Execute_FQC_EngInbuiltAuditPoint]
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID;


        /* ============================================================
           3. VALIDATE CURRENT LEVEL
           ============================================================ */

        IF @CurrentLevel IS NULL
        BEGIN
            RAISERROR(
                'No FQC Engine Inbuilt execution data found for the given AuditListID and AuditInstanceID.',
                16,
                1
            );

            ROLLBACK TRANSACTION;
            RETURN;
        END;


        /* ============================================================
           4. DETERMINE NEXT LEVEL
           
           Level 1 -> Level 2
               Samples 6-30
               Quantity 25

           Level 2 -> Level 3
               Samples 31-80
               Quantity 50

           Level 3 -> Final
           ============================================================ */

        IF @CurrentLevel = 1
        BEGIN

            SET @NextLevel = 2;
            SET @NextSampleQty = 25;
            SET @StartSampleNo = 6;
            SET @EndSampleNo = 30;

        END
        ELSE IF @CurrentLevel = 2
        BEGIN

            SET @NextLevel = 3;
            SET @NextSampleQty = 50;
            SET @StartSampleNo = 31;
            SET @EndSampleNo = 80;

        END
        ELSE IF @CurrentLevel = 3
        BEGIN

            /* ========================================================
               LEVEL 3 IS FINAL LEVEL
               Move Level 3 to History and remove from execution
               ======================================================== */

            INSERT INTO
                [dbo].[QA_Execute_FQC_EngInbuiltAuditPoint_History]
            (
                AuditPointID,
                AuditListID,
                SampleLevel,
                SampleNo,
                EngineNo,
                ObservationValue,
                Result,
                Remark,
                Timestamp,
                AuditInstanceID,
                Revision,
                TicketID
            )
            SELECT
                AuditPointID,
                AuditListID,
                SampleLevel,
                SampleNo,
                EngineNo,
                ObservationValue,
                Result,
                Remark,
                GETDATE(),
                AuditInstanceID,
                Revision,
                TicketID
            FROM
                [dbo].[QA_Execute_FQC_EngInbuiltAuditPoint]
            WHERE AuditListID = @AuditListID
              AND AuditInstanceID = @AuditInstanceID
              AND SampleLevel = 3;


            DELETE FROM
                [dbo].[QA_Execute_FQC_EngInbuiltAuditPoint]
            WHERE AuditListID = @AuditListID
              AND AuditInstanceID = @AuditInstanceID
              AND SampleLevel = 3;


            COMMIT TRANSACTION;


            SELECT
                @AuditListID AS AuditListID,
                @AuditInstanceID AS AuditInstanceID,
                3 AS PreviousLevel,
                NULL AS NextLevel,
                50 AS SampleQty,
                31 AS StartSampleNo,
                80 AS EndSampleNo,
                'Level 3 completed. FQC audit sample execution completed.'
                    AS Message;

            RETURN;

        END
        ELSE
        BEGIN

            RAISERROR(
                'Invalid SampleLevel found in FQC Engine Inbuilt execution table.',
                16,
                1
            );

            ROLLBACK TRANSACTION;
            RETURN;

        END;


        /* ============================================================
           5. CHECK CURRENT LEVEL DATA
           ============================================================ */

        SELECT
            @ExistingCount = COUNT(*)
        FROM
            [dbo].[QA_Execute_FQC_EngInbuiltAuditPoint]
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID
          AND SampleLevel = @CurrentLevel;


        IF @ExistingCount = 0
        BEGIN
            RAISERROR(
                'Current level data does not exist in FQC Engine Inbuilt execution table.',
                16,
                1
            );

            ROLLBACK TRANSACTION;
            RETURN;
        END;


        /* ============================================================
           6. MOVE CURRENT LEVEL TO HISTORY
           ============================================================ */

        INSERT INTO
            [dbo].[QA_Execute_FQC_EngInbuiltAuditPoint_History]
        (
            AuditPointID,
            AuditListID,
            SampleLevel,
            SampleNo,
            EngineNo,
            ObservationValue,
            Result,
            Remark,
            Timestamp,
            AuditInstanceID,
            Revision,
            TicketID
        )
        SELECT
            AuditPointID,
            AuditListID,
            SampleLevel,
            SampleNo,
            EngineNo,
            ObservationValue,
            Result,
            Remark,
            GETDATE(),
            AuditInstanceID,
            Revision,
            TicketID
        FROM
            [dbo].[QA_Execute_FQC_EngInbuiltAuditPoint]
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID
          AND SampleLevel = @CurrentLevel;


        /* ============================================================
           7. DELETE CURRENT LEVEL FROM EXECUTION
           ============================================================ */

        DELETE FROM
            [dbo].[QA_Execute_FQC_EngInbuiltAuditPoint]
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID
          AND SampleLevel = @CurrentLevel;


        /* ============================================================
           8. CREATE SAMPLE NUMBERS

           Level 1 -> Level 2
           6 - 30

           Level 2 -> Level 3
           31 - 80
           ============================================================ */

        ;WITH SampleNumbers AS
        (
            SELECT TOP (@NextSampleQty)
                ROW_NUMBER() OVER
                (
                    ORDER BY (SELECT NULL)
                )
                + @StartSampleNo - 1 AS SampleNo
            FROM sys.all_objects A
            CROSS JOIN sys.all_objects B
        )


        /* ============================================================
           9. INSERT NEXT LEVEL

           Every Config checkpoint gets every sample.

           Example:

           5 checkpoints × 25 samples
           = 125 execution rows

           EngineNo = NULL
           ObservationValue = NULL
           Result = NULL
           Remark = NULL
           ============================================================ */

        INSERT INTO
            [dbo].[QA_Execute_FQC_EngInbuiltAuditPoint]
        (
            AuditPointID,
            AuditListID,
            SampleLevel,
            SampleNo,
            EngineNo,
            ObservationValue,
            Result,
            Remark,
            Timestamp,
            AuditInstanceID,
            Revision,
            TicketID
        )
        SELECT
            C.UID AS AuditPointID,
            C.AuditListID,
            @NextLevel AS SampleLevel,
            S.SampleNo,

            NULL AS EngineNo,
            NULL AS ObservationValue,
            NULL AS Result,
            NULL AS Remark,

            GETDATE() AS Timestamp,

            @AuditInstanceID,

            C.Revision,

            NULL AS TicketID

        FROM
            [dbo].[Config_FQC_EngInbuiltAuditPoint] C

        CROSS JOIN
            SampleNumbers S

        WHERE
            C.AuditListID = @AuditListID

            AND C.Status = 1;


        /* ============================================================
           10. VERIFY NEXT LEVEL INSERT
           ============================================================ */

        IF NOT EXISTS
        (
            SELECT 1
            FROM [dbo].[QA_Execute_FQC_EngInbuiltAuditPoint]
            WHERE AuditListID = @AuditListID
              AND AuditInstanceID = @AuditInstanceID
              AND SampleLevel = @NextLevel
        )
        BEGIN
            RAISERROR(
                'Next sample level was not inserted into FQC Engine Inbuilt execution table.',
                16,
                1
            );

            ROLLBACK TRANSACTION;
            RETURN;
        END;


        /* ============================================================
           11. COMMIT
           ============================================================ */

        COMMIT TRANSACTION;


        /* ============================================================
           12. RETURN RESPONSE
           ============================================================ */

        SELECT
            @AuditListID AS AuditListID,
            @AuditInstanceID AS AuditInstanceID,
            @CurrentLevel AS PreviousLevel,
            @NextLevel AS NextLevel,
            @NextSampleQty AS SampleQty,
            @StartSampleNo AS StartSampleNo,
            @EndSampleNo AS EndSampleNo,
            'FQC sample level moved successfully.'
                AS Message;


    END TRY

    BEGIN CATCH

        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        SELECT
            ERROR_NUMBER() AS ErrorNumber,
            ERROR_MESSAGE() AS ErrorMessage,
            ERROR_LINE() AS ErrorLine;

    END CATCH

END
GO

-- ------------------------------------------------------------------------
-- [350/376] Stored Procedure: [dbo].[Tab_Q_FQC_MoveToNextSampleLevel_EngPerformance]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[Tab_Q_FQC_MoveToNextSampleLevel_EngPerformance]
    @AuditListID INT,
    @AuditInstanceID BIGINT
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY

        ------------------------------------------------------------
        -- Validate inputs
        ------------------------------------------------------------
        IF @AuditListID IS NULL
        BEGIN
            RAISERROR('AuditListID is required', 16, 1);
            RETURN;
        END;

        IF @AuditInstanceID IS NULL
        BEGIN
            RAISERROR('AuditInstanceID is required', 16, 1);
            RETURN;
        END;


        ------------------------------------------------------------
        -- Variables
        ------------------------------------------------------------
        DECLARE @CurrentLevel INT;
        DECLARE @NextLevel INT;
        DECLARE @StartSampleNo INT;
        DECLARE @EndSampleNo INT;


        ------------------------------------------------------------
        -- Get current sample level
        ------------------------------------------------------------
        SELECT @CurrentLevel = MAX(SampleLevel)
        FROM QA_Execute_FQC_EngPerformanceAuditPoint
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID;


        IF @CurrentLevel IS NULL
        BEGIN
            RAISERROR(
                'No active FQC Engine Performance sample found',
                16,
                1
            );
            RETURN;
        END;


        ------------------------------------------------------------
        -- Determine next level
        ------------------------------------------------------------
        IF @CurrentLevel = 1
        BEGIN
            SET @NextLevel = 2;
            SET @StartSampleNo = 6;
            SET @EndSampleNo = 30;
        END
        ELSE IF @CurrentLevel = 2
        BEGIN
            SET @NextLevel = 3;
            SET @StartSampleNo = 31;
            SET @EndSampleNo = 80;
        END
        ELSE IF @CurrentLevel = 3
        BEGIN

            --------------------------------------------------------
            -- Final Level 3
            -- Move Level 3 execution records to history only
            --------------------------------------------------------
            BEGIN TRANSACTION;


            INSERT INTO QA_Execute_FQC_EngPerformanceAuditPoint_History
            (
                AuditPointID,
                AuditListID,
                SampleLevel,
                SampleNo,
                EngineNo,

                PowerRPM,
                LLPowerValue,
                ULPowerValue,
                ObservationPowerRPMValue,
                ObservationPowerValue,
                ObservationPowerValueResult,

                TorqueRPM,
                LLTorqueValue,
                ULTorqueValue,
                ObservationTorqueRPMValue,
                ObservationTorqueValue,
                ObservationTorqueValueResult,

                ObservationRemark,

                [Timestamp],
                AuditInstanceID,
                Revision,
                TicketID
            )
            SELECT
                AuditPointID,
                AuditListID,
                SampleLevel,
                SampleNo,
                EngineNo,

                PowerRPM,
                LLPowerValue,
                ULPowerValue,
                ObservationPowerRPMValue,
                ObservationPowerValue,
                ObservationPowerValueResult,

                TorqueRPM,
                LLTorqueValue,
                ULTorqueValue,
                ObservationTorqueRPMValue,
                ObservationTorqueValue,
                ObservationTorqueValueResult,

                ObservationRemark,

                [Timestamp],
                AuditInstanceID,
                Revision,
                TicketID

            FROM QA_Execute_FQC_EngPerformanceAuditPoint

            WHERE AuditListID = @AuditListID
              AND AuditInstanceID = @AuditInstanceID
              AND SampleLevel = @CurrentLevel;


            --------------------------------------------------------
            -- Delete Level 3 from execution table
            --------------------------------------------------------
            DELETE FROM QA_Execute_FQC_EngPerformanceAuditPoint
            WHERE AuditListID = @AuditListID
              AND AuditInstanceID = @AuditInstanceID
              AND SampleLevel = @CurrentLevel;


            COMMIT TRANSACTION;


            --------------------------------------------------------
            -- Final response
            --------------------------------------------------------
            SELECT
                @CurrentLevel AS PreviousLevel,
                NULL AS NextLevel,
                0 AS NextSampleCount,
                'Final Level 3 moved to history successfully' AS Message;

            RETURN;
        END
        ELSE
        BEGIN
            RAISERROR('Invalid SampleLevel', 16, 1);
            RETURN;
        END;


        ------------------------------------------------------------
        -- Start transaction
        ------------------------------------------------------------
        BEGIN TRANSACTION;


        ------------------------------------------------------------
        -- Move current level to history
        ------------------------------------------------------------
        INSERT INTO QA_Execute_FQC_EngPerformanceAuditPoint_History
        (
            AuditPointID,
            AuditListID,
            SampleLevel,
            SampleNo,
            EngineNo,

            PowerRPM,
            LLPowerValue,
            ULPowerValue,
            ObservationPowerRPMValue,
            ObservationPowerValue,
            ObservationPowerValueResult,

            TorqueRPM,
            LLTorqueValue,
            ULTorqueValue,
            ObservationTorqueRPMValue,
            ObservationTorqueValue,
            ObservationTorqueValueResult,

            ObservationRemark,

            [Timestamp],
            AuditInstanceID,
            Revision,
            TicketID
        )
        SELECT
            AuditPointID,
            AuditListID,
            SampleLevel,
            SampleNo,
            EngineNo,

            PowerRPM,
            LLPowerValue,
            ULPowerValue,
            ObservationPowerRPMValue,
            ObservationPowerValue,
            ObservationPowerValueResult,

            TorqueRPM,
            LLTorqueValue,
            ULTorqueValue,
            ObservationTorqueRPMValue,
            ObservationTorqueValue,
            ObservationTorqueValueResult,

            ObservationRemark,

            [Timestamp],
            AuditInstanceID,
            Revision,
            TicketID

        FROM QA_Execute_FQC_EngPerformanceAuditPoint

        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID
          AND SampleLevel = @CurrentLevel;


        ------------------------------------------------------------
        -- Delete current level from execution table
        ------------------------------------------------------------
        DELETE FROM QA_Execute_FQC_EngPerformanceAuditPoint
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID
          AND SampleLevel = @CurrentLevel;


        ------------------------------------------------------------
        -- Create next sample level
        --
        -- Level 2 = Sample 6 to 30
        -- Level 3 = Sample 31 to 80
        ------------------------------------------------------------
        INSERT INTO QA_Execute_FQC_EngPerformanceAuditPoint
        (
            AuditPointID,
            AuditListID,
            SampleLevel,
            SampleNo,
            EngineNo,

            PowerRPM,
            LLPowerValue,
            ULPowerValue,
            ObservationPowerRPMValue,
            ObservationPowerValue,
            ObservationPowerValueResult,

            TorqueRPM,
            LLTorqueValue,
            ULTorqueValue,
            ObservationTorqueRPMValue,
            ObservationTorqueValue,
            ObservationTorqueValueResult,

            ObservationRemark,

            [Timestamp],
            AuditInstanceID,
            Revision,
            TicketID
        )
        SELECT
            C.UID,
            C.AuditListID,
            @NextLevel,
            S.SampleNo,
            NULL AS EngineNo,

            --------------------------------------------------------
            -- Power configuration
            --------------------------------------------------------
            C.PowerRPM,
            C.LLPowerValue,
            C.ULPowerValue,
            NULL AS ObservationPowerRPMValue,
            NULL AS ObservationPowerValue,
            NULL AS ObservationPowerValueResult,

            --------------------------------------------------------
            -- Torque configuration
            --------------------------------------------------------
            C.TorqueRPM,
            C.LLTorqueValue,
            C.ULTorqueValue,
            NULL AS ObservationTorqueRPMValue,
            NULL AS ObservationTorqueValue,
            NULL AS ObservationTorqueValueResult,

            --------------------------------------------------------
            -- Common remark
            --------------------------------------------------------
            NULL AS ObservationRemark,

            GETDATE(),
            @AuditInstanceID,
            C.Revision,
            NULL AS TicketID

        FROM Config_FQC_EngPerformanceAuditPoint C

        CROSS JOIN
        (
            SELECT TOP (@EndSampleNo - @StartSampleNo + 1)
                ROW_NUMBER() OVER (ORDER BY (SELECT NULL))
                + @StartSampleNo - 1 AS SampleNo
            FROM sys.all_objects A
            CROSS JOIN sys.all_objects B
        ) S

        WHERE C.AuditListID = @AuditListID
          AND C.Status = 1
          AND S.SampleNo BETWEEN @StartSampleNo AND @EndSampleNo;


        ------------------------------------------------------------
        -- Verify next level was created
        ------------------------------------------------------------
        IF NOT EXISTS
        (
            SELECT 1
            FROM QA_Execute_FQC_EngPerformanceAuditPoint
            WHERE AuditListID = @AuditListID
              AND AuditInstanceID = @AuditInstanceID
              AND SampleLevel = @NextLevel
        )
        BEGIN
            ROLLBACK TRANSACTION;

            RAISERROR(
                'Failed to create next FQC Engine Performance sample level',
                16,
                1
            );

            RETURN;
        END;


        ------------------------------------------------------------
        -- Commit transaction
        ------------------------------------------------------------
        COMMIT TRANSACTION;


        ------------------------------------------------------------
        -- Success response
        ------------------------------------------------------------
        SELECT
            @CurrentLevel AS PreviousLevel,
            @NextLevel AS NextLevel,
            (@EndSampleNo - @StartSampleNo + 1) AS NextSampleCount,
            @StartSampleNo AS StartSampleNo,
            @EndSampleNo AS EndSampleNo,
            'FQC Engine Performance sample level moved successfully' AS Message;


    END TRY

    BEGIN CATCH

        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        THROW;

    END CATCH
END
GO

-- ------------------------------------------------------------------------
-- [351/376] Stored Procedure: [dbo].[Tab_Q_FQC_UpdateEngInbuilt_EngineNo]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE   PROCEDURE [dbo].[Tab_Q_FQC_UpdateEngInbuilt_EngineNo]
(
    @AuditListID INT,
    @SampleLevel INT,
    @SampleNo INT,
    @EngineNo NVARCHAR(100)
)
AS
BEGIN
    SET NOCOUNT ON;

    -- Validate AuditListID
    IF @AuditListID IS NULL OR @AuditListID <= 0
    BEGIN
        RAISERROR('Invalid AuditListID. AuditListID must be provided.', 16, 1);
        RETURN;
    END;

    -- Validate SampleLevel
    IF @SampleLevel IS NULL OR @SampleLevel <= 0
    BEGIN
        RAISERROR('Invalid SampleLevel. SampleLevel must be provided.', 16, 1);
        RETURN;
    END;

    -- Validate SampleNo
    IF @SampleNo IS NULL OR @SampleNo <= 0
    BEGIN
        RAISERROR('Invalid SampleNo. SampleNo must be provided.', 16, 1);
        RETURN;
    END;

    -- Validate EngineNo
    IF @EngineNo IS NULL OR LTRIM(RTRIM(@EngineNo)) = ''
    BEGIN
        RAISERROR('EngineNo is required.', 16, 1);
        RETURN;
    END;

    -- Check whether sample records exist
    IF NOT EXISTS
    (
        SELECT 1
        FROM [dbo].[QA_Execute_FQC_EngInbuiltAuditPoint]
        WHERE AuditListID = @AuditListID
          AND SampleLevel = @SampleLevel
          AND SampleNo = @SampleNo
    )
    BEGIN
        RAISERROR(
            'No FQC Engine Inbuilt checkpoint records found for the given AuditListID, SampleLevel and SampleNo.',
            16,
            1
        );
        RETURN;
    END;

    -- Update EngineNo for ALL checkpoints of this sample
    UPDATE [dbo].[QA_Execute_FQC_EngInbuiltAuditPoint]
    SET
        EngineNo = @EngineNo,
        [Timestamp] = GETDATE()
    WHERE AuditListID = @AuditListID
      AND SampleLevel = @SampleLevel
      AND SampleNo = @SampleNo;

    -- Return updated records
    SELECT
        UID,
        AuditPointID,
        AuditListID,
        SampleLevel,
        SampleNo,
        EngineNo,
        ObservationValue,
        Result,
        Remark,
        [Timestamp],
        AuditInstanceID,
        Revision,
        TicketID
    FROM [dbo].[QA_Execute_FQC_EngInbuiltAuditPoint]
    WHERE AuditListID = @AuditListID
      AND SampleLevel = @SampleLevel
      AND SampleNo = @SampleNo
    ORDER BY UID;

END
GO

-- ------------------------------------------------------------------------
-- [352/376] Stored Procedure: [dbo].[Tab_Q_FQC_UpdateEngInbuiltCheckpointResult]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE   PROCEDURE [dbo].[Tab_Q_FQC_UpdateEngInbuiltCheckpointResult]
(
    @UID INT,
    @SampleLevel INT,
    @SampleNo INT,
    @Result INT,
    @Remark NVARCHAR(500) = NULL,
    @ObservationValue NVARCHAR(500) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    /* ============================================================
       1. VALIDATE UID
       ============================================================ */

    IF @UID IS NULL OR @UID <= 0
    BEGIN
        RAISERROR(
            'Invalid UID. UID must be provided.',
            16,
            1
        );
        RETURN;
    END;


    /* ============================================================
       2. VALIDATE SAMPLE LEVEL
       ============================================================ */

    IF @SampleLevel IS NULL OR @SampleLevel <= 0
    BEGIN
        RAISERROR(
            'Invalid SampleLevel. SampleLevel must be provided.',
            16,
            1
        );
        RETURN;
    END;


    /* ============================================================
       3. VALIDATE SAMPLE NO
       ============================================================ */

    IF @SampleNo IS NULL OR @SampleNo <= 0
    BEGIN
        RAISERROR(
            'Invalid SampleNo. SampleNo must be provided.',
            16,
            1
        );
        RETURN;
    END;


    /* ============================================================
       4. VALIDATE RESULT
       
       1 = OK
       2 = NOK
       ============================================================ */

    IF @Result NOT IN (1, 2)
    BEGIN
        RAISERROR(
            'Invalid Result. Result must be 1 (OK) or 2 (NOK).',
            16,
            1
        );
        RETURN;
    END;


    /* ============================================================
       5. CHECK EXECUTION RECORD
       ============================================================ */

    IF NOT EXISTS
    (
        SELECT 1
        FROM [dbo].[QA_Execute_FQC_EngInbuiltAuditPoint]
        WHERE UID = @UID
          AND SampleLevel = @SampleLevel
          AND SampleNo = @SampleNo
    )
    BEGIN
        RAISERROR(
            'FQC Engine Inbuilt checkpoint execution record not found for the given UID, SampleLevel and SampleNo.',
            16,
            1
        );
        RETURN;
    END;


    /* ============================================================
       6. UPDATE CHECKPOINT RESULT
       
       EngineNo is NOT updated.
       ============================================================ */

    UPDATE [dbo].[QA_Execute_FQC_EngInbuiltAuditPoint]
    SET
        ObservationValue = @ObservationValue,
        Result = @Result,
        Remark = @Remark,
        [Timestamp] = GETDATE()
    WHERE UID = @UID
      AND SampleLevel = @SampleLevel
      AND SampleNo = @SampleNo;


    /* ============================================================
       7. RETURN UPDATED RECORD
       ============================================================ */

    SELECT
        UID,
        AuditPointID,
        AuditListID,
        SampleLevel,
        SampleNo,
        EngineNo,
        ObservationValue,
        Result,
        Remark,
        [Timestamp],
        AuditInstanceID,
        Revision,
        TicketID
    FROM [dbo].[QA_Execute_FQC_EngInbuiltAuditPoint]
    WHERE UID = @UID
      AND SampleLevel = @SampleLevel
      AND SampleNo = @SampleNo;

END
GO

-- ------------------------------------------------------------------------
-- [353/376] Stored Procedure: [dbo].[Tab_Q_FQC_UpdateEngPerformance_EngineNo]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[Tab_Q_FQC_UpdateEngPerformance_EngineNo]
(
    @AuditListID INT,
    @SampleLevel INT,
    @SampleNo INT,
    @EngineNo NVARCHAR(100)
)
AS
BEGIN
    SET NOCOUNT ON;

    ----------------------------------------------------
    -- Validate AuditListID
    ----------------------------------------------------
    IF @AuditListID IS NULL OR @AuditListID <= 0
    BEGIN
        RAISERROR(
            'Invalid AuditListID. AuditListID must be provided.',
            16,
            1
        );
        RETURN;
    END;

    ----------------------------------------------------
    -- Validate SampleLevel
    ----------------------------------------------------
    IF @SampleLevel IS NULL OR @SampleLevel <= 0
    BEGIN
        RAISERROR(
            'Invalid SampleLevel. SampleLevel must be provided.',
            16,
            1
        );
        RETURN;
    END;

    ----------------------------------------------------
    -- Validate SampleNo
    ----------------------------------------------------
    IF @SampleNo IS NULL OR @SampleNo <= 0
    BEGIN
        RAISERROR(
            'Invalid SampleNo. SampleNo must be provided.',
            16,
            1
        );
        RETURN;
    END;

    ----------------------------------------------------
    -- Validate EngineNo
    ----------------------------------------------------
    IF @EngineNo IS NULL
       OR LTRIM(RTRIM(@EngineNo)) = ''
    BEGIN
        RAISERROR(
            'EngineNo is required.',
            16,
            1
        );
        RETURN;
    END;

    ----------------------------------------------------
    -- Check whether records exist for this sample
    ----------------------------------------------------
    IF NOT EXISTS
    (
        SELECT 1
        FROM [dbo].[QA_Execute_FQC_EngPerformanceAuditPoint]
        WHERE AuditListID = @AuditListID
          AND SampleLevel = @SampleLevel
          AND SampleNo = @SampleNo
    )
    BEGIN
        RAISERROR(
            'FQC Engine Performance checkpoint records not found for the given AuditListID, SampleLevel and SampleNo.',
            16,
            1
        );
        RETURN;
    END;

    ----------------------------------------------------
    -- Update EngineNo for ALL checkpoints of this sample
    ----------------------------------------------------
    UPDATE [dbo].[QA_Execute_FQC_EngPerformanceAuditPoint]
    SET
        EngineNo = @EngineNo,
        [Timestamp] = GETDATE()
    WHERE AuditListID = @AuditListID
      AND SampleLevel = @SampleLevel
      AND SampleNo = @SampleNo;

    ----------------------------------------------------
    -- Return updated records
    ----------------------------------------------------
    SELECT
        UID,
        AuditPointID,
        AuditListID,
        SampleLevel,
        SampleNo,
        EngineNo,

        ------------------------------------------------
        -- Power
        ------------------------------------------------
        PowerRPM,
        LLPowerValue,
        ULPowerValue,
        ObservationPowerRPMValue,
        ObservationPowerValue,
        ObservationPowerValueResult,

        ------------------------------------------------
        -- Torque
        ------------------------------------------------
        TorqueRPM,
        LLTorqueValue,
        ULTorqueValue,
        ObservationTorqueRPMValue,
        ObservationTorqueValue,
        ObservationTorqueValueResult,

        ------------------------------------------------
        -- Common Remark
        ------------------------------------------------
        ObservationRemark,

        ------------------------------------------------
        -- Common
        ------------------------------------------------
        [Timestamp],
        AuditInstanceID,
        Revision,
        TicketID

    FROM [dbo].[QA_Execute_FQC_EngPerformanceAuditPoint]

    WHERE AuditListID = @AuditListID
      AND SampleLevel = @SampleLevel
      AND SampleNo = @SampleNo

    ORDER BY UID;

END
GO

-- ------------------------------------------------------------------------
-- [354/376] Stored Procedure: [dbo].[Tab_Q_FQC_UpdateEngPerformanceCheckpointResult]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[Tab_Q_FQC_UpdateEngPerformanceCheckpointResult]
(
    @UID INT,
    @SampleLevel INT,
    @SampleNo INT,

    ----------------------------------------------------
    -- Power
    ----------------------------------------------------
    @ObservationPowerValue NVARCHAR(500) = NULL,
    @ObservationPowerValueResult INT = NULL,

    @ObservationPowerRPMValue NVARCHAR(500) = NULL,

    ----------------------------------------------------
    -- Torque
    ----------------------------------------------------
    @ObservationTorqueValue NVARCHAR(500) = NULL,
    @ObservationTorqueValueResult INT = NULL,

    @ObservationTorqueRPMValue NVARCHAR(500) = NULL,

    ----------------------------------------------------
    -- Common Remark
    ----------------------------------------------------
    @ObservationRemark NVARCHAR(500) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    ----------------------------------------------------
    -- Validate UID
    ----------------------------------------------------
    IF @UID IS NULL OR @UID <= 0
    BEGIN
        RAISERROR(
            'Invalid UID. UID must be provided.',
            16,
            1
        );
        RETURN;
    END;

    ----------------------------------------------------
    -- Validate SampleLevel
    ----------------------------------------------------
    IF @SampleLevel IS NULL OR @SampleLevel <= 0
    BEGIN
        RAISERROR(
            'Invalid SampleLevel. SampleLevel must be provided.',
            16,
            1
        );
        RETURN;
    END;

    ----------------------------------------------------
    -- Validate SampleNo
    ----------------------------------------------------
    IF @SampleNo IS NULL OR @SampleNo <= 0
    BEGIN
        RAISERROR(
            'Invalid SampleNo. SampleNo must be provided.',
            16,
            1
        );
        RETURN;
    END;

    ----------------------------------------------------
    -- Validate Power Result
    -- 1 = OK
    -- 2 = NOK
    ----------------------------------------------------
    IF @ObservationPowerValueResult IS NOT NULL
       AND @ObservationPowerValueResult NOT IN (1, 2)
    BEGIN
        RAISERROR(
            'Invalid ObservationPowerValueResult. Result must be 1 (OK) or 2 (NOK).',
            16,
            1
        );
        RETURN;
    END;

    ----------------------------------------------------
    -- Validate Torque Result
    -- 1 = OK
    -- 2 = NOK
    ----------------------------------------------------
    IF @ObservationTorqueValueResult IS NOT NULL
       AND @ObservationTorqueValueResult NOT IN (1, 2)
    BEGIN
        RAISERROR(
            'Invalid ObservationTorqueValueResult. Result must be 1 (OK) or 2 (NOK).',
            16,
            1
        );
        RETURN;
    END;

    ----------------------------------------------------
    -- Check execution record
    ----------------------------------------------------
    IF NOT EXISTS
    (
        SELECT 1
        FROM [dbo].[QA_Execute_FQC_EngPerformanceAuditPoint]
        WHERE UID = @UID
          AND SampleLevel = @SampleLevel
          AND SampleNo = @SampleNo
    )
    BEGIN
        RAISERROR(
            'FQC Engine Performance checkpoint execution record not found for the given UID, SampleLevel and SampleNo.',
            16,
            1
        );
        RETURN;
    END;

    ----------------------------------------------------
    -- Update checkpoint
    ----------------------------------------------------
    UPDATE [dbo].[QA_Execute_FQC_EngPerformanceAuditPoint]
    SET
        ------------------------------------------------
        -- Power
        ------------------------------------------------
        ObservationPowerValue = @ObservationPowerValue,
        ObservationPowerValueResult = @ObservationPowerValueResult,
        ObservationPowerRPMValue = @ObservationPowerRPMValue,

        ------------------------------------------------
        -- Torque
        ------------------------------------------------
        ObservationTorqueValue = @ObservationTorqueValue,
        ObservationTorqueValueResult = @ObservationTorqueValueResult,
        ObservationTorqueRPMValue = @ObservationTorqueRPMValue,

        ------------------------------------------------
        -- Common Remark
        ------------------------------------------------
        ObservationRemark = @ObservationRemark,

        ------------------------------------------------
        -- Timestamp
        ------------------------------------------------
        [Timestamp] = GETDATE()

    WHERE UID = @UID
      AND SampleLevel = @SampleLevel
      AND SampleNo = @SampleNo;

    ----------------------------------------------------
    -- Return updated record
    ----------------------------------------------------
    SELECT
        UID,
        AuditPointID,
        AuditListID,
        SampleLevel,
        SampleNo,
        EngineNo,

        ------------------------------------------------
        -- Power
        ------------------------------------------------
        PowerRPM,
        LLPowerValue,
        ULPowerValue,
        ObservationPowerRPMValue,
        ObservationPowerValue,
        ObservationPowerValueResult,

        ------------------------------------------------
        -- Torque
        ------------------------------------------------
        TorqueRPM,
        LLTorqueValue,
        ULTorqueValue,
        ObservationTorqueRPMValue,
        ObservationTorqueValue,
        ObservationTorqueValueResult,

        ------------------------------------------------
        -- Common Remark
        ------------------------------------------------
        ObservationRemark,

        ------------------------------------------------
        -- Common
        ------------------------------------------------
        [Timestamp],
        AuditInstanceID,
        Revision,
        TicketID

    FROM [dbo].[QA_Execute_FQC_EngPerformanceAuditPoint]

    WHERE UID = @UID
      AND SampleLevel = @SampleLevel
      AND SampleNo = @SampleNo;

END
GO

-- ------------------------------------------------------------------------
-- [355/376] Stored Procedure: [dbo].[Tab_Q_IPQC_AuditPoint_Submit]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[Tab_Q_IPQC_AuditPoint_Submit]
(
    @AuditListID INT,
    @AuditInstanceID BIGINT,
    @ExecutedByRemark NVARCHAR(MAX) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY

        BEGIN TRANSACTION;

        DECLARE @PendingCount INT = 0;
        DECLARE @NOKCount INT = 0;
        DECLARE @AuditStatus INT;
        DECLARE @DocumentID INT;
        DECLARE @IncompleteAuditCount INT = 0;


        /* ========================================================
           1. GET DOCUMENT ID
        ======================================================== */

        SELECT
            @DocumentID = DocumentID
        FROM Config_AuditList
        WHERE AuditListID = @AuditListID;


        IF @DocumentID IS NULL
        BEGIN
            RAISERROR(
                'Audit not found.',
                16,
                1
            );
            RETURN;
        END;


        /* ========================================================
           2. VALIDATE PENDING IPQC CHECKPOINTS

           Result:
           1 = OK
           2 = NOK
        ======================================================== */

        SELECT
            @PendingCount = COUNT(*)
        FROM QA_Execute_IPQC_AuditPoint
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID
          AND ISNULL(Result, 0) = 0;


        IF @PendingCount > 0
        BEGIN
            RAISERROR(
                'Please complete all IPQC checkpoints before submit.',
                16,
                1
            );
            RETURN;
        END;


        /* ========================================================
           3. DETERMINE CURRENT IPQC AUDIT STATUS

           3 = Waiting For Approval - OK
           4 = Waiting For Approval - NOK

           Any NOK -> 4
           All OK  -> 3
        ======================================================== */

        SELECT
            @NOKCount = COUNT(*)
        FROM QA_Execute_IPQC_AuditPoint
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID
          AND Result = 2;


        IF @NOKCount > 0
            SET @AuditStatus = 4;
        ELSE
            SET @AuditStatus = 3;


        /* ========================================================
           4. UPDATE IPQC AUDIT HEADER

           3 = Waiting For Approval - OK
           4 = Waiting For Approval - NOK
        ======================================================== */

        UPDATE QA_Execute_IPQC_AuditList
        SET
            Status = @AuditStatus,
            ExecutedEndTime = GETDATE(),
            ExecutedByRemark = @ExecutedByRemark
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID;


        /* ========================================================
           5. UPDATE CURRENT AUDIT SCHEDULE TO STATUS 3
           
           ONLY WHEN ALL AUDIT LISTS OF THIS DOCUMENT ARE COMPLETE.

           QA_AuditMonitoring:
           0 = Not Started
           1 = Plan
           2 = Inprocess
           3 = Complete
        ======================================================== */

        SELECT
            @IncompleteAuditCount = COUNT(*)
        FROM QA_AuditMonitoring M
        INNER JOIN Config_AuditList AL
            ON M.AuditListID = AL.AuditListID
        WHERE AL.DocumentID = @DocumentID
          AND M.Status IN (0, 1, 2);


        IF @IncompleteAuditCount = 0
        BEGIN

            UPDATE Config_AuditSchedule
            SET
                Status = 3
            WHERE DocumentID = @DocumentID
              AND AuditInstanceID = @AuditInstanceID;

        END;


        /* ========================================================
           6. UPDATE CURRENT AUDIT MONITORING

           Current Audit:
           2 = Inprocess
           3 = Complete
        ======================================================== */

        UPDATE QA_AuditMonitoring
        SET
            Status = 3,
            ActualEndDateTime = GETDATE()
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID
          AND Status = 2;


        /* ========================================================
           7. RE-CHECK ALL AUDIT LISTS OF DOCUMENT

           This check is performed AFTER current AuditList
           is changed to Complete.
        ======================================================== */

        SELECT
            @IncompleteAuditCount = COUNT(*)
        FROM QA_AuditMonitoring M
        INNER JOIN Config_AuditList AL
            ON M.AuditListID = AL.AuditListID
        WHERE AL.DocumentID = @DocumentID
          AND M.Status IN (0, 1, 2);


        /* ========================================================
           8. MOVE IPQC CHECKPOINTS TO HISTORY
        ======================================================== */

        INSERT INTO QA_Execute_IPQC_AuditPoint_History
        (
            AuditPointID,
            AuditListID,
            ObservationValue,
            Result,
            Remark,
            [TimeStamp],
            AuditInstanceID,
            Revision,
            TicketID
        )
        SELECT
            AuditPointID,
            AuditListID,
            ObservationValue,
            Result,
            Remark,
            [TimeStamp],
            AuditInstanceID,
            Revision,
            TicketID
        FROM QA_Execute_IPQC_AuditPoint
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID;


        /* ========================================================
           9. DELETE IPQC CHECKPOINTS FROM EXECUTION
        ======================================================== */

        DELETE
        FROM QA_Execute_IPQC_AuditPoint
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID;


        /* ========================================================
           10. MOVE IPQC AUDIT HEADER TO HISTORY

           Keep the same calculated status:
           3 = Waiting For Approval - OK
           4 = Waiting For Approval - NOK
        ======================================================== */

        INSERT INTO QA_Execute_IPQC_AuditList_History
        (
            AuditListID,
            Status,
            ProdDate,
            ProdShift,
            AuditInstanceID,
            ExecutedStartTime,
            ExecutedBy,
            ExecutedEndTime,
            ExecutedByRemark,
            ApprovedBy,
            ApprovedTime,
            ApprovedByRemark,
            ReviewBy,
            ReviewTime,
            ReviewByRemark,
            Revision
        )
        SELECT
            AuditListID,
            @AuditStatus,
            ProdDate,
            ProdShift,
            AuditInstanceID,
            ExecutedStartTime,
            ExecutedBy,
            ExecutedEndTime,
            ExecutedByRemark,
            ApprovedBy,
            ApprovedTime,
            ApprovedByRemark,
            ReviewBy,
            ReviewTime,
            ReviewByRemark,
            Revision
        FROM QA_Execute_IPQC_AuditList
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID;


        /* ========================================================
           11. DELETE IPQC AUDIT HEADER
        ======================================================== */

        DELETE
        FROM QA_Execute_IPQC_AuditList
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID;


        /* ========================================================
           12. UPDATE SCHEDULE TO COMPLETE
           
           This is done AFTER current AuditList becomes Complete.
           
           Only Status 0,1,2 means incomplete.
           If none exist -> Schedule Status = 3.
        ======================================================== */

        IF @IncompleteAuditCount = 0
        BEGIN

            UPDATE Config_AuditSchedule
            SET
                Status = 3
            WHERE DocumentID = @DocumentID
              AND AuditInstanceID = @AuditInstanceID;

        END;


        /* ========================================================
           13. MOVE DOCUMENT TO HISTORY

           Only when ALL AuditLists of the document are complete.
        ======================================================== */

        IF @IncompleteAuditCount = 0
        BEGIN

            INSERT INTO QA_Execute_DocumentList_History
            (
                DocumentID,
                DocumentNo,
                DocumentName,
                AuditGroup,
                Revision,
                AuditInstanceID
            )
            SELECT
                DocumentID,
                DocumentNo,
                DocumentName,
                AuditGroup,
                Revision,
                AuditInstanceID
            FROM QA_Execute_DocumentList
            WHERE DocumentID = @DocumentID
              AND AuditInstanceID = @AuditInstanceID;


            /* ====================================================
               14. DELETE EXECUTION DOCUMENT
            ==================================================== */

            DELETE
            FROM QA_Execute_DocumentList
            WHERE DocumentID = @DocumentID
              AND AuditInstanceID = @AuditInstanceID;

        END;


        /* ========================================================
           15. COMMIT TRANSACTION
        ======================================================== */

        COMMIT TRANSACTION;


        /* ========================================================
           16. SUCCESS RESPONSE
        ======================================================== */

        SELECT
            1 AS Success,
            @AuditListID AS AuditListID,
            @AuditInstanceID AS AuditInstanceID,
            @AuditStatus AS Status,
            CASE
                WHEN @AuditStatus = 3
                    THEN 'Waiting For Approval'
                WHEN @AuditStatus = 4
                    THEN 'Waiting For Approval - NOK'
                ELSE ''
            END AS StatusName,
            @IncompleteAuditCount AS IncompleteAuditCount,
            CASE
                WHEN @IncompleteAuditCount = 0
                    THEN 'Document Completed'
                ELSE 'Other AuditLists Pending'
            END AS DocumentStatus,
            'IPQC Audit Submitted Successfully' AS Message;


    END TRY

    BEGIN CATCH

        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        SELECT
            0 AS Success,
            ERROR_MESSAGE() AS Message,
            ERROR_NUMBER() AS ErrorNumber,
            ERROR_LINE() AS ErrorLine;

    END CATCH

END
GO

-- ------------------------------------------------------------------------
-- [356/376] Stored Procedure: [dbo].[Tab_Q_IPQC_AuditPoints_ForExecute]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[Tab_Q_IPQC_AuditPoints_ForExecute]
(
    @AuditListID INT,
    @AuditInstanceID INT
)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        -- Execution Table Details
        E.UID,
        E.AuditPointID,
        E.AuditListID,
        E.ObservationValue,
        E.Result,
        E.Remark,
        E.[TimeStamp],
        E.AuditInstanceID,
        E.Revision,
        E.TicketID,

        -- Configuration Table Details
        C.ModelID,
        M.ModelName,
        C.SKUID,
        S.SKUName,
        C.Category,
        C.AuditPointName,
        C.AuditPointProcess,
        C.UpperLimit,
        C.LowerLimit,
        C.CheckingMethod,
        C.Status AS ConfigStatus,
        C.Revision AS ConfigRevision

    FROM QA_Execute_IPQC_AuditPoint E

    INNER JOIN Config_IPQC_AuditPoint C
        ON E.AuditPointID = C.UID
        AND E.AuditListID = C.AuditListID

    LEFT JOIN Config_Model M
        ON C.ModelID = M.ModelID

    LEFT JOIN Config_SKU S
        ON C.SKUID = S.SKUID

    WHERE E.AuditListID = @AuditListID
      AND E.AuditInstanceID = @AuditInstanceID

    ORDER BY E.UID;
END
GO

-- ------------------------------------------------------------------------
-- [357/376] Stored Procedure: [dbo].[Tab_Q_IPQC_GetExecuted_CheckpointDetails]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
create PROCEDURE [dbo].[Tab_Q_IPQC_GetExecuted_CheckpointDetails]
    @AuditListID INT,
    @AuditInstanceID BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        H.UID,
        H.AuditListID,
        H.AuditPointID,

        H.ObservationValue,

        H.Result,

        CASE H.Result
            WHEN 1 THEN 'OK'
            WHEN 2 THEN 'NOK'
            ELSE 'Unknown'
        END AS ResultName,

        H.Remark,
        H.[TimeStamp],
        H.AuditInstanceID,
        H.Revision,
        H.TicketID,

        -- Configuration Details
        C.ModelID,
        M.ModelName,

        C.SKUID,
        S.SKUName,

        C.Category,
        C.AuditPointName,
        C.AuditPointProcess,
        C.LowerLimit,
        C.UpperLimit,
        C.CheckingMethod

    FROM QA_Execute_IPQC_AuditPoint_History H

    LEFT JOIN Config_IPQC_AuditPoint C
        ON H.AuditListID = C.AuditListID
        AND H.AuditPointID = C.UID

    LEFT JOIN Config_Model M
        ON C.ModelID = M.ModelID

    LEFT JOIN Config_SKU S
        ON C.SKUID = S.SKUID

    WHERE
        H.AuditListID = @AuditListID
        AND H.AuditInstanceID = @AuditInstanceID

    ORDER BY H.UID;

END
GO

-- ------------------------------------------------------------------------
-- [358/376] Stored Procedure: [dbo].[Tab_Q_IPQC_GetScheduledAuditList]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE   PROCEDURE [dbo].[Tab_Q_IPQC_GetScheduledAuditList]
(
    @Group NVARCHAR(100)
)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        ---------------------------------------------------------
        -- Schedule Table Fields
        ---------------------------------------------------------
        SCH.UID,
        SCH.LineID,
        SCH.DocumentID,
        SCH.AuditInstanceID,
        SCH.StartDateTime,
        SCH.NextDueDate,

        SCH.FrequencyType,

        CASE SCH.FrequencyType
            WHEN 1 THEN 'Day'
            WHEN 2 THEN 'Count'
            WHEN 3 THEN 'Hourly'
            ELSE 'Unknown'
        END AS FrequencyTypeName,

        SCH.FrequencyValue,
        SCH.Notification,

        CASE SCH.Notification
            WHEN 1 THEN 'Alert'
            WHEN 2 THEN 'Warning'
            WHEN 3 THEN 'Alarm'
            WHEN 4 THEN 'Critical'
            ELSE 'Unknown'
        END AS NotificationName,

        SCH.Status,

        CASE SCH.Status
            WHEN 1 THEN 'Plan'
            WHEN 2 THEN 'In Process'
            WHEN 3 THEN 'Waiting For Approval'
            ELSE 'Unknown'
        END AS StatusName,


        ---------------------------------------------------------
        -- Audit List Details
        ---------------------------------------------------------
        AL.AuditListID,
        AL.AuditListName,
        AL.ModelFamilyID,
        AL.ModelID,
        AL.SKUID,
        AL.PartID,


        ---------------------------------------------------------
        -- Document Details
        ---------------------------------------------------------
        D.DocumentNo,
        D.DocumentName,
        D.[Group],
        D.Revision,


        ---------------------------------------------------------
        -- Master Names
        ---------------------------------------------------------
        MF.ModelFamilyName,
        M.ModelName,
        SKU.SKUName,


        ---------------------------------------------------------
        -- Audit Monitoring Details
        ---------------------------------------------------------
        AM.UID AS MonitoringUID,
        AM.StartDateTime AS MonitoringStartDateTime,
        AM.EndDateTime AS MonitoringEndDateTime,
        AM.ActualStartDateTime,
        AM.ActualEndDateTime,
        AM.Notification AS MonitoringNotification,
        AM.Status AS MonitoringStatus,

        CASE AM.Status
            WHEN 1 THEN 'Plan'
            WHEN 2 THEN 'In Process'
            WHEN 3 THEN 'Waiting For Approval'
            ELSE 'Unknown'
        END AS MonitoringStatusName,

        CASE AM.Notification
            WHEN 1 THEN 'Alert'
            WHEN 2 THEN 'Warning'
            WHEN 3 THEN 'Alarm'
            WHEN 4 THEN 'Critical'
            ELSE 'Unknown'
        END AS MonitoringNotificationName


    FROM Config_AuditSchedule SCH


    ---------------------------------------------------------
    -- Document
    ---------------------------------------------------------
    INNER JOIN Config_QADocumentList D
        ON SCH.DocumentID = D.DocumentID


    ---------------------------------------------------------
    -- Audit List
    ---------------------------------------------------------
    LEFT JOIN Config_AuditList AL
        ON SCH.DocumentID = AL.DocumentID


    ---------------------------------------------------------
    -- Model Family
    ---------------------------------------------------------
    LEFT JOIN Config_ModelFamily MF
        ON AL.ModelFamilyID = MF.ModelFamilyID


    ---------------------------------------------------------
    -- Model
    ---------------------------------------------------------
    LEFT JOIN Config_Model M
        ON AL.ModelID = M.ModelID


    ---------------------------------------------------------
    -- SKU
    ---------------------------------------------------------
    LEFT JOIN Config_SKU SKU
        ON AL.SKUID = SKU.SKUID


    ---------------------------------------------------------
    -- Audit Monitoring
    ---------------------------------------------------------
    LEFT JOIN QA_AuditMonitoring AM
        ON AM.AuditListID = AL.AuditListID
        AND AM.AuditInstanceID = SCH.AuditInstanceID


    ---------------------------------------------------------
    -- Group Filter
    ---------------------------------------------------------
    WHERE D.[Group] = @Group


      ---------------------------------------------------------
      -- Active Schedule
      ---------------------------------------------------------
      AND SCH.Status IN (1, 2)


      ---------------------------------------------------------
      -- Active Notification
      ---------------------------------------------------------
      AND SCH.Notification IN (2, 3, 4)


      ---------------------------------------------------------
      -- Active Audit Monitoring
      ---------------------------------------------------------
      AND EXISTS
      (
          SELECT 1
          FROM QA_AuditMonitoring AM2
          WHERE AM2.AuditListID = AL.AuditListID
            AND AM2.AuditInstanceID = SCH.AuditInstanceID
            AND AM2.Status IN (1, 2)
            AND AM2.Notification IN (2, 3, 4)
      )


    ---------------------------------------------------------
    -- Order
    ---------------------------------------------------------
    ORDER BY
        SCH.StartDateTime DESC,
        SCH.DocumentID,
        AL.AuditListID;


    ---------------------------------------------------------
    -- No Data
    ---------------------------------------------------------
    IF @@ROWCOUNT = 0
    BEGIN
        SELECT
            0 AS Status,
            'No Active Schedule Found For The Given Group' AS Message;
    END

END
GO

-- ------------------------------------------------------------------------
-- [359/376] Stored Procedure: [dbo].[Tab_Q_IPQC_GetWaitingForApprovalIPQCAuditList]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
create PROCEDURE [dbo].[Tab_Q_IPQC_GetWaitingForApprovalIPQCAuditList]
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        ---------------------------------------------------------
        -- History
        ---------------------------------------------------------
        H.UID,

        H.AuditListID,
        AL.AuditListName,

        ---------------------------------------------------------
        -- Document Details
        ---------------------------------------------------------
        D.DocumentID,
        D.DocumentNo,
        D.DocumentName,
        D.[Group],
        D.Revision AS DocumentRevision,

        ---------------------------------------------------------
        -- Model Family
        ---------------------------------------------------------
        MF.ModelFamilyID,
        MF.ModelFamilyName,

        ---------------------------------------------------------
        -- Model
        ---------------------------------------------------------
        M.ModelID,
        M.ModelName,

        ---------------------------------------------------------
        -- SKU
        ---------------------------------------------------------
        SK.SKUID,
        SK.SKUName,

        ---------------------------------------------------------
        -- Audit Status
        ---------------------------------------------------------
        H.Status,

        CASE H.Status
            WHEN 3 THEN 'Waiting for Approval - OK'
            WHEN 4 THEN 'Waiting for Approval - NOK'
            ELSE 'Unknown'
        END AS StatusName,

        ---------------------------------------------------------
        -- Production Details
        ---------------------------------------------------------
        H.ProdDate,
        H.ProdShift,

        H.AuditInstanceID,

        ---------------------------------------------------------
        -- Execution Details
        ---------------------------------------------------------
        H.ExecutedStartTime,
        H.ExecutedBy,

        H.ExecutedEndTime,
        H.ExecutedByRemark,

        ---------------------------------------------------------
        -- Approval Details
        ---------------------------------------------------------
        H.ApprovedBy,
        H.ApprovedTime,
        H.ApprovedByRemark,

        ---------------------------------------------------------
        -- Review Details
        ---------------------------------------------------------
        H.ReviewBy,
        H.ReviewTime,
        H.ReviewByRemark,

        H.Revision,

        ---------------------------------------------------------
        -- Schedule Details
        ---------------------------------------------------------
        SCH.FrequencyType,

        CASE SCH.FrequencyType
            WHEN 1 THEN 'Day'
            WHEN 2 THEN 'Count'
            WHEN 3 THEN 'Hourly'
            ELSE ''
        END AS FrequencyTypeName,

        SCH.FrequencyValue,
        SCH.StartDateTime,
        SCH.NextDueDate

    FROM QA_Execute_IPQC_AuditList_History H

    ---------------------------------------------------------
    -- Audit List
    ---------------------------------------------------------
    INNER JOIN Config_AuditList AL
        ON H.AuditListID = AL.AuditListID

    ---------------------------------------------------------
    -- Document
    ---------------------------------------------------------
    INNER JOIN Config_QADocumentList D
        ON AL.DocumentID = D.DocumentID

    ---------------------------------------------------------
    -- Model Family
    ---------------------------------------------------------
    LEFT JOIN Config_ModelFamily MF
        ON AL.ModelFamilyID = MF.ModelFamilyID

    ---------------------------------------------------------
    -- Model
    ---------------------------------------------------------
    LEFT JOIN Config_Model M
        ON AL.ModelID = M.ModelID

    ---------------------------------------------------------
    -- SKU
    ---------------------------------------------------------
    LEFT JOIN Config_SKU SK
        ON AL.SKUID = SK.SKUID

    ---------------------------------------------------------
    -- Schedule
    ---------------------------------------------------------
    LEFT JOIN Config_AuditSchedule SCH
        ON SCH.DocumentID = AL.DocumentID
       AND SCH.AuditInstanceID = H.AuditInstanceID

    ---------------------------------------------------------
    -- WAITING FOR APPROVAL
    -- 3 = OK
    -- 4 = NOK
    ---------------------------------------------------------
    WHERE H.Status IN (3, 4)

    ORDER BY H.ExecutedEndTime DESC;

END
GO

-- ------------------------------------------------------------------------
-- [360/376] Stored Procedure: [dbo].[Tab_Q_IPQC_MonitoringScreenInspectBtn]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE   PROCEDURE [dbo].[Tab_Q_IPQC_MonitoringScreenInspectBtn]
(
    @DocumentID INT,
    @AuditListID INT,
    @ExecutedBy NVARCHAR(100)
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY

        DECLARE @AuditInstanceID BIGINT;
        DECLARE @ProdDate DATE;
        DECLARE @ProdShift NVARCHAR(50);

        /* =========================================================
           1. CHECK IF AUDIT IS ALREADY IN PROGRESS
        ========================================================= */

        IF EXISTS
        (
            SELECT 1
            FROM QA_Execute_IPQC_AuditList
            WHERE AuditListID = @AuditListID
              AND ExecutedEndTime IS NULL
        )
        BEGIN
            RAISERROR('Audit already in progress.', 16, 1);
            RETURN;
        END;


        /* =========================================================
           2. GET AUDIT INSTANCE ID FROM AUDIT SCHEDULE
        ========================================================= */

        SELECT TOP 1
            @AuditInstanceID = AuditInstanceID
        FROM Config_AuditSchedule
        WHERE DocumentID = @DocumentID
        ORDER BY UID DESC;


        IF @AuditInstanceID IS NULL
        BEGIN
            RAISERROR('Audit Schedule not found.', 16, 1);
            RETURN;
        END;


        /* =========================================================
           3. GET CURRENT PRODUCTION DATE
        ========================================================= */

        SELECT TOP 1
            @ProdDate = TRY_CONVERT(DATE, [ParameterValue], 105)
        FROM ApplicationSetting
        WHERE [ParameterName] = 'ProdDate'
        ORDER BY UID DESC;


        /* =========================================================
           4. GET CURRENT PRODUCTION SHIFT
        ========================================================= */

        SELECT TOP 1
            @ProdShift = [ParameterValue]
        FROM ApplicationSetting
        WHERE [ParameterName] = 'ProdShift'
        ORDER BY UID DESC;


        IF @ProdDate IS NULL
        BEGIN
            RAISERROR(
                'Production Date not found or invalid in ApplicationSetting.',
                16,
                1
            );
            RETURN;
        END;


        IF @ProdShift IS NULL
           OR LTRIM(RTRIM(@ProdShift)) = ''
        BEGIN
            RAISERROR(
                'Production Shift not found in ApplicationSetting.',
                16,
                1
            );
            RETURN;
        END;


        /* =========================================================
           5. VALIDATE AUDIT LIST
        ========================================================= */

        IF NOT EXISTS
        (
            SELECT 1
            FROM Config_AuditList
            WHERE AuditListID = @AuditListID
              AND DocumentID = @DocumentID
        )
        BEGIN
            RAISERROR(
                'Invalid AuditListID for the selected DocumentID.',
                16,
                1
            );
            RETURN;
        END;


        /* =========================================================
           6. TRANSACTION START
        ========================================================= */

        BEGIN TRANSACTION;


        /* =========================================================
           7. INSERT EXECUTION DOCUMENT
        ========================================================= */

        INSERT INTO QA_Execute_DocumentList
        (
            DocumentID,
            DocumentNo,
            DocumentName,
            AuditGroup,
            Revision,
            AuditInstanceID
        )
        SELECT
            DocumentID,
            DocumentNo,
            DocumentName,
            [Group],
            Revision,
            @AuditInstanceID
        FROM Config_QADocumentList
        WHERE DocumentID = @DocumentID;


      /* ========================================================= 
   8. INSERT IPQC AUDIT HEADER
========================================================= */

INSERT INTO QA_Execute_IPQC_AuditList 
(
    AuditListID, 
    Status, 
    ProdDate, 
    ProdShift, 
    AuditInstanceID, 
    ExecutedStartTime, 
    ExecutedBy, 
    ExecutedEndTime, 
    ExecutedByRemark, 
    ApprovedBy, 
    ApprovedTime, 
    ApprovedByRemark, 
    ReviewBy, 
    ReviewTime, 
    ReviewByRemark, 
    Revision 
) 
SELECT 
    AL.AuditListID, 
    2,
    @ProdDate, 
    @ProdShift, 
    @AuditInstanceID, 
    GETDATE() AS ExecutedStartTime, 
    @ExecutedBy, 
    NULL AS ExecutedEndTime, 
    NULL AS ExecutedByRemark, 
    NULL AS ApprovedBy, 
    NULL AS ApprovedTime, 
    NULL AS ApprovedByRemark, 
    NULL AS ReviewBy, 
    NULL AS ReviewTime, 
    NULL AS ReviewByRemark, 
    D.Revision
FROM Config_AuditList AL
INNER JOIN Config_QADocumentList D
    ON D.DocumentID = AL.DocumentID
WHERE AL.AuditListID = @AuditListID 
  AND AL.DocumentID = @DocumentID;


       /* =========================================================
   9. INSERT IPQC CHECKPOINTS

   For each AuditPointID:
   - Only Status = 1 (Enabled) records are considered
   - Highest Revision is selected
   - Only that latest revision is inserted
========================================================= */

INSERT INTO QA_Execute_IPQC_AuditPoint
(
    AuditPointID,
    AuditListID,
    ObservationValue,
    Result,
    Remark,
    [TimeStamp],
    AuditInstanceID,
    Revision,
    TicketID
)
SELECT
    C.UID AS AuditPointID,
    C.AuditListID,
    NULL AS ObservationValue,
    NULL AS Result,
    NULL AS Remark,
    GETDATE() AS [TimeStamp],
    @AuditInstanceID,
    C.Revision,
    NULL AS TicketID
FROM
(
    SELECT
        C.UID,
        C.AuditPointID,
        C.AuditListID,
        C.Revision,
        ROW_NUMBER() OVER
        (
            PARTITION BY C.AuditListID, C.AuditPointID
            ORDER BY C.Revision DESC
        ) AS RN
    FROM Config_IPQC_AuditPoint C
    WHERE C.AuditListID = @AuditListID
      AND C.Status = 1
) C
WHERE C.RN = 1;

        /* =========================================================
           10. UPDATE AUDIT SCHEDULE
        ========================================================= */

        UPDATE Config_AuditSchedule
        SET Status = 2,
		Notification = 1
        WHERE DocumentID = @DocumentID
          AND Status = 1;


        /* =========================================================
           11. UPDATE AUDIT MONITORING
        ========================================================= */

        UPDATE QA_AuditMonitoring
        SET
            Status = 2,
			Notification = 1,
            ActualStartDateTime = GETDATE(),
            AuditInstanceID = @AuditInstanceID
        WHERE AuditListID = @AuditListID
          AND Status = 1;


        /* =========================================================
           12. COMMIT TRANSACTION
        ========================================================= */

        COMMIT TRANSACTION;


        /* =========================================================
           13. SUCCESS RESPONSE
        ========================================================= */

        SELECT
            1 AS Success,
            'IPQC Audit Executed Successfully' AS Message,
            @AuditInstanceID AS AuditInstanceID,
            @ProdDate AS ProdDate,
            @ProdShift AS ProdShift;


    END TRY

    BEGIN CATCH

        /* =========================================================
           ROLLBACK IF ERROR
        ========================================================= */

        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;


        SELECT
            0 AS Success,
            ERROR_MESSAGE() AS Message,
            ERROR_NUMBER() AS ErrorNumber,
            ERROR_LINE() AS ErrorLine;

    END CATCH

END
GO

-- ------------------------------------------------------------------------
-- [361/376] Stored Procedure: [dbo].[Tab_Q_IPQC_UpdateCheckpointResult]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
create PROCEDURE [dbo].[Tab_Q_IPQC_UpdateCheckpointResult]
(
    @UID INT,
    @Result INT,
    @Remark NVARCHAR(500) = NULL,
    @ObservationValue NVARCHAR(500) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    /* ============================================================
       1. VALIDATE UID
       ============================================================ */

    IF @UID IS NULL OR @UID <= 0
    BEGIN
        RAISERROR(
            'Invalid UID. UID must be provided.',
            16,
            1
        );
        RETURN;
    END;


    /* ============================================================
       2. VALIDATE RESULT

       1 = OK
       2 = NOK
       ============================================================ */

    IF @Result NOT IN (1, 2)
    BEGIN
        RAISERROR(
            'Invalid Result. Result must be 1 (OK) or 2 (NOK).',
            16,
            1
        );
        RETURN;
    END;


    /* ============================================================
       3. CHECK EXECUTION RECORD
       ============================================================ */

    IF NOT EXISTS
    (
        SELECT 1
        FROM [dbo].[QA_Execute_IPQC_AuditPoint]
        WHERE UID = @UID
    )
    BEGIN
        RAISERROR(
            'IPQC checkpoint execution record not found for the given UID.',
            16,
            1
        );
        RETURN;
    END;


    /* ============================================================
       4. UPDATE CHECKPOINT RESULT
       ============================================================ */

    UPDATE [dbo].[QA_Execute_IPQC_AuditPoint]
    SET
        ObservationValue = @ObservationValue,
        Result = @Result,
        Remark = @Remark,
        [TimeStamp] = GETDATE()
    WHERE UID = @UID;


    /* ============================================================
       5. RETURN UPDATED RECORD
       ============================================================ */

    SELECT
        UID,
        AuditPointID,
        AuditListID,
        ObservationValue,
        Result,
        Remark,
        [TimeStamp],
        AuditInstanceID,
        Revision,
        TicketID
    FROM [dbo].[QA_Execute_IPQC_AuditPoint]
    WHERE UID = @UID;

END
GO

-- ------------------------------------------------------------------------
-- [362/376] Stored Procedure: [dbo].[Tab_Q_IQC_ApproveIQCAudit]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[Tab_Q_IQC_ApproveIQCAudit]
(
    @AuditListID INT,
    @PartID NVARCHAR(50),
    @AuditInstanceID BIGINT,
    @ApprovedBy NVARCHAR(100),
    @ApprovedByRemark NVARCHAR(500) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY

        BEGIN TRANSACTION;

        DECLARE @DocumentID INT;

        ------------------------------------------------------------
        -- Validate PartID
        ------------------------------------------------------------
        IF @PartID IS NULL OR LTRIM(RTRIM(@PartID)) = ''
        BEGIN
            RAISERROR('PartID is required.', 16, 1);
            ROLLBACK TRANSACTION;
            RETURN;
        END;

        ------------------------------------------------------------
        -- Get DocumentID and validate Audit
        ------------------------------------------------------------
        SELECT TOP 1
            @DocumentID = D.DocumentID
        FROM QA_Execute_IQC_AuditList_History H
        INNER JOIN Config_AuditList D
            ON H.AuditListID = D.AuditListID
        WHERE H.AuditListID = @AuditListID
          AND H.PartID = @PartID
          AND H.AuditInstanceID = @AuditInstanceID;

        ------------------------------------------------------------
        -- Validate Audit exists for given PartID
        ------------------------------------------------------------
        IF @DocumentID IS NULL
        BEGIN
            RAISERROR(
                'No IQC audit found for the given AuditListID, PartID and AuditInstanceID.',
                16,
                1
            );
            ROLLBACK TRANSACTION;
            RETURN;
        END;

        ------------------------------------------------------------
        -- Validate Audit is in In-Process / Waiting for Approval
        -- Status = 1
        ------------------------------------------------------------
        IF NOT EXISTS
        (
            SELECT 1
            FROM QA_Execute_IQC_AuditList_History
            WHERE AuditListID = @AuditListID
              AND PartID = @PartID
              AND AuditInstanceID = @AuditInstanceID
              AND Status = 1
        )
        BEGIN
            RAISERROR(
                'Audit is not available for approval or has already been approved.',
                16,
                1
            );
            ROLLBACK TRANSACTION;
            RETURN;
        END;

        ------------------------------------------------------------
        -- Update History
        ------------------------------------------------------------
        UPDATE QA_Execute_IQC_AuditList_History
        SET
            Status = 2,
            ApprovedBy = @ApprovedBy,
            ApprovedTime = GETDATE(),
            ApprovedByRemark = @ApprovedByRemark
        WHERE AuditListID = @AuditListID
          AND PartID = @PartID
          AND AuditInstanceID = @AuditInstanceID
          AND Status = 1;

        ------------------------------------------------------------
        -- Check update happened
        ------------------------------------------------------------
        IF @@ROWCOUNT = 0
        BEGIN
            RAISERROR(
                'Audit approval failed. No matching audit record found.',
                16,
                1
            );
            ROLLBACK TRANSACTION;
            RETURN;
        END;

        COMMIT TRANSACTION;

        ------------------------------------------------------------
        -- Success Response
        ------------------------------------------------------------
        SELECT
            1 AS Success,
            'Audit Approved Successfully' AS Message,
            @DocumentID AS DocumentID,
            @AuditListID AS AuditListID,
            @PartID AS PartID,
            @AuditInstanceID AS AuditInstanceID;

    END TRY

    BEGIN CATCH

        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        SELECT
            0 AS Success,
            ERROR_MESSAGE() AS Message;

    END CATCH
END
GO

-- ------------------------------------------------------------------------
-- [363/376] Stored Procedure: [dbo].[Tab_Q_IQC_GetApprovedIQCAuditHistory]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[Tab_Q_IQC_GetApprovedIQCAuditHistory]
    @DocumentID INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT 
        H.UID,
        H.AuditListID,

        -- Document
        A.DocumentID,

        -- Model Family
        H.ModelFamilyID,
        MF.ModelFamilyName,

        -- Model
        H.ModelID,
        M.ModelName,

        -- SKU
        H.SKUID,
        S.SKUName,

        -- Part
        H.PartID,
        P.PartName,

        -- Vendor
        H.VendorID,
        V.VendorName,

        -- Sample Details
        H.SampleLevel,
        H.SampleSize,
        H.NokSample,

        -- Status
        H.Status,
        CASE H.Status
            WHEN 1 THEN 'Waiting For Approval'
            WHEN 2 THEN 'Approved'
            ELSE 'Unknown'
        END AS StatusName,

        -- Production Details
        H.ProdDate,
        H.ProdShift,

        -- Audit Instance
        H.AuditInstanceID,

        -- Execution Details
        H.ExecutedStartTime,
        H.ExecutedBy,
        H.ExecutedEndTime,
        H.ExecutedByRemark,

        -- Approval Details
        H.ApprovedBy,
        H.ApprovedTime,
        H.ApprovedByRemark,

        -- Review Details
        H.ReviewBy,
        H.ReviewTime,
        H.ReviewByRemark,

        H.Revision,

        -- Audit List
        A.AuditListName

    FROM QA_Execute_IQC_AuditList_History H

    INNER JOIN Config_AuditList A
        ON H.AuditListID = A.AuditListID
        AND A.DocumentID = @DocumentID

    LEFT JOIN Config_Model M
        ON H.ModelID = M.ModelID

    LEFT JOIN Config_ModelFamily MF
        ON H.ModelFamilyID = MF.ModelFamilyID

    LEFT JOIN Config_SKU S
        ON H.SKUID = S.SKUID

    LEFT JOIN Config_Vendor V
        ON H.VendorID = V.VendorID

    LEFT JOIN  Config_PartVariant P
        ON H.PartID = P.PartID

    WHERE H.Status = 2

    ORDER BY
        H.AuditInstanceID DESC,
        H.UID;
END
GO

-- ------------------------------------------------------------------------
-- [364/376] Stored Procedure: [dbo].[Tab_Q_IQC_GetCheckpointDetailsForExecute]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[Tab_Q_IQC_GetCheckpointDetailsForExecute]
(
    @DocumentID INT,
    @AuditListID INT,
    @PartID NVARCHAR(50) = NULL,
    @SampleLevel INT = NULL,
    @SampleNo INT = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
 
    /* ============================================================
       DOCUMENT ID = 1
       IQC VISUAL INSPECTION
       ============================================================ */
 
    IF @DocumentID = 1
    BEGIN
 
        SELECT
            E.UID,
            E.AuditListID,
            E.AuditPointID,
            E.PartScanID,
            E.SampleLevel,
            E.SampleNo,
            E.Aspect AS ExecutionAspect,
            E.Result,
            E.Remark,
            E.Timestamp,
            E.AuditInstanceID,
            E.Status,
            E.Revision,
 
            C.UID AS ConfigUID,
            C.ModelFamilyID,
            C.ModelID,
            C.AuditPointName,
            C.Aspect AS ConfigAspect,
            C.CheckingMethod,
 
            M.ModelName,
            MF.ModelFamilyName
 
        FROM dbo.QA_Execute_IQC_VisualInspectAuditPoint E
 
        LEFT JOIN dbo.Config_IQC_VisualInspectAuditPoint C
            ON E.AuditListID = C.AuditListID
            AND E.AuditPointID = C.UID
 
        LEFT JOIN dbo.Config_Model M
            ON C.ModelID = M.ModelID
 
        LEFT JOIN dbo.Config_ModelFamily MF
            ON C.ModelFamilyID = MF.ModelFamilyID
 
        WHERE E.AuditListID = @AuditListID
 
          AND (
                @SampleLevel IS NULL
                OR E.SampleLevel = @SampleLevel
              )
 
          AND (
                @SampleNo IS NULL
                OR E.SampleNo = @SampleNo
              )
 
        ORDER BY
            E.AuditPointID,
            E.SampleLevel,
            E.SampleNo;
 
        RETURN;
    END;
 
 
    /* ============================================================
       DOCUMENT ID = 2
       IQC MILIPORE
       ============================================================ */
 
    IF @DocumentID = 2
    BEGIN
 
        SELECT
            E.UID,
            E.AuditListID,
            E.AuditPointID,
            E.PartScanID,
            E.SampleLevel,
            E.SampleNo,
            E.ObservationValue,
            E.Result,
            E.Remark,
            E.Timestamp,
            E.AuditInstanceID,
            E.Status,
            E.Revision,
 
            C.UID AS ConfigUID,
            C.PartID AS ConfigPartID,
            C.VendorID,
            C.AuditPointId,
            C.TargetLimit,
            C.SpecificationLimit,
 
            P.PartName,
            V.VendorName
 
        FROM dbo.QA_Execute_IQC_MiliporeAuditpoint E
 
        LEFT JOIN dbo.Config_IQC_MiliporeAuditPoint C
            ON E.AuditListID = C.AuditListID
            AND E.AuditPointID = C.UID
 
        LEFT JOIN dbo.Config_PartVariant P
            ON C.PartID = P.PartID
 
        LEFT JOIN dbo.Config_Vendor V
            ON C.VendorID = V.VendorID
 
        WHERE E.AuditListID = @AuditListID
 
          AND (
                @SampleLevel IS NULL
                OR E.SampleLevel = @SampleLevel
              )
 
          AND (
                @SampleNo IS NULL
                OR E.SampleNo = @SampleNo
              )
 
        ORDER BY
            E.AuditPointID,
            E.SampleLevel,
            E.SampleNo;
 
        RETURN;
    END;
 
 
    /* ============================================================
       INVALID DOCUMENT ID
       ============================================================ */
 
    SELECT
        0 AS Success,
        'Invalid DocumentID. Use 1 for Visual Inspection or 2 for Milipore.' AS Message;
 
END;
GO

-- ------------------------------------------------------------------------
-- [365/376] Stored Procedure: [dbo].[Tab_Q_IQC_GetExecutedCheckpointDetails]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[Tab_Q_IQC_GetExecutedCheckpointDetails]

    @DocumentID INT,

    @AuditListID INT,

    @AuditInstanceID BIGINT

AS

BEGIN

    SET NOCOUNT ON;
 
    ------------------------------------------------------------

    -- DocumentID = 1 : Visual Inspection

    ------------------------------------------------------------

    IF @DocumentID = 1

    BEGIN
 
        SELECT

            H.UID,

            H.AuditListID,

            H.AuditPointID,

            H.PartScanID,
 
            H.Aspect AS HistoryAspect,
 
            H.SampleLevel,

            H.SampleNo,
 
            H.Result,
 
            CASE H.Result

                WHEN 1 THEN 'OK'

                WHEN 2 THEN 'NOK'

                ELSE 'Unknown'

            END AS ResultName,
 
            H.Remark,

            H.Timestamp,

            H.Status,

            H.AuditInstanceID,

            H.Revision,
 
            -- Configuration Details

            C.AuditPointName,

            C.Aspect AS ConfigAspect
 
        FROM QA_Execute_IQC_VisualInspectAuditPoint_History H
 
        LEFT JOIN Config_IQC_VisualInspectAuditPoint C

            ON H.AuditListID = C.AuditListID

            AND H.AuditPointID = C.AuditPointId
 
        WHERE

            H.AuditListID = @AuditListID

            AND H.AuditInstanceID = @AuditInstanceID
 
        ORDER BY

            H.SampleLevel,

            H.SampleNo,

            H.UID;
 
        RETURN;

    END;
 
 
    ------------------------------------------------------------

    -- DocumentID = 2 : Milipore

    ------------------------------------------------------------

    ELSE IF @DocumentID = 2

    BEGIN
 
        SELECT

            H.UID,

            H.AuditListID,

            H.AuditPointID,

            H.PartScanID,
 
            H.ObservationValue,
 
            H.SampleLevel,

            H.SampleNo,
 
            H.Result,
 
            CASE H.Result

                WHEN 1 THEN 'OK'

                WHEN 2 THEN 'NOK'

                ELSE 'Unknown'

            END AS ResultName,
 
            H.Remark,

            H.Timestamp,

            H.AuditInstanceID,

            H.Status,

            H.Revision,
 
            -- Configuration Details

            C.PartID,

            C.VendorID,

            C.TargetLimit,

            C.SpecificationLimit
 
        FROM QA_Execute_IQC_MiliporeAuditpoint_History H
 
        LEFT JOIN Config_IQC_MiliporeAuditPoint C

            ON H.AuditListID = C.AuditListID

            AND H.AuditPointID = C.AuditPointId
 
        WHERE

            H.AuditListID = @AuditListID

            AND H.AuditInstanceID = @AuditInstanceID
 
        ORDER BY

            H.SampleLevel,

            H.SampleNo,

            H.UID;
 
        RETURN;

    END;
 
 
    ------------------------------------------------------------

    -- Invalid DocumentID

    ------------------------------------------------------------

    ELSE

    BEGIN

        RAISERROR(

            'Invalid DocumentID. DocumentID must be 1 or 2.',

            16,

            1

        );

        RETURN;

    END;
 
END
GO

-- ------------------------------------------------------------------------
-- [366/376] Stored Procedure: [dbo].[Tab_Q_IQC_GetPlannedIQCAuditList]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[Tab_Q_IQC_GetPlannedIQCAuditList]
    @DocumentID INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
        Q.UID,
        Q.AuditListID,

        -- Model / Part Details
        Q.ModelFamilyID,
        MF.ModelFamilyName,

        Q.ModelID,
        M.ModelName,

        Q.SKUID,
        S.SKUName,

        Q.PartID,
        P.PartName,

        Q.VendorID,
        V.VendorName,

        Q.BatchID,

        -- Material Receiving Details
        MR.ValidatedQty,
		MR.EDINumber,
        Q.SampleLevel,
        Q.SampleSize,
        Q.NokSample,

        -- Status
        Q.Status,
        CASE Q.Status
            WHEN 1 THEN 'Plan'
            WHEN 2 THEN 'Inprocess'
            WHEN 3 THEN 'OK'
            WHEN 4 THEN 'NOK'
            WHEN 5 THEN 'Bypass'
            ELSE 'Unknown'
        END AS StatusName,

        -- Production Details
        Q.ProdDate,
        Q.ProdShift,

        -- Audit Instance
        Q.AuditInstanceID,

        -- Execution Details
        Q.ExecutedStartTime,
        Q.ExecutedBy,
        Q.ExecutedEndTime,
        Q.ExecutedByRemark,

        -- Approval Details
        Q.ApprovedBy,
        Q.ApprovedTime,
        Q.ApprovedByRemark,

        -- Review Details
        Q.ReviewBy,
        Q.ReviewTime,
        Q.ReviewByRemark,

        Q.Revision,

        -- Audit List Details
        A.DocumentID,
        A.AuditListName,

        -- Document Details
        D.DocumentNo,
        D.DocumentName,
        D.[Group],
        D.Revision AS DocumentRevision

    FROM QA_Execute_IQC_AuditList Q

    INNER JOIN Config_AuditList A
        ON Q.AuditListID = A.AuditListID

    INNER JOIN Config_QADocumentList D
        ON A.DocumentID = D.DocumentID

    LEFT JOIN  Config_PartVariant P
        ON Q.PartID = P.PartID

    LEFT JOIN Config_Model M
        ON Q.ModelID = M.ModelID

    LEFT JOIN Config_ModelFamily MF
        ON Q.ModelFamilyID = MF.ModelFamilyID

    LEFT JOIN Config_SKU S
        ON Q.SKUID = S.SKUID

    LEFT JOIN Config_Vendor V
        ON Q.VendorID = V.VendorID

    OUTER APPLY
    (
        SELECT TOP 1
            MR.ValidatedQty,MR.EDINumber
        FROM Material_Receiving MR
        WHERE MR.PartID = Q.PartID
          AND MR.BatchID = Q.BatchID
        ORDER BY MR.UID DESC
    ) MR

    WHERE
        A.DocumentID = @DocumentID

    ORDER BY
        Q.UID;
END
GO

-- ------------------------------------------------------------------------
-- [367/376] Stored Procedure: [dbo].[Tab_Q_IQC_GetWaitingForApprovalAuditHistory]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[Tab_Q_IQC_GetWaitingForApprovalAuditHistory]
    @DocumentID INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT 
        H.UID,
        H.AuditListID,

        -- Document
        A.DocumentID,

        -- Model Family
        H.ModelFamilyID,
        MF.ModelFamilyName,

        -- Model
        H.ModelID,
        M.ModelName,

        -- SKU
        H.SKUID,
        S.SKUName,

        -- Part
        H.PartID,
        P.PartName,

        -- Vendor
        H.VendorID,
        V.VendorName,

        -- Sample Details
        H.SampleLevel,
        H.SampleSize,
        H.NokSample,

        -- Status
        H.Status,
        CASE H.Status
            WHEN 1 THEN 'Waiting For Approval'
            WHEN 2 THEN 'Approved'
            ELSE 'Unknown'
        END AS StatusName,

        -- Production Details
        H.ProdDate,
        H.ProdShift,

        -- Audit Instance
        H.AuditInstanceID,

        -- Execution Details
        H.ExecutedStartTime,
        H.ExecutedBy,
        H.ExecutedEndTime,
        H.ExecutedByRemark,

        -- Approval Details
        H.ApprovedBy,
        H.ApprovedTime,
        H.ApprovedByRemark,

        -- Review Details
        H.ReviewBy,
        H.ReviewTime,
        H.ReviewByRemark,

        H.Revision,

        -- Audit List
        A.AuditListName

    FROM QA_Execute_IQC_AuditList_History H

    INNER JOIN Config_AuditList A
        ON H.AuditListID = A.AuditListID
        AND A.DocumentID = @DocumentID

    LEFT JOIN Config_Model M
        ON H.ModelID = M.ModelID

    LEFT JOIN Config_ModelFamily MF
        ON H.ModelFamilyID = MF.ModelFamilyID

    LEFT JOIN Config_SKU S
        ON H.SKUID = S.SKUID

    LEFT JOIN Config_Vendor V
        ON H.VendorID = V.VendorID

    LEFT JOIN  Config_PartVariant P
        ON H.PartID = P.PartID

    WHERE H.Status = 4

    ORDER BY
        H.AuditInstanceID DESC,
        H.UID;
END
GO

-- ------------------------------------------------------------------------
-- [368/376] Stored Procedure: [dbo].[Tab_Q_IQC_MoveToNextSampleLevel]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[Tab_Q_IQC_MoveToNextSampleLevel]
(
    @DocumentID INT,
    @AuditListID INT,
    @AuditInstanceID BIGINT,
    @PartID NVARCHAR(50) = NULL,
    @VendorID INT = NULL,
    @ValidatedBy NVARCHAR(50) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
 
    BEGIN TRY
 
        BEGIN TRANSACTION;
 
        DECLARE
            @CurrentLevel INT,
            @NextLevel INT,
            @CurrentSampleQty INT,
            @NextSampleQty INT,
            @StartSampleNo INT,
            @EndSampleNo INT,
            @ExistingCount INT;
 
 
        /* ============================================================
           1. VALIDATE DOCUMENT
           ============================================================ */
 
        IF @DocumentID NOT IN (1, 2)
        BEGIN
            RAISERROR(
                'Invalid DocumentID. Only DocumentID 1 and 2 are supported.',
                16,
                1
            );
 
            ROLLBACK TRANSACTION;
            RETURN;
        END;
 
 
        /* ============================================================
           2. VALIDATE AUDIT PARAMETERS
           ============================================================ */
 
        IF @AuditListID IS NULL
        BEGIN
            RAISERROR(
                'AuditListID is required.',
                16,
                1
            );
 
            ROLLBACK TRANSACTION;
            RETURN;
        END;
 
 
        IF @AuditInstanceID IS NULL
        BEGIN
            RAISERROR(
                'AuditInstanceID is required.',
                16,
                1
            );
 
            ROLLBACK TRANSACTION;
            RETURN;
        END;
 
 
        /* ============================================================
           3. FIND CURRENT LEVEL
           Level 1 = Samples 1-5
           Level 2 = Samples 6-30
           Level 3 = Samples 31-80
 
           We use MAX(SampleLevel) so that if multiple checkpoints
           exist, the latest level is correctly identified.
           ============================================================ */
 
        IF @DocumentID = 1
        BEGIN
 
            SELECT
                @CurrentLevel = MAX(SampleLevel)
            FROM [dbo].[QA_Execute_IQC_VisualInspectAuditPoint]
            WHERE AuditListID = @AuditListID
              AND AuditInstanceID = @AuditInstanceID
              AND Status = 1;
 
        END
        ELSE IF @DocumentID = 2
        BEGIN
 
            SELECT
                @CurrentLevel = MAX(SampleLevel)
            FROM [dbo].[QA_Execute_IQC_MiliporeAuditpoint]
            WHERE AuditListID = @AuditListID
              AND AuditInstanceID = @AuditInstanceID
              AND Status = 1;
 
        END;
 
 
        /* ============================================================
           4. VALIDATE CURRENT LEVEL
           ============================================================ */
 
        IF @CurrentLevel IS NULL
        BEGIN
            RAISERROR(
                'No execution data found for the given AuditListID and AuditInstanceID.',
                16,
                1
            );
 
            ROLLBACK TRANSACTION;
            RETURN;
        END;
 
 
        /* ============================================================
           5. DETERMINE NEXT LEVEL AND SAMPLE NUMBER RANGE
           Level 1:
               Samples = 1-5
               Quantity = 5
 
           Level 2:
               Samples = 6-30
               Quantity = 25
 
           Level 3:
               Samples = 31-80
               Quantity = 50
           ============================================================ */
 
        IF @CurrentLevel = 1
        BEGIN
 
            SET @NextLevel = 2;
 
            SET @CurrentSampleQty = 5;
 
            SET @NextSampleQty = 25;
 
            SET @StartSampleNo = 6;
 
            SET @EndSampleNo = 30;
 
        END
        ELSE IF @CurrentLevel = 2
        BEGIN
 
            SET @NextLevel = 3;
 
            SET @CurrentSampleQty = 25;
 
            SET @NextSampleQty = 50;
 
            SET @StartSampleNo = 31;
 
            SET @EndSampleNo = 80;
 
        END
        ELSE IF @CurrentLevel = 3
        BEGIN
 
            /* ========================================================
               LEVEL 3 IS THE FINAL LEVEL
               ======================================================== */
 
            IF @DocumentID = 1
            BEGIN
 
                /* Move Level 3 to History */
 
                INSERT INTO
                    [dbo].[QA_Execute_IQC_VisualInspectAuditPoint_History]
                (
                    AuditListID,
                    AuditPointID,
                    Aspect,
                    PartScanID,
                    SampleLevel,
                    SampleNo,
                    Result,
                    Remark,
                    Timestamp,
                    Status,
                    AuditInstanceID,
                    Revision
                )
                SELECT
                    AuditListID,
                    AuditPointID,
                    Aspect,
                    PartScanID,
                    SampleLevel,
                    SampleNo,
                    Result,
                    Remark,
                    GETDATE(),
                    Status,
                    AuditInstanceID,
                    Revision
                FROM
                    [dbo].[QA_Execute_IQC_VisualInspectAuditPoint]
                WHERE AuditListID = @AuditListID
                  AND AuditInstanceID = @AuditInstanceID
                  AND SampleLevel = 3;
 
 
                /* Delete Level 3 from Execution */
 
                DELETE FROM
                    [dbo].[QA_Execute_IQC_VisualInspectAuditPoint]
                WHERE AuditListID = @AuditListID
                  AND AuditInstanceID = @AuditInstanceID
                  AND SampleLevel = 3;
 
            END
            ELSE IF @DocumentID = 2
            BEGIN
 
                /* Move Level 3 to History */
 
                INSERT INTO
                    [dbo].[QA_Execute_IQC_MiliporeAuditpoint_History]
                (
                    AuditListID,
                    AuditPointID,
                    PartScanID,
                    ObservationValue,
                    SampleLevel,
                    SampleNo,
                    Result,
                    Remark,
                    Timestamp,
                    AuditInstanceID,
                    Status,
                    Revision
                )
                SELECT
                    AuditListID,
                    AuditPointID,
                    PartScanID,
                    ObservationValue,
                    SampleLevel,
                    SampleNo,
                    Result,
                    Remark,
                    GETDATE(),
                    AuditInstanceID,
                    Status,
                    Revision
                FROM
                    [dbo].[QA_Execute_IQC_MiliporeAuditpoint]
                WHERE AuditListID = @AuditListID
                  AND AuditInstanceID = @AuditInstanceID
                  AND SampleLevel = 3;
 
 
                /* Delete Level 3 from Execution */
 
                DELETE FROM
                    [dbo].[QA_Execute_IQC_MiliporeAuditpoint]
                WHERE AuditListID = @AuditListID
                  AND AuditInstanceID = @AuditInstanceID
                  AND SampleLevel = 3;
 
            END;
 
 
            COMMIT TRANSACTION;
 
 
            SELECT
                @DocumentID AS DocumentID,
                @AuditListID AS AuditListID,
                @AuditInstanceID AS AuditInstanceID,
                3 AS PreviousLevel,
                NULL AS NextLevel,
                50 AS SampleQty,
                31 AS StartSampleNo,
                80 AS EndSampleNo,
                'Level 3 completed. No further sample level available.'
                    AS Message;
 
            RETURN;
 
        END
        ELSE
        BEGIN
 
            RAISERROR(
                'Invalid SampleLevel found in execution table.',
                16,
                1
            );
 
            ROLLBACK TRANSACTION;
            RETURN;
 
        END;
 
 
        /* ============================================================
           6. DOCUMENT ID = 1
              VISUAL INSPECTION
           ============================================================ */
 
        IF @DocumentID = 1
        BEGIN
 
            /* ========================================================
               6A. CHECK WHETHER CURRENT LEVEL DATA EXISTS
               ======================================================== */
 
            SELECT
                @ExistingCount = COUNT(*)
            FROM
                [dbo].[QA_Execute_IQC_VisualInspectAuditPoint]
            WHERE AuditListID = @AuditListID
              AND AuditInstanceID = @AuditInstanceID
              AND SampleLevel = @CurrentLevel;
 
 
            IF @ExistingCount = 0
            BEGIN
                RAISERROR(
                    'Current level data does not exist in Visual Inspection Execution table.',
                    16,
                    1
                );
 
                ROLLBACK TRANSACTION;
                RETURN;
            END;
 
 
            /* ========================================================
               6B. MOVE CURRENT LEVEL TO HISTORY
               ======================================================== */
 
            INSERT INTO
                [dbo].[QA_Execute_IQC_VisualInspectAuditPoint_History]
            (
                AuditListID,
                AuditPointID,
                Aspect,
                PartScanID,
                SampleLevel,
                SampleNo,
                Result,
                Remark,
                Timestamp,
                Status,
                AuditInstanceID,
                Revision
            )
            SELECT
                AuditListID,
                AuditPointID,
                Aspect,
                PartScanID,
                SampleLevel,
                SampleNo,
                Result,
                Remark,
                GETDATE(),
                Status,
                AuditInstanceID,
                Revision
            FROM
                [dbo].[QA_Execute_IQC_VisualInspectAuditPoint]
            WHERE AuditListID = @AuditListID
              AND AuditInstanceID = @AuditInstanceID
              AND SampleLevel = @CurrentLevel;
 
 
            /* ========================================================
               6C. DELETE CURRENT LEVEL FROM EXECUTION
               ======================================================== */
 
            DELETE FROM
                [dbo].[QA_Execute_IQC_VisualInspectAuditPoint]
            WHERE AuditListID = @AuditListID
              AND AuditInstanceID = @AuditInstanceID
              AND SampleLevel = @CurrentLevel;
 
 
            /* ========================================================
               6D. INSERT NEXT LEVEL
 
               Level 1 -> Level 2
                   SampleNo 6-30
 
               Level 2 -> Level 3
                   SampleNo 31-80
               ======================================================== */
 
            ;WITH SampleNumbers AS
            (
                SELECT TOP (@NextSampleQty)
                    ROW_NUMBER() OVER
                    (
                        ORDER BY (SELECT NULL)
                    )
                    + @StartSampleNo - 1 AS SampleNo
                FROM sys.all_objects A
                CROSS JOIN sys.all_objects B
            )
            INSERT INTO
                [dbo].[QA_Execute_IQC_VisualInspectAuditPoint]
            (
                AuditListID,
                AuditPointID,
                PartScanID,
                SampleLevel,
                SampleNo,
                Aspect,
                Result,
                Remark,
                Timestamp,
                AuditInstanceID,
                Status,
                Revision
            )
            SELECT
                C.AuditListID,
                C.AuditPointId,
                NULL,
                @NextLevel,
                S.SampleNo,
                C.Aspect,
                NULL,
                NULL,
                GETDATE(),
                @AuditInstanceID,
                1,
                C.Revision
            FROM
                [dbo].[Config_IQC_VisualInspectAuditPoint] C
            CROSS JOIN SampleNumbers S
            WHERE C.AuditListID = @AuditListID;
 
 
            /* ========================================================
               6E. UPDATE MATERIAL RECEIVING
 
               Level 2 -> SampleQty = 24
               Level 3 -> SampleQty = 49
               ======================================================== */
 
            IF @PartID IS NOT NULL
            BEGIN
 
                UPDATE MR
                SET
                    MR.SampleQty = @NextSampleQty - 1,
                    MR.SampleLevel = @NextLevel,
                    MR.ValidatedBy = @ValidatedBy
                FROM
                    [dbo].[Material_Receiving] MR
                WHERE MR.PartID = @PartID
                  AND
                  (
                      MR.SampleLevel = @CurrentLevel
                      OR MR.SampleLevel IS NULL
                  );
 
            END;
 
        END;
 
 
        /* ============================================================
           7. DOCUMENT ID = 2
              MILIPORE
           ============================================================ */
 
      /* ============================================================
   7. DOCUMENT ID = 2
      MILIPORE
   ============================================================ */
 
ELSE IF @DocumentID = 2
BEGIN
 
    /* ========================================================
       7A. CHECK CURRENT LEVEL DATA
       ======================================================== */
 
    SELECT
        @ExistingCount = COUNT(*)
    FROM [dbo].[QA_Execute_IQC_MiliporeAuditpoint]
    WHERE AuditListID = @AuditListID
      AND AuditInstanceID = @AuditInstanceID
      AND SampleLevel = @CurrentLevel;
 
 
    IF @ExistingCount = 0
    BEGIN
        RAISERROR(
            'Current level data does not exist in Milipore Execution table.',
            16,
            1
        );
 
        ROLLBACK TRANSACTION;
        RETURN;
    END;
 
 
    /* ========================================================
       7B. VALIDATE CONFIGURATION
 
       Same concept as DocumentID = 1.
 
       AuditPointID inserted into execution MUST be
       Config_IQC_MiliporeAuditPoint.UID
       because of the FK.
       ======================================================== */
 
    DECLARE @ConfigCount INT;
 
    SELECT
        @ConfigCount = COUNT(*)
    FROM [dbo].[Config_IQC_MiliporeAuditPoint]
    WHERE AuditListID = @AuditListID
      AND Status = 1
      --AND
      --(
      --    @PartID IS NULL
      --    OR PartID = @PartID
      --)
      --AND
      --(
      --    @VendorID IS NULL
      --    OR VendorID = @VendorID
      --);
 
 
    IF @ConfigCount = 0
    BEGIN
        RAISERROR(
            'No active Milipore audit points found in Config_IQC_MiliporeAuditPoint for the given AuditListID, PartID and VendorID.',
            16,
            1
        );
 
        ROLLBACK TRANSACTION;
        RETURN;
    END;
 
 
    /* ========================================================
       7C. MOVE CURRENT LEVEL TO HISTORY
       ======================================================== */
 
    INSERT INTO
        [dbo].[QA_Execute_IQC_MiliporeAuditpoint_History]
    (
        AuditListID,
        AuditPointID,
        PartScanID,
        ObservationValue,
        SampleLevel,
        SampleNo,
        Result,
        Remark,
        Timestamp,
        AuditInstanceID,
        Status,
        Revision
    )
    SELECT
        AuditListID,
        AuditPointID,
        PartScanID,
        ObservationValue,
        SampleLevel,
        SampleNo,
        Result,
        Remark,
        GETDATE(),
        AuditInstanceID,
        Status,
        Revision
    FROM
        [dbo].[QA_Execute_IQC_MiliporeAuditpoint]
    WHERE AuditListID = @AuditListID
      AND AuditInstanceID = @AuditInstanceID
      AND SampleLevel = @CurrentLevel;
 
 
    /* ========================================================
       7D. DELETE CURRENT LEVEL FROM EXECUTION
       ======================================================== */
 
    DELETE FROM
        [dbo].[QA_Execute_IQC_MiliporeAuditpoint]
    WHERE AuditListID = @AuditListID
      AND AuditInstanceID = @AuditInstanceID
      AND SampleLevel = @CurrentLevel;
 
 
    /* ========================================================
       7E. INSERT NEXT LEVEL
 
       Level 1 -> Level 2
       SampleNo 6 - 30
 
       Level 2 -> Level 3
       SampleNo 31 - 80
       ======================================================== */
 
    ;WITH SampleNumbers AS
    (
        SELECT TOP (@NextSampleQty)
            ROW_NUMBER() OVER
            (
                ORDER BY (SELECT NULL)
            ) + @StartSampleNo - 1 AS SampleNo
        FROM sys.all_objects A
        CROSS JOIN sys.all_objects B
    )
    INSERT INTO
        [dbo].[QA_Execute_IQC_MiliporeAuditpoint]
    (
        AuditListID,
        AuditPointID,
        PartScanID,
        SampleLevel,
        SampleNo,
        ObservationValue,
        Result,
        Remark,
        Timestamp,
        AuditInstanceID,
        Status,
        Revision
    )
    SELECT
        C.AuditListID,
 
        /* IMPORTANT:
           FK points to Config UID */
        C.UID AS AuditPointID,
 
        NULL AS PartScanID,
 
        @NextLevel AS SampleLevel,
 
        S.SampleNo,
 
        NULL AS ObservationValue,
 
        NULL AS Result,
 
        NULL AS Remark,
 
        GETDATE() AS Timestamp,
 
        @AuditInstanceID,
 
        1 AS Status,
 
        C.Revision
 
    FROM
        [dbo].[Config_IQC_MiliporeAuditPoint] C
 
    CROSS JOIN
        SampleNumbers S
 
    WHERE
        C.AuditListID = @AuditListID
 
        AND C.Status = 1
 
        --AND
        --(
        --    @PartID IS NULL
        --    OR C.PartID = @PartID
        --)
 
        --AND
        --(
        --    @VendorID IS NULL
        --    OR C.VendorID = @VendorID
        --);
 
 
    /* ========================================================
       7F. VERIFY NEXT LEVEL INSERT
       ======================================================== */
 
    IF NOT EXISTS
    (
        SELECT 1
        FROM [dbo].[QA_Execute_IQC_MiliporeAuditpoint]
        WHERE AuditListID = @AuditListID
          AND AuditInstanceID = @AuditInstanceID
          AND SampleLevel = @NextLevel
    )
    BEGIN
        RAISERROR(
            'Next sample level was not inserted into Milipore Execution table.',
            16,
            1
        );
 
        ROLLBACK TRANSACTION;
        RETURN;
    END;
 
 
    /* ========================================================
       7G. UPDATE MATERIAL RECEIVING
       ======================================================== */
 
    IF @PartID IS NOT NULL
    BEGIN
 
        UPDATE MR
        SET
            MR.SampleQty = @NextSampleQty - 1,
            MR.SampleLevel = @NextLevel,
            MR.ValidatedBy = @ValidatedBy
 
        FROM [dbo].[Material_Receiving] MR
 
        WHERE MR.PartID = @PartID
 
          AND
          (
              MR.SampleLevel = @CurrentLevel
              OR MR.SampleLevel IS NULL
          );
 
    END;
 
END;
 
 
        /* ============================================================
           8. COMMIT TRANSACTION
           ============================================================ */
 
        COMMIT TRANSACTION;
 
 
        /* ============================================================
           9. RETURN RESPONSE
           ============================================================ */
 
        SELECT
            @DocumentID AS DocumentID,
            @AuditListID AS AuditListID,
            @AuditInstanceID AS AuditInstanceID,
            @CurrentLevel AS PreviousLevel,
            @NextLevel AS NextLevel,
            @NextSampleQty AS SampleQty,
            @StartSampleNo AS StartSampleNo,
            @EndSampleNo AS EndSampleNo,
            'Sample level moved successfully.'
                AS Message;
 
 
    END TRY
 
    BEGIN CATCH
 
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;
 
        SELECT
            ERROR_NUMBER() AS ErrorNumber,
            ERROR_MESSAGE() AS ErrorMessage,
            ERROR_LINE() AS ErrorLine;
 
    END CATCH
 
END
GO

-- ------------------------------------------------------------------------
-- [369/376] Stored Procedure: [dbo].[Tab_Q_IQC_UpdateIQCCheckpointResult]
-- Created: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time) | Last Modified: Fri Oct 09 2026 14:26:13 GMT+0530 (India Standard Time)
-- ------------------------------------------------------------------------
CREATE PROCEDURE [dbo].[Tab_Q_IQC_UpdateIQCCheckpointResult]
(
    @DocumentID INT,
    @UID INT,
    @Result INT,
    @Remark NVARCHAR(500) = NULL,
    @ObservationValue NVARCHAR(500) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    /* ============================================================
       1. VALIDATE DOCUMENT ID
       ============================================================ */

    IF @DocumentID NOT IN (1, 2)
    BEGIN
        RAISERROR(
            'Invalid DocumentID. DocumentID must be 1 for Visual Inspection or 2 for Milipore.',
            16,
            1
        );
        RETURN;
    END;


    /* ============================================================
       2. VALIDATE UID
       ============================================================ */

    IF @UID IS NULL OR @UID <= 0
    BEGIN
        RAISERROR(
            'Invalid UID. UID must be provided.',
            16,
            1
        );
        RETURN;
    END;


    /* ============================================================
       3. VALIDATE RESULT
       1 = OK
       2 = NOK
       ============================================================ */

    IF @Result NOT IN (1, 2)
    BEGIN
        RAISERROR(
            'Invalid Result. Result must be 1 (OK) or 2 (NOK).',
            16,
            1
        );
        RETURN;
    END;


    /* ============================================================
       4. DOCUMENT ID = 1
       IQC VISUAL INSPECTION
       ============================================================ */

    IF @DocumentID = 1
    BEGIN

        /* Check UID exists */

        IF NOT EXISTS
        (
            SELECT 1
            FROM [dbo].[QA_Execute_IQC_VisualInspectAuditPoint]
            WHERE UID = @UID
        )
        BEGIN
            RAISERROR(
                'Visual Inspection checkpoint execution record not found for the given UID.',
                16,
                1
            );
            RETURN;
        END;


        /* Update exact record using UID */

        UPDATE [dbo].[QA_Execute_IQC_VisualInspectAuditPoint]
        SET
            Result = @Result,
            Remark = @Remark,
            Timestamp = GETDATE()
        WHERE UID = @UID;


        /* Return updated record */

        SELECT
            UID,
            AuditListID,
            AuditPointID,
            PartScanID,
            SampleLevel,
            SampleNo,
            Aspect,
            Result,
            Remark,
            Timestamp,
            AuditInstanceID,
            Status,
            Revision
        FROM [dbo].[QA_Execute_IQC_VisualInspectAuditPoint]
        WHERE UID = @UID;

        RETURN;
    END;


    /* ============================================================
       5. DOCUMENT ID = 2
       IQC MILIPORE
       ============================================================ */

    IF @DocumentID = 2
    BEGIN

        /* Check UID exists */

        IF NOT EXISTS
        (
            SELECT 1
            FROM [dbo].[QA_Execute_IQC_MiliporeAuditpoint]
            WHERE UID = @UID
        )
        BEGIN
            RAISERROR(
                'Milipore checkpoint execution record not found for the given UID.',
                16,
                1
            );
            RETURN;
        END;


        /* Update exact record using UID */

        UPDATE [dbo].[QA_Execute_IQC_MiliporeAuditpoint]
        SET
            ObservationValue = @ObservationValue,
            Result = @Result,
            Remark = @Remark,
            Timestamp = GETDATE()
        WHERE UID = @UID;


        /* Return updated record */

        SELECT
            UID,
            AuditListID,
            AuditPointID,
            PartScanID,
            SampleLevel,
            SampleNo,
            ObservationValue,
            Result,
            Remark,
            Timestamp,
            AuditInstanceID,
            Status,
            Revision
        FROM [dbo].[QA_Execute_IQC_MiliporeAuditpoint]
        WHERE UID = @UID;

        RETURN;
    END;

END
GO

